  'nationalTitles': r.nationalTitles,
  'conferenceTitles': r.conferenceTitles,
  'bowlWins': r.bowlWins,
  'bowlPoints': r.bowlPoints,
  'undefeatedSeasons': r.undefeatedSeasons,
  'conferenceOverride': r.conferenceOverride,
  'subdivisionOverride': r.subdivisionOverride?.name,
  'consecutiveWinningSeasons': r.consecutiveWinningSeasons,
  'playoffAppearances': r.playoffAppearances,
  'seasonsSinceRealignment': r.seasonsSinceRealignment,
};

RivalCoachRecord rivalCoachFromJson(Map<String, dynamic> json) =>
    RivalCoachRecord(
      coachName: '${json['coachName'] ?? 'Coach'}',
      teamName: '${json['teamName'] ?? ''}',
      currentPrestige: (json['currentPrestige'] as num?)?.toInt() ?? 50,
      tenureYears: (json['tenureYears'] as num?)?.toInt() ?? 0,
      careerWins: (json['careerWins'] as num?)?.toInt() ?? 0,
      careerLosses: (json['careerLosses'] as num?)?.toInt() ?? 0,
      nationalTitles: (json['nationalTitles'] as num?)?.toInt() ?? 0,
      conferenceTitles: (json['conferenceTitles'] as num?)?.toInt() ?? 0,
      bowlWins: (json['bowlWins'] as num?)?.toInt() ?? 0,
      // Old saves predate tiered bowl scoring — a flat 75/bowl fallback
      // (rather than 0) keeps a pre-existing rival's score from suddenly
      // dropping the moment this update loads their save.
      bowlPoints:
          (json['bowlPoints'] as num?)?.toInt() ??
          ((json['bowlWins'] as num?)?.toInt() ?? 0) * 75,
      undefeatedSeasons: (json['undefeatedSeasons'] as num?)?.toInt() ?? 0,
      conferenceOverride: json['conferenceOverride'] == null
          ? null
          : '${json['conferenceOverride']}',
      subdivisionOverride: Subdivision.values
          .where((s) => s.name == json['subdivisionOverride'])
          .firstOrNull,
      consecutiveWinningSeasons:
          (json['consecutiveWinningSeasons'] as num?)?.toInt() ?? 0,
      playoffAppearances: (json['playoffAppearances'] as num?)?.toInt() ?? 0,
      // A save from before realignment existed has never been realigned —
      // default high (not 0) so it doesn't read as "just realigned" and
      // sit falsely inside the cooldown window.
      seasonsSinceRealignment:
          (json['seasonsSinceRealignment'] as num?)?.toInt() ?? 99,
    );

