/// Retired coaches, global across every career on this device — reused by
/// the Legacy Board's Hall of Fame section alongside the fixed
/// [legendCoaches] roster.
Future<List<LegendCoachRecord>> loadRetiredLegends() async {
  try {
    final preferences = await SharedPreferences.getInstance();
    final raw = preferences.getString(_retiredLegendsPrefsKey);
    if (raw == null) return [];
    final decoded = jsonDecode(raw);
    if (decoded is! List) return [];
    return decoded
        .whereType<Map>()
        .map((e) => legendCoachFromJson(Map<String, dynamic>.from(e)))
        .toList();
  } catch (_) {
    return [];
  }
}

Future<void> _writeRetiredLegends(List<LegendCoachRecord> legends) async {
  final preferences = await SharedPreferences.getInstance();
  await preferences.setString(
    _retiredLegendsPrefsKey,
    jsonEncode(legends.map(legendCoachToJson).toList()),
  );
}

Future<void> addRetiredLegend(LegendCoachRecord legend) async {
  final existing = await loadRetiredLegends();
  existing.add(legend);
  await _writeRetiredLegends(existing);
}

