  'year': r.year,
  'description': r.description,
  'met': r.met,
};

SeasonGoalRecord seasonGoalRecordFromJson(Map<String, dynamic> json) =>
    SeasonGoalRecord(
      year: (json['year'] as num?)?.toInt() ?? 1,
      description: '${json['description'] ?? ''}',
      met: json['met'] ?? false,
    );

Map<String, dynamic> seasonGoalToJson(SeasonGoal g) => {
  'type': g.type.name,
  'targetWins': g.targetWins,
};

SeasonGoal seasonGoalFromJson(Map<String, dynamic> json) {
  // firstWhere+orElse, not .byName — a persisted value must survive an
  // unknown/missing/future-renamed type without throwing.
  final typeName = '${json['type'] ?? ''}';
  final type = SeasonGoalType.values.firstWhere(
    (t) => t.name == typeName,
    orElse: () => SeasonGoalType.winTotal,
  );
  return SeasonGoal(
    type: type,
    targetWins: (json['targetWins'] as num?)?.toInt(),
  );
}

Future<List<Map<String, dynamic>>> loadCareerSaves() async {
  try {
    final preferences = await SharedPreferences.getInstance();
    var raw = preferences.getString(_careerSavesPrefsKey);

    if (raw == null) {
      // One-time migration from the old temp-directory save file, so a
      // career already in progress isn't stranded by the storage change.
      final legacyFile = File(_legacyTempSaveFilePath);
      if (await legacyFile.exists()) {
        raw = await legacyFile.readAsString();
        await preferences.setString(_careerSavesPrefsKey, raw);
      }
    }

    if (raw == null) return [];
    final decoded = jsonDecode(raw);
    if (decoded is! List) return [];
    return decoded
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
  } catch (_) {
    return [];
  }
}

Future<void> writeCareerSaves(List<Map<String, dynamic>> saves) async {
  final preferences = await SharedPreferences.getInstance();
  await preferences.setString(_careerSavesPrefsKey, jsonEncode(saves));
}

String careerKeyFromCoachName(String coachName) {
  final clean = coachName
      .trim()
      .toLowerCase()
      .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
      .replaceAll(RegExp(r'_+'), '_')
      .replaceAll(RegExp(r'^_|_$'), '');

  return clean.isEmpty ? 'coach' : 'coach_$clean';
}

String careerKeyFromSave(Map<String, dynamic> save) {
  final existing = '${save['careerKey'] ?? ''}';
  if (existing.isNotEmpty && existing != 'null') return existing;

  final coachMap = Map<String, dynamic>.from(save['coach'] ?? {});
  return careerKeyFromCoachName('${coachMap['name'] ?? 'Coach'}');
}

Future<void> upsertCareerSave(Map<String, dynamic> save) async {
  final saves = await loadCareerSaves();
  final key = careerKeyFromSave(save);

  save['careerKey'] = key;
  save['id'] = key;

  // This is the important part:
  // remove every older autosave for this coach career, then write the newest one.
  final cleaned = saves.where((s) => careerKeyFromSave(s) != key).toList();
  cleaned.add(save);

  await writeCareerSaves(cleaned);
}

String rankedDisplayName(CollegeTeam team, int rank) {
  if (rank > 0 && rank <= 25) {
    return '#$rank ${team.displayName}';
  }
  return team.displayName;
}

/// Division I's two subdivisions. Defaults to `fbs` on every existing
/// `CollegeTeam` literal so the entire pre-FCS `g5Teams` list — and every
/// save built against it, which only ever persists a team-name string, not
/// a serialized `CollegeTeam` — keeps compiling and loading unchanged.
enum Subdivision { fbs, fcs }

class CollegeTeam {
  final String name;
  final String conference;
  final int prestige;
  final Color primary;
  final Color secondary;
  final Subdivision subdivision;

  /// A single emoji hinting at the school's identity (its real mascot).
  /// A visual assist alongside the team name, not a replacement for the
  /// authored monogram badge (GKTeamBadge) used as the actual icon system.
  final String emoji;

  /// The school's real mascot/nickname (e.g. "Buckeyes", "Crimson Tide"),
  /// paired with `name` for display as "Columbus Buckeyes".
  final String mascot;

  const CollegeTeam({
    required this.name,
    required this.conference,
    required this.prestige,
    required this.primary,
    required this.secondary,
    this.subdivision = Subdivision.fbs,
    this.emoji = '🏈',
    this.mascot = 'Program',
  });

  bool get isStarterSchool => prestige == 1;
  bool get isFcs => subdivision == Subdivision.fcs;
}

class TeamSeasonRecord {
  int wins;
  int losses;
  int confWins;
  int confLosses;

  TeamSeasonRecord({
    this.wins = 0,
    this.losses = 0,
    this.confWins = 0,
    this.confLosses = 0,
  });

  int get gamesPlayed => wins + losses;
  double get winPct => gamesPlayed == 0 ? 0 : wins / gamesPlayed;
  String get overallText => '$wins-$losses';
  String get confText => '$confWins-$confLosses';

  void reset() {
    wins = 0;
    losses = 0;
    confWins = 0;
    confLosses = 0;
  }
}

// Pads or trims a team's record in place so it has exactly targetConf
// conference games and targetTotal total games — the record of how many
// games a team "should" have at this point in the season. Idempotent:
// calling this again with the same targets on an already-correct record
// is a no-op, which is the property that was missing before (normalizing
// mid-season used to always target a full 12-game season regardless of how
// far the season had actually gotten, so calling it twice at different
// points could silently erase real, already-simulated results).
void normalizeTeamRecordToTarget(
  TeamSeasonRecord rec, {
  required int targetTotal,
  required int targetConf,
  required int prestige,
  required Random rng,
}) {
  final targetNonConf = targetTotal - targetConf;

  final confPlayed = rec.confWins + rec.confLosses;
  if (confPlayed < targetConf) {
    final remaining = targetConf - confPlayed;
    final strength = prestige100(prestige);
    for (int i = 0; i < remaining; i++) {
      final winChance = (0.28 + (strength / 180)).clamp(.25, .82);
      if (rng.nextDouble() < winChance) {
        rec.confWins++;
      } else {
        rec.confLosses++;
      }
    }
  } else if (confPlayed > targetConf) {
    while (rec.confWins + rec.confLosses > targetConf && rec.confLosses > 0) {
      rec.confLosses--;
      if (rec.losses > 0) rec.losses--;
    }
    while (rec.confWins + rec.confLosses > targetConf && rec.confWins > 0) {
      rec.confWins--;
      if (rec.wins > 0) rec.wins--;
    }
  }

  final nonConfWins = max(0, rec.wins - rec.confWins);
  final nonConfLosses = max(0, rec.losses - rec.confLosses);
  final cappedNonConfWins = min(nonConfWins, targetNonConf);
  final cappedNonConfLosses = min(
    nonConfLosses,
    targetNonConf - cappedNonConfWins,
  );

  rec.wins = cappedNonConfWins + rec.confWins;
  rec.losses = cappedNonConfLosses + rec.confLosses;

  final totalPlayed = rec.wins + rec.losses;
  if (totalPlayed < targetTotal) {
    final remaining = targetTotal - totalPlayed;
    for (int i = 0; i < remaining; i++) {
      if (rng.nextDouble() < .50) {
        rec.wins++;
      } else {
        rec.losses++;
      }
    }
  }
}

