// ============================================================================
// LEGACY BOARD — a simulated coach-prestige leaderboard: the user's own
// coach, one AI rival per program, and a fixed "Hall of Fame" of fictional
// retired legends, ranked by a shared legacy-score formula. Also the
// realistic season-goal system that regenerates every year from prestige.
// ============================================================================

enum SeasonGoalType { winTotal, bowlBerth, conferenceTitle, playoffBerth, nationalTitle }

/// This season's coaching target, generated fresh each offseason from that
/// season's starting prestige (seasonGoalFor). targetWins only matters for
/// winTotal; every other type is a plain pass/fail resolved by goalWasMet.
class SeasonGoal {
  final SeasonGoalType type;
  final int? targetWins;

  const SeasonGoal({required this.type, this.targetWins});

  String get description => switch (type) {
    SeasonGoalType.winTotal => 'WIN $targetWins GAMES',
    SeasonGoalType.bowlBerth => 'REACH A BOWL GAME',
    SeasonGoalType.conferenceTitle => 'WIN THE CONFERENCE',
    SeasonGoalType.playoffBerth => 'MAKE THE KP',
    SeasonGoalType.nationalTitle => 'WIN THE NATIONAL CHAMPIONSHIP',
  };
}

/// A resolved snapshot of a past season's goal — kept as-worded even if
/// seasonGoalFor's copy later changes, so history always reads as it did
/// the year it happened.
class SeasonGoalRecord {
  final int year;
  final String description;
  final bool met;

  const SeasonGoalRecord({
    required this.year,
    required this.description,
    required this.met,
  });
}

/// One AI program's coach, simulated once per offseason. teamName is a
/// lookup key into g5Teams (via teamByName) for display — not duplicated.
class RivalCoachRecord {
  final String coachName;
  final String teamName;
  final int currentPrestige;
  final int tenureYears;
  final int careerWins;
  final int careerLosses;
  final int nationalTitles;
  final int conferenceTitles;
  final int bowlWins;
  // Tiered total across every bowl this rival has won (see bowlWinPoints)
  // — the real scoring input; bowlWins stays around as the raw count for
  // display.
  final int bowlPoints;
  final int undefeatedSeasons;
  // Live conference/subdivision overrides — a team's static CollegeTeam
  // entry never changes, so a realigned or promoted program's actual
  // current conference/subdivision lives here instead (see liveTeamFor/
  // _DashboardScreenState._liveTeam), exactly mirroring how currentPrestige
  // already overrides the static day-one prestige.
  final String? conferenceOverride;
  final Subdivision? subdivisionOverride;
  // Promotion/realignment tracking (see isPromotionEligible).
  final int consecutiveWinningSeasons;
  final int playoffAppearances;
  final int seasonsSinceRealignment;

  const RivalCoachRecord({
    required this.coachName,
    required this.teamName,
    required this.currentPrestige,
    required this.tenureYears,
    required this.careerWins,
    required this.careerLosses,
    required this.nationalTitles,
    required this.conferenceTitles,
    required this.bowlWins,
    this.bowlPoints = 0,
    this.undefeatedSeasons = 0,
    this.conferenceOverride,
    this.subdivisionOverride,
    this.consecutiveWinningSeasons = 0,
    this.playoffAppearances = 0,
    this.seasonsSinceRealignment = 99,
  });

  RivalCoachRecord copyWith({
    int? currentPrestige,
    int? tenureYears,
    int? careerWins,
    int? careerLosses,
    int? nationalTitles,
    int? conferenceTitles,
    int? bowlWins,
    int? bowlPoints,
    int? undefeatedSeasons,
    String? conferenceOverride,
    Subdivision? subdivisionOverride,
    int? consecutiveWinningSeasons,
    int? playoffAppearances,
    int? seasonsSinceRealignment,
  }) {
    return RivalCoachRecord(
      coachName: coachName,
      teamName: teamName,
      currentPrestige: currentPrestige ?? this.currentPrestige,
      tenureYears: tenureYears ?? this.tenureYears,
      careerWins: careerWins ?? this.careerWins,
      careerLosses: careerLosses ?? this.careerLosses,
      nationalTitles: nationalTitles ?? this.nationalTitles,
      conferenceTitles: conferenceTitles ?? this.conferenceTitles,
      bowlWins: bowlWins ?? this.bowlWins,
      bowlPoints: bowlPoints ?? this.bowlPoints,
      undefeatedSeasons: undefeatedSeasons ?? this.undefeatedSeasons,
      conferenceOverride: conferenceOverride ?? this.conferenceOverride,
      subdivisionOverride: subdivisionOverride ?? this.subdivisionOverride,
      consecutiveWinningSeasons:
          consecutiveWinningSeasons ?? this.consecutiveWinningSeasons,
      playoffAppearances: playoffAppearances ?? this.playoffAppearances,
      seasonsSinceRealignment:
          seasonsSinceRealignment ?? this.seasonsSinceRealignment,
    );
  }
}

/// A fixed, entirely fictional retired coach shown in the Legacy Board's
/// Hall of Fame — invented name, invented career stats loosely evoking a
/// broad coaching archetype, never a stand-in for any specific real coach.
class LegendCoachRecord {
  final String name;
  final String archetype;
  final int careerWins;
  final int nationalTitles;
  final int conferenceTitles;
  final int bowlWins;
  final int bowlPoints;
  final int undefeatedSeasons;

  const LegendCoachRecord({
    required this.name,
    required this.archetype,
    required this.careerWins,
    required this.nationalTitles,
    required this.conferenceTitles,
    required this.bowlWins,
    required this.bowlPoints,
    required this.undefeatedSeasons,
  });
}

/// A set point value per bowl, tiered by which win-band the bowl comes
/// from (mirrors _bowlNameForRecord's exact tiers — an 11-win Grove Bowl
/// win is a bigger deal than a 6-win Beacon Bowl win, and now scores like
/// one). Every bowl a coach could ever be assigned appears here exactly
/// once; a base win (see bowlWinPoints) still counts for something even
/// for a name this map somehow doesn't recognize.
const Map<String, int> bowlTierPoints = {
  // 11+ wins
  'Grove Bowl': 150,
  'Mission Bowl': 150,
  'Bayfront Bowl': 150,
  'Coastline Bowl': 150,
  // 10 wins
  'Harmony Bowl': 130,
  'Rio Bowl': 130,
  'Neon Bowl': 130,
  'Riverside Bowl': 130,
  // 9 wins
  'Heritage Bowl': 110,
  'Solstice Bowl': 110,
  'Empire Bowl': 110,
  'Queen City Bowl': 110,
  // 8 wins
  'Patriots Bowl': 95,
  'Service Bowl': 95,
  'Ironworks Bowl': 95,
  'Desert Sky Bowl': 95,
  // 7 wins
  'Frontline Bowl': 85,
  'Metroplex Bowl': 85,
  'Mesa Bowl': 85,
  'Buccaneer Bowl': 85,
  // 6 or fewer wins
  'Beacon Bowl': 75,
  'Boardwalk Bowl': 75,
  'Bayou Bowl': 75,
  'Magnolia Bowl': 75,
};

/// A trophy's title is always '$bowlName Champions' (see _addTrophy call
/// sites) — match the bowl name out of that and look up its tier. Falls
/// back to the base value so an unrecognized name still counts as a real
/// bowl win rather than scoring zero.
int bowlWinPoints(String trophyTitle) {
  for (final entry in bowlTierPoints.entries) {
    if (trophyTitle.startsWith(entry.key)) return entry.value;
  }
  return 75;
}

/// One shared formula used identically for the user, every rival, and
/// every legend, so the board's ranking is apples-to-apples. A national
/// title dominates a pile of conference titles, which dominates a pile of
/// bowl points, which dominates raw win totals; currentPrestige (max 100)
/// is only a minor tiebreaker. bowlPoints is the SUM of bowlWinPoints
/// across every bowl a coach has won (tiered, not a flat count), and
/// undefeatedSeasons is a real, rare record — worth more than any single
/// bowl, but well short of a conference title.
int legacyScoreFor({
  required int nationalTitles,
  required int conferenceTitles,
  required int bowlPoints,
  required int careerWins,
  required int currentPrestige,
  int undefeatedSeasons = 0,
}) {
  return nationalTitles * 1000 +
      conferenceTitles * 250 +
      bowlPoints +
      undefeatedSeasons * 200 +
      careerWins * 2 +
      currentPrestige;
}

/// Generates the upcoming season's goal from the prestige it'll be played
/// at. Follows realisticContractGoal's tier philosophy, but every tier maps
/// to exactly one cleanly boolean-resolvable SeasonGoalType (unlike
/// realisticContractGoal's tier-3 "WIN 7-8 GAMES", which isn't pass/fail).
SeasonGoal seasonGoalFor(int prestige) {
  final tier = prestigeTier(prestige);
  return switch (tier) {
    1 => SeasonGoal(
      type: SeasonGoalType.winTotal,
      targetWins: prestigeExpectationWins(prestige),
    ),
    2 => const SeasonGoal(type: SeasonGoalType.bowlBerth),
    3 => const SeasonGoal(type: SeasonGoalType.conferenceTitle),
    4 => const SeasonGoal(type: SeasonGoalType.playoffBerth),
    _ => const SeasonGoal(type: SeasonGoalType.nationalTitle),
  };
}

/// Resolves a just-finished season's goal. Reuses the exact wins >= 6
/// bowl-eligibility threshold already used for the user's own bowl
/// selection, for consistency with how bowl eligibility works everywhere
/// else in the sim.
bool goalWasMet(
  SeasonGoal goal, {
  required int wins,
  required bool wonConference,
  required bool madeCfp,
  required bool wonTitle,
}) {
  switch (goal.type) {
    case SeasonGoalType.winTotal:
      return wins >= (goal.targetWins ?? 0);
    case SeasonGoalType.bowlBerth:
      return wins >= 6;
    case SeasonGoalType.conferenceTitle:
      return wonConference;
    case SeasonGoalType.playoffBerth:
      return madeCfp;
    case SeasonGoalType.nationalTitle:
      return wonTitle;
  }
}

