}

class CoachBackground {
  final String hometownState;
  final String hometownRegion;
  final String almaMater;
  final String priorStop;

  const CoachBackground({
    required this.hometownState,
    required this.hometownRegion,
    required this.almaMater,
    required this.priorStop,
  });

  // Every state that gives a (smaller) regional pipeline bonus alongside
  // the coach's exact hometown state.
  List<String> get regionStates => pipelineRegions[hometownRegion] ?? const [];

  String get pipelineBlurb =>
      'Deep ties to $hometownState high school football give this staff a real recruiting pipeline there, and a broader $hometownRegion network beyond it — prospects across the region trust the connection.';
}

// Matches the state pool generateRecruits() actually draws from, so the
// pipeline bonus can ever mean something.
const List<String> _coachPipelineStates = [
  'RI',
  'MA',
  'CT',
  'NY',
  'NJ',
  'PA',
  'OH',
  'MI',
  'FL',
  'GA',
  'TX',
  'CA',
  'AZ',
  'NC',
  'SC',
  'VA',
  'MD',
  'AL',
  'LA',
  'TN',
];

// Named, broad recruiting footprints — every pipeline state belongs to
// exactly one region, so a coach's pipeline is never just a single state
// in isolation. A coach's exact hometown state still gets the strongest
// pipeline bonus; every other state in the same region gets a smaller one.
const Map<String, List<String>> pipelineRegions = {
  'New England': ['RI', 'MA', 'CT'],
  'Mid-Atlantic': ['NY', 'NJ', 'PA', 'MD'],
  'Rust Belt': ['OH', 'MI'],
  'Sun Belt': ['FL', 'GA', 'SC', 'NC'],
  'Deep South': ['AL', 'LA', 'TN'],
  'Texas Triangle': ['TX'],
  'West Coast': ['CA', 'AZ'],
  'Old Dominion': ['VA'],
};

String regionForState(String state) {
  for (final entry in pipelineRegions.entries) {
    if (entry.value.contains(state)) return entry.key;
  }
  return 'National';
}

// ============================================================================
// SCHEME MASTERY — offensive/defensive scheme identity and how well it fits
// each of the sim's seven roster positions. A small, bounded, deterministic
// signed int added into whatever formula already exists (recruiting interest,
// training efficiency, in-game matchup odds) — never a parallel system, and
// never large enough to override a real Overall gap.
// ============================================================================

const List<String> offensiveSchemes = [
  'Air Raid',
  'Ground & Pound',
  'Option',
  'Pro Style',
  'Spread',
];

const List<String> defensiveSchemes = [
  '4-3 Defense',
  '3-4 Defense',
  'Nickel',
  'Man Blitz',
  'Zone Heavy',
];

const Set<String> _offensiveSchemePositions = {'QB', 'HB', 'WR', 'TE'};

// Air Raid wants a rhythm-and-timing pocket passer and burns you with WRs;
// Ground & Pound is built around a bell-cow HB and a blocking TE and has
// little use for a pocket passer; Option lives and dies on a dual-threat QB
// and a downhill back; Pro Style is the deliberate "no weaknesses, no
// strengths" generalist; Spread stretches the field with WRs and a QB
// comfortable throwing on the move.
const Map<String, Map<String, int>> offensiveSchemeFitByPosition = {
  'Air Raid': {'QB': 8, 'HB': -4, 'WR': 12, 'TE': 4},
  'Ground & Pound': {'QB': -6, 'HB': 12, 'WR': -4, 'TE': 9},
  'Option': {'QB': 10, 'HB': 8, 'WR': -2, 'TE': 3},
  'Pro Style': {'QB': 3, 'HB': 3, 'WR': 3, 'TE': 3},
  'Spread': {'QB': 6, 'HB': 2, 'WR': 10, 'TE': -3},
};

// 4-3 wants stout DEs and full-time LBs; 3-4 trades a lineman for a fourth
// LB and lives on LB versatility; Nickel and Zone Heavy both prioritize an
// extra/disciplined DB over the front; Man Blitz wants pass-rushing DEs and
// DBs who can survive on an island.
const Map<String, Map<String, int>> defensiveSchemeFitByPosition = {
  '4-3 Defense': {'DE': 10, 'LB': 8, 'DB': -2},
  '3-4 Defense': {'DE': -3, 'LB': 12, 'DB': 0},
  'Nickel': {'DE': -2, 'LB': -3, 'DB': 11},
  'Man Blitz': {'DE': 9, 'LB': -4, 'DB': 7},
  'Zone Heavy': {'DE': -2, 'LB': 2, 'DB': 9},
};

/// A single signed fit value for [position] under the given scheme(s).
/// Offense/defense tables are mutually exclusive by position, so exactly
/// one lookup ever applies. Returns 0 (no opinion) whenever the relevant
/// scheme isn't supplied, mirroring the pipeline bonus's "no coach info yet"
/// behavior.
int schemeFitBonus(
  String position, {
  String? offensiveScheme,
  String? defensiveScheme,
}) {
  if (_offensiveSchemePositions.contains(position)) {
    if (offensiveScheme == null) return 0;
    return offensiveSchemeFitByPosition[offensiveScheme]?[position] ?? 0;
  }
  if (defensiveScheme == null) return 0;
  return defensiveSchemeFitByPosition[defensiveScheme]?[position] ?? 0;
}

/// Why a roster player is flagged as a transfer risk — always at least one
/// of these three real, checkable signals, never a vague morale number.
enum TransferRiskReason { playingTime, schemeFit, nil }

class TransferRiskAssessment {
  final Player player;
  final List<TransferRiskReason> reasons;
  final int riskScore;

  const TransferRiskAssessment({
    required this.player,
    required this.reasons,
    required this.riskScore,
  });

  String reasonLabel(TransferRiskReason reason) => switch (reason) {
    TransferRiskReason.playingTime => 'PLAYING TIME',
    TransferRiskReason.schemeFit => 'SCHEME FIT',
    TransferRiskReason.nil => 'NIL',
  };
}

/// A stable seed derived from the player's own name — same shape as the
/// hidden-gem/bust seeds used for recruits, so a player's NIL frustration
/// reads the same every time the roster renders instead of reshuffling.
int _nilFrustrationSeed(Player p) => p.name.hashCode.abs() % 100;

/// One real, derivable transfer-risk read per roster player: a proven
/// upperclassman stuck on the bench, a player whose position doesn't fit
/// the coach's own scheme, or a talented player the program isn't
/// financially backing. No new persisted state — every signal is computed
/// from data the roster/coach/program already carry.
TransferRiskAssessment transferRiskFor(
  Player p, {
  required bool isStarter,
  required String? offensiveScheme,
  required String? defensiveScheme,
  required int boosterApproval,
}) {
  final reasons = <TransferRiskReason>[];
  var score = 0;

  final isUpperclassman = p.year == 'JR' || p.year == 'SR';
  if (!isStarter && isUpperclassman && p.stars >= 3) {
    reasons.add(TransferRiskReason.playingTime);
    score += 30 + (p.stars - 3) * 8;
  }

  final fit = schemeFitBonus(
    p.position,
    offensiveScheme: offensiveScheme,
    defensiveScheme: defensiveScheme,
  );
  if (fit < 0) {
    reasons.add(TransferRiskReason.schemeFit);
    score += -fit * 2;
  }

  if (p.stars >= 4 && boosterApproval < 60 && _nilFrustrationSeed(p) < 40) {
    reasons.add(TransferRiskReason.nil);
    score += 25;
  }

  return TransferRiskAssessment(
    player: p,
    reasons: reasons,
    riskScore: score.clamp(0, 100),
  );
}

// A deterministic (but not persisted) scheme identity for every AI
// opponent — same (team, season) always gives the same answer, matching
// the pattern nationalStartingQbFor already uses via _nationalRosterSeed.
// Salts chosen well clear of every other _nationalRosterSeed use in this
// file (roster-position salts run 0-24, recruiting-class salts run
// 500000-500024).
String offensiveSchemeFor(CollegeTeam team, int season) =>
    offensiveSchemes[Random(
      _nationalRosterSeed(team.name, season, 900001),
    ).nextInt(offensiveSchemes.length)];

String defensiveSchemeFor(CollegeTeam team, int season) =>
    defensiveSchemes[Random(
      _nationalRosterSeed(team.name, season, 900002),
    ).nextInt(defensiveSchemes.length)];

// Row = offensive scheme, column = defensive scheme. Values are in the same
// OVR-point units as `diff` in _simPlay — added straight into it, so this
// can only ever nudge outcomes by roughly what a handful of Overall points
// would, never override a real talent gap. Ground & Pound is smothered by a
// 3-4's extra run-fitter but gashes a light Nickel box; Air Raid torches a
// base 4-3 but stalls against Nickel coverage; Option is shut down by Man
// Blitz's discipline but guts Zone Heavy/Nickel's softer fronts; Spread
// isolates Man Blitz's corners in space but Zone Heavy takes that away; Pro
// Style is a flat 0 row everywhere — no bad matchups, no great ones.
const Map<String, Map<String, int>> schemeMatchupMatrix = {
  'Air Raid': {
    '4-3 Defense': 3,
    '3-4 Defense': 1,
    'Nickel': -3,
    'Man Blitz': -1,
    'Zone Heavy': -2,
  },
  'Ground & Pound': {
    '4-3 Defense': -1,
    '3-4 Defense': -4,
    'Nickel': 4,
    'Man Blitz': 1,
    'Zone Heavy': 0,
  },
  'Option': {
    '4-3 Defense': 1,
    '3-4 Defense': 0,
    'Nickel': 3,
    'Man Blitz': -4,
    'Zone Heavy': 2,
  },
  'Pro Style': {
    '4-3 Defense': 0,
    '3-4 Defense': 0,
    'Nickel': 0,
    'Man Blitz': 0,
    'Zone Heavy': 0,
  },
  'Spread': {
    '4-3 Defense': 1,
    '3-4 Defense': 0,
    'Nickel': -1,
    'Man Blitz': 3,
    'Zone Heavy': -3,
  },
};

int schemeMatchupModifier(String offensiveScheme, String defensiveScheme) =>
    schemeMatchupMatrix[offensiveScheme]?[defensiveScheme] ?? 0;

/// One drive's outcome odds — pulled out of _GameSimScreenState._simPlay
/// as a pure, unit-testable function. The four base curves and clamps are
/// unchanged from the original inline formula; tdDelta/fgDelta/
/// turnoverDelta/bigPlayDelta are additive hooks (halftime adjustments use
/// them) that always apply before the same clamps, so no caller — not even
/// an adversarial combination of every bonus at once — can push a chance
/// outside its original declared range.
class DriveChances {
  final double td, fg, turnover, bigPlay;
  const DriveChances({
    required this.td,
    required this.fg,
    required this.turnover,
    required this.bigPlay,
  });
}

// Halftime adjustments are two independent decisions — how the offense
// plays the rest of the game, and how the defense does — so a coach can
// mix and match (e.g. air it out AND bring pressure) instead of picking
// one combined archetype.
enum _OffensivePlan { airItOut, balanced, runItOut }

enum _DefensivePlan { bringPressure, balanced, bendDontBreak }

DriveChances driveChancesFor({
  required double diff,
  double tdDelta = 0,
  double fgDelta = 0,
  double turnoverDelta = 0,
  double bigPlayDelta = 0,
}) {
  return DriveChances(
    td: (0.105 + diff * 0.006 + tdDelta).clamp(0.018, 0.28),
    fg: (0.078 + diff * 0.0025 + fgDelta).clamp(0.020, 0.16),
    turnover: (0.105 - diff * 0.002 + turnoverDelta).clamp(0.045, 0.22),
    bigPlay: (0.100 + diff * 0.003 + bigPlayDelta).clamp(0.035, 0.20),
  );
}

const List<String> _coachAlmaMaters = [
  'Ridgeview State',
  'Harlow University',
  'Fort Union College',
  'Blackwood Tech',
  'Prairie Crossing U',
  'Deacon Hill College',
  'Ashcombe State',
  'Millbrook University',
  'Northgate College',
  'Cedar Point University',
];

const List<String> _coachPriorStops = [
  'Rose up through the high school ranks as a position coach before breaking into the college game.',
  'Spent a decade grinding as a coordinator before landing this first head job.',
  'Cut their teeth as a graduate assistant, then built a reputation on the recruiting trail.',
  'Came up through a pro coaching tree, bringing a pro-style approach to the college level.',
  'Built a name at the FCS level before making the jump to the top division.',
  'Started as a walk-on player, stuck around as a student assistant, and never left the building.',
];

// A story background derived from the coach's own name — same coach
// always gets the same background, no separate picker needed. Used to
// give a real recruiting pipeline bonus (see generateRecruits) in the
// coach's home state.
CoachBackground coachBackgroundFor(String coachName) {
  var hash = 17;
  for (final unit in coachName.codeUnits) {
    hash = ((hash * 31) + unit) & 0x7fffffff;
  }

  final hometownState =
      _coachPipelineStates[hash % _coachPipelineStates.length];

  return CoachBackground(
    hometownState: hometownState,
    hometownRegion: regionForState(hometownState),
    almaMater: _coachAlmaMaters[(hash ~/ 7) % _coachAlmaMaters.length],
    priorStop: _coachPriorStops[(hash ~/ 13) % _coachPriorStops.length],
  );
}

// Real coaching departures are rarely just "took a better job" — there's
// almost always a messier story underneath. This is that story: picked
// deterministically per (coach, old team, new team, season) so the same
// move always gets the same reported reason.
const List<String> coachDepartureStorylines = [
  'sources cite a breakdown in trust with the administration',
  'friction over facility investment reportedly boiled over',
  'a booster-driven push for more resources went unanswered',
  'philosophical differences with the athletic director became public',
  'a locker-room culture dispute reportedly forced the issue',
  'recruiting oversight questions — never substantiated — piled up',
  'the staff felt boxed out of key roster decisions',
  'a leaked memo revealed tension over program direction',
  'a contract-extension standoff went nowhere for months',
  'the administration reportedly wanted a "different voice" after a plateau',
];

String coachDepartureStorylineFor(
  String coachName,
  String oldTeam,
  String newTeam,
  int season,
) {
  var hash = 17;
  for (final unit in '$coachName|$oldTeam|$newTeam|$season'.codeUnits) {
    hash = ((hash * 31) + unit) & 0x7fffffff;
  }
  return coachDepartureStorylines[hash % coachDepartureStorylines.length];
}

int rosterBaseForPrestige(num prestige) {
  final p = prestige100(prestige);
  if (p >= 95) return 88;
  if (p >= 90) return 84;
  if (p >= 80) return 77;
  if (p >= 70) return 69;
  if (p >= 60) return 62;
  return 54;
}

int playerOverallForTeam(
  num prestige, {
  bool starter = false,
  bool freshman = false,
}) {
  final p = prestige100(prestige);
  int minOvr;
  int maxOvr;

  if (p >= 95) {
    minOvr = starter ? 84 : 75;
    maxOvr = starter ? 94 : 88;
  } else if (p >= 90) {
    minOvr = starter ? 80 : 72;
    maxOvr = starter ? 91 : 85;
  } else if (p >= 80) {
    minOvr = starter ? 73 : 66;
    maxOvr = starter ? 85 : 78;
  } else if (p >= 70) {
    minOvr = starter ? 66 : 60;
    maxOvr = starter ? 78 : 72;
  } else if (p >= 60) {
    minOvr = starter ? 59 : 54;
    maxOvr = starter ? 70 : 66;
  } else {
    minOvr = starter ? 51 : 45;
    maxOvr = starter ? 64 : 59;
  }

  if (freshman) {
    maxOvr = maxOvr.clamp(45, 78);
    minOvr = (minOvr - 4).clamp(40, maxOvr);
  }

  return minOvr + rng.nextInt(max(1, maxOvr - minOvr + 1));
}

int teamOverallFromPrestige(num prestige) {
  final base = rosterBaseForPrestige(prestige);
  return (base + rng.nextInt(5) - 2).clamp(45, 94);
}

int realisticTeamOverall(num prestige) {
  final p = prestige100(prestige);
  if (p >= 95) return 92 + rng.nextInt(4); // 92-95
  if (p >= 90) return 87 + rng.nextInt(5); // 87-91
  if (p >= 80) return 78 + rng.nextInt(7); // 78-84
  if (p >= 70) return 68 + rng.nextInt(8); // 68-75
  if (p >= 60) return 59 + rng.nextInt(8); // 59-66
  return 50 + rng.nextInt(9); // 50-58
}

int clampTeamOverallToPrestige(num overall, num prestige) {
  final p = prestige100(prestige);
  if (p >= 95) return overall.round().clamp(88, 96);
  if (p >= 90) return overall.round().clamp(84, 92);
  if (p >= 80) return overall.round().clamp(75, 86);
  if (p >= 70) return overall.round().clamp(65, 78);
  if (p >= 60) return overall.round().clamp(56, 68);
  return overall.round().clamp(48, 60);
}

class Player {
  final String name;
  final String position;
  final int overall;
  final int potential;
  final String year;
  final int stars;
  // A player gets exactly one redshirt across their whole career (real NCAA
  // rule: one season that doesn't count against the standard 4 years of
  // eligibility). Defaulted so every pre-existing Player() call site and
  // every saved career predating this field keeps compiling/loading.
  final bool hasRedshirted;

  const Player({
    required this.name,
    required this.position,
    required this.overall,
    required this.potential,
    required this.year,
    required this.stars,
    this.hasRedshirted = false,
  });

  int get devRoom => potential - overall;
}

/// Compatibility helpers used by awards, mock drafts, roster displays,
/// and the offseason. These are derived rather than persisted, so existing
/// career saves remain compatible with this version.
extension PlayerDynastyDetails on Player {
  int get _stablePlayerSeed {
    var hash = 17;
    for (final unit in name.codeUnits) {
      hash = ((hash * 31) + unit) & 0x7fffffff;
    }
    return hash;
  }

  String get cleanName {
    final separator = name.indexOf('|');
    return separator == -1 ? name : name.substring(0, separator);
  }

  String get awardTeamName {
    final separator = name.indexOf('|');
    if (separator == -1 || separator == name.length - 1) {
      return 'Your Team';
    }
    return name.substring(separator + 1);
  }

  int get teamWins {
    final base = 5 + (_stablePlayerSeed % 8);
    final qualityBoost = overall >= 88
        ? 2
        : overall >= 78
        ? 1
        : 0;
    return (base + qualityBoost).clamp(0, 15);
  }

  int get passYards {
    if (position != 'QB') return 0;
    return 1900 + (_stablePlayerSeed % 2100) + max(0, overall - 70) * 18;
  }

  int get rushYards {
    if (position != 'HB' && position != 'RB' && position != 'QB') {
      return 0;
    }

    final base = position == 'QB' ? 180 : 650;
    final range = position == 'QB' ? 620 : 1150;
    return base + (_stablePlayerSeed % range) + max(0, overall - 65) * 8;
  }

  int get recYards {
    if (position != 'WR' && position != 'TE' && position != 'HB') {
      return 0;
    }

    final base = position == 'HB' ? 120 : 500;
    final range = position == 'HB' ? 480 : 1250;
    return base + (_stablePlayerSeed % range) + max(0, overall - 65) * 7;
  }

  int get touchdowns {
    final production = switch (position) {
      'QB' => passYards ~/ 420,
      'HB' || 'RB' => rushYards ~/ 180,
      'WR' || 'TE' => recYards ~/ 190,
      _ => 1 + (_stablePlayerSeed % 4),
    };
    return production.clamp(1, 45);
  }

  int get sacks {
    if (position != 'DE' && position != 'DL' && position != 'LB') {
      return 0;
    }
    return 2 + (_stablePlayerSeed % 12) + max(0, overall - 75) ~/ 4;
  }

  int get interceptions {
    if (position != 'DB' &&
        position != 'CB' &&
        position != 'S' &&
        position != 'LB') {
      return 0;
    }
    return _stablePlayerSeed % 7;
  }

  double get ppg {
    final scoring = switch (position) {
      'QB' => touchdowns * 1.45,
      'HB' || 'RB' => touchdowns * 1.25,
      'WR' || 'TE' => touchdowns * 1.15,
      _ => (sacks * .35) + (interceptions * .75),
    };
    return double.parse(scoring.toStringAsFixed(1));
  }
}

int awardOverall(Player player) {
  final classAdjustment = switch (player.year) {
    'SR' => 2,
    'JR' => 1,
    'FR' => -1,
    _ => 0,
  };

  return (player.overall + classAdjustment).clamp(40, 99);
}

/// One player's real, attributed stat line from a single simulated game.
/// Immutable and additive — season totals are always the sum of every game
/// line a player has actually recorded, never a separately generated number.
class GamePlayerLine {
  final int passYards;
  final int passTDs;
  final int rushYards;
  final int rushTDs;
  final int recYards;
  final int recTDs;
  final int tackles;
  final int sacks;
  final int interceptions;

  const GamePlayerLine({
    this.passYards = 0,
    this.passTDs = 0,
    this.rushYards = 0,
    this.rushTDs = 0,
    this.recYards = 0,
    this.recTDs = 0,
    this.tackles = 0,
    this.sacks = 0,
    this.interceptions = 0,
  });

  static const zero = GamePlayerLine();

  GamePlayerLine operator +(GamePlayerLine other) => GamePlayerLine(
    passYards: passYards + other.passYards,
    passTDs: passTDs + other.passTDs,
    rushYards: rushYards + other.rushYards,
    rushTDs: rushTDs + other.rushTDs,
    recYards: recYards + other.recYards,
    recTDs: recTDs + other.recTDs,
    tackles: tackles + other.tackles,
    sacks: sacks + other.sacks,
    interceptions: interceptions + other.interceptions,
  );

  int get totalTDs => passTDs + rushTDs + recTDs;
  int get totalYards => passYards + rushYards + recYards;

  Map<String, dynamic> toJson() => {
    'passYards': passYards,
    'passTDs': passTDs,
    'rushYards': rushYards,
    'rushTDs': rushTDs,
    'recYards': recYards,
    'recTDs': recTDs,
    'tackles': tackles,
    'sacks': sacks,
    'interceptions': interceptions,
  };

  factory GamePlayerLine.fromJson(Map<String, dynamic> json) => GamePlayerLine(
    passYards: (json['passYards'] as num?)?.toInt() ?? 0,
    passTDs: (json['passTDs'] as num?)?.toInt() ?? 0,
    rushYards: (json['rushYards'] as num?)?.toInt() ?? 0,
    rushTDs: (json['rushTDs'] as num?)?.toInt() ?? 0,
    recYards: (json['recYards'] as num?)?.toInt() ?? 0,
    recTDs: (json['recTDs'] as num?)?.toInt() ?? 0,
    tackles: (json['tackles'] as num?)?.toInt() ?? 0,
    sacks: (json['sacks'] as num?)?.toInt() ?? 0,
    interceptions: (json['interceptions'] as num?)?.toInt() ?? 0,
  );
}

/// A finished regular-season game's result, keyed by its schedule week
/// index so the Schedule screen can show a real score (and box score)
/// for any past week instead of a bare "FINAL" label.
class GameResultRecord {
  final String opponentName;
  final int userScore;
  final int opponentScore;
  final bool won;
  final String? playerOfGameName;
  final String? playerOfGameLine;
  final Map<String, GamePlayerLine> boxScore;

  const GameResultRecord({
    required this.opponentName,
    required this.userScore,
    required this.opponentScore,
    required this.won,
    this.playerOfGameName,
    this.playerOfGameLine,
    this.boxScore = const {},
  });

  Map<String, dynamic> toJson() => {
    'opponentName': opponentName,
    'userScore': userScore,
    'opponentScore': opponentScore,
    'won': won,
    'playerOfGameName': playerOfGameName,
    'playerOfGameLine': playerOfGameLine,
    'boxScore': boxScore.map((name, line) => MapEntry(name, line.toJson())),
  };

  factory GameResultRecord.fromJson(Map<String, dynamic> json) =>
      GameResultRecord(
        opponentName: '${json['opponentName'] ?? ''}',
        userScore: (json['userScore'] as num?)?.toInt() ?? 0,
        opponentScore: (json['opponentScore'] as num?)?.toInt() ?? 0,
        won: json['won'] == true,
        playerOfGameName: json['playerOfGameName'] as String?,
        playerOfGameLine: json['playerOfGameLine'] as String?,
        boxScore: (json['boxScore'] is Map)
            ? Map<String, dynamic>.from(
                json['boxScore'] as Map,
              ).map(
                (name, line) => MapEntry(
                  name,
                  GamePlayerLine.fromJson(Map<String, dynamic>.from(line)),
                ),
              )
            : const {},
      );
}

/// One player's current injury — real enough to actually sideline them
/// (see _playersAt's injury filter), not just a cosmetic status label.
class Injury {
  final String playerName;
  final String description;
  final int weeksRemaining;
  final int weekOccurred;

  const Injury({
    required this.playerName,
    required this.description,
    required this.weeksRemaining,
    required this.weekOccurred,
  });

  Injury copyWith({int? weeksRemaining}) => Injury(
    playerName: playerName,
    description: description,
    weeksRemaining: weeksRemaining ?? this.weeksRemaining,
    weekOccurred: weekOccurred,
  );

  Map<String, dynamic> toJson() => {
    'playerName': playerName,
    'description': description,
    'weeksRemaining': weeksRemaining,
    'weekOccurred': weekOccurred,
  };

  factory Injury.fromJson(Map<String, dynamic> json) => Injury(
    playerName: '${json['playerName'] ?? ''}',
    description: '${json['description'] ?? 'Injury'}',
    weeksRemaining: (json['weeksRemaining'] as num?)?.toInt() ?? 0,
    weekOccurred: (json['weekOccurred'] as num?)?.toInt() ?? 0,
  );
}

const List<({String description, int minWeeks, int maxWeeks})> injuryTypes = [
  (description: 'Ankle Sprain', minWeeks: 1, maxWeeks: 1),
  (description: 'Hamstring Strain', minWeeks: 1, maxWeeks: 2),
  (description: 'Shoulder Injury', minWeeks: 2, maxWeeks: 3),
  (description: 'Concussion Protocol', minWeeks: 1, maxWeeks: 1),
  (description: 'Knee Injury', minWeeks: 3, maxWeeks: 5),
  (description: 'Torn ACL', minWeeks: 8, maxWeeks: 8),
];

/// Rolls one new injury for a player who just went down. rng is passed in
/// (rather than a global) so this stays independently unit-testable.
Injury rollInjuryFor(String playerName, int currentWeek, Random rng) {
  final type = injuryTypes[rng.nextInt(injuryTypes.length)];
  final weeks =
      type.minWeeks + rng.nextInt(type.maxWeeks - type.minWeeks + 1);
  return Injury(
    playerName: playerName,
    description: type.description,
    weeksRemaining: weeks,
    weekOccurred: currentWeek,
  );
}

/// A rivalry's real head-to-head history — a traveling trophy, not just a
/// flavor label. Persists across the whole career, keyed by the rival
/// program's name, so switching rivals doesn't erase an old series.
class RivalrySeriesRecord {
  final int userWins;
  final int rivalWins;
  // Whoever won the most recent meeting — the user's own team name, or
  // the rival's.
  final String trophyHolder;

  const RivalrySeriesRecord({
    required this.userWins,
    required this.rivalWins,
    required this.trophyHolder,
  });

  Map<String, dynamic> toJson() => {
    'userWins': userWins,
    'rivalWins': rivalWins,
    'trophyHolder': trophyHolder,
  };

  factory RivalrySeriesRecord.fromJson(Map<String, dynamic> json) =>
      RivalrySeriesRecord(
        userWins: (json['userWins'] as num?)?.toInt() ?? 0,
        rivalWins: (json['rivalWins'] as num?)?.toInt() ?? 0,
        trophyHolder: '${json['trophyHolder'] ?? ''}',
      );
}

/// The program's all-time best single season in one stat category — a
/// real record book, not just a season leaderboard. Persists across the
/// whole career.
class SeasonStatRecord {
  final int value;
  final String playerName;
  final int season;

  const SeasonStatRecord({
    required this.value,
    required this.playerName,
    required this.season,
  });

  Map<String, dynamic> toJson() => {
    'value': value,
    'playerName': playerName,
    'season': season,
  };

  factory SeasonStatRecord.fromJson(Map<String, dynamic> json) =>
      SeasonStatRecord(
        value: (json['value'] as num?)?.toInt() ?? 0,
        playerName: '${json['playerName'] ?? ''}',
        season: (json['season'] as num?)?.toInt() ?? 1,
      );
}

/// Every stat category the program record book tracks, with a real
/// display label — one entry per GamePlayerLine numeric field.
const Map<String, String> seasonRecordCategoryLabels = {
  'passYards': 'Passing Yards',
  'passTDs': 'Passing Touchdowns',
  'rushYards': 'Rushing Yards',
  'rushTDs': 'Rushing Touchdowns',
  'recYards': 'Receiving Yards',
  'recTDs': 'Receiving Touchdowns',
  'tackles': 'Tackles',
  'sacks': 'Sacks',
  'interceptions': 'Interceptions',
};

int seasonStatValueFor(GamePlayerLine line, String category) => switch (category) {
  'passYards' => line.passYards,
  'passTDs' => line.passTDs,
  'rushYards' => line.rushYards,
  'rushTDs' => line.rushTDs,
  'recYards' => line.recYards,
  'recTDs' => line.recTDs,
  'tackles' => line.tackles,
  'sacks' => line.sacks,
  'interceptions' => line.interceptions,
  _ => 0,
};

/// Several real phrasings for the same event, picked by rng — a headline
/// that reads identically every single game (just swapping a word or two)
/// stops feeling like real coverage. Templates take the raw pieces
/// (coach name, tone, result) and each phrase them differently.
String pressRoomHeadline({
  required String coachName,
  required String toneLower,
  required bool won,
  required Random rng,
}) {
  final resultWord = won ? 'win' : 'loss';
  final templates = <String>[
    'PRESS ROOM: Coach $coachName chose a $toneLower message after the $resultWord.',
    '$coachName faced the media with a $toneLower tone following the $resultWord.',
    'POSTGAME: $coachName struck a $toneLower note in the press conference after the $resultWord.',
    "Reporters described $coachName's presser as $toneLower in the wake of the $resultWord.",
    '$coachName kept things $toneLower addressing the locker room and press after the $resultWord.',
    'NOTEBOOK: the tone out of the $coachName presser was $toneLower after the $resultWord.',
  ];
  return templates[rng.nextInt(templates.length)];
}

String byeWeekHeadline({
  required String teamName,
  required String label,
  required Random rng,
}) {
  final templates = <String>[
    '$label: $teamName rests up and preps for what\'s next.',
    '$label: $teamName uses the off week to get healthy and refine the game plan.',
    '$label: with no game this week, $teamName turns its focus to practice and film study.',
    '$label: $teamName gets a breather before the next matchup.',
    '$label: the coaching staff spends the week on self-scouting and depth chart tweaks.',
  ];
  return templates[rng.nextInt(templates.length)];
}

String gameRecapHeadline({
  required String teamName,
  required String opponentName,
  required Random rng,
}) {
  final templates = <String>[
    'Last game: $teamName vs $opponentName recap is now on the feed.',
    'Full coverage of $teamName vs $opponentName is up on the wire.',
    'The tape from $teamName vs $opponentName is in — beat writers have their takes posted.',
    '$teamName vs $opponentName is already being broken down by the national media.',
  ];
  return templates[rng.nextInt(templates.length)];
}

/// Total offensive yards for a completed game, from the box score events
/// that actually happened — the one formula every stats surface (the live
/// postgame panel and the season accumulator) reads from, so they can never
/// disagree about a game that's already over.
int gameTotalYardsFor({
  required int score,
  required int bigPlays,
  required int turnovers,
}) {
  return max(80, 185 + score * 4 + bigPlays * 18 - turnovers * 12);
}

/// Greedy touchdown/field-goal breakdown of a final score — used only when
/// the real per-drive event counts aren't available (a quick-simmed game
/// has no live drives to count), so the box score still adds up to the
/// score the user actually saw.
({int tds, int fgs}) decomposeScoreIntoScoring(int score) {
  var remaining = max(0, score);
  final tds = remaining ~/ 7;
  remaining -= tds * 7;
  final fgs = remaining ~/ 3;
  return (tds: tds, fgs: fgs);
}

/// Splits an integer total across `parts` slots with some random variance,
/// while guaranteeing the slots sum to exactly `total` — no yard or
/// touchdown is ever silently gained or lost in the split.
List<int> splitIntegerWithVariance(int total, int parts, Random rng) {
  if (parts <= 0) return const [];
  if (total <= 0) return List.filled(parts, 0);

  final weights = List.generate(parts, (_) => 0.4 + rng.nextDouble());
  final weightSum = weights.reduce((a, b) => a + b);
  final result = weights.map((w) => (total * w / weightSum).floor()).toList();

  var used = result.fold<int>(0, (a, b) => a + b);
  var i = 0;
  while (used < total) {
    result[i % parts]++;
    used++;
    i++;
  }
  return result;
}

/// Attributes a game's real team-level events (touchdowns, field goals,
/// total yards, turnovers forced) to the actual players on the roster who
/// would have produced them — the starting QB throws the passing
/// touchdowns, the starting back carries the rushing production, the
/// starting receivers/tight end split the receiving yards, and the
/// defensive starters pick up tackles/sacks/interceptions. Every yard and
/// touchdown handed to the offense is conserved exactly (via
/// [splitIntegerWithVariance]), so summing every player's line reproduces
/// the team's real totals for the game.
Map<String, GamePlayerLine> attributeGameStatsToRoster({
  required List<Player> starters,
  required int teamTDs,
  required int teamFGs,
  required int teamTotalYards,
  required int turnoversForced,
  required Random rng,
}) {
  final lines = <String, GamePlayerLine>{};
  void add(Player p, GamePlayerLine line) {
    lines[p.name] = (lines[p.name] ?? GamePlayerLine.zero) + line;
  }

  Player? bestAt(List<String> positions) {
    final matches =
        starters.where((p) => positions.contains(p.position)).toList()
          ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
    return matches.isEmpty ? null : matches.first;
  }

  final qb = bestAt(const ['QB']);
  final hb = bestAt(const ['HB', 'RB']);
  final receivers = <Player>[
    ...starters.where((p) => p.position == 'WR'),
    ...starters.where((p) => p.position == 'TE'),
  ]..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));

  final passRatio = teamTDs <= 0 ? 0.0 : 0.55 + rng.nextDouble() * 0.2;
  final passTDs = (teamTDs * passRatio).round().clamp(0, teamTDs);
  final rushTDs = teamTDs - passTDs;

  final rushYardShare = 0.30 + rng.nextDouble() * 0.16;
  final rushYards = qb == null && hb == null
      ? 0
      : (teamTotalYards * rushYardShare).round().clamp(0, teamTotalYards);
  final passYards = teamTotalYards - rushYards;

  if (qb != null && (passYards > 0 || passTDs > 0)) {
    add(qb, GamePlayerLine(passYards: passYards, passTDs: passTDs));
  }
  if (hb != null && (rushYards > 0 || rushTDs > 0)) {
    add(hb, GamePlayerLine(rushYards: rushYards, rushTDs: rushTDs));
  } else if (qb != null && (rushYards > 0 || rushTDs > 0)) {
    // No dedicated back on the depth chart — the QB's legs picked up the
    // rushing production instead of it vanishing.
    add(qb, GamePlayerLine(rushYards: rushYards, rushTDs: rushTDs));
  }

  if (receivers.isNotEmpty && passYards > 0) {
    final yardShares = splitIntegerWithVariance(
      passYards,
      receivers.length,
      rng,
    );
    final tdShares = splitIntegerWithVariance(passTDs, receivers.length, rng);
    for (var i = 0; i < receivers.length; i++) {
      add(
        receivers[i],
        GamePlayerLine(recYards: yardShares[i], recTDs: tdShares[i]),
      );
    }
  }

  final defenders = starters
      .where(
        (p) => const [
          'DE',
          'DL',
          'DT',
          'LB',
          'DB',
          'CB',
          'S',
        ].contains(p.position),
      )
      .toList();
  for (final d in defenders) {
    add(d, GamePlayerLine(tackles: 3 + rng.nextInt(6)));
  }
  if (defenders.isNotEmpty) {
    final sackCount = rng.nextInt(4);
    for (var i = 0; i < sackCount; i++) {
      add(
        defenders[rng.nextInt(defenders.length)],
        const GamePlayerLine(sacks: 1),
      );
    }

    final dbs = defenders
        .where((p) => const ['DB', 'CB', 'S'].contains(p.position))
        .toList();
    final intPool = dbs.isNotEmpty ? dbs : defenders;
    for (var i = 0; i < turnoversForced.clamp(0, 4); i++) {
      add(
        intPool[rng.nextInt(intPool.length)],
        const GamePlayerLine(interceptions: 1),
      );
    }
  }

  return lines;
}

// Picks 2 bye weeks for a totalWeeks-long season, kept away from the very
// first and last week (nobody byes in week 1, and the last week always
// leads into conference championship week) and at least 3 weeks apart from
// each other, so a team is never on bye in back-to-back weeks.
Set<int> generateByeWeeks(Random rng, {int totalWeeks = 14}) {
  final byeWeeks = <int>{};
  while (byeWeeks.length < 2) {
    final candidate = 1 + rng.nextInt(totalWeeks - 2);
    if (byeWeeks.any((w) => (w - candidate).abs() < 3)) continue;
    byeWeeks.add(candidate);
  }
  return byeWeeks;
}

/// Whether a coach-picked bye-week placement is legal: exactly two weeks,
/// both real week-index slots (never the season opener or the week
/// leading into conference championship week), and never back-to-back.
bool isValidByeWeekPlacement(List<int> weeks, {int totalWeeks = 14}) {
  if (weeks.length != 2) return false;
  final distinct = weeks.toSet();
  if (distinct.length != 2) return false;
  for (final w in distinct) {
    if (w < 1 || w > totalWeeks - 2) return false;
  }
  final sorted = distinct.toList()..sort();
  return (sorted[1] - sorted[0]) >= 2;
}

class Recruit {
  final String name;
  final String position;
  final String state;
  final int stars;
  final int trueOverall;
  final int truePotential;
  // Not final: a "Boost Morale" recruiting action can raise it after
  // generation (see _boostRecruitMorale), same mutability as scouts/offered.
  int interest;
  int scouts;
  bool offered;
  String? committedSchool;
  int? decisionWindow;
  bool commitmentPopupShown = false;
  // The game week (gamesPlayed) this recruit was first scouted or offered.
  // Visits can only be scheduled a week after that first contact.
  int? firstContactGame;
  int visits = 0;
  // Dollars actually pledged toward this recruit's NIL ask. Stays 0 for
  // 1-2 star recruits, who don't negotiate NIL at all.
  int nilOffered = 0;

  Recruit({
    required this.name,
    required this.position,
    required this.state,
    required this.stars,
    required this.trueOverall,
    required this.truePotential,
    required this.interest,
    this.scouts = 0,
    this.offered = false,
    this.committedSchool,
    this.decisionWindow,
    this.commitmentPopupShown = false,
    this.firstContactGame,
    this.visits = 0,
    this.nilOffered = 0,
  });

  String get scoutText {
    if (scouts == 0) return 'OVR ??? • POT ???';
    if (scouts == 1) {
      return 'OVR ${trueOverall - 10}-${trueOverall + 10} • POT ${truePotential - 10}-${truePotential + 8}';
    }
    if (scouts == 2) {
      return 'OVR ${trueOverall - 4}-${trueOverall + 4} • POT ${truePotential - 5}-${truePotential + 4}';
    }
    return 'OVR $trueOverall • POT $truePotential';
  }

  String get tag {
    if (scouts < 3) return '';

    final expected = switch (stars) {
      5 => 88,
      4 => 78,
      3 => 68,
      2 => 58,
      _ => 48,
    };

    if (trueOverall >= expected + 7 || truePotential >= trueOverall + 16) {
      return 'GEM';
    }

    if (trueOverall <= expected - 5 || truePotential <= trueOverall + 3) {
      return 'BUST';
    }

    return 'NORMAL';
  }

  int get expectedOverall {
    return switch (stars) {
      1 => 50,
      2 => 60,
      3 => 70,
      4 => 80,
      _ => 88,
    };
  }

  int get hiddenDelta {
    final raw = name.hashCode.abs() % 100;
    if (raw < 9) return 9 + (raw % 9);
    if (raw < 21) return -5 - (raw % 8);
    return (raw % 9) - 4;
  }

  int get displayedOverall =>
      cappedFreshmanOverall(expectedOverall + hiddenDelta);

  int get estimatedOverall {
    final miss = ((name.hashCode ~/ 11).abs() % 13) - 6;
    final adjusted = miss == 0 ? 4 : miss;
    return cappedFreshmanOverall(expectedOverall + adjusted);
  }

  int get fakeCardOverall {
    final miss = ((name.hashCode ~/ 17).abs() % 17) - 8;
    final adjusted = miss == 0 ? 6 : miss;
    return cappedFreshmanOverall(expectedOverall + adjusted);
  }

  bool get isGem => hiddenDelta >= 9;
  bool get isBust => hiddenDelta <= -5;
  String get gemLabel => isGem
      ? 'GEM'
      : isBust
      ? 'BUST'
      : '';

  String get cardOverallText {
    if (scouts <= 0) return '$fakeCardOverall?';
    if (scouts == 1) return '~$estimatedOverall';
    if (scouts == 2)
      return '${(displayedOverall - 5).clamp(40, 94)}-${(displayedOverall + 5).clamp(40, 94)}';
    return '$displayedOverall';
  }

  String get potentialText {
    if (scouts <= 0) return 'POT ?';
    if (scouts == 1) return 'POT ~';
    if (scouts == 2)
      return 'POT ${(truePotential - 6).clamp(40, 94)}-${(truePotential + 4).clamp(40, 94)}';
    return 'POT $truePotential';
  }

  String get scoutingReport {
    if (scouts <= 0)
      return '${stars}★ recruit • Initial grade: $fakeCardOverall?';
    if (scouts == 1) return 'Estimate: ~$estimatedOverall OVR';
    if (scouts == 2)
      return 'Range: ${(displayedOverall - 5).clamp(40, 94)}-${(displayedOverall + 5).clamp(40, 94)} OVR • $potentialText';
    return 'Exact: $displayedOverall OVR • $truePotential POT';
  }

  // 1- and 2-star recruits don't negotiate NIL at all — they're chasing
  // playing time and development, not a payday. 3-5 star recruits have a
  // real (deterministic, per-recruit) ask.
  int get nilAsk {
    if (stars < 3) return 0;
    final base = switch (stars) {
      5 => 220000,
      4 => 90000,
      _ => 30000,
    };
    final spread = base ~/ 2;
    final variance = (name.hashCode.abs() % spread) - (spread ~/ 2);
    return (base + variance).clamp(10000, 500000);
  }

  bool get wantsNil => nilAsk > 0;
}

extension RecruitFootballDetails on Recruit {
  int get detailSeed => name.hashCode.abs();

  String get heightText {
    final base = switch (position) {
      'QB' => 74,
      'HB' => 70,
      'WR' => 73,
      'TE' => 76,
      'DE' => 76,
      'LB' => 74,
      'DB' => 71,
      _ => 73,
    };
    final inches = base + (detailSeed % 5) - 2;
    return "${inches ~/ 12}'${inches % 12}\"";
  }

  int get weight {
    final base = switch (position) {
      'QB' => 215,
      'HB' => 205,
      'WR' => 195,
      'TE' => 245,
      'DE' => 255,
      'LB' => 230,
      'DB' => 190,
      _ => 210,
    };
    return base + (detailSeed % 31) - 15;
  }

  double get forty {
    final base = switch (position) {
      'HB' => 4.48,
      'WR' => 4.46,
      'DB' => 4.50,
      'QB' => 4.78,
      'LB' => 4.68,
      'TE' => 4.72,
      'DE' => 4.76,
      _ => 4.70,
    };
    return double.parse(
      (base + ((detailSeed % 21) - 10) / 100).toStringAsFixed(2),
    );
  }

  int get bench => 225 + (detailSeed % 15);
  int get squat => 405 + (detailSeed % 26) * 5;
  int get vertical => 28 + (detailSeed % 13);

  int get passYards => position == 'QB' ? 1800 + (detailSeed % 2200) : 0;
  int get rushYards =>
      position == 'HB' || position == 'QB' ? 500 + (detailSeed % 1700) : 0;
  int get recYards =>
      position == 'WR' || position == 'TE' ? 450 + (detailSeed % 1600) : 0;
  int get tackles => position == 'DE' || position == 'LB' || position == 'DB'
      ? 35 + (detailSeed % 75)
      : 0;
  int get sacks =>
      position == 'DE' || position == 'LB' ? 3 + (detailSeed % 15) : 0;
  int get interceptions =>
      position == 'DB' || position == 'LB' ? detailSeed % 7 : 0;

  String get archetype {
    return switch (position) {
      'QB' => detailSeed % 2 == 0 ? 'Pocket Passer' : 'Dual Threat',
      'HB' => detailSeed % 2 == 0 ? 'Power Back' : 'Speed Back',
      'WR' => detailSeed % 2 == 0 ? 'Deep Threat' : 'Route Runner',
      'TE' => detailSeed % 2 == 0 ? 'Receiving TE' : 'Blocking TE',
      'DE' => detailSeed % 2 == 0 ? 'Edge Rusher' : 'Run Stopper',
      'LB' => detailSeed % 2 == 0 ? 'Field General' : 'Blitzer',
      'DB' => detailSeed % 2 == 0 ? 'Lockdown Corner' : 'Ball Hawk',
      _ => 'Athlete',
    };
  }

  int get starOverallFloor {
    return switch (stars) {
      1 => 45,
      2 => 56,
      3 => 66,
      4 => 76,
      _ => 86,
    };
  }

  int get nextStarOverallFloor {
    return switch (stars) {
      1 => 56,
      2 => 66,
      3 => 76,
      4 => 86,
      _ => 100,
    };
  }

  String get shortFit {
    if (committedSchool != null) return committedSchool!;
    if (stars >= 5) return 'Prestige';
    if (truePotential >= trueOverall + 16) return 'Development';
    if (interest >= 75) return 'Strong Fit';
    return 'Open';
  }

  String get personality {
    if (stars >= 5) return 'Wants Prestige + Playing Time';
    if (truePotential >= trueOverall + 16) return 'Wants Development';
    if (interest >= 75) return 'Program Fit';
    return 'Wants Early Offers';
  }
}

