// Every team regardless of subdivision — used wherever code needs the
// full league (team lookup, league-wide rival-coach seeding) rather than
// one subdivision's pool. g5Teams itself keeps meaning "the FBS pool"
// everywhere else in the file (schedule generation, FBS rankings/CFP,
// FBS standings all stay scoped to it unchanged).
List<CollegeTeam> get allTeams => [...g5Teams, ...fcsTeams];

// The "ideal" full 22-player roster shape — same distribution
// generateRoster() below uses to build the user's own starting team.
// Reused when backfilling roster gaps (e.g. walk-ons) so the fill targets
// whatever position is actually running short, not just whichever
// position happens to win a random batch's top-overall roll.
const Map<String, int> idealRosterPositionCounts = {
  'QB': 2,
  'HB': 3,
  'WR': 5,
  'TE': 2,
  'DE': 3,
  'LB': 4,
  'DB': 3,
};

// A single low-cost walk-on at a specific position — used to backfill
// open roster spots without the waste of generating (and discarding) a
// full 22-player roster just to keep one player from it.
Player generateWalkOn(num prestige, String position) {
  final tier = prestigeTier(prestige);
  final minOverall = switch (tier) {
    1 => 45,
    2 => 50,
    3 => 55,
    4 => 60,
    _ => 65,
  };
  final maxOverall = switch (tier) {
    1 => 58,
    2 => 63,
    3 => 68,
    4 => 73,
    _ => 78,
  };
  const years = ['FR', 'SO', 'JR', 'SR'];

  final overall = minOverall + rng.nextInt(maxOverall - minOverall + 1);
  final potential = (overall + rng.nextInt(10)).clamp(overall, 90);

  return Player(
    name: NameGenerator.generate(),
    position: position,
    overall: overall,
    potential: potential,
    year: years[rng.nextInt(years.length)],
    stars: 1,
  );
}

List<Player> generateRoster(int prestige, {Subdivision subdivision = Subdivision.fbs}) {
  final tier = prestigeTier(prestige);
  final positionCounts = <String, int>{
    'QB': 2,
    'HB': 3,
    'WR': 5,
    'TE': 2,
    'DE': 3,
    'LB': 4,
    'DB': 3,
  };

  final years = ['FR', 'SO', 'JR', 'SR'];
  final roster = <Player>[];

  final minOverall = switch (tier) {
    1 => 48,
    2 => 56,
    3 => 64,
    4 => 74,
    _ => 84,
  };

  final maxOverall = switch (tier) {
    1 => 60,
    2 => 68,
    3 => 78,
    4 => 88,
    _ => 94,
  };

  final minDev = switch (tier) {
    1 => 2,
    2 => 3,
    3 => 4,
    4 => 5,
    _ => 6,
  };

  final maxDev = switch (tier) {
    1 => 8,
    2 => 11,
    3 => 14,
    4 => 17,
    _ => 20,
  };

  for (final entry in positionCounts.entries) {
    for (int i = 0; i < entry.value; i++) {
      final rawOverall = minOverall + rng.nextInt(maxOverall - minOverall + 1);
      final dev = minDev + rng.nextInt(maxDev - minDev + 1);
      final rawPotential = (rawOverall + dev).clamp(rawOverall, 99);
      // Even tier 3 (FCS's own max tier) allows potential up to 92 — the
      // same training-over-a-career loophole fcsMaxPlayerOverall closes
      // for recruits and transfers.
      final overall = subdivision == Subdivision.fcs
          ? min(rawOverall, fcsMaxPlayerOverall)
          : rawOverall;
      final potential = subdivision == Subdivision.fcs
          ? min(rawPotential, fcsMaxPlayerOverall)
          : rawPotential;

      final stars = switch (overall) {
        >= 88 => 5,
        >= 78 => 4,
        >= 68 => 3,
        >= 58 => 2,
        _ => 1,
      };

      roster.add(
        Player(
          name: NameGenerator.generate(),
          position: entry.key,
          overall: overall,
          potential: potential,
          year: years[rng.nextInt(years.length)],
          stars: stars,
        ),
      );
    }
  }

  roster.sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
  return roster;
}

int _nationalRosterSeed(String school, int season, int salt) {
  var hash = 17;
  for (final unit in school.codeUnits) {
    hash = ((hash * 31) + unit) & 0x7fffffff;
  }
  return season * 1000003 + hash * 97 + salt;
}

/// A deterministic, season-stable roster for any school that isn't the
/// user's own team. The same (team, season) pair always produces the same
/// players, so every screen that names one of this school's players —
/// award ballots, a live Player of the Game, pregame team leaders — draws
/// from the same real, checkable roster instead of each inventing its own
/// disposable name. Mirrors generateRoster()'s position spread and
/// prestige-to-overall curve so opponent talent is calibrated the same way
/// the user's own roster is.
List<Player> nationalRosterFor(CollegeTeam team, int season) {
  final tier = prestigeTier(team.prestige);
  const positionCounts = <String, int>{
    'QB': 2,
    'HB': 3,
    'WR': 5,
    'TE': 2,
    'DE': 3,
    'LB': 4,
    'DB': 3,
  };
  const years = ['FR', 'SO', 'JR', 'SR'];

  final minOverall = switch (tier) {
    1 => 48,
    2 => 56,
    3 => 64,
    4 => 74,
    _ => 84,
  };
  final maxOverall = switch (tier) {
    1 => 60,
    2 => 68,
    3 => 78,
    4 => 88,
    _ => 94,
  };
  final minDev = switch (tier) {
    1 => 2,
    2 => 3,
    3 => 4,
    4 => 5,
    _ => 6,
  };
  final maxDev = switch (tier) {
    1 => 8,
    2 => 11,
    3 => 14,
    4 => 17,
    _ => 20,
  };

  final roster = <Player>[];
  var index = 0;

  for (final entry in positionCounts.entries) {
    for (int i = 0; i < entry.value; i++) {
      final local = Random(_nationalRosterSeed(team.name, season, index));
      final rawOverall = minOverall + local.nextInt(maxOverall - minOverall + 1);
      final dev = minDev + local.nextInt(maxDev - minDev + 1);
      final rawPotential = (rawOverall + dev).clamp(rawOverall, 99);
      final overall = team.isFcs ? min(rawOverall, fcsMaxPlayerOverall) : rawOverall;
      final potential = team.isFcs
          ? min(rawPotential, fcsMaxPlayerOverall)
          : rawPotential;

      final stars = switch (overall) {
        >= 88 => 5,
        >= 78 => 4,
        >= 68 => 3,
        >= 58 => 2,
        _ => 1,
      };

      final first = NameGenerator
          .firstNames[local.nextInt(NameGenerator.firstNames.length)];
      final last = NameGenerator
          .lastNames[local.nextInt(NameGenerator.lastNames.length)];

      roster.add(
        Player(
          name: '$first $last|${team.name}',
          position: entry.key,
          overall: overall,
          potential: potential,
          year: years[local.nextInt(years.length)],
          stars: stars,
        ),
      );

      index++;
    }
  }

  roster.sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
  return roster;
}

/// The best available QB on [team]'s deterministic national roster —
/// used anywhere a specific opposing school needs a real starting QB
/// identity (Player of the Game, team leaders) rather than a random name.
Player nationalStartingQbFor(CollegeTeam team, int season) {
  final roster = nationalRosterFor(team, season);
  return roster.firstWhere(
    (p) => p.position == 'QB',
    orElse: () => roster.isNotEmpty
        ? roster.first
        : Player(
            name: 'Unknown Player|${team.name}',
            position: 'QB',
            overall: 60,
            potential: 70,
            year: 'FR',
            stars: 1,
          ),
  );
}

int recruitClassPoints(Recruit r) {
  final base = switch (r.stars) {
    5 => 100,
    4 => 88,
    3 => 78,
    2 => 68,
    _ => 60,
  };
  return (base + (r.displayedOverall - r.expectedOverall)).clamp(40, 110);
}

// Quality (average recruit value) is the dominant factor, with a modest
// bonus for filling out more of the class at that same quality level. A
// raw, uncapped sum would let a big class of ordinary recruits outrank a
// small class stacked with blue-chips just for having more bodies — a
// team that lands seven 5-stars should never rank behind one that signs
// twenty-five 2-stars.
int recruitingClassScoreFor(List<Recruit> committedClass) {
  if (committedClass.isEmpty) return 0;
  final totalPoints = committedClass
      .map(recruitClassPoints)
      .reduce((a, b) => a + b);
  final avgPoints = totalPoints / committedClass.length;
  final volumeBonus = committedClass.length * 15;
  return (avgPoints * 100).round() + volumeBonus;
}

// A deterministic, season-stable "what this school's class would have
// scored" for every other program — same principle as nationalRosterFor:
// the same (team, season) always gives the same number, used purely to
// rank the user's real class against the field without simulating every
// other school's actual board.
int nationalRecruitingClassScore(CollegeTeam team, int season) {
  final tier = prestigeTier(team.prestige);
  final classSize = switch (tier) {
    1 => 17,
    2 => 19,
    3 => 21,
    4 => 23,
    _ => 25,
  };
  final avgPoints = switch (tier) {
    1 => 58,
    2 => 66,
    3 => 76,
    4 => 86,
    _ => 95,
  };

  var total = 0;
  for (var i = 0; i < classSize; i++) {
    final local = Random(_nationalRosterSeed(team.name, season, 500000 + i));
    final variance = local.nextInt(15) - 7;
    total += (avgPoints + variance).clamp(40, 110);
  }

  // Same quality-first formula as recruitingClassScoreFor, so the user's
  // real class and every simulated national class are compared like-for-like.
  final actualAvgPoints = total / classSize;
  final volumeBonus = classSize * 15;
  return (actualAvgPoints * 100).round() + volumeBonus;
}

// 1 = best class in the country.
int recruitingClassNationalRank({
  required int userScore,
  required CollegeTeam userTeam,
  required int season,
}) {
  var betterCount = 0;
  for (final team in (userTeam.isFcs ? fcsTeams : g5Teams)) {
    if (team.name == userTeam.name) continue;
    if (nationalRecruitingClassScore(team, season) > userScore) {
      betterCount++;
    }
  }
  return betterCount + 1;
}

String recruitingClassRankLabel(int rank, int totalTeams) {
  if (rank <= 5) return 'TOP 5 CLASS';
  if (rank <= 10) return 'TOP 10 CLASS';
  if (rank <= 25) return 'TOP 25 CLASS';
  if (rank <= 50) return 'TOP 50 CLASS';
  if (rank <= totalTeams * 3 ~/ 4) return 'MID-MAJOR CLASS';
  return 'REBUILDING CLASS';
}

// The star band a program's board is allowed to show, by prestige tier —
// the same bands _recruitingAccessText() describes to the user, now
// actually enforced on the board itself rather than just stated.
({int min, int max}) recruitStarBandForPrestigeTier(int tier) {
  return switch (tier) {
    1 => (min: 1, max: 2),
    2 => (min: 1, max: 3),
    3 => (min: 2, max: 4),
    4 => (min: 3, max: 5),
    _ => (min: 3, max: 5),
  };
}

int weightedRecruitStars(Random rng, int maxStars) {
  final roll = rng.nextDouble();

  if (maxStars <= 2) {
    return roll < .62 ? 1 : 2;
  }

  if (maxStars == 3) {
    if (roll < .43) return 1;
    if (roll < .78) return 2;
    return 3;
  }

  if (maxStars == 4) {
    if (roll < .34) return 1;
    if (roll < .62) return 2;
    if (roll < .86) return 3;
    return 4;
  }

  // Even when 5-stars are available, they should be rare.
  if (roll < .30) return 1;
  if (roll < .58) return 2;
  if (roll < .82) return 3;
  if (roll < .95) return 4;
  return 5;
}

// Subdivision-specific interest adjustment layered on top of the existing
// prestige-tier interestBonus. Two goals: (1) an FCS class leans heavily
// 1-2★ with a real but limited number of 3★s that scale with how strong
// the FCS program actually is, and reads 4-5★ as essentially unreachable
// (see recruitCanCommitToSubdivision for the hard gate that backs this up
// — interest dampening alone can't reach "essentially never," since every
// commit-decision formula has its own probability floor); (2) the weakest
// FBS program still competes for 3★s on FBS-level scholarships, facilities
// and exposure alone, independent of its current prestige tier.
int recruitSubdivisionInterestAdjustment({
  required int stars,
  required Subdivision subdivision,
  required int prestigeTier,
}) {
  if (subdivision == Subdivision.fbs) {
    if (stars == 3) return 20;
    return 0;
  }

  return switch (stars) {
    5 => -90,
    4 => -70,
    3 => switch (prestigeTier) {
      1 => -45,
      2 => -30,
      _ => -15, // FCS tops out at tier 3 (max prestige 78) — this is elite FCS.
    },
    2 => 15,
    _ => 20, // 1★ and unranked.
  };
}

// Five-star recruits essentially never sign with FCS programs; four-stars
// are an extremely rare exception (a major hometown pipeline, guaranteed
// early playing time, a family connection) rather than a normal outcome.
// Applied as a hard final gate on top of the interest-driven probability
// system — every commit-decision formula below has its own floor clamp
// (there to keep recruiting feeling alive, not to guarantee any specific
// outcome), so interest dampening alone can never reach "essentially
// never" on its own.
bool recruitCanCommitToSubdivision(Recruit recruit, Subdivision subdivision) {
  if (subdivision != Subdivision.fcs) return true;
  if (recruit.stars >= 5) return false;
  if (recruit.stars == 4) {
    return recruit.interest >= 90 && rng.nextDouble() < 0.05;
  }
  return true;
}

// No FCS player — recruit, transfer, walk-on, or a multi-year development
// story — should ever reach FBS-elite territory. Without this, the rare
// (but real) 4★ FCS signing could still generate with the same overall/
// potential range (78-87 overall, potential up to 99) as an FBS one, and a
// few years of training could push them into the low-90s despite every
// recruiting restriction above — this is the actual ceiling that closes
// that loophole, applied to both overall and potential (capping potential
// keeps training's own clamp-to-potential logic from ever exceeding this
// on its own, years later).
const int fcsMaxPlayerOverall = 84;

List<Recruit> generateRecruits(
  int prestige, {
  String? pipelineState,
  List<String> pipelineRegionStates = const [],
  String? offensiveScheme,
  String? defensiveScheme,
  Subdivision subdivision = Subdivision.fbs,
}) {
  final positions = ['QB', 'HB', 'WR', 'TE', 'DE', 'LB', 'DB'];
  final states = [
    'RI',
    'MA',
    'CT',
    'NY',
    'NJ',
    'PA',
    'OH',
    'MI',
    'FL',
    'GA',
    'TX',
    'CA',
    'AZ',
    'NC',
    'SC',
    'VA',
    'MD',
    'AL',
    'LA',
    'TN',
  ];
  final recruits = <Recruit>[];

  final potentialBoostMin = switch (prestigeTier(prestige)) {
    1 => 2,
    2 => 3,
    3 => 4,
    4 => 5,
    _ => 6,
  };

  final potentialBoostMax = switch (prestigeTier(prestige)) {
    1 => 10,
    2 => 13,
    3 => 16,
    4 => 19,
    _ => 22,
  };

  final interestBonus = switch (prestigeTier(prestige)) {
    1 => 0,
    2 => 6,
    3 => 12,
    4 => 18,
    _ => 25,
  };

  // A real signing class' scale: the full national talent pool for a
  // cycle, not just the handful of names one program would ever see. Fixed
  // counts (rather than a per-recruit weighted roll) so the class always
  // has this shape and a 5-star stays genuinely scarce against the rest of
  // the field — 40 of them nationally, against 150 one-stars.
  const starCounts = {5: 40, 4: 70, 3: 100, 2: 125, 1: 150};

  for (final tierEntry in starCounts.entries) {
    final stars = tierEntry.key;
    final count = tierEntry.value;

    final minOverall = switch (stars) {
      5 => 88,
      4 => 78,
      3 => 68,
      2 => 58,
      _ => 48,
    };

    final maxOverall = switch (stars) {
      5 => 99,
      4 => 87,
      3 => 77,
      2 => 67,
      _ => 57,
    };

    for (int i = 0; i < count; i++) {
      final overall = minOverall + rng.nextInt(maxOverall - minOverall + 1);
      final boost =
          potentialBoostMin +
          rng.nextInt(potentialBoostMax - potentialBoostMin + 1);
      final potential = (overall + boost).clamp(overall, 99);

      final state = states[rng.nextInt(states.length)];
      final position = positions[rng.nextInt(positions.length)];
      // A coach's home-state pipeline gives a real, noticeable edge with
      // in-state talent — the kind of trust a staff builds over years of
      // relationships that an out-of-state program just doesn't have. The
      // broader region (New England, the West Coast, and so on) still
      // means something too, just not as much as the exact home state.
      final pipelineBonus = pipelineState != null && state == pipelineState
          ? 18
          : pipelineRegionStates.contains(state)
          ? 9
          : 0;
      // A recruit who actually fits the program's scheme is easier to
      // land — a WR wants to play Air Raid, a bruising HB wants Ground &
      // Pound. Mirrors pipelineBonus's shape exactly: a small, bounded,
      // additive nudge into interest, never a gate.
      final fitBonus = schemeFitBonus(
        position,
        offensiveScheme: offensiveScheme,
        defensiveScheme: defensiveScheme,
      );
      final subdivisionAdjustment = recruitSubdivisionInterestAdjustment(
        stars: stars,
        subdivision: subdivision,
        prestigeTier: prestigeTier(prestige),
      );
      final cappedOverall = subdivision == Subdivision.fcs
          ? min(overall, fcsMaxPlayerOverall)
          : overall;
      final cappedPotential = subdivision == Subdivision.fcs
          ? min(potential, fcsMaxPlayerOverall)
          : potential;

      recruits.add(
        Recruit(
          name: NameGenerator.generate(),
          position: position,
          state: state,
          stars: stars,
          trueOverall: cappedOverall,
          truePotential: cappedPotential,
          interest:
              (25 +
                      interestBonus +
                      pipelineBonus +
                      fitBonus +
                      subdivisionAdjustment +
                      rng.nextInt(46))
                  .clamp(1, 100),
        ),
      );
    }
  }

  recruits.sort((a, b) {
    final starCompare = b.stars.compareTo(a.stars);
    if (starCompare != 0) return starCompare;
    return b.interest.compareTo(a.interest);
  });
  return recruits;
}

// ============================================================================
// GRIDIRON KINGDOM — PHASE 1 DESIGN SYSTEM
// Presentation-only components. Simulation, saves, AdMob, and purchases remain
// unchanged.
// ============================================================================

// ---------------------------------------------------------------------------
// THE KINGDOM'S LEDGER — direction contract
// THESIS: the app is a worn leather program ledger under desk-lamp light, not
//   a glowing tech dashboard. It refuses this codebase's own former look
//   (near-black ground + one flat gold glow) because that pairing is a
//   recognized AI-generated-interface default, not a chosen identity.
// OWN-WORLD: dark saddle-leather and oxblood ground, antique-brass stitching
//   and hardware as the single accent system, aged-kraft paper insets (never
//   the whole ground) for dense data — rosters, stat tables, standings. Sharp
//   architectural corners, not soft rounded-everything. Engraved Cinzel for
//   headlines/labels, Zilla Slab as the workhorse ledger-page body face.
// STORY: the coach's own leather-bound program ledger, filling in season by
//   season. Every screen is a page in that ledger, not a card in a feed.
// FIRST VIEWPORT: HomeScreen — the ledger's cover/title page, brass corner
//   hardware, embossed masthead, no card grid of icon+heading+text.
// FORM: assigned direction 5 of 7 (Stadium Signage) was rolled by
//   concept-seed.mjs; the user pinned the "Heritage leather archive"
//   challenger instead after seeing both fully committed. A user-pinned
//   choice overrides the roll, per the skill's own rule.
// FINISH: unreviewed and undocumented is unfinished; this build ends with
//   the finish review, the verdict, and DESIGN.md.
// ---------------------------------------------------------------------------

