class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  Future<void> _restoreRemoveAds(BuildContext context) async {
    if (!PurchaseManager.storeAvailable) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('The App Store is not available right now.'),
        ),
      );
      return;
    }

    await PurchaseManager.restorePurchases();

    if (!context.mounted) return;

    await Future<void>.delayed(const Duration(milliseconds: 800));

    if (!context.mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          PurchaseManager.adsRemoved
              ? 'Your remove-ads purchase was restored.'
              : 'No previous remove-ads purchase was found.',
        ),
      ),
    );
  }

  Future<void> _openLoadScreen(BuildContext context) async {
    final saves = await loadCareerSaves();

    if (!context.mounted) return;

    Navigator.of(
      context,
    ).push(MaterialPageRoute(builder: (_) => LoadCareerScreen(saves: saves)));
  }

  Future<void> _continueLatestCareer(BuildContext context) async {
    final saves = await loadCareerSaves();

    if (!context.mounted) return;

    if (saves.isEmpty) {
      Navigator.of(
        context,
      ).push(MaterialPageRoute(builder: (_) => const TeamSelectionScreen()));
      return;
    }

    saves.sort(
      (a, b) => '${b['savedAt'] ?? ''}'.compareTo('${a['savedAt'] ?? ''}'),
    );

    final save = saves.first;
    final team = teamByName(save['team'] ?? '');
    final coach = coachFromJson(Map<String, dynamic>.from(save['coach'] ?? {}));

    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => DashboardScreen(
          team: team,
          coach: coach,
          careerId: careerKeyFromSave(save),
          savedCareer: save,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: GKBackground(
        child: SafeArea(
          child: FutureBuilder<List<Map<String, dynamic>>>(
            future: loadCareerSaves(),
            builder: (context, snapshot) {
              final saves = snapshot.data ?? const <Map<String, dynamic>>[];
              final hasSave = saves.isNotEmpty;

              Map<String, dynamic>? latestSave;
              if (hasSave) {
                final sorted = [...saves]
                  ..sort(
                    (a, b) => '${b['savedAt'] ?? ''}'.compareTo(
                      '${a['savedAt'] ?? ''}',
                    ),
                  );
                latestSave = sorted.first;
              }

              return Padding(
                padding: const EdgeInsets.fromLTRB(
                  GKSpace.xl,
                  GKSpace.lg,
                  GKSpace.xl,
                  GKSpace.xl,
                ),
                // A returning player's extra "Continue Dynasty" preview card
                // and button can push this taller than the shortest phones
                // have room for — LayoutBuilder + a scroll view lets the
                // Spacers still center everything when it fits, and scroll
                // instead of overflowing when it doesn't.
                child: LayoutBuilder(
                  builder: (context, constraints) => SingleChildScrollView(
                    child: ConstrainedBox(
                      constraints: BoxConstraints(
                        minHeight: constraints.maxHeight,
                      ),
                      child: IntrinsicHeight(
                        child: Column(
                          children: [
                            const Spacer(flex: 2),
                    // The crest already carries the full "Gridiron Kingdom"
