class LoadCareerScreen extends StatelessWidget {
  final List<Map<String, dynamic>> saves;

  const LoadCareerScreen({super.key, required this.saves});

  List<Map<String, dynamic>> _latestCareerSaves() {
    final latestByCareer = <String, Map<String, dynamic>>{};

    for (final save in saves) {
      final key = careerKeyFromSave(save);
      final existing = latestByCareer[key];

      if (existing == null ||
          '${save['savedAt'] ?? ''}'.compareTo('${existing['savedAt'] ?? ''}') >
              0) {
        latestByCareer[key] = save;
      }
    }

    return latestByCareer.values.toList()..sort(
      (a, b) => '${b['savedAt'] ?? ''}'.compareTo('${a['savedAt'] ?? ''}'),
    );
  }

  @override
  Widget build(BuildContext context) {
    final sorted = _latestCareerSaves();

    return Scaffold(
      body: GKBackground(
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(
                  GKSpace.sm,
                  GKSpace.xs,
                  GKSpace.xl,
                  GKSpace.md,
                ),
                child: Row(
                  children: [
                    IconButton(
                      onPressed: () => Navigator.of(context).pop(),
                      icon: const Icon(
                        Icons.arrow_back_ios_new_rounded,
                        color: GKColors.warmWhite,
                      ),
                    ),
                    const SizedBox(width: GKSpace.xs),
                    const Expanded(
                      child: GKSectionHeader(
                        title: 'Saved Careers',
                        subtitle:
                            'Continue a coaching career without changing its simulation data.',
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: sorted.isEmpty
                    ? _EmptyCareerState(
                        onStart: () {
                          Navigator.of(context).pushReplacement(
                            MaterialPageRoute(
                              builder: (_) => const TeamSelectionScreen(),
                            ),
                          );
                        },
                      )
                    : ListView.separated(
                        padding: const EdgeInsets.fromLTRB(
                          GKSpace.xl,
                          GKSpace.sm,
                          GKSpace.xl,
                          GKSpace.xxl,
                        ),
                        itemCount: sorted.length,
                        separatorBuilder: (_, _unused) =>
                            const SizedBox(height: GKSpace.sm),
                        itemBuilder: (context, index) {
                          return _CareerSaveCard(
                            save: sorted[index],
                            isMostRecent: index == 0,
                          );
                        },
                      ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

