class GKSetupProgress extends StatelessWidget {
  final int currentStep;

  const GKSetupProgress({super.key, required this.currentStep});

  @override
  Widget build(BuildContext context) {
    const labels = ['Program', 'Coach', 'Contract'];

    return Row(
      children: List.generate(labels.length, (index) {
        final complete = index < currentStep;
        final active = index == currentStep;

        return Expanded(
          child: Row(
            children: [
              Expanded(
                child: Column(
                  children: [
                    AnimatedContainer(
                      duration: const Duration(milliseconds: 220),
                      height: 4,
                      decoration: BoxDecoration(
                        color: complete || active
                            ? GKColors.kingdomGold
                            : GKColors.divider,
                        borderRadius: BorderRadius.circular(4),
                      ),
                    ),
                    const SizedBox(height: 7),
                    Text(
                      labels[index].toUpperCase(),
                      style: TextStyle(
                        color: active
                            ? GKColors.warmWhite
                            : complete
                            ? GKColors.kingdomGold
                            : GKColors.mutedSilver,
                        fontSize: 9,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1.2,
                      ),
                    ),
                  ],
                ),
              ),
              if (index != labels.length - 1) const SizedBox(width: GKSpace.xs),
            ],
          ),
        );
      }),
    );
  }
}

