class OffseasonResult {
  final CollegeTeam team;
  final List<Player> roster;
  final CollegeTeam? rivalry;
  final List<CollegeTeam> customNonConference;
  final int contractYearsRemaining;
  // A coach-picked bye-week placement (two week indices, 1-12, never
  // adjacent) — null means auto-place them the same way the game always
  // has (generateByeWeeks), which stays the default for every user.
  final List<int>? customByeWeeks;

  const OffseasonResult({
    required this.team,
    required this.roster,
    required this.rivalry,
    required this.customNonConference,
    required this.contractYearsRemaining,
    this.customByeWeeks,
  });
}

int realisticExpectedWins(num prestigeValue) {
  return switch (prestigeTier(prestigeValue)) {
    1 => 6,
    2 => 6,
    3 => 7,
    4 => 8,
    _ => 10,
  };
}

String realisticContractGoal(num prestigeValue) {
  final expectedWins = realisticExpectedWins(prestigeValue);
  final tier = prestigeTier(prestigeValue);

  return switch (tier) {
    1 => 'WIN $expectedWins GAMES',
    2 => 'MAKE A BOWL',
    3 => 'WIN 7-8 GAMES',
    4 => 'CONTEND FOR CONFERENCE',
    _ => 'MAKE THE KP',
  };
}

String realisticJobSecurityLabel(num prestigeValue) {
  return switch (prestigeTier(prestigeValue)) {
    1 => 'REBUILDING',
    2 => 'DEVELOPING',
    3 => 'STABLE',
    4 => 'HIGH EXPECTATIONS',
    _ => 'CHAMPIONSHIP PRESSURE',
  };
}

int seasonScoreFor(int wins, int losses, int prestige) {
  final expectedWins = switch (prestige) {
    1 => 4,
    2 => 6,
    3 => 7,
    4 => 8,
    _ => 9,
  };

  return (50 + (wins - expectedWins) * 9 + wins * 2 - losses * 2).clamp(0, 100);
}

int maxJobPrestigeForSeason(int wins, int losses, int currentPrestige) {
  if (wins <= 6) return currentPrestige;
  if (wins == 7) return (currentPrestige + 1).clamp(1, 2);
  if (wins == 8) return (currentPrestige + 1).clamp(1, 3);
  if (wins == 9) return (currentPrestige + 2).clamp(1, 3);
  if (wins == 10) return (currentPrestige + 2).clamp(1, 4);
  return (currentPrestige + 3).clamp(1, 5);
}

int retentionBudgetForSeason(int wins, int losses, num prestige) {
  // A 1-star program's booster collective just doesn't have the money an
  // elite blueblood's does, even after a good year — both the base and the
  // per-win/bonus scaling grow with prestige tier, not just wins, so a
  // small program's ceiling stays well below a big program's floor.
  final tier = prestigeTier(prestige);
  final base = switch (tier) {
    1 => 120000,
    2 => 350000,
    3 => 900000,
    4 => 2200000,
    _ => 5000000,
  };

  final perWin = switch (tier) {
    1 => 20000,
    2 => 40000,
    3 => 70000,
    4 => 110000,
    _ => 160000,
  };

  final minFloor = switch (tier) {
    1 => 60000,
    2 => 150000,
    3 => 400000,
    4 => 900000,
    _ => 2000000,
  };

  final maxCap = switch (tier) {
    1 => 800000,
    2 => 2000000,
    3 => 4500000,
    4 => 9000000,
    _ => 16000000,
  };

  final bonus = wins * perWin;
  final bowlBonus = wins >= 6 ? (base * 0.25).round() : 0;
  final greatSeason = wins >= 9 ? (base * 0.6).round() : 0;
  final eliteSeason = wins >= 11 ? (base * 1.2).round() : 0;
  final penalty = losses * (perWin ~/ 2);

  return (base + bonus + bowlBonus + greatSeason + eliteSeason - penalty).clamp(
    minFloor,
    maxCap,
  );
}

int recruitingNilBudgetForSeason(num prestige) {
  // Separate pool from retention — this covers persuading a whole
  // incoming class over a season, not keeping a handful of proven
  // players, so it's calibrated smaller per tier even though it uses the
  // same tier shape for consistency.
  return switch (prestigeTier(prestige)) {
    1 => 80000,
    2 => 220000,
    3 => 550000,
    4 => 1300000,
    _ => 3000000,
  };
}

int transferNilBudgetForSeason(num prestige) {
  // A separate pool from recruiting NIL — the portal window is a much
  // smaller group of targets (proven, immediate-impact players) rather
  // than a whole incoming class, so per-tier the budget runs a bit
  // higher even though the shape matches the other NIL pools.
  return switch (prestigeTier(prestige)) {
    1 => 100000,
    2 => 280000,
    3 => 700000,
    4 => 1600000,
    _ => 3600000,
  };
}

String moneyText(int amount) {
  if (amount >= 1000000) {
    final m = amount / 1000000;
    return '\$${m.toStringAsFixed(m >= 10 ? 0 : 1)}M';
  }
  return '\$${(amount / 1000).round()}K';
}

List<String> skillCategoriesForPosition(String position) {
  return switch (position) {
    'QB' => ['Accuracy', 'Power', 'Mobility'],
    'HB' => ['Speed', 'Power', 'Ball Security'],
    'WR' => ['Speed', 'Hands', 'Route Running'],
    'TE' => ['Hands', 'Blocking', 'Power'],
    'DE' => ['Power', 'Pass Rush', 'Speed'],
    'LB' => ['Tackling', 'Coverage', 'Speed'],
    'DB' => ['Coverage', 'Speed', 'Tackling'],
    _ => ['Power', 'Speed', 'Awareness'],
  };
}

Map<String, int> playerSkillRatings(Player p) {
  final skills = skillCategoriesForPosition(p.position);
  final spread = [
    ((p.name.hashCode.abs() % 9) - 4),
    (((p.name.hashCode ~/ 7).abs() % 9) - 4),
    (((p.name.hashCode ~/ 13).abs() % 9) - 4),
  ];

  return {
    for (int i = 0; i < skills.length; i++)
      skills[i]: (p.overall + spread[i]).clamp(40, 94),
  };
}

int playerRetentionAsk(Player p) {
  // NIL retention should feel like a real market: a fringe rotation piece
  // is a rounding error against the budget, and a true star can eat a huge
  // chunk of it. Cost grows on a cubic curve above a 45-overall floor, with
  // stars acting as a multiplier on top — a 5-star performer costs
  // meaningfully more to keep loyal than a 1-star player at the same
  // overall. (The old quadratic-overall formula only spread ~2.5x between
  // a 60 OVR and a 95 OVR player, both trivial next to a $250K-$14M budget;
  // this spreads that same range to roughly 60x.)
  final overallAbove = max(0, p.overall - 45);
  final base = overallAbove * overallAbove * overallAbove * 6;
  final starMultiplier = 1 + (p.stars - 1) * 0.3;
  return (base * starMultiplier).round().clamp(10000, 6000000);
}

int transferMaxStarsForPrestige(num prestige, int wins) {
  final p = prestige100(prestige);
  var maxStars = 2;

  if (p >= 90) {
    maxStars = 5;
  } else if (p >= 80) {
    maxStars = 4;
  } else if (p >= 70) {
    maxStars = 4;
  } else if (p >= 60) {
    maxStars = 3;
  } else {
    maxStars = 2;
  }

  if (wins >= 9) maxStars += 1;
  if (wins <= 4) maxStars -= 1;

  return maxStars.clamp(1, 5);
}

int transferStarsForUserSchool(num prestige, int wins) {
  final maxStars = transferMaxStarsForPrestige(prestige, wins);
  final roll = rng.nextInt(100);

  if (maxStars <= 2) {
    if (roll < 72) return 1;
    if (roll < 96) return 2;
    return 3; // rare good transfer for a bad program
  }

  if (maxStars == 3) {
    if (roll < 42) return 1;
    if (roll < 82) return 2;
    if (roll < 98) return 3;
    return 4;
  }

  if (maxStars == 4) {
    if (roll < 20) return 2;
    if (roll < 58) return 3;
    if (roll < 94) return 4;
    return 5;
  }

  if (roll < 12) return 3;
  if (roll < 45) return 4;
  return 5;
}

int transferOverallForStarsAndPrestige(int stars, num prestige, int wins) {
  final p = prestige100(prestige);
  final maxAllowed = transferMaxStarsForPrestige(prestige, wins);

  // If a player is above the realistic max for the user's school, make them less common and not absurdly high.
  final effectiveStars = min(stars, maxAllowed);

  int minOvr;
  int maxOvr;
  switch (effectiveStars) {
    case 1:
      minOvr = 50;
      maxOvr = 61;
      break;
    case 2:
      minOvr = 58;
      maxOvr = 70;
      break;
    case 3:
      minOvr = 66;
      maxOvr = 78;
      break;
    case 4:
      minOvr = 75;
      maxOvr = 86;
      break;
    default:
      minOvr = 84;
      maxOvr = 94;
  }

  if (p < 60 && wins < 8) {
    maxOvr = min(maxOvr, 74);
  } else if (p < 70 && wins < 8) {
    maxOvr = min(maxOvr, 80);
  }

  return minOvr + rng.nextInt(max(1, maxOvr - minOvr + 1));
}

int transferInterestForUserSchool({
  required int playerStars,
  required int playerOverall,
  required num prestige,
  required int wins,
}) {
  final p = prestige100(prestige);
  final maxStars = transferMaxStarsForPrestige(prestige, wins);

  var interest = 35 + ((p - 50) ~/ 2) + (wins * 3);
  interest += (maxStars - playerStars) * 12;

  if (playerStars > maxStars) interest -= (playerStars - maxStars) * 28;
  if (playerOverall >= 88 && p < 80) interest -= 25;
  if (playerOverall >= 92 && p < 90) interest -= 30;
  if (wins >= 9) interest += 12;
  if (wins <= 4) interest -= 12;

  return interest.clamp(1, 99);
}

class TransferTarget {
  final String name;
  final String position;
  final int overall;
  final int potential;
  final String year;
  final int stars;
  final int interest;
  bool offered = false;
  bool signed = false;
  bool declined = false;
  // Which other program this target actually signed with — set whenever
  // they decline the user, so a decline reads as a real outcome ("signed
  // with Tuscaloosa") instead of a dead end with no destination shown.
  String? destinationSchool;
  // Dollars pledged toward this transfer's NIL ask. Stays 0 for 1-2 star
  // targets, who — like 1-2 star high school recruits — aren't negotiating
  // NIL at all.
  int nilOffered = 0;

  TransferTarget({
    required this.name,
    required this.position,
    required this.overall,
    required this.potential,
    required this.year,
    required this.stars,
    required this.interest,
  });

  // Portal players are already proven college producers, so a 3+ star
  // transfer's NIL ask runs higher than an unproven freshman recruit's at
  // the same star level.
  int get nilAsk {
    if (stars < 3) return 0;
    final base = switch (stars) {
      5 => 350000,
      4 => 150000,
      _ => 50000,
    };
    final spread = base ~/ 2;
    final variance = (name.hashCode.abs() % spread) - (spread ~/ 2);
    return (base + variance).clamp(15000, 750000);
  }

  bool get wantsNil => nilAsk > 0;

  Player toPlayer() {
    return Player(
      name: name,
      position: position,
      overall: overall,
      potential: potential,
      year: year,
      stars: stars,
    );
  }

  double get lastYearYards {
    final base = overall * 7.0 + (name.hashCode.abs() % 220);
    if (position == 'QB') return base * 4.8;
    if (position == 'HB' || position == 'RB') return base * 2.2;
    if (position == 'WR' || position == 'TE') return base * 1.8;
    return base * .45;
  }

  int get lastYearTd {
    final bonus = position == 'QB'
        ? 15
        : (position == 'HB' || position == 'RB' || position == 'WR')
        ? 6
        : 2;
    return ((overall - 55) / 5).round().clamp(0, 12) + bonus;
  }

  int get lastYearTackles {
    if (['DE', 'DL', 'LB', 'DB', 'CB', 'S'].contains(position)) {
      return (overall + 15 + (name.hashCode.abs() % 55)).clamp(30, 145);
    }
    return (name.hashCode.abs() % 10);
  }

  String get transferProfileText {
    if (position == 'QB')
      return '${lastYearYards.round()} pass yds • $lastYearTd TD • ${lastYearTackles} tackles';
    if (position == 'HB' || position == 'RB')
      return '${lastYearYards.round()} rush yds • $lastYearTd TD';
    if (position == 'WR' || position == 'TE')
      return '${lastYearYards.round()} rec yds • $lastYearTd TD';
    return '$lastYearTackles tackles • $lastYearTd impact plays';
  }

  String get hometown {
    final states = [
      'TX',
      'FL',
      'CA',
      'GA',
      'OH',
      'PA',
      'NC',
      'VA',
      'AL',
      'LA',
      'AZ',
      'NJ',
    ];
    return states[name.hashCode.abs() % states.length];
  }

  String get previousSchool {
    final schools = [
      'Tempe',
      'Boulder',
      'Chestnut Hill',
      'West Lafayette',
      'Bluff City',
      'Boise',
      'Orlando',
      'Broad Street',
      'Salt City',
      'Old Dominion',
      'Houston',
      'Boone',
    ];
    return schools[(name.hashCode.abs() ~/ 7) % schools.length];
  }

  String get roleFit {
    if (overall >= 84) return 'Day-one starter';
    if (overall >= 76) return 'Rotation player with starter upside';
    if (overall >= 68) return 'Depth piece with development upside';
    return 'Long-term developmental add';
  }

  String get scoutingReport {
    final upside = potential - overall;
    if (upside >= 10)
      return 'High-upside transfer with room to grow quickly in the right system.';
    if (overall >= 82)
      return 'Polished veteran who can help immediately if the fit is right.';
    if (interest >= 75)
      return 'Strong interest and a realistic target for this program.';
    return 'Could be a tough pull, but worth monitoring if roster need is high.';
  }

  String get pastSeasonHeadline {
    if (position == 'QB')
      return '${lastYearYards.round()} pass yds • $lastYearTd TD';
    if (position == 'HB' || position == 'RB')
      return '${lastYearYards.round()} rush yds • $lastYearTd TD';
    if (position == 'WR' || position == 'TE')
      return '${lastYearYards.round()} rec yds • $lastYearTd TD';
    return '$lastYearTackles tackles • $lastYearTd impact plays';
  }
}

List<int> jobOfferPrestigeTargets({
  required int currentPrestige,
  required int wins,
  required int losses,
  required int expectedWins,
}) {
  final current = prestige100(currentPrestige);
  final overExpectation = wins - expectedWins;
  final winningSeason = wins >= 7;
  final greatSeason = wins >= 9 || overExpectation >= 3;
  final badSeason = wins <= 5 || overExpectation <= -2;

  int clampP(int v) => v.clamp(50, 100);

  if (greatSeason) {
    return [
      clampP(current + 8 + rng.nextInt(8)), // clear better offer
      clampP(current + 3 + rng.nextInt(7)), // slightly better
      clampP(current - 4 + rng.nextInt(9)), // similar/fallback
    ];
  }

  if (winningSeason) {
    return [
      clampP(current + 3 + rng.nextInt(6)), // one better
      clampP(current - 2 + rng.nextInt(7)), // similar
      clampP(current - 8 + rng.nextInt(8)), // slightly lower
    ];
  }

  if (badSeason) {
    return [
      clampP(current + rng.nextInt(5)), // maybe one small upgrade
      clampP(current - 8 - rng.nextInt(8)), // worse
      clampP(current - 12 - rng.nextInt(10)), // much worse
    ];
  }

  return [
    clampP(current + rng.nextInt(5)), // similar/slightly better
    clampP(current - 4 + rng.nextInt(7)), // similar
    clampP(current - 10 + rng.nextInt(8)), // lower
  ];
}

CollegeTeam teamClosestToPrestige(
  List<CollegeTeam> teams,
  int target,
  Set<String> usedNames,
  CollegeTeam currentTeam,
) {
  final pool = teams
      .where((t) => t.name != currentTeam.name && !usedNames.contains(t.name))
      .toList();

  if (pool.isEmpty)
    return teams.firstWhere(
      (t) => t.name != currentTeam.name,
      orElse: () => currentTeam,
    );

  pool.sort((a, b) {
    final da = (prestige100(a.prestige) - target).abs();
    final db = (prestige100(b.prestige) - target).abs();
    if (da != db) return da.compareTo(db);
    return rng.nextInt(3) - 1;
  });

  return pool.first;
}

class JobOffer {
  final CollegeTeam team;
  final int years;

  const JobOffer({required this.team, required this.years});
}

class CoachTransitionResult {
  final List<Player> playersFollowing;
  final List<Recruit> recruitsFollowing;
  final List<Recruit> recruitsStayed;
  final List<Recruit> recruitsReopened;

  const CoachTransitionResult({
    required this.playersFollowing,
    required this.recruitsFollowing,
    required this.recruitsStayed,
    required this.recruitsReopened,
  });
}

int prestigeExpectationWins(int prestige) {
  if (prestige >= 88) return 10;
  if (prestige >= 78) return 8;
  if (prestige >= 66) return 6;
  if (prestige >= 55) return 5;
  return 4;
}

int updatedPrestigeAfterSeason(
  int prestige,
  int wins,
  int losses, {
  bool madeCfp = false,
  bool wonConference = false,
  bool wonTitle = false,
}) {
  final expected = prestigeExpectationWins(prestige);
  int change = 0;
  if (wins >= expected + 4)
    change += 5;
  else if (wins >= expected + 2)
    change += 3;
  else if (wins >= expected)
    change += 1;
  else if (wins <= expected - 3)
    change -= 4;
  else if (wins < expected)
    change -= 2;
  if (wonConference) change += 2;
  if (madeCfp) change += 3;
  if (wonTitle) change += 5;
  if (losses >= 9) change -= 2;
  return (prestige + change).clamp(1, 100);
}

/// One cheap, prestige-weighted roll for a rival's whole season — not a
/// real schedule sim (none exists for non-user teams anywhere in this
/// file; see _simulateNationalWeek/_recordSimulatedNationalTitleIfNeeded
/// for the existing precedent this follows). Win total varies around
/// prestigeExpectationWins; conference/playoff/title/bowl chances all
/// scale with prestigeTier (1-5).
/// Mirrors _bowlNameForRecord's own win-count tiers, so a rival's bowl win
/// scores exactly like a user's bowl win from the same win total would.
int bowlTierPointsForWins(int wins) {
  if (wins >= 11) return 150;
  if (wins == 10) return 130;
  if (wins == 9) return 110;
  if (wins == 8) return 95;
  if (wins == 7) return 85;
  return 75;
}

RivalCoachRecord simulateRivalCoachSeason(RivalCoachRecord rival) {
  final expected = prestigeExpectationWins(rival.currentPrestige);
  final variance = rng.nextInt(7) - 3; // -3..+3
  final seasonWins = (expected + variance).clamp(0, 12);
  final seasonLosses = 12 - seasonWins;
  final tier = prestigeTier(rival.currentPrestige);

  final wonConference = rng.nextDouble() < (0.02 + (tier - 1) * 0.03);
  final cfpChance = wonConference
      ? 0.55 + (tier - 1) * 0.05
      : 0.02 + (tier - 1) * 0.02;
  final madeCfp = rng.nextDouble() < cfpChance.clamp(0.0, 0.9);
  final titleChance = madeCfp ? 0.05 + (tier - 1) * 0.03 : 0.0;
  final wonTitle = madeCfp && rng.nextDouble() < titleChance;
  // Mirrors the user's own trophy rules: a bowl win only counts when the
  // team reached a bowl WITHOUT making the KP.
  final wonBowl =
      !madeCfp &&
      seasonWins >= 6 &&
      rng.nextDouble() < (0.45 + (tier - 1) * 0.05).clamp(0.0, 0.9);

  final updatedPrestige = updatedPrestigeAfterSeason(
    rival.currentPrestige,
    seasonWins,
    seasonLosses,
    madeCfp: madeCfp,
    wonConference: wonConference,
    wonTitle: wonTitle,
  );

  return rival.copyWith(
    currentPrestige: updatedPrestige,
    tenureYears: rival.tenureYears + 1,
    careerWins: rival.careerWins + seasonWins,
    careerLosses: rival.careerLosses + seasonLosses,
    nationalTitles: rival.nationalTitles + (wonTitle ? 1 : 0),
    conferenceTitles: rival.conferenceTitles + (wonConference ? 1 : 0),
    bowlWins: rival.bowlWins + (wonBowl ? 1 : 0),
    bowlPoints:
        rival.bowlPoints + (wonBowl ? bowlTierPointsForWins(seasonWins) : 0),
    undefeatedSeasons: rival.undefeatedSeasons + (seasonLosses == 0 ? 1 : 0),
    // Promotion/realignment tracking (see isPromotionEligible) — a
    // genuine multi-season streak, not a single good year, and madeCfp
    // here means "made the playoff," real for either subdivision (the
    // FBS CFP or the FCS 24-team bracket).
    consecutiveWinningSeasons: seasonWins > seasonLosses
        ? rival.consecutiveWinningSeasons + 1
        : 0,
    playoffAppearances:
        rival.playoffAppearances + (madeCfp ? 1 : 0),
    seasonsSinceRealignment: rival.seasonsSinceRealignment + 1,
  );
}

/// The weak-FBS prestige floor (see the FCS subdivision ratings bands) — a
/// program has to be genuinely FBS-competitive, not merely successful
/// within FCS, before it's a realistic promotion candidate.
const int fbsPromotionPrestigeFloor = 55;

/// True if this FCS program has earned a real look from FBS conferences.
/// Two independent paths in:
///   1. At least 3 consecutive winning seasons (never a single good year)
///      plus at least one of a conference title / multiple playoff
///      appearances / a national title — sustained success, not just one
///      big season.
///   2. Two or more FCS national championships, on their own — a program
///      that's won the whole thing more than once has already proven it,
///      independent of whether its most recent seasons happen to form an
///      unbroken streak.
/// Either way, a prestige already at the weak-FBS floor is required, and
/// this is never true for a team that's already FBS or one still inside
/// its cooldown window since its last realignment (so a program can't hop
/// conferences or subdivisions every single offseason).
bool isPromotionEligible(RivalCoachRecord r) {
  final subdivision = r.subdivisionOverride ?? Subdivision.fcs;
  if (subdivision != Subdivision.fcs) return false;
  if (r.seasonsSinceRealignment < 2) return false;
  if (r.currentPrestige < fbsPromotionPrestigeFloor) return false;

  if (r.nationalTitles >= 2) return true;

  if (r.consecutiveWinningSeasons < 3) return false;
  return r.conferenceTitles >= 1 ||
      r.playoffAppearances >= 2 ||
      r.nationalTitles >= 1;
}

/// A pending offseason invitation to change conference (and, for an FCS
/// program moving to an FBS one, subdivision). Purely a proposal — nothing
/// changes until it's accepted (see _DashboardScreenState/_OffseasonScreenState
/// realignment handling).
class ConferenceInvitation {
  final String conference;
  final Subdivision subdivision;
  final int conferenceAvgPrestige;
  final String reason;

  const ConferenceInvitation({
    required this.conference,
    required this.subdivision,
    required this.conferenceAvgPrestige,
    required this.reason,
  });

  bool get movesUpToFbs => subdivision == Subdivision.fbs;
}

String _promotionReasonFor(RivalCoachRecord r) {
  return r.nationalTitles >= 2
      ? '${r.nationalTitles} FCS national championships — there\'s nothing left to prove at this level'
      : r.consecutiveWinningSeasons >= 4
      ? 'Sustained FCS success across ${r.consecutiveWinningSeasons} straight winning seasons'
      : r.nationalTitles >= 1
      ? 'An FCS national championship on the résumé'
      : 'A strong, multi-season FCS playoff track record';
}

/// FBS conferences ranked by how well their average prestige fits a
/// promoted program's own live prestige — a promoted FCS power shouldn't
/// land in the weakest FBS conference, nor challenge for a Power-4 spot on
/// day one. A promoted program fits best a bit BELOW its own live
/// prestige on purpose: it's about to face deeper, more experienced FBS
/// rosters, not simply slot in as an equal (see the "challenging
/// transition period" the FCS subdivision plan calls for).
List<ConferenceInvitation> _rankedRealignmentOptionsFor(RivalCoachRecord r) {
  final conferenceAverages = <String, List<int>>{};
  for (final team in g5Teams) {
    if (isIndependentConference(team.conference)) continue;
    conferenceAverages.putIfAbsent(team.conference, () => []).add(team.prestige);
  }

  final targetPrestige = (r.currentPrestige - 8).clamp(1, 100);
  final ranked = conferenceAverages.entries.toList()
    ..sort((a, b) {
      final avgA = a.value.reduce((x, y) => x + y) / a.value.length;
      final avgB = b.value.reduce((x, y) => x + y) / b.value.length;
      return (avgA - targetPrestige).abs().compareTo((avgB - targetPrestige).abs());
    });

  final reason = _promotionReasonFor(r);
  return ranked
      .map(
        (entry) => ConferenceInvitation(
          conference: entry.key,
          subdivision: Subdivision.fbs,
          conferenceAvgPrestige:
              (entry.value.reduce((x, y) => x + y) / entry.value.length).round(),
          reason: reason,
        ),
      )
      .toList();
}

/// One realistic invitation for a program that has earned a real look.
/// Returns null if no invitation is generated this offseason — promotion
/// is meant to feel uncommon and earned, never automatic or guaranteed
/// just because a team is eligible.
ConferenceInvitation? realignmentInvitationFor(
  RivalCoachRecord r, {
  required double chance,
}) {
  if (!isPromotionEligible(r)) return null;
  if (rng.nextDouble() >= chance) return null;
  final options = _rankedRealignmentOptionsFor(r);
  return options.isEmpty ? null : options.first;
}

/// The 1-2 best-fitting invitations for a program that has earned a real
/// look — used only for the user's own "Conference Invitations" offseason
/// step, so there's always something real to compare when eligible (a CPU
/// program only ever needs the single best option — see
/// realignmentInvitationFor).
List<ConferenceInvitation> realignmentInvitationOptionsFor(RivalCoachRecord r) {
  if (!isPromotionEligible(r)) return [];
  return _rankedRealignmentOptionsFor(r).take(2).toList();
}

/// One-time league generation for a brand-new career: one rival coach per
/// AI program across BOTH subdivisions (allTeams, not just g5Teams — an FCS
/// team with no RivalCoachRecord would never get a live-tracked prestige at
/// all, silently defeating the whole point of _livePrestigeFor for half the
/// league), excluding the team the user is coaching. No rival job-hopping/
/// firing is simulated — teamName is fixed for the whole career, keeping
/// this cheap.
RivalCoachRecord _generateOneRivalCoach(CollegeTeam team) {
  var rival = RivalCoachRecord(
    coachName: NameGenerator.generate(),
    teamName: team.name,
    currentPrestige: team.prestige,
    tenureYears: 0,
    careerWins: 0,
    careerLosses: 0,
    nationalTitles: 0,
    conferenceTitles: 0,
    bowlWins: 0,
  );
  // A brand-new rival with a blank 0-everything career scores as just their
  // prestige number relabeled on the Legacy Board — not a real résumé.
  // Fast-forward 3-15 seasons of real pre-career history through the exact
  // same season-simulation formula used to advance every rival each
  // offseason, so day-one standings already show differentiated coaches,
  // not a flat rating list.
  final priorSeasons = 3 + rng.nextInt(13);
  for (var i = 0; i < priorSeasons; i++) {
    rival = simulateRivalCoachSeason(rival);
  }
  return rival;
}

List<RivalCoachRecord> generateRivalCoachLeague(String userTeamName) {
  return allTeams
      .where((team) => team.name != userTeamName)
      .map(_generateOneRivalCoach)
      .toList();
}

int coachRecruitingRating(CoachProfile coach) {
  try {
    final dyn = coach as dynamic;
    final v = dyn.recruiting;
    if (v is int) return v.clamp(25, 99);
    if (v is num) return v.round().clamp(25, 99);
  } catch (_) {}
  return 45;
}

int maxVisibleStarsForCoachAndSchool(CoachProfile coach, CollegeTeam team) {
  final cr = coachRecruitingRating(coach);
  final p = team.prestige;
  if (p >= 88 || cr >= 85) return 5;
  if (p >= 76 || cr >= 75) return 4;
  if (p >= 62 || cr >= 65) return 3;
  return 2;
}

int cappedFreshmanOverall(int overall) => overall.clamp(40, 94);

int awardScoreForPlayer(Player player) {
  final overall = awardOverall(player);
  final yearBonus = switch (player.year) {
    'SR' => 6,
    'JR' => 4,
    'SO' => 2,
    _ => 0,
  };

  final positionBonus = switch (player.position) {
    'QB' => 8,
    'HB' => 5,
    'WR' => 4,
    'DE' => 4,
    'LB' => 3,
    'DB' => 3,
    'TE' => 1,
    _ => 0,
  };

  final starBonus = player.stars * 2;
  final seedBonus = player.name.hashCode.abs() % 7;

  return overall * 3 + yearBonus + positionBonus + starBonus + seedBonus;
}

List<Player> realisticAllAmericanTeam(
  List<Player> players, {
  required Set<String> usedNames,
}) {
  final positionNeeds = <String, int>{
    'QB': 1,
    'HB': 1,
    'WR': 2,
    'TE': 1,
    'DE': 2,
    'LB': 2,
    'DB': 3,
  };

  final selected = <Player>[];

  for (final entry in positionNeeds.entries) {
    final candidates =
        players
            .where(
              (p) => p.position == entry.key && !usedNames.contains(p.name),
            )
            .toList()
          ..sort(
            (a, b) => awardScoreForPlayer(b).compareTo(awardScoreForPlayer(a)),
          );

    for (final player in candidates.take(entry.value)) {
      selected.add(player);
      usedNames.add(player.name);
    }
  }

  selected.sort(
    (a, b) => awardScoreForPlayer(b).compareTo(awardScoreForPlayer(a)),
  );
  return selected;
}

class DashboardScreen extends StatefulWidget {
  final CollegeTeam team;
  final CoachProfile coach;
  final String? careerId;
  final Map<String, dynamic>? savedCareer;
  final List<TrophyEntry> initialTrophies;
  final List<NationalTitleHistoryEntry> initialNationalHistory;
  final List<NationalTitleHistoryEntry> initialFcsNationalHistory;
  final List<RivalCoachRecord> initialRivalCoaches;
  final List<SeasonGoalRecord> initialSeasonGoalHistory;
  final int initialCareerWins;
  final int initialUndefeatedSeasons;
  final bool initialHasRetired;
  // Set only on a mid-career job change — the roster the coaching
  // transition (players who followed, walk-on backfill, etc.) actually
  // computed. Null for a brand-new career or a resumed save, both of
  // which build their own roster (generateRoster / the saved roster).
  final List<Player>? initialRoster;

  const DashboardScreen({
    super.key,
    required this.team,
    required this.coach,
    this.careerId,
    this.savedCareer,
    this.initialTrophies = const [],
    this.initialNationalHistory = const [],
    this.initialFcsNationalHistory = const [],
    this.initialRivalCoaches = const [],
    this.initialSeasonGoalHistory = const [],
    this.initialCareerWins = 0,
    this.initialUndefeatedSeasons = 0,
    this.initialHasRetired = false,
    this.initialRoster,
  });

  @override
  State<DashboardScreen> createState() => _DashboardScreenState();
}

class _DashboardScreenState extends State<DashboardScreen>
    with WidgetsBindingObserver {
  final List<String> weeklyNewsHeadlines = [];
  final List<TrophyEntry> trophyRoom = [];
  final List<NationalTitleHistoryEntry> nationalHistory = [];
  bool nationalHistoryRecordedThisSeason = false;
  // Kept entirely separate from nationalHistory so FBS and FCS national
  // championship history never mix in the archive/trophy views.
  final List<NationalTitleHistoryEntry> fcsNationalHistory = [];
  bool fcsNationalHistoryRecordedThisSeason = false;

  // Legacy Board: one simulated rival coach per AI program, this coach's
  // season-goal history, and the current season's goal. Populated at
  // initState (new career: generateRivalCoachLeague; loaded save:
  // _loadSavedCareer) and advanced once per offseason in _openOffseason.
  final List<RivalCoachRecord> rivalCoaches = [];
  final List<SeasonGoalRecord> seasonGoalHistory = [];
  SeasonGoal? currentSeasonGoal;

  // How a CPU program has actually fared under simulateRivalCoachSeason,
  // not its frozen day-one CollegeTeam.prestige. Without this, a team's
  // in-game strength (win probability, roster overall, bowl/ranking
  // projections) never reflected its simulated win/loss history at all —
  // only its RivalCoachRecord (job-offer targeting, Legacy Board) did. This
  // is also the mechanism the FBS/FCS ratings overlap depends on: a rising
  // FCS program's live prestige has to actually climb for it to become
  // competitive with weak FBS over a career, not just on paper.
  int _livePrestigeFor(CollegeTeam team) {
    for (final r in rivalCoaches) {
      if (r.teamName == team.name) return r.currentPrestige;
    }
    return team.prestige;
  }

  // A live-resolved copy of `team` — prestige from _livePrestigeFor, plus
  // conference/subdivision from the matching RivalCoachRecord's override
  // fields if this program has ever been realigned or promoted (see
  // isPromotionEligible / the offseason "Conference Invitations" step).
  // The one canonical way to read "this CPU program's current state"
  // anywhere gameplay-relevant strength or standing matters.
  CollegeTeam _liveTeam(CollegeTeam team) {
    final rival = rivalCoaches.where((r) => r.teamName == team.name).firstOrNull;
    if (rival == null) return team;

    final live = rival.currentPrestige;
    final conference = rival.conferenceOverride ?? team.conference;
    final subdivision = rival.subdivisionOverride ?? team.subdivision;
    if (live == team.prestige &&
        conference == team.conference &&
        subdivision == team.subdivision) {
      return team;
    }
    return CollegeTeam(
      name: team.name,
      conference: conference,
      prestige: live,
      primary: team.primary,
      secondary: team.secondary,
      subdivision: subdivision,
      emoji: team.emoji,
      mascot: team.mascot,
    );
  }
  int careerWins = 0;
  int undefeatedSeasons = 0;
  // Once true, this specific career has already added its Hall of Fame
  // entry — the Retire button on the Legacy Board only ever fires once
  // per career, so a coach can't pad the board with duplicate entries.
  bool hasRetired = false;

  late CollegeTeam selectedTeam;
  late List<Player> roster;
  late List<Recruit> recruits;
  // 14 weeks for a 12-game season — 2 of them are byes (null), spread out
  // so they're never back to back.
  late List<CollegeTeam?> schedule;
  int currentWeek = 0;
  late CollegeTeam nextOpponent;
  CollegeTeam? rivalryTeam;
  CoachTransitionResult? transitionResult;
  List<CollegeTeam> nextCustomNonConference = [];
  List<int>? nextCustomByeWeeks;
  late Map<String, TeamSeasonRecord> teamRecords;
  // Real, resolved Power 4 conference champions for the current season, keyed
  // by conference name. Populated by simulating actual championship games
  // (see _resolveOtherConferenceChampionships) rather than projecting from
  // regular-season record, so the KP field is only ever final once every
  // Power 4 title game has actually been decided. Cleared each new season.
  final Map<String, String> resolvedConferenceChampions = {};
  // Real, accumulated season stat lines for this team's own players, keyed
  // by player name — every entry is the exact sum of that player's
  // attributed lines from every game actually simulated this season (see
  // attributeGameStatsToRoster). Cleared each new season.
  final Map<String, GamePlayerLine> seasonPlayerStats = {};
  // Keyed by schedule week index — lets the Schedule screen show a real
  // final score and box score for any past regular-season game instead of
  // a bare "FINAL" label.
  final Map<int, GameResultRecord> gameResults = {};
  // Every player currently sidelined — see _playersAt, which actually
  // excludes these names from starting, not just displaying a label.
  final List<Injury> activeInjuries = [];
  // A real, persisted result of spending RP to talk to a player — added on
  // top of transferRiskFor's signal-derived score (see _moraleForPlayer),
  // not a separate made-up number. Keyed by player name; cleared each
  // season along with everyone else's roster-cycle state.
  final Map<String, int> playerMoraleBoosts = {};
  // A player who told you the relationship is unfixable during a talk —
  // permanent for the rest of this season: no amount of RP moves their
  // morale, and _playerRetentionCard blocks a retention NIL offer to them
  // outright, since they're leaving regardless of what you pay.
  final Set<String> irreconcilablePlayerNames = {};
  // The real head-to-head history against every rival this career has
  // ever had — keyed by the rival program's name, never cleared, so the
  // trophy and series record actually mean something over time.
  final Map<String, RivalrySeriesRecord> rivalrySeries = {};
  // The program's all-time best single season per stat category — a real
  // record book, never cleared. See seasonRecordCategoryLabels.
  final Map<String, SeasonStatRecord> seasonStatRecords = {};
  // Categories already flagged with a "closing in on the record" headline
  // this season, so the same watch doesn't repeat every single week.
  // Cleared each season alongside everyone else's season-cycle state.
  final Set<String> _recordWatchAlerted = {};
  // Program prestige (stars) for the team the coach currently leads. Starts
  // at the team's base prestige but evolves offseason to offseason via
  // updatedPrestigeAfterSeason — wins above expectation, conference titles,
  // CFP runs, and national titles raise it; bad seasons lower it. widget.team
  // itself never changes across seasons while staying at the same job, so
  // this is the field everything season-quality-related should read instead
  // of widget.team.prestige.
  late int programPrestige;

  // Conference realignment overrides for the CURRENT job — mirrors
  // programPrestige's own pattern (widget.team itself never changes while
  // staying at the same job, so the evolving truth lives here instead).
  // Reset to widget.team's own values on every fresh DashboardScreen
  // (a new career, a resumed save, OR a job change — a new job always
  // starts in its own real conference/subdivision, never an old one's
  // override). currentSubdivision specifically is what every subdivision-
  // sensitive read of "the user's own team" should use from here on,
  // taking over from currentSubdivision now that it can change
  // mid-career via promotion.
  late String currentConference;
  late Subdivision currentSubdivision;
  int consecutiveWinningSeasons = 0;
  int userPlayoffAppearances = 0;
  int seasonsSinceRealignment = 99;
  List<ConferenceInvitation> pendingRealignmentInvitations = [];

  int selectedTab = 0;
  int recruitingPoints = 150;
  int wins = 0;
  int losses = 0;
  int confWins = 0;
  int confLosses = 0;
  int gamesPlayed = 0;
  int season = 1;
  int commits = 0;
  int recruitingWindow = 1;
  // Season-long NIL pool for signing new recruits — separate from the
  // offseason retention budget. Set once per recruiting class, not reset
  // per window like recruitingPoints is.
  int recruitingNilBudget = 0;
  int recruitingNilSpent = 0;
  // Years left on the current contract at the current job. Set from the
  // hiring school's prestige tier when a career (or a new job) starts, and
  // updated each offseason by the Contract Decision step — extensions add
  // years, a plain season without one just ticks it down.
  int contractYearsRemaining = 0;
  String seasonPhase = 'regular';
  int postseasonRound = 0;
  // Every team the user has already played this postseason (first round
  // through the championship) — a real single-elimination bracket never
  // runs the same matchup back, so _playoffOpponent() refuses to pick any
  // team in here. Cleared at the start of each CFP run and each new season.
  final Set<String> _cfpOpponentsFaced = {};
  bool madeCfpThisSeason = false;
  String assignedBowlName = '';
  int mediaReputation = 50;
  int playerMorale = 50;
  int boosterApproval = 50;
  int recruitingBuzz = 50;
  int fanHappiness = 50;
  final List<String> worldNewsHeadlines = [];
  String lastPressTone = '';
  String lastPressQuote = '';
  late String activeCareerId;

  int? starFilter;
  String? positionFilter;
  String? stateFilter;
  String recruitSort = 'Rank';
  int recruitBoardTab = 0;
  String _newCareerId() {
    return careerKeyFromCoachName(widget.coach.name);
  }

  Map<String, dynamic> _careerSaveJson() {
    return {
      'id': activeCareerId,
      'careerKey': activeCareerId,
      'coach': coachToJson(widget.coach),
      'team': selectedTeam.name,
      'season': season,
      'wins': wins,
      'losses': losses,
      'confWins': confWins,
      'confLosses': confLosses,
      'gamesPlayed': gamesPlayed,
      'currentWeek': currentWeek,
      'recruitingPoints': recruitingPoints,
      'recruitingWindow': recruitingWindow,
      'recruitingNilBudget': recruitingNilBudget,
      'recruitingNilSpent': recruitingNilSpent,
      'contractYearsRemaining': contractYearsRemaining,
      'commits': commits,
      'seasonPhase': seasonPhase,
      'postseasonRound': postseasonRound,
      'madeCfpThisSeason': madeCfpThisSeason,
      'programPrestige': programPrestige,
      'assignedBowlName': assignedBowlName,
      'mediaReputation': mediaReputation,
      'playerMorale': playerMorale,
      'boosterApproval': boosterApproval,
      'recruitingBuzz': recruitingBuzz,
      'fanHappiness': fanHappiness,
      'worldNewsHeadlines': worldNewsHeadlines,
      'lastPressTone': lastPressTone,
      'lastPressQuote': lastPressQuote,
      'roster': roster.map(playerToJson).toList(),
      'trophies': trophyRoom.map(trophyToJson).toList(),
      'seasonPlayerStats': seasonPlayerStats.map(
        (name, line) => MapEntry(name, line.toJson()),
      ),
      'gameResults': gameResults.map(
        (week, result) => MapEntry('$week', result.toJson()),
      ),
      'activeInjuries': activeInjuries.map((i) => i.toJson()).toList(),
      'playerMoraleBoosts': playerMoraleBoosts,
      'irreconcilablePlayerNames': irreconcilablePlayerNames.toList(),
      'rivalrySeries': rivalrySeries.map(
        (name, record) => MapEntry(name, record.toJson()),
      ),
      'seasonStatRecords': seasonStatRecords.map(
        (category, record) => MapEntry(category, record.toJson()),
      ),
      'history': nationalHistory.map(historyToJson).toList(),
      'fcsHistory': fcsNationalHistory.map(historyToJson).toList(),
      'rivalCoaches': rivalCoaches.map(rivalCoachToJson).toList(),
      'seasonGoalHistory': seasonGoalHistory.map(seasonGoalRecordToJson).toList(),
      'currentSeasonGoal': currentSeasonGoal == null
          ? null
          : seasonGoalToJson(currentSeasonGoal!),
      'careerWins': careerWins,
      'undefeatedSeasons': undefeatedSeasons,
      'hasRetired': hasRetired,
      'currentConference': currentConference,
      'currentSubdivision': currentSubdivision.name,
      'consecutiveWinningSeasons': consecutiveWinningSeasons,
      'userPlayoffAppearances': userPlayoffAppearances,
      'seasonsSinceRealignment': seasonsSinceRealignment,
      'savedAt': DateTime.now().toIso8601String(),
    };
  }

  void _autoSaveCareer() {
    upsertCareerSave(_careerSaveJson());
  }

  void _loadSavedCareer(Map<String, dynamic> save) {
    selectedTeam = teamByName(save['team'] ?? selectedTeam.name);
    season = save['season'] ?? season;
    wins = save['wins'] ?? 0;
    losses = save['losses'] ?? 0;
    confWins = save['confWins'] ?? 0;
    confLosses = save['confLosses'] ?? 0;
    gamesPlayed = save['gamesPlayed'] ?? 0;
    // Older saves predate bye weeks and never recorded a week pointer
    // separate from games played — for those, week and game count were
    // always the same thing, so that's the best migration default.
    currentWeek = (save['currentWeek'] as num?)?.toInt() ?? gamesPlayed;
    recruitingPoints = save['recruitingPoints'] ?? 150;
    recruitingWindow = save['recruitingWindow'] ?? 1;
    recruitingNilBudget = save['recruitingNilBudget'] ?? 0;
    recruitingNilSpent = save['recruitingNilSpent'] ?? 0;
    contractYearsRemaining =
        (save['contractYearsRemaining'] as num?)?.toInt() ??
        contractYearsRemaining;
    commits = save['commits'] ?? 0;
    seasonPhase = save['seasonPhase'] ?? 'regular';
    postseasonRound = save['postseasonRound'] ?? 0;
    madeCfpThisSeason = save['madeCfpThisSeason'] ?? false;
    programPrestige =
        (save['programPrestige'] as num?)?.toInt() ?? widget.team.prestige;
    assignedBowlName = '${save['assignedBowlName'] ?? ''}';
    mediaReputation = (save['mediaReputation'] as num?)?.toInt() ?? 50;
    playerMorale = (save['playerMorale'] as num?)?.toInt() ?? 50;
    boosterApproval = (save['boosterApproval'] as num?)?.toInt() ?? 50;
    recruitingBuzz = (save['recruitingBuzz'] as num?)?.toInt() ?? 50;
    fanHappiness = (save['fanHappiness'] as num?)?.toInt() ?? 50;
    final savedWorldNews = save['worldNewsHeadlines'];
    if (savedWorldNews is List) {
      worldNewsHeadlines
        ..clear()
        ..addAll(savedWorldNews.map((item) => '$item'));
    }
    lastPressTone = '${save['lastPressTone'] ?? ''}';
    lastPressQuote = '${save['lastPressQuote'] ?? ''}';

    final savedRoster = save['roster'];
    if (savedRoster is List) {
      roster = savedRoster
          .whereType<Map>()
          .map((e) => playerFromJson(Map<String, dynamic>.from(e)))
          .toList();
    }

    final savedTrophies = save['trophies'];
    if (savedTrophies is List) {
      trophyRoom
        ..clear()
        ..addAll(
          savedTrophies.whereType<Map>().map(
            (e) => trophyFromJson(Map<String, dynamic>.from(e)),
          ),
        );
    }

    final savedHistory = save['history'];
    if (savedHistory is List) {
      nationalHistory
        ..clear()
        ..addAll(
          savedHistory.whereType<Map>().map(
            (e) => historyFromJson(Map<String, dynamic>.from(e)),
          ),
        );
    }

    final savedFcsHistory = save['fcsHistory'];
    if (savedFcsHistory is List) {
      fcsNationalHistory
        ..clear()
        ..addAll(
          savedFcsHistory.whereType<Map>().map(
            (e) => historyFromJson(Map<String, dynamic>.from(e)),
          ),
        );
    }

    final savedRivalCoaches = save['rivalCoaches'];
    if (savedRivalCoaches is List) {
      rivalCoaches
        ..clear()
        ..addAll(
          savedRivalCoaches.whereType<Map>().map(
            (e) => rivalCoachFromJson(Map<String, dynamic>.from(e)),
          ),
        );
    }
    // A save from before the FCS subdivision existed only ever generated a
    // RivalCoachRecord per FBS program — backfill one for every FCS team
    // too, so an old career's FCS opponents get real live-tracked prestige
    // (job offers, ratings overlap) instead of silently falling back to
    // static prestige forever. A no-op for any save already covering the
    // full league.
    final knownRivalNames = rivalCoaches.map((r) => r.teamName).toSet();
    for (final team in allTeams) {
      if (team.name == selectedTeam.name) continue;
      if (knownRivalNames.contains(team.name)) continue;
      rivalCoaches.add(_generateOneRivalCoach(team));
    }

    final savedGoalHistory = save['seasonGoalHistory'];
    if (savedGoalHistory is List) {
      seasonGoalHistory
        ..clear()
        ..addAll(
          savedGoalHistory.whereType<Map>().map(
            (e) => seasonGoalRecordFromJson(Map<String, dynamic>.from(e)),
          ),
        );
    }

    final savedCurrentGoal = save['currentSeasonGoal'];
    if (savedCurrentGoal is Map) {
      currentSeasonGoal = seasonGoalFromJson(
        Map<String, dynamic>.from(savedCurrentGoal),
      );
    }

    careerWins = (save['careerWins'] as num?)?.toInt() ?? careerWins;
    undefeatedSeasons =
        (save['undefeatedSeasons'] as num?)?.toInt() ?? undefeatedSeasons;
    hasRetired = save['hasRetired'] ?? hasRetired;
    currentConference = '${save['currentConference'] ?? currentConference}';
    currentSubdivision = Subdivision.values
            .where((s) => s.name == save['currentSubdivision'])
            .firstOrNull ??
        currentSubdivision;
    consecutiveWinningSeasons =
        (save['consecutiveWinningSeasons'] as num?)?.toInt() ??
        consecutiveWinningSeasons;
    userPlayoffAppearances =
        (save['userPlayoffAppearances'] as num?)?.toInt() ??
        userPlayoffAppearances;
    seasonsSinceRealignment =
        (save['seasonsSinceRealignment'] as num?)?.toInt() ??
        seasonsSinceRealignment;

    final savedPlayerStats = save['seasonPlayerStats'];
    if (savedPlayerStats is Map) {
      seasonPlayerStats.clear();
      savedPlayerStats.forEach((name, line) {
        if (line is Map) {
          seasonPlayerStats['$name'] = GamePlayerLine.fromJson(
            Map<String, dynamic>.from(line),
          );
        }
      });
    }

    final savedGameResults = save['gameResults'];
    if (savedGameResults is Map) {
      gameResults.clear();
      savedGameResults.forEach((week, result) {
        final weekIndex = int.tryParse('$week');
        if (weekIndex != null && result is Map) {
          gameResults[weekIndex] = GameResultRecord.fromJson(
            Map<String, dynamic>.from(result),
          );
        }
      });
    }

    final savedInjuries = save['activeInjuries'];
    if (savedInjuries is List) {
      activeInjuries
        ..clear()
        ..addAll(
          savedInjuries.whereType<Map>().map(
            (e) => Injury.fromJson(Map<String, dynamic>.from(e)),
          ),
        );
    }

    final savedMoraleBoosts = save['playerMoraleBoosts'];
    if (savedMoraleBoosts is Map) {
      playerMoraleBoosts
        ..clear()
        ..addAll(
          savedMoraleBoosts.map(
            (name, boost) =>
                MapEntry('$name', (boost as num?)?.toInt() ?? 0),
          ),
        );
    }

    final savedIrreconcilable = save['irreconcilablePlayerNames'];
    if (savedIrreconcilable is List) {
      irreconcilablePlayerNames
        ..clear()
        ..addAll(savedIrreconcilable.map((e) => '$e'));
    }

    final savedRivalrySeries = save['rivalrySeries'];
    if (savedRivalrySeries is Map) {
      rivalrySeries
        ..clear()
        ..addAll(
          savedRivalrySeries.map(
            (name, record) => MapEntry(
              '$name',
              RivalrySeriesRecord.fromJson(Map<String, dynamic>.from(record)),
            ),
          ),
        );
    }

    final savedStatRecords = save['seasonStatRecords'];
    if (savedStatRecords is Map) {
      seasonStatRecords
        ..clear()
        ..addAll(
          savedStatRecords.map(
            (category, record) => MapEntry(
              '$category',
              SeasonStatRecord.fromJson(Map<String, dynamic>.from(record)),
            ),
          ),
        );
    }
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    selectedTeam = widget.team;
    activeCareerId = widget.savedCareer != null
        ? careerKeyFromSave(widget.savedCareer!)
        : (widget.careerId ?? _newCareerId());
    trophyRoom.addAll(widget.initialTrophies);
    nationalHistory.addAll(widget.initialNationalHistory);
    fcsNationalHistory.addAll(widget.initialFcsNationalHistory);
    // Legacy Board: rival league seeding has no ordering hazard (each
    // rival seeds from its own fixed g5Teams prestige, independent of this
    // coach's programPrestige) — safe to do immediately. Skip generating a
    // whole 127-coach league here when a save is about to load one anyway
    // (_loadSavedCareer overwrites this list moments later) — only a save
    // predating this feature still needs the generated fallback.
    final savedRivalCoachList = widget.savedCareer?['rivalCoaches'];
    final savedCareerHasRivalCoaches =
        savedRivalCoachList is List && savedRivalCoachList.isNotEmpty;
    rivalCoaches.addAll(
      widget.initialRivalCoaches.isNotEmpty
          ? widget.initialRivalCoaches
          : savedCareerHasRivalCoaches
          ? const <RivalCoachRecord>[]
          : generateRivalCoachLeague(widget.team.name),
    );
    seasonGoalHistory.addAll(widget.initialSeasonGoalHistory);
    careerWins = widget.initialCareerWins;
    undefeatedSeasons = widget.initialUndefeatedSeasons;
    hasRetired = widget.initialHasRetired;
    programPrestige = widget.team.prestige;
    currentConference = widget.team.conference;
    currentSubdivision = widget.team.subdivision;
    roster = widget.initialRoster ??
        generateRoster(programPrestige, subdivision: currentSubdivision);
    recruits = generateRecruits(
      programPrestige,
      pipelineState: widget.coach.background.hometownState,
      pipelineRegionStates: widget.coach.background.regionStates,
      offensiveScheme: widget.coach.offensiveScheme,
      defensiveScheme: widget.coach.defensiveScheme,
      subdivision: currentSubdivision,
    );
    recruitingNilBudget = recruitingNilBudgetForSeason(programPrestige);
    recruitingNilSpent = 0;
    contractYearsRemaining = contractYearsForTier(
      prestigeTier(programPrestige),
    );
    teamRecords = {for (final team in allTeams) team.name: TeamSeasonRecord()};
    schedule = _generateSchedule();

    if (widget.savedCareer != null) {
      _loadSavedCareer(widget.savedCareer!);
      schedule = _generateSchedule();
      // Defensive backfill: a save should always carry a full 22-player
      // roster (the offseason flow guarantees it before handing control
      // back), but if an older or otherwise short save ever slips through,
      // don't let the user play a season a man down.
      _ensureFullRoster();
    }

    // Legacy Board: a genuinely new career has no goal yet. An old save
    // predating this feature also lands here with it still null — and by
    // this point programPrestige already reflects the loaded value (not
    // widget.team.prestige), so this is always computed against the right
    // number either way.
    currentSeasonGoal ??= seasonGoalFor(programPrestige);

    nextOpponent = currentWeek < schedule.length
        ? _scheduledOpponentFrom(currentWeek)
        : _scheduledOpponentFrom(schedule.length - 1);
    WidgetsBinding.instance.addPostFrameCallback((_) => _autoSaveCareer());
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    // paused: user backgrounded the app. detached: the engine is being torn
    // down. Both are points after which the process may be killed with no
    // further callback, so the career must be persisted right away rather
    // than waiting for the next in-game autosave trigger.
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.detached ||
        state == AppLifecycleState.inactive) {
      _autoSaveCareer();
    }
    super.didChangeAppLifecycleState(state);
  }

  // Interleaves 2 bye weeks into the real 12-game slate, for a real 14-week
  // season. The byes are kept away from the very first and very last week
  // (nobody byes in week 1, and the last week always leads into conference
  // championship week) and at least 3 weeks apart from each other, so they
  // never land back to back.
  List<CollegeTeam?> _generateSchedule({
    List<CollegeTeam>? customNonConference,
    CollegeTeam? rivalry,
    List<int>? customByeWeeks,
  }) {
    final games = _generateTwelveGameSlate(
      customNonConference: customNonConference,
      rivalry: rivalry,
    );

    const totalWeeks = 14;
    final byeWeeks =
        (customByeWeeks != null && isValidByeWeekPlacement(customByeWeeks, totalWeeks: totalWeeks))
        ? customByeWeeks.toSet()
        : generateByeWeeks(rng, totalWeeks: totalWeeks);

    final result = <CollegeTeam?>[];
    var gameIndex = 0;
    for (var week = 0; week < totalWeeks; week++) {
      if (byeWeeks.contains(week)) {
        result.add(null);
      } else {
        result.add(gameIndex < games.length ? games[gameIndex] : null);
        gameIndex++;
      }
    }
    return result;
  }

  List<CollegeTeam> _generateTwelveGameSlate({
    List<CollegeTeam>? customNonConference,
    CollegeTeam? rivalry,
  }) {
    final isIndependent = isIndependentConference(currentConference);

    // allTeams, not g5Teams: FBS and FCS conference names never collide, so
    // this stays exactly as FBS-scoped as before for an FBS team — but for
    // an FCS team, filtering g5Teams alone would find zero conference-mates
    // (every FCS team's real conference-mates live in fcsTeams instead).
    final sameConf = allTeams
        .where(
          (t) =>
              t.conference == currentConference &&
              t.name != widget.team.name,
        )
        .toList();

    final ownSubdivisionPool =
        currentSubdivision == Subdivision.fbs ? g5Teams : fcsTeams;
    final otherSubdivisionPool =
        currentSubdivision == Subdivision.fbs ? fcsTeams : g5Teams;

    final sameSubdivisionNonConf = ownSubdivisionPool
        .where(
          (t) =>
              t.name != widget.team.name &&
              (isIndependent || t.conference != currentConference),
        )
        .toList();
    final crossSubdivisionPool = otherSubdivisionPool.toList();

    sameSubdivisionNonConf.shuffle(rng);
    crossSubdivisionPool.shuffle(rng);

    final ncGames = <CollegeTeam>[];
    final confGames = <CollegeTeam>[];

    if (rivalry != null && rivalry.name != widget.team.name) {
      if (!isIndependent && rivalry.conference == currentConference) {
        confGames.add(rivalry);
      } else {
        ncGames.add(rivalry);
      }
    }

    if (customNonConference != null) {
      // A non-conference rivalry already claimed one of the 3 non-conference
      // slots above — without this cap, a full 3-team custom pick plus that
      // rivalry game silently lost its 3rd pick to the final take(3) below
      // (this was the actual bug: picking 3 games only ever showed 1-2 of
      // them once a rivalry was also set). Independents have no such cap —
      // they fill from a 12-game nationwide pool, not a 3-game budget.
      for (final team in customNonConference) {
        if (!isIndependent && ncGames.length >= 3) break;
        if (team.name != widget.team.name &&
            (isIndependent || team.conference != currentConference) &&
            !ncGames.any((t) => t.name == team.name)) {
          ncGames.add(team);
        }
      }
    }

    if (isIndependent) {
      // Independents have no conference-mates, so the whole 12-game slate
      // is drawn at random from schools nationwide instead of the usual
      // 9 conference + 3 non-conference split — mostly the same
      // subdivision, with room for a handful of cross-subdivision games
      // (an independent has no conference schedule to protect, so this can
      // be more generous than a normal team's single cross-subdivision
      // slot below).
      final independentPool = [...sameSubdivisionNonConf, ...crossSubdivisionPool.take(2)]
        ..shuffle(rng);
      while (ncGames.length < 12 && independentPool.isNotEmpty) {
        final candidate = independentPool[rng.nextInt(independentPool.length)];
        if (!ncGames.any((t) => t.name == candidate.name)) {
          ncGames.add(candidate);
        }
      }
      return ncGames.take(12).toList();
    }

    // At most 1 of the 3 nonconference slots — and only ~40% of seasons —
    // comes from the other subdivision, so an FBS schedule still reads as
    // an FBS schedule (and the reverse for FCS), per "avoid excessive FCS
    // games on one team's schedule." Added directly to ncGames (not just
    // mixed into the random-fill pool below) so a selected cross-
    // subdivision game is actually guaranteed to land on the schedule
    // rather than getting lost among 100+ same-subdivision candidates.
    if (ncGames.length < 3 &&
        rng.nextDouble() < 0.40 &&
        crossSubdivisionPool.isNotEmpty) {
      final candidate = crossSubdivisionPool.first;
      if (!ncGames.any((t) => t.name == candidate.name)) {
        ncGames.add(candidate);
      }
    }

    while (ncGames.length < 3 && sameSubdivisionNonConf.isNotEmpty) {
      final candidate =
          sameSubdivisionNonConf[rng.nextInt(sameSubdivisionNonConf.length)];
      if (!ncGames.any((t) => t.name == candidate.name)) {
        ncGames.add(candidate);
      }
    }

    for (final team in sameConf) {
      if (confGames.length >= 9) break;
      if (!confGames.any((t) => t.name == team.name)) {
        confGames.add(team);
      }
    }

    while (confGames.length < 9) {
      if (sameConf.isNotEmpty) {
        final candidate = sameConf[confGames.length % sameConf.length];
        confGames.add(candidate);
      } else if (sameSubdivisionNonConf.isNotEmpty) {
        confGames.add(
          sameSubdivisionNonConf[rng.nextInt(sameSubdivisionNonConf.length)],
        );
      } else {
        break;
      }
    }

    return [...ncGames.take(3), ...confGames.take(9)];
  }

  // The real opponent for a given week — never a bye, by construction (week
  // 0 and the last week are always kept as real games), but this walks
  // forward defensively in case a reload ever regenerates a schedule whose
  // bye placement no longer lines up with the saved week pointer.
  CollegeTeam _scheduledOpponentFrom(int week) {
    for (var i = week.clamp(0, schedule.length - 1); i < schedule.length; i++) {
      final opponent = schedule[i];
      if (opponent != null) return opponent;
    }
    return schedule.firstWhere((t) => t != null)!;
  }

  double get teamOvr {
    if (roster.isEmpty) {
      return rosterBaseForPrestige(programPrestige).clamp(48, 96).toDouble();
    }
    // The team's overall is the average of the actual starting lineup — no
    // clamping against the program's prestige tier. Prestige (stars) is a
    // separate, slow-moving reputation metric that only shifts a little
    // each offseason via updatedPrestigeAfterSeason (winning culture); team
    // overall should track the real starters immediately as they develop,
    // graduate, or get replaced, even if that temporarily runs ahead of or
    // behind what the program's reputation currently says it "should" be.
    final lineup = starters.isEmpty ? roster : starters;
    final avg =
        lineup.map((p) => p.overall).reduce((a, b) => a + b) / lineup.length;
    return avg.clamp(40, 99);
  }

  int get opponentOvr {
    final livePrestige = _livePrestigeFor(nextOpponent);
    final min = switch (prestigeTier(livePrestige)) {
      1 => 50,
      2 => 58,
      3 => 68,
      4 => 78,
      _ => 88,
    };
    final max = switch (prestigeTier(livePrestige)) {
      1 => 60,
      2 => 68,
      3 => 78,
      4 => 88,
      _ => 99,
    };
    return ((min + max) / 2).round();
  }

  List<CollegeTeam> _rankedTeams() {
    final teams = g5Teams.toList();

    teams.sort((a, b) {
      final ar = teamRecords[a.name] ?? TeamSeasonRecord();
      final br = teamRecords[b.name] ?? TeamSeasonRecord();

      final bPct = br.winPct.compareTo(ar.winPct);
      if (bPct != 0) return bPct;

      final bWins = br.wins.compareTo(ar.wins);
      if (bWins != 0) return bWins;

      final bPrestige = b.prestige.compareTo(a.prestige);
      if (bPrestige != 0) return bPrestige;

      return a.name.compareTo(b.name);
    });

    return teams;
  }

  int get displayRank {
    final ranked = currentSubdivision == Subdivision.fcs
        ? _fcsRankedTeams()
        : _rankedTeams();
    final index = ranked.indexWhere(
      (team) => team.name == widget.team.name,
    );
    return index < 0 ? 260 : index + 1;
  }

  List<CollegeTeam> _standingsForConference(String conference) {
    final teams = g5Teams
        .where((team) => team.conference == conference)
        .toList();

    teams.sort((a, b) {
      final ar = teamRecords[a.name] ?? TeamSeasonRecord();
      final br = teamRecords[b.name] ?? TeamSeasonRecord();

      final aPlayed = max(1, ar.confWins + ar.confLosses);
      final bPlayed = max(1, br.confWins + br.confLosses);
      final aConfPct = ar.confWins / aPlayed;
      final bConfPct = br.confWins / bPlayed;

      final pctCompare = bConfPct.compareTo(aConfPct);
      if (pctCompare != 0) return pctCompare;

      final confWinsCompare = br.confWins.compareTo(ar.confWins);
      if (confWinsCompare != 0) return confWinsCompare;

      final overallWinsCompare = br.wins.compareTo(ar.wins);
      if (overallWinsCompare != 0) return overallWinsCompare;

      final prestigeCompare = prestige100(
        b.prestige,
      ).compareTo(prestige100(a.prestige));
      if (prestigeCompare != 0) return prestigeCompare;

      return a.name.compareTo(b.name);
    });

    return teams;
  }

  List<CollegeTeam> _conferenceStandings() {
    return _standingsForConference(currentConference);
  }

  List<CollegeTeam> get conferenceTopTwo {
    return _conferenceStandings().take(2).toList();
  }

  bool get userMadeConferenceChampionship {
    if (gamesPlayed < 12) return false;
    return conferenceTopTwo.any((team) => team.name == widget.team.name);
  }

  CollegeTeam _conferenceTitleOpponent() {
    final opponent = conferenceTopTwo
        .where((team) => team.name != widget.team.name)
        .toList();
    if (opponent.isNotEmpty) return opponent.first;
    return _bestConferenceOpponent();
  }

  void _beginConferenceChampionship({
    bool openGame = false,
    bool simGame = false,
  }) {
    setState(() {
      seasonPhase = 'confChamp';
      postseasonRound = 1;
      nextOpponent = _conferenceTitleOpponent();
    });

    if (openGame) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _openGameSim();
      });
    }

    if (simGame) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _simNextGame();
      });
    }
  }

  String get recordText => '$wins-$losses';
  String get confText => '$confWins-$confLosses';

  String get jobSecurity {
    if (losses >= 8) return 'HOT SEAT';
    if (losses >= 5) return 'SHAKY';
    return 'SECURE';
  }

  Color get jobSecurityColor {
    if (jobSecurity == 'HOT SEAT') return kRed;
    if (jobSecurity == 'SHAKY') return kGold;
    return kGreen;
  }

  bool get conferenceChampEligible {
    if (gamesPlayed < 12) return false;
    // "Independent" is a bucket in the team data, not a real conference —
    // there's no conference championship for an independent team to play
    // in, so that week is always a simulated bye for them, same as a
    // conference team that didn't finish top 2.
    if (isIndependentConference(currentConference)) return false;
    return _conferenceRankForTeam(widget.team) <= 2;
  }

  bool get cfpEligible => gamesPlayed >= 12 && _userSelectedForCfp;
  bool get bowlEligible => gamesPlayed >= 12 && wins >= 6 && !cfpEligible;

  String get postseasonStatus {
    if (seasonPhase == 'regular') {
      if (gamesPlayed < 12) return 'REGULAR SEASON';
      if (conferenceChampEligible) return 'CONFERENCE CHAMPIONSHIP';
      if (cfpEligible) return 'KP SELECTION';
      if (bowlEligible) return 'BOWL SELECTION';
      return 'SEASON COMPLETE';
    }
    if (seasonPhase == 'confChamp') return 'CONFERENCE CHAMPIONSHIP';
    if (seasonPhase == 'confChampBye') return 'CONFERENCE CHAMPIONSHIP WEEK';
    if (seasonPhase == 'selectionShow') return 'KP SELECTION SHOW';
    if (seasonPhase == 'cfp') return _cfpGameNameForRound(postseasonRound);
    if (seasonPhase == 'bowl') return _assignedBowlName.toUpperCase();
    return 'OFFSEASON';
  }

  bool _isInjured(String name) =>
      activeInjuries.any((i) => i.playerName == name);

  List<Player> _playersAt(String position) {
    return roster
        .where((p) => p.position == position && !_isInjured(p.name))
        .toList()
      ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
  }

  // The exact same real-signal score MoraleScreen shows, plus any
  // persisted boost from talking to this player — the single source of
  // truth for whether a talk is available and what it's worth right now.
  int _moraleForPlayer(Player p) {
    final risk = transferRiskFor(
      p,
      isStarter: starters.any((s) => s.name == p.name),
      offensiveScheme: widget.coach.offensiveScheme,
      defensiveScheme: widget.coach.defensiveScheme,
      boosterApproval: boosterApproval,
    ).riskScore;
    final boost = playerMoraleBoosts[p.name] ?? 0;
    return (100 - risk + boost).clamp(0, 100);
  }

  bool _canTalkToPlayer(Player p) {
    if (recruitingPoints < 5) return false;
    if (irreconcilablePlayerNames.contains(p.name)) return false;
    if (_moraleForPlayer(p) >= 70) return false; // already happy — no need
    return true;
  }

  // A real conversation with real stakes: usually raises morale for 5 RP,
  // but a player who's already deeply unhappy has a real chance of
  // instead telling you the relationship is unreconcilable — permanently
  // blocking a future retention NIL offer to them (_playerRetentionCard).
  void _talkToPlayer(Player p) {
    if (!_canTalkToPlayer(p)) return;

    setState(() {
      recruitingPoints -= 5;
      final morale = _moraleForPlayer(p);
      if (morale < 25 && rng.nextDouble() < 0.25) {
        irreconcilablePlayerNames.add(p.name);
      } else {
        playerMoraleBoosts[p.name] = (playerMoraleBoosts[p.name] ?? 0) + 15;
      }
    });
  }

  // Updates the real head-to-head series against this career's rivalry
  // team (a no-op for every other opponent) and gives a rivalry win real
  // weight — a small prestige and recruiting-buzz bump beyond the normal
  // result, on top of the trophy itself changing hands.
  void _recordRivalryResult(CollegeTeam opponent, bool won) {
    if (rivalryTeam?.name != opponent.name) return;

    final existing =
        rivalrySeries[opponent.name] ??
        const RivalrySeriesRecord(userWins: 0, rivalWins: 0, trophyHolder: '');
    rivalrySeries[opponent.name] = RivalrySeriesRecord(
      userWins: existing.userWins + (won ? 1 : 0),
      rivalWins: existing.rivalWins + (won ? 0 : 1),
      trophyHolder: won ? widget.team.name : opponent.name,
    );

    if (won) {
      programPrestige = (programPrestige + 2).clamp(1, 100);
      recruitingBuzz = (recruitingBuzz + 8).clamp(0, 100);
      weeklyNewsHeadlines.insert(
        0,
        'RIVALRY: ${widget.team.name} keeps the trophy with a win over '
        '${opponent.name}.',
      );
    } else {
      weeklyNewsHeadlines.insert(
        0,
        'RIVALRY: ${opponent.name} takes the trophy back from '
        '${widget.team.name}.',
      );
    }
    if (weeklyNewsHeadlines.length > 10) {
      weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
    }
  }

  // Flags a season's stat leader once they're within reach of an
  // established program record — one alert per category per season, so
  // it reads as real anticipation building rather than a weekly nag.
  void _checkRecordWatch() {
    for (final category in seasonRecordCategoryLabels.keys) {
      final record = seasonStatRecords[category];
      if (record == null) continue;
      if (_recordWatchAlerted.contains(category)) continue;

      String? leaderName;
      var leaderValue = 0;
      for (final entry in seasonPlayerStats.entries) {
        final value = seasonStatValueFor(entry.value, category);
        if (value > leaderValue) {
          leaderValue = value;
          leaderName = entry.key;
        }
      }
      if (leaderName == null) continue;

      final threshold = (record.value * 0.85).round();
      if (leaderValue >= threshold && leaderValue < record.value) {
        _recordWatchAlerted.add(category);
        final label = seasonRecordCategoryLabels[category]!;
        weeklyNewsHeadlines.insert(
          0,
          'RECORD WATCH: $leaderName needs ${record.value - leaderValue} '
          'more $label to break the program record of ${record.value}, '
          'set by ${record.playerName} in Season ${record.season}.',
        );
      }
    }
    if (weeklyNewsHeadlines.length > 10) {
      weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
    }
  }

  // Ticks every active injury down one week, dropping any that just
  // healed. Called once per week regardless of how that week was spent
  // (a game or a bye), so recovery timelines are always real elapsed time.
  void _healInjuriesOneWeek() {
    for (var i = activeInjuries.length - 1; i >= 0; i--) {
      final healed = activeInjuries[i].copyWith(
        weeksRemaining: activeInjuries[i].weeksRemaining - 1,
      );
      if (healed.weeksRemaining <= 0) {
        activeInjuries.removeAt(i);
      } else {
        activeInjuries[i] = healed;
      }
    }
  }

  // A real chance, once per game, that a currently-healthy starter goes
  // down — never a bench player, and never someone already hurt (starters
  // already excludes anyone in activeInjuries via _playersAt).
  void _maybeInjureAPlayer() {
    if (rng.nextDouble() >= 0.12) return;
    final healthyStarters = starters;
    if (healthyStarters.isEmpty) return;

    final victim = healthyStarters[rng.nextInt(healthyStarters.length)];
    final injury = rollInjuryFor(victim.name, currentWeek, rng);
    activeInjuries.add(injury);
    weeklyNewsHeadlines.insert(
      0,
      'INJURY REPORT: ${victim.cleanName} (${victim.position}) is out with '
      'a ${injury.description.toLowerCase()} — expected back in '
      '${injury.weeksRemaining} week${injury.weeksRemaining == 1 ? '' : 's'}.',
    );
    if (weeklyNewsHeadlines.length > 10) {
      weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
    }
  }

  List<Player> get starters {
    final s = <Player>[];
    void add(String pos, int count) => s.addAll(_playersAt(pos).take(count));
    add('QB', 1);
    add('HB', 1);
    add('WR', 2);
    add('TE', 1);
    add('DE', 1);
    add('LB', 1);
    add('DB', 2);
    return s;
  }

  List<Player> get bench {
    final starterNames = starters.map((p) => p.name).toSet();
    return roster.where((p) => !starterNames.contains(p.name)).toList()
      ..sort((a, b) {
        final pos = a.position.compareTo(b.position);
        if (pos != 0) return pos;
        return awardOverall(b).compareTo(awardOverall(a));
      });
  }

  int _rankForTeam(CollegeTeam team) {
    final ranked = _rankedTeams();
    final index = ranked.indexWhere((t) => t.name == team.name);
    return index < 0 ? 999 : index + 1;
  }

  String _rankedDisplayNameForTeam(CollegeTeam team) {
    return rankedDisplayName(team, _rankForTeam(team));
  }

  // FCS's own national ranking — the exact same sort as _rankedTeams(), just
  // scoped to fcsTeams so an FCS team's rank is never diluted by (or
  // confused with) the separate FBS field.
  List<CollegeTeam> _fcsRankedTeams() {
    final teams = fcsTeams.toList();

    teams.sort((a, b) {
      final ar = teamRecords[a.name] ?? TeamSeasonRecord();
      final br = teamRecords[b.name] ?? TeamSeasonRecord();

      final bPct = br.winPct.compareTo(ar.winPct);
      if (bPct != 0) return bPct;

      final bWins = br.wins.compareTo(ar.wins);
      if (bWins != 0) return bWins;

      final bPrestige = b.prestige.compareTo(a.prestige);
      if (bPrestige != 0) return bPrestige;

      return a.name.compareTo(b.name);
    });

    return teams;
  }

  int _fcsRankForTeam(CollegeTeam team) {
    final ranked = _fcsRankedTeams();
    final index = ranked.indexWhere((t) => t.name == team.name);
    return index < 0 ? 999 : index + 1;
  }

  static const List<String> _powerFourConferenceNames = [
    'Southern Crown Conference',
    'Heartland Conference',
    'Atlantic Coalition',
    'Frontier Conference',
  ];

  // Simulates a real winner for a conference championship game between the
  // top two teams in a conference's standings, rather than just projecting
  // the better regular-season record straight through as champion. Reuses
  // the same prestige-based probability curve as _simulateNationalWeek so
  // upsets stay possible.
  String _simulateConferenceChampionshipWinner(List<CollegeTeam> topTwo) {
    if (topTwo.isEmpty) return widget.team.name;
    if (topTwo.length == 1) return topTwo.first.name;
    final a = topTwo[0];
    final b = topTwo[1];
    final aChance = (0.50 + ((a.prestige - b.prestige) * 0.08)).clamp(
      0.20,
      0.80,
    );
    return rng.nextDouble() < aChance ? a.name : b.name;
  }

  // Resolves every Power 4 conference championship that isn't the user's own
  // live-played title game into a real, randomized result, so the KP field
  // is only ever presented as final once actual championship games (not
  // regular-season projections) have decided who's in. Safe to call
  // repeatedly per season — already-resolved conferences are skipped.
  void _resolveOtherConferenceChampionships() {
    _normalizeConferenceRecords();

    for (final conference in _powerFourConferenceNames) {
      if (resolvedConferenceChampions.containsKey(conference)) continue;

      if (currentConference == conference && conferenceChampEligible) {
        // The user is playing this title game live — recorded on completion.
        continue;
      }

      final topTwo = _standingsForConference(conference).take(2).toList();
      resolvedConferenceChampions[conference] =
          _simulateConferenceChampionshipWinner(topTwo);
    }
  }

  CollegeTeam _projectedConferenceChampion(String conference) {
    final resolvedName = resolvedConferenceChampions[conference];
    if (resolvedName != null) {
      return g5Teams.firstWhere(
        (team) => team.name == resolvedName,
        orElse: () => widget.team,
      );
    }

    final conferenceTeams = g5Teams
        .where((team) => team.conference == conference)
        .toList();

    if (conferenceTeams.isEmpty) return widget.team;

    final userWonConference =
        currentConference == conference &&
        trophyRoom.any(
          (trophy) =>
              trophy.year == season && trophy.type == 'Conference Championship',
        );

    if (userWonConference) return widget.team;

    conferenceTeams.sort((a, b) {
      final aRecord = teamRecords[a.name] ?? TeamSeasonRecord();
      final bRecord = teamRecords[b.name] ?? TeamSeasonRecord();

      final conferenceWinCompare = bRecord.confWins.compareTo(aRecord.confWins);
      if (conferenceWinCompare != 0) return conferenceWinCompare;

      final conferenceLossCompare = aRecord.confLosses.compareTo(
        bRecord.confLosses,
      );
      if (conferenceLossCompare != 0) return conferenceLossCompare;

      final overallWinCompare = bRecord.wins.compareTo(aRecord.wins);
      if (overallWinCompare != 0) return overallWinCompare;

      return _rankForTeam(a).compareTo(_rankForTeam(b));
    });

    return conferenceTeams.first;
  }

  List<CollegeTeam> _powerFourConferenceChampions() {
    return _powerFourConferenceNames
        .map(_projectedConferenceChampion)
        .fold<List<CollegeTeam>>(<CollegeTeam>[], (champions, team) {
          if (!champions.any((existing) => existing.name == team.name)) {
            champions.add(team);
          }
          return champions;
        });
  }

  List<CollegeTeam> _cfpSeeds() {
    _normalizeConferenceRecords();

    final nationalRanking = _rankedTeams();
    final selected = <CollegeTeam>[];

    // Every Power 4 conference champion receives a guaranteed bid.
    for (final champion in _powerFourConferenceChampions()) {
      if (!selected.any((team) => team.name == champion.name)) {
        selected.add(champion);
      }
    }

    // Fill the remaining positions with the best available teams nationally.
    for (final team in nationalRanking) {
      if (selected.length >= 12) break;

      if (!selected.any((selectedTeam) => selectedTeam.name == team.name)) {
        selected.add(team);
      }
    }

    // Seed all selected teams according to the national committee ranking.
    selected.sort((a, b) => _rankForTeam(a).compareTo(_rankForTeam(b)));

    return selected.take(12).toList();
  }

  // The FCS 24-team field: every FCS conference's regular-season standings
  // leader gets an auto-bid (mirrors _powerFourConferenceChampions' shape,
  // scaled to all 13 FCS conferences instead of 4 named ones — real FCS
  // conferences don't play a title game, so "champion" is just the best
  // conference record, no simulated championship game needed), then
  // at-large bids fill the rest by national rank, then the whole field is
  // reseeded by rank exactly like _cfpSeeds().
  List<CollegeTeam> _fcsPlayoffSeeds() {
    _normalizeConferenceRecords();

    final nationalRanking = _fcsRankedTeams();
    final selected = <CollegeTeam>[];

    final fcsConferenceNames = fcsTeams
        .map((t) => t.conference)
        .where((conference) => !isIndependentConference(conference))
        .where((conference) => !isPlayoffIneligibleFcsConference(conference))
        .toSet();
    for (final conference in fcsConferenceNames) {
      final standings = _standingsForConference(conference);
      if (standings.isEmpty) continue;
      final leader = standings.first;
      if (!selected.any((team) => team.name == leader.name)) {
        selected.add(leader);
      }
    }

    for (final team in nationalRanking) {
      if (selected.length >= 24) break;
      if (isPlayoffIneligibleFcsConference(team.conference)) continue;
      if (!selected.any((selectedTeam) => selectedTeam.name == team.name)) {
        selected.add(team);
      }
    }

    selected.sort((a, b) => _fcsRankForTeam(a).compareTo(_fcsRankForTeam(b)));

    return selected.take(24).toList();
  }

  bool _userHasPowerFourAutoBid() {
    return isPowerFourConference(currentConference) &&
        trophyRoom.any(
          (trophy) =>
              trophy.year == season && trophy.type == 'Conference Championship',
        );
  }

  bool get _userSelectedForCfp {
    final seeds = currentSubdivision == Subdivision.fcs
        ? _fcsPlayoffSeeds()
        : _cfpSeeds();
    return seeds.any((team) => team.name == widget.team.name);
  }

  int get _userCfpSeed {
    final seeds = currentSubdivision == Subdivision.fcs
        ? _fcsPlayoffSeeds()
        : _cfpSeeds();
    final index = seeds.indexWhere((team) => team.name == widget.team.name);
    return index < 0 ? 999 : index + 1;
  }

  // FCS's bracket has one extra round on top (24 teams + a real first-round
  // bye vs FBS's 12) — see _fcsPlayoffOpponent/_advanceFcsPostseason.
  int get _finalPlayoffRound =>
      currentSubdivision == Subdivision.fcs ? 5 : 4;

  String _cfpGameNameForRound(int round) {
    final seed = _userCfpSeed;

    if (currentSubdivision == Subdivision.fcs) {
      return switch (round) {
        <= 1 => 'FCS PLAYOFF · OPENING ROUND',
        2 => 'FCS PLAYOFF · SECOND ROUND',
        3 => 'FCS PLAYOFF · QUARTERFINAL',
        4 => 'FCS PLAYOFF · SEMIFINAL',
        _ => 'FCS NATIONAL CHAMPIONSHIP',
      };
    }

    if (round <= 1) {
      const firstRoundNames = [
        'Heritage Bowl',
        'Coastline Bowl',
        'Mission Bowl',
        'Grove Bowl',
      ];
      return '${firstRoundNames[(max(seed, 5) - 5).clamp(0, 3)]} · KP FIRST ROUND';
    }

    if (round == 2) {
      const quarterfinalNames = [
        'Arroyo Bowl',
        'Cane Bowl',
        'Saguaro Bowl',
        'Orchard Bowl',
      ];
      return '${quarterfinalNames[(max(seed, 1) - 1) % quarterfinalNames.length]} · KP QUARTERFINAL';
    }

    if (round == 3) {
      return seed.isEven
          ? 'COTTON BOWL · KP SEMIFINAL'
          : 'ORANGE BOWL · KP SEMIFINAL';
    }

    return 'KP NATIONAL CHAMPIONSHIP';
  }

  String _bowlNameForRecord({
    required int teamWins,
    required int teamLosses,
    required CollegeTeam team,
  }) {
    final recordKey =
        teamWins * 31 + teamLosses * 17 + team.name.hashCode.abs();

    final List<String> choices;

    if (teamWins >= 11) {
      choices = const [
        'Grove Bowl',
        'Mission Bowl',
        'Bayfront Bowl',
        'Coastline Bowl',
      ];
    } else if (teamWins == 10) {
      choices = const [
        'Harmony Bowl',
        'Rio Bowl',
        'Neon Bowl',
        'Riverside Bowl',
      ];
    } else if (teamWins == 9) {
      choices = const [
        'Heritage Bowl',
        'Solstice Bowl',
        'Empire Bowl',
        'Queen City Bowl',
      ];
    } else if (teamWins == 8) {
      choices = const [
        'Patriots Bowl',
        'Service Bowl',
        'Ironworks Bowl',
        'Desert Sky Bowl',
      ];
    } else if (teamWins == 7) {
      choices = const [
        'Frontline Bowl',
        'Metroplex Bowl',
        'Mesa Bowl',
        'Buccaneer Bowl',
      ];
    } else {
      choices = const [
        'Beacon Bowl',
        'Boardwalk Bowl',
        'Bayou Bowl',
        'Magnolia Bowl',
      ];
    }

    return choices[recordKey % choices.length];
  }

  String get _assignedBowlName {
    if (assignedBowlName.trim().isNotEmpty) {
      return assignedBowlName;
    }

    return _bowlNameForRecord(
      teamWins: wins,
      teamLosses: losses,
      team: widget.team,
    );
  }

  // Other teams' records should track roughly the same number of games the
  // user has actually played so far, not jump straight to a finished
  // 9-conference/12-total season the moment this runs. This used to be
  // hardcoded to a full season regardless of when in the year it was
  // called — since it's called constantly (every conference-rank check,
  // every standings view), that meant an opponent's record could get
  // padded up to a full season in week 2, then get randomly trimmed back
  // down every time this ran again as the user's own games (and
  // _simulateNationalWeek calls) accumulated past that — the exact reason
  // an opponent could show as 4-0 in week 12 while the user sat at 9-2.
  void _normalizeConferenceRecords() {
    final targetTotal = gamesPlayed.clamp(0, 12);
    final targetConf = (9 * targetTotal / 12).round().clamp(0, 9);

    // Both subdivisions get normalized toward the user's own progress
    // through the season — the user only ever plays in one, but the other
    // subdivision's standings/rankings still need to move realistically
    // (e.g. an FCS team's page, or a cross-subdivision news storyline)
    // rather than sitting frozen at 0-0 all year.
    for (final team in allTeams) {
      final rec = teamRecords[team.name] ?? TeamSeasonRecord();
      normalizeTeamRecordToTarget(
        rec,
        targetTotal: targetTotal,
        targetConf: targetConf,
        prestige: _livePrestigeFor(team),
        rng: rng,
      );
      teamRecords[team.name] = rec;
    }
  }

  int _conferenceRankForTeam(CollegeTeam team) {
    _normalizeConferenceRecords();
    final standings = _standingsForConference(team.conference);
    final index = standings.indexWhere((t) => t.name == team.name);
    return index < 0 ? 999 : index + 1;
  }

  CollegeTeam _bestConferenceOpponent() {
    final teams = g5Teams
        .where(
          (t) =>
              t.conference == currentConference &&
              t.name != widget.team.name,
        )
        .toList();
    teams.sort((a, b) => b.prestige.compareTo(a.prestige));
    return teams.isEmpty ? _scheduledOpponentFrom(0) : teams.first;
  }

  CollegeTeam _playoffOpponent() {
    if (currentSubdivision == Subdivision.fcs) {
      return _fcsPlayoffOpponent();
    }

    final seeds = _cfpSeeds();
    final userIndex = seeds.indexWhere((team) => team.name == widget.team.name);

    if (seeds.isEmpty || userIndex < 0) {
      final fallback = _rankedTeams()
          .where((team) => team.name != widget.team.name)
          .where((team) => !_cfpOpponentsFaced.contains(team.name))
          .toList();
      return fallback.isEmpty ? _scheduledOpponentFrom(0) : fallback.first;
    }

    final seed = userIndex + 1;
    int opponentSeed;

    if (postseasonRound <= 1) {
      opponentSeed = switch (seed) {
        5 => 12,
        6 => 11,
        7 => 10,
        8 => 9,
        9 => 8,
        10 => 7,
        11 => 6,
        12 => 5,
        _ => min(12, max(5, 13 - seed)),
      };
    } else if (postseasonRound == 2) {
      opponentSeed = switch (seed) {
        1 => 8,
        2 => 7,
        3 => 6,
        4 => 5,
        _ => ((seed + 3).clamp(1, 12)),
      };
    } else if (postseasonRound == 3) {
      // Real bracket topology: 1 and 4 share a quarter, 2 and 3 share the
      // other, so they're the semifinal pairing when both hold seed —
      // named explicitly rather than "4 if I'm on the top half," which
      // self-referenced when the user's own seed WAS 4 (see below).
      opponentSeed = switch (seed) {
        1 => 4,
        4 => 1,
        2 => 3,
        3 => 2,
        _ => seed <= 6 ? 4 : 2,
      };
    } else {
      opponentSeed = seed == 1 ? 2 : 1;
    }

    final opponentIndex = (opponentSeed - 1).clamp(0, seeds.length - 1);
    final selectedOpponent = seeds[opponentIndex];

    // A real single-elimination bracket never runs back a matchup, so any
    // team the user already faced this postseason (including themselves,
    // when the formula above self-references) is refused, not just self.
    final valid =
        selectedOpponent.name != widget.team.name &&
        !_cfpOpponentsFaced.contains(selectedOpponent.name);
    if (valid) return selectedOpponent;

    final freshSeed = seeds.where(
      (team) =>
          team.name != widget.team.name &&
          !_cfpOpponentsFaced.contains(team.name),
    );
    if (freshSeed.isNotEmpty) return freshSeed.first;

    final freshRanked = _rankedTeams().where(
      (team) =>
          team.name != widget.team.name &&
          !_cfpOpponentsFaced.contains(team.name),
    );
    return freshRanked.isNotEmpty
        ? freshRanked.first
        : _scheduledOpponentFrom(0);
  }

  // The FCS 24-team bracket: seeds 1-8 get a real first-round bye (only
  // seeds 9-24 play round 1); round 2 is the round of 16 (byes + round-1
  // winners); quarterfinal/semifinal/final follow. Like _playoffOpponent(),
  // this is a seed-index lookup into the fixed opening field, not a live
  // simulation of every other bracket game — the same simplification the
  // FBS bracket already makes, made safe by the identical
  // never-repeat/never-self-reference guard below.
  CollegeTeam _fcsPlayoffOpponent() {
    final seeds = _fcsPlayoffSeeds();
    final userIndex = seeds.indexWhere((team) => team.name == widget.team.name);

    if (seeds.isEmpty || userIndex < 0) {
      final fallback = _fcsRankedTeams()
          .where((team) => team.name != widget.team.name)
          .where((team) => !_cfpOpponentsFaced.contains(team.name))
          .toList();
      return fallback.isEmpty ? _scheduledOpponentFrom(0) : fallback.first;
    }

    final seed = userIndex + 1;
    int opponentSeed;

    if (postseasonRound <= 1) {
      // Opening round: 9v24, 10v23, ... 16v17 (seeds sum to 33). Seeds 1-8
      // hold a bye and should never actually reach this branch (see the
      // postseasonRound seeding in _advanceFcsPostseason), but a safe
      // fallback still clamps them into the round-1 range rather than
      // crashing on an out-of-bracket index.
      opponentSeed = (seed >= 9 && seed <= 24)
          ? 33 - seed
          : (33 - seed).clamp(9, 24);
    } else if (postseasonRound == 2) {
      // Round of 16: byes (1-8) face the better-seeded half of each
      // round-1 pair (9-16); a seed that upset from the 17-24 half
      // inherits that same pairing slot.
      opponentSeed = seed <= 16 ? (17 - seed) : (seed - 16);
    } else if (postseasonRound == 3) {
      // Quarterfinal, named explicitly rather than derived — same lesson
      // as the FBS bracket's round-3 fix earlier this session: a formula
      // that self-references on the user's own seed is a real bug, not a
      // theoretical one.
      opponentSeed = switch (seed) {
        1 => 8,
        8 => 1,
        4 => 5,
        5 => 4,
        2 => 7,
        7 => 2,
        3 => 6,
        6 => 3,
        _ => seed <= 4 ? 8 : 1,
      };
    } else if (postseasonRound == 4) {
      opponentSeed = switch (seed) {
        1 => 4,
        4 => 1,
        2 => 3,
        3 => 2,
        _ => seed <= 2 ? 4 : 2,
      };
    } else {
      opponentSeed = seed == 1 ? 2 : 1;
    }

    final opponentIndex = (opponentSeed - 1).clamp(0, seeds.length - 1);
    final selectedOpponent = seeds[opponentIndex];

    final valid =
        selectedOpponent.name != widget.team.name &&
        !_cfpOpponentsFaced.contains(selectedOpponent.name);
    if (valid) return selectedOpponent;

    final freshSeed = seeds.where(
      (team) =>
          team.name != widget.team.name &&
          !_cfpOpponentsFaced.contains(team.name),
    );
    if (freshSeed.isNotEmpty) return freshSeed.first;

    final freshRanked = _fcsRankedTeams().where(
      (team) =>
          team.name != widget.team.name &&
          !_cfpOpponentsFaced.contains(team.name),
    );
    return freshRanked.isNotEmpty
        ? freshRanked.first
        : _scheduledOpponentFrom(0);
  }

  int _projectedOvrForTeam(CollegeTeam team) {
    final tier = prestigeTier(_livePrestigeFor(team));
    final min = switch (tier) {
      1 => 50,
      2 => 58,
      3 => 68,
      4 => 78,
      _ => 88,
    };
    final max = switch (tier) {
      1 => 60,
      2 => 68,
      3 => 78,
      4 => 88,
      _ => 96,
    };
    return ((min + max) / 2).round();
  }

  CollegeTeam _bowlOpponent() {
    final ranked = _rankedTeams();
    final myWins = wins;
    final myOvr = teamOvr.round();
    // A team already claimed by the KP field plays there, not in a bowl —
    // exclude it so a bowl opponent can never double-book with the playoff.
    final cfpFieldNames = _cfpSeeds().map((t) => t.name).toSet();

    int targetWins;
    int maxOvrGap;

    if (myWins >= 10) {
      targetWins = 9;
      maxOvrGap = 8;
    } else if (myWins == 9) {
      targetWins = 8;
      maxOvrGap = 7;
    } else if (myWins == 8) {
      targetWins = 7;
      maxOvrGap = 6;
    } else if (myWins == 7) {
      targetWins = 7;
      maxOvrGap = 5;
    } else {
      targetWins = 6;
      maxOvrGap = 5;
    }

    final candidates = ranked
        .where((t) => t.name != widget.team.name)
        .where((t) => t.conference != currentConference)
        .where((t) => !cfpFieldNames.contains(t.name))
        .where((t) {
          final rec = teamRecords[t.name] ?? TeamSeasonRecord();
          final oppWins = rec.gamesPlayed == 0 ? targetWins : rec.wins;
          final oppLosses = rec.gamesPlayed == 0
              ? max(12 - oppWins, 0)
              : rec.losses;
          final oppOvr = _projectedOvrForTeam(t);

          final recordFits = (oppWins - targetWins).abs() <= 1 && oppWins >= 6;
          final overallFits = (oppOvr - myOvr).abs() <= maxOvrGap;

          // Avoid giving 6-6/7-5 teams elite opponents.
          final notTooElite =
              myWins >= 9 || (oppWins <= 8 && oppOvr <= myOvr + maxOvrGap);

          // Avoid giving 10+ win teams a weak 6-6 team unless there are no options.
          final notTooWeak = myWins < 9 || oppWins >= 8;

          return recordFits &&
              overallFits &&
              notTooElite &&
              notTooWeak &&
              oppLosses <= 7;
        })
        .toList();

    if (candidates.isNotEmpty) {
      candidates.sort((a, b) {
        final ar = teamRecords[a.name] ?? TeamSeasonRecord();
        final br = teamRecords[b.name] ?? TeamSeasonRecord();

        final aWins = ar.gamesPlayed == 0 ? targetWins : ar.wins;
        final bWins = br.gamesPlayed == 0 ? targetWins : br.wins;
        final aOvr = _projectedOvrForTeam(a);
        final bOvr = _projectedOvrForTeam(b);

        final aScore = (aWins - targetWins).abs() * 10 + (aOvr - myOvr).abs();
        final bScore = (bWins - targetWins).abs() * 10 + (bOvr - myOvr).abs();
        return aScore.compareTo(bScore);
      });

      final top = candidates.take(min(4, candidates.length)).toList();
      return top[rng.nextInt(top.length)];
    }

    final fallback =
        ranked
            .where((t) => t.name != widget.team.name)
            .where((t) => t.conference != currentConference)
            .where((t) => !cfpFieldNames.contains(t.name))
            .toList()
          ..sort((a, b) {
            final aOvr = _projectedOvrForTeam(a);
            final bOvr = _projectedOvrForTeam(b);
            return (aOvr - myOvr).abs().compareTo((bOvr - myOvr).abs());
          });

    return fallback.isEmpty ? _scheduledOpponentFrom(0) : fallback.first;
  }

  // No reveal show here anymore — the best 2 teams in each conference just
  // go play their championship, and everyone else takes conference
  // championship week as a bye. The one real reveal happens after that
  // week is over, once every Power 4 title is actually decided.
  void _advancePostseason() {
    if (currentSubdivision == Subdivision.fcs) {
      _advanceFcsPostseason();
      return;
    }

    _normalizeConferenceRecords();
    // Resolve every Power 4 title game the user isn't personally playing in
    // (all of them, if the user didn't make their own conference championship)
    // so the eventual reveal only reflects actual decided outcomes rather
    // than a regular-season projection.
    _resolveOtherConferenceChampionships();

    if (conferenceChampEligible) {
      setState(() {
        seasonPhase = 'confChamp';
        postseasonRound = 1;
        // The real #2-in-conference team (falls back to _bestConferenceOpponent
        // only if standings data is somehow degenerate) — NOT just whichever
        // conference-mate has the highest static day-one prestige.
        nextOpponent = _conferenceTitleOpponent();
      });
      _autoSaveCareer();
      return;
    }

    setState(() {
      seasonPhase = 'confChampBye';
    });
    _autoSaveCareer();
  }

  void _advanceConfChampBye() {
    setState(() {
      weeklyNewsHeadlines.insert(
        0,
        'CONFERENCE CHAMPIONSHIP WEEK: ${widget.team.name} watches from home '
        'while the top 2 in ${currentConference} play for the title.',
      );
      if (weeklyNewsHeadlines.length > 10) {
        weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
      }
    });
    _advanceFromSelectionShow();
  }

  // FCS's real postseason structure is simpler than FBS's: no conference
  // championship games, no bowls — the regular season just ends and every
  // eligible team goes straight to playoff selection (see
  // _fcsPlayoffSeeds). A team that misses the field goes straight to the
  // offseason instead, exactly like a real FCS team's season actually ends.
  void _advanceFcsPostseason() {
    _normalizeConferenceRecords();

    final conferenceStandings = _standingsForConference(currentConference);
    final wonConference =
        !isIndependentConference(currentConference) &&
        conferenceStandings.isNotEmpty &&
        conferenceStandings.first.name == widget.team.name;
    if (wonConference) {
      final runnerUp = conferenceStandings
          .where((t) => t.name != widget.team.name)
          .toList();
      _addTrophy(
        type: 'FCS Conference Championship',
        title: '${currentConference} Champions',
        opponent: runnerUp.isNotEmpty ? runnerUp.first : widget.team,
      );
    }

    // The FCS-coaching equivalent of the FBS Selection Show — an FBS coach
    // watches SelectionScreen reveal the 12-team field; an FCS coach
    // watches this reveal the 24-team field instead. Each user only ever
    // watches the one that actually applies to their own program.
    final seeds = _fcsPlayoffSeeds();
    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => FcsSelectionScreen(
          team: widget.team,
          seeds: seeds,
          teamRecords: teamRecords,
          onContinue: _applyFcsPlayoffSelection,
        ),
      ),
    );
  }

  void _applyFcsPlayoffSelection() {
    final seeds = _fcsPlayoffSeeds();
    final userSeedIndex = seeds.indexWhere(
      (team) => team.name == widget.team.name,
    );

    setState(() {
      if (userSeedIndex >= 0) {
        seasonPhase = 'cfp';
        // Seeds 1-8 get a real first-round bye, exactly like the FBS
        // bracket's top-4 seeds (see _advanceFromSelectionShow).
        postseasonRound = userSeedIndex < 8 ? 2 : 1;
        madeCfpThisSeason = true;
        _cfpOpponentsFaced.clear();
        nextOpponent = _fcsPlayoffOpponent();
        _cfpOpponentsFaced.add(nextOpponent.name);
      } else {
        // Real FCS has no bowl subsystem — missing the field just ends
        // the season.
        seasonPhase = 'offseason';
      }
    });
    _autoSaveCareer();
  }

  List<Recruit> get committedRecruits {
    return recruits
        .where((r) => r.committedSchool == widget.team.name)
        .toList();
  }

  // _initialRoster() (the offseason step that actually builds next year's
  // roster) only has room for 22 - returning-non-seniors incoming players,
  // and gives recruits first claim on those slots before transfers. Mirror
  // that same math here, live during the season, so a class can't commit
  // more prospects than will ever fit — without this, the overflow used to
  // commit successfully, show up as a "signed" recruit all season, and then
  // silently vanish the moment _initialRoster() truncated the list.
  int get _projectedOpenRecruitSlots {
    final returningNonSeniors = roster
        .where((p) => p.year != 'SR')
        .length;
    return max(0, 22 - returningNonSeniors);
  }

  bool get _recruitingClassHasRoom =>
      committedRecruits.length < _projectedOpenRecruitSlots;

  void _openOffseason() {
    _recordSimulatedNationalTitleIfNeeded();
    _recordSimulatedFcsTitleIfNeeded();

    // A season's results move the program's prestige (and star rating)
    // before the offseason begins, so contract talks, job offers, the
    // retention budget, and the incoming recruiting class all react to it
    // immediately rather than a season late.
    final seasonEndPrestige = updatedPrestigeAfterSeason(
      programPrestige,
      wins,
      losses,
      madeCfp: madeCfpThisSeason,
      wonConference: _wonConferenceChampionshipThisSeason,
      wonTitle: _wonNationalChampionshipThisSeason,
    );

    // Legacy Board: resolve this season's goal, log it, advance every
    // rival coach's season, then generate the upcoming season's goal. This
    // must run here (not in _advanceSeason) because wins/madeCfpThisSeason/
    // the two _wonXThisSeason getters are still valid for the season that
    // JUST ended — _advanceSeason resets all of them a moment later.
    if (currentSeasonGoal != null) {
      final met = goalWasMet(
        currentSeasonGoal!,
        wins: wins,
        wonConference: _wonConferenceChampionshipThisSeason,
        madeCfp: madeCfpThisSeason,
        wonTitle: _wonNationalChampionshipThisSeason,
      );
      seasonGoalHistory.add(
        SeasonGoalRecord(
          year: season,
          description: currentSeasonGoal!.description,
          met: met,
        ),
      );
    }
    careerWins += wins;
    if (losses == 0 && wins > 0) undefeatedSeasons++;

    // The user's own promotion/realignment tracking — same shape as
    // RivalCoachRecord's, evaluated from this season's real, played-out
    // results rather than a simulated season.
    consecutiveWinningSeasons =
        wins > losses ? consecutiveWinningSeasons + 1 : 0;
    if (madeCfpThisSeason) userPlayoffAppearances++;
    seasonsSinceRealignment++;

    // Wraps the user's own tracking into the exact same RivalCoachRecord
    // shape isPromotionEligible/realignmentInvitationFor already know how
    // to judge — reusing that logic instead of a second copy of it. A
    // user-initiated invitation is never automatic like a CPU one (no
    // probability roll here) — it's surfaced for the user to accept or
    // decline in the new "Conference Invitations" offseason step, always
    // when eligible, since only the user needs to actually be asked.
    final userAsRival = RivalCoachRecord(
      coachName: widget.coach.name,
      teamName: widget.team.name,
      currentPrestige: seasonEndPrestige,
      tenureYears: 0,
      careerWins: careerWins,
      careerLosses: 0,
      nationalTitles: _careerFcsNationalTitles,
      conferenceTitles: _careerFcsConferenceTitles,
      bowlWins: 0,
      subdivisionOverride: currentSubdivision,
      consecutiveWinningSeasons: consecutiveWinningSeasons,
      playoffAppearances: userPlayoffAppearances,
      seasonsSinceRealignment: seasonsSinceRealignment,
    );
    pendingRealignmentInvitations = realignmentInvitationOptionsFor(userAsRival);

    for (var i = 0; i < rivalCoaches.length; i++) {
      rivalCoaches[i] = simulateRivalCoachSeason(rivalCoaches[i]);
    }

    // CPU FCS→FBS promotion — same eligibility bar as the user's own
    // "Conference Invitations" offseason step, but resolved silently
    // (no CPU program ever needs a decision screen). Deliberately
    // uncommon (see realignmentInvitationFor's chance param) — promotion
    // should read as a rare event across the whole league each year, not
    // something that happens to several teams every single offseason.
    for (var i = 0; i < rivalCoaches.length; i++) {
      final invite = realignmentInvitationFor(rivalCoaches[i], chance: 0.15);
      if (invite == null) continue;

      final promotedName = rivalCoaches[i].teamName;
      rivalCoaches[i] = rivalCoaches[i].copyWith(
        conferenceOverride: invite.conference,
        subdivisionOverride: Subdivision.fbs,
        consecutiveWinningSeasons: 0,
        seasonsSinceRealignment: 0,
      );
      weeklyNewsHeadlines.insert(
        0,
        'CONFERENCE REALIGNMENT: $promotedName is moving up to FBS, joining the '
        '${invite.conference}.',
      );
    }
    if (weeklyNewsHeadlines.length > 10) {
      weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
    }

    // The program record book: this season's leader per category becomes
    // the new record if they beat it. A category with no prior record
    // just establishes the baseline silently — there's nothing to "break"
    // the very first time a number is ever recorded.
    for (final category in seasonRecordCategoryLabels.keys) {
      String? leaderName;
      var leaderValue = 0;
      for (final entry in seasonPlayerStats.entries) {
        final value = seasonStatValueFor(entry.value, category);
        if (value > leaderValue) {
          leaderValue = value;
          leaderName = entry.key;
        }
      }
      if (leaderName == null || leaderValue <= 0) continue;

      final existing = seasonStatRecords[category];
      if (existing == null || leaderValue > existing.value) {
        seasonStatRecords[category] = SeasonStatRecord(
          value: leaderValue,
          playerName: leaderName,
          season: season,
        );
        if (existing != null) {
          final label = seasonRecordCategoryLabels[category]!;
          weeklyNewsHeadlines.insert(
            0,
            'NEW PROGRAM RECORD: $leaderName set the single-season $label '
            'record at $leaderValue, breaking ${existing.playerName}\'s '
            '${existing.value} from Season ${existing.season}.',
          );
        }
      }
    }
    if (weeklyNewsHeadlines.length > 10) {
      weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
    }

    currentSeasonGoal = seasonGoalFor(seasonEndPrestige);

    final teamForOffseason = CollegeTeam(
      name: widget.team.name,
      conference: currentConference,
      prestige: seasonEndPrestige,
      primary: widget.team.primary,
      secondary: widget.team.secondary,
      subdivision: currentSubdivision,
      emoji: widget.team.emoji,
      mascot: widget.team.mascot,
    );

    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => OffseasonScreen(
          team: teamForOffseason,
          coach: widget.coach,
          season: season,
          wins: wins,
          losses: losses,
          confWins: confWins,
          confLosses: confLosses,
          roster: roster,
          incomingRecruits: committedRecruits,
          contractYearsRemaining: contractYearsRemaining,
          rivalCoaches: rivalCoaches,
          irreconcilablePlayerNames: irreconcilablePlayerNames,
          realignmentInvitations: pendingRealignmentInvitations,
          onFinish: (result) {
            if (result.team.name != widget.team.name) {
              // A new job means a fresh contract — DashboardScreen's own
              // initState computes that from the new team's prestige tier,
              // so there's nothing to carry over from result here.
              Navigator.of(context).pushReplacement(
                MaterialPageRoute(
                  builder: (_) => DashboardScreen(
                    team: result.team,
                    coach: widget.coach,
                    careerId: activeCareerId,
                    initialTrophies: trophyRoom,
                    initialNationalHistory: nationalHistory,
                    initialFcsNationalHistory: fcsNationalHistory,
                    initialRivalCoaches: rivalCoaches,
                    initialSeasonGoalHistory: seasonGoalHistory,
                    initialCareerWins: careerWins,
                    initialUndefeatedSeasons: undefeatedSeasons,
                    initialHasRetired: hasRetired,
                    // The real computed roster from the coaching transition
                    // (players who followed, walk-on backfill) — without
                    // this, the whole "who follows you to the new job"
                    // screen was cosmetic: a brand-new random roster was
                    // silently generated instead.
                    initialRoster: result.roster,
                  ),
                ),
              );
              return;
            }

            setState(() {
              programPrestige = result.team.prestige;
              // An accepted realignment invitation moves the same program
              // to a new conference (and, for FCS→FBS, a new subdivision)
              // without changing the team's name — the "changed jobs"
              // branch above only fires on an actual name change, so this
              // is the path that has to pick up that move.
              currentConference = result.team.conference;
              currentSubdivision = result.team.subdivision;
              // Keeps every UI surface that reads selectedTeam (Legacy
              // Board, the Kingdom masthead, badges) in sync with the same
              // move — selectedTeam otherwise only ever gets set once, at
              // career start/load, and would silently go stale here.
              selectedTeam = CollegeTeam(
                name: selectedTeam.name,
                conference: currentConference,
                prestige: programPrestige,
                primary: selectedTeam.primary,
                secondary: selectedTeam.secondary,
                subdivision: currentSubdivision,
                emoji: selectedTeam.emoji,
                mascot: selectedTeam.mascot,
              );
              roster = result.roster;
              rivalryTeam = result.rivalry;
              nextCustomNonConference = result.customNonConference;
              nextCustomByeWeeks = result.customByeWeeks;
              contractYearsRemaining = result.contractYearsRemaining;
              if (currentConference != widget.team.conference ||
                  currentSubdivision != widget.team.subdivision) {
                consecutiveWinningSeasons = 0;
                seasonsSinceRealignment = 0;
                pendingRealignmentInvitations = [];
              }
            });
            _autoSaveCareer();
            _advanceSeason();
          },
        ),
      ),
    );
  }

  void _advanceSeason() {
    setState(() {
      // Note: roster is intentionally left untouched here. OffseasonScreen
      // already advanced every returning player's class year, applied
      // graduations/draft declarations/transfers, added the signed
      // recruiting class, and filled any remaining walk-on spots — its
      // result was assigned to `roster` in _openOffseason's onFinish just
      // before this method runs. Re-deriving it here would double-advance
      // class years and duplicate the incoming recruiting class.
      season++;
      nationalHistoryRecordedThisSeason = false;
      fcsNationalHistoryRecordedThisSeason = false;
      wins = 0;
      losses = 0;
      confWins = 0;
      confLosses = 0;
      gamesPlayed = 0;
      currentWeek = 0;
      recruitingPoints = 150;
      recruitingWindow = 1;
      recruitingNilBudget = recruitingNilBudgetForSeason(programPrestige);
      recruitingNilSpent = 0;
      commits = 0;
      seasonPhase = 'regular';
      postseasonRound = 0;
      madeCfpThisSeason = false;
      assignedBowlName = '';
      teamRecords = {for (final team in allTeams) team.name: TeamSeasonRecord()};
      resolvedConferenceChampions.clear();
      seasonPlayerStats.clear();
      gameResults.clear();
      activeInjuries.clear();
      playerMoraleBoosts.clear();
      irreconcilablePlayerNames.clear();
      _cfpOpponentsFaced.clear();
      _recordWatchAlerted.clear();
      schedule = _generateSchedule(
        customNonConference: nextCustomNonConference,
        rivalry: rivalryTeam,
        customByeWeeks: nextCustomByeWeeks,
      );
      nextOpponent = _scheduledOpponentFrom(0);
      recruits = generateRecruits(
        programPrestige,
        pipelineState: widget.coach.background.hometownState,
        pipelineRegionStates: widget.coach.background.regionStates,
        offensiveScheme: widget.coach.offensiveScheme,
        defensiveScheme: widget.coach.defensiveScheme,
        subdivision: currentSubdivision,
      );
    });
  }

  void _updateUserAndOpponentRecord({
    required bool won,
    required bool wasConferenceGame,
    required CollegeTeam opponent,
  }) {
    final userRecord = teamRecords[widget.team.name]!;
    final opponentRecord = teamRecords[opponent.name] ?? TeamSeasonRecord();

    if (won) {
      userRecord.wins++;
      opponentRecord.losses++;
      if (wasConferenceGame) {
        userRecord.confWins++;
        opponentRecord.confLosses++;
      }
    } else {
      userRecord.losses++;
      opponentRecord.wins++;
      if (wasConferenceGame) {
        userRecord.confLosses++;
        opponentRecord.confWins++;
      }
    }

    teamRecords[opponent.name] = opponentRecord;
  }

  // Pairs up every OTHER team in the user's own subdivision for a lightweight
  // simulated result (this is display/standings flavor, not a real
  // schedule — see normalizeTeamRecordToTarget for the same philosophy).
  // The other subdivision plays its own week entirely separately so an FBS
  // team and an FCS team are never paired here — that only ever happens
  // through a real scheduled cross-subdivision game via the normal
  // game-result pipeline, never this abstraction.
  void _simulateNationalWeek(CollegeTeam userOpponent) {
    final userSubdivisionPool =
        (currentSubdivision == Subdivision.fbs ? g5Teams : fcsTeams)
            .where(
              (team) =>
                  team.name != widget.team.name &&
                  team.name != userOpponent.name,
            )
            .toList();
    _simulateNationalWeekFor(userSubdivisionPool);

    final otherSubdivisionPool =
        currentSubdivision == Subdivision.fbs ? fcsTeams : g5Teams;
    _simulateNationalWeekFor(otherSubdivisionPool);
  }

  void _simulateNationalWeekFor(List<CollegeTeam> subdivisionPool) {
    final pool = subdivisionPool.toList()..shuffle(rng);

    for (int i = 0; i + 1 < pool.length; i += 2) {
      final a = pool[i];
      final b = pool[i + 1];
      final aRecord = teamRecords[a.name] ?? TeamSeasonRecord();
      final bRecord = teamRecords[b.name] ?? TeamSeasonRecord();

      final aChance =
          (0.50 + ((_livePrestigeFor(a) - _livePrestigeFor(b)) * 0.08)).clamp(
            0.20,
            0.80,
          );
      final aWon = rng.nextDouble() < aChance;
      final conferenceGame =
          a.conference == b.conference && rng.nextDouble() < .65;

      if (aWon) {
        aRecord.wins++;
        bRecord.losses++;
        if (conferenceGame) {
          aRecord.confWins++;
          bRecord.confLosses++;
        }
      } else {
        aRecord.losses++;
        bRecord.wins++;
        if (conferenceGame) {
          aRecord.confLosses++;
          bRecord.confWins++;
        }
      }

      teamRecords[a.name] = aRecord;
      teamRecords[b.name] = bRecord;
    }
  }

  Player _currentStartingQb() {
    final pool = starters.isNotEmpty ? starters : roster;
    if (pool.isEmpty) {
      return Player(
        name: 'Unknown Player',
        position: 'QB',
        overall: 60,
        potential: 70,
        year: 'FR',
        stars: 1,
      );
    }
    return pool.firstWhere((p) => p.position == 'QB', orElse: () => pool.first);
  }

  // Best real starter at QB, HB, and on defense — used for the pregame
  // "team leaders" card so it names actual roster players instead of the
  // random names it used to invent.
  List<Player> _currentTeamLeaders() {
    final pool = starters.isNotEmpty ? starters : roster;
    if (pool.isEmpty) return const [];

    Player? bestAt(List<String> positions) {
      final matches = pool.where((p) => positions.contains(p.position)).toList()
        ..sort((a, b) => b.overall.compareTo(a.overall));
      return matches.isEmpty ? null : matches.first;
    }

    return [
      bestAt(['QB']),
      bestAt(['HB']),
      bestAt(['DE', 'LB', 'DB']),
    ].whereType<Player>().toList();
  }

  // Tops the roster back up to 22 if it's ever short, targeting whichever
  // position is furthest below the ideal shape (same logic the offseason
  // flow's own walk-on fill uses).
  void _ensureFullRoster() {
    if (roster.length >= 22) return;

    while (roster.length < 22) {
      final counts = <String, int>{};
      for (final player in roster) {
        counts[player.position] = (counts[player.position] ?? 0) + 1;
      }

      var neediestPosition = idealRosterPositionCounts.keys.first;
      var worstDeficit = -1 << 30;
      for (final entry in idealRosterPositionCounts.entries) {
        final deficit = entry.value - (counts[entry.key] ?? 0);
        if (deficit > worstDeficit) {
          worstDeficit = deficit;
          neediestPosition = entry.key;
        }
      }

      roster.add(generateWalkOn(programPrestige, neediestPosition));
    }
  }

  Player _playerOfGameForResult(bool won, CollegeTeam opponent) {
    // A loss means the opponent had the standout performance — pull from
    // their real (deterministic, season-stable) roster rather than still
    // crediting one of the user's own players.
    final pool = won
        ? (starters.isNotEmpty ? starters : roster)
        : nationalRosterFor(_liveTeam(opponent), season);
    if (pool.isEmpty) {
      return Player(
        name: 'Unknown Player',
        position: 'QB',
        overall: 60,
        potential: 70,
        year: 'FR',
        stars: 1,
      );
    }

    final offense = pool
        .where((p) => ['QB', 'HB', 'RB', 'WR', 'TE'].contains(p.position))
        .toList();
    final defense = pool
        .where((p) => ['DE', 'DL', 'LB', 'DB', 'CB', 'S'].contains(p.position))
        .toList();
    final candidates = (won || rng.nextInt(100) < 70)
        ? (offense.isNotEmpty ? offense : pool)
        : (defense.isNotEmpty ? defense : pool);

    candidates.sort((a, b) => b.overall.compareTo(a.overall));
    final top = candidates.take(min(4, candidates.length)).toList();
    return top[rng.nextInt(top.length)];
  }

  String _statLineForPlayer(Player p) {
    switch (p.position) {
      case 'QB':
        return '${210 + rng.nextInt(190)} pass yds, ${2 + rng.nextInt(4)} TD';
      case 'HB':
      case 'RB':
        return '${80 + rng.nextInt(120)} rush yds, ${1 + rng.nextInt(3)} TD';
      case 'WR':
      case 'TE':
        return '${65 + rng.nextInt(125)} rec yds, ${1 + rng.nextInt(3)} TD';
      case 'DE':
      case 'DL':
      case 'LB':
        return '${6 + rng.nextInt(8)} tackles, ${1 + rng.nextInt(3)} sacks';
      default:
        return '${5 + rng.nextInt(7)} tackles, ${rng.nextInt(2) + 1} impact plays';
    }
  }

  (int, int) _headlineScoreForResult(bool won) {
    final baseUser = teamOvr.round().clamp(45, 99).toInt();
    final baseOpp = opponentOvr.clamp(45, 99).toInt();
    final strengthGap = ((baseUser - baseOpp) / 4).round();

    var userScore = 17 + rng.nextInt(24) + max(0, strengthGap);
    var oppScore = 17 + rng.nextInt(24) + max(0, -strengthGap);

    if (won && userScore <= oppScore) {
      userScore = oppScore + 1 + rng.nextInt(10);
    }

    if (!won && oppScore <= userScore) {
      oppScore = userScore + 1 + rng.nextInt(10);
    }

    final safeUserScore = userScore.clamp(3, 63).toInt();
    final safeOppScore = oppScore.clamp(3, 63).toInt();

    return (safeUserScore, safeOppScore);
  }

  void _addGameHeadlines({
    required bool won,
    required CollegeTeam opponent,
    // Real numbers from a watched GameSimScreen run, when available. When
    // the game was resolved via quick-sim instead, these are null and we
    // fall back to generating placeholder numbers — but a watched game must
    // never have its headline contradict the score/plays the user just saw.
    int? realUserScore,
    int? realOpponentScore,
    String? realPlayerOfGameName,
    String? realPlayerOfGameLine,
  }) {
    final int userScore;
    final int opponentScore;
    if (realUserScore != null && realOpponentScore != null) {
      userScore = realUserScore;
      opponentScore = realOpponentScore;
    } else {
      (userScore, opponentScore) = _headlineScoreForResult(won);
    }

    final weekLabel = seasonPhase == 'regular'
        ? 'Week ${currentWeek + 1}'
        : postseasonStatus;
    final resultHeadline = won
        ? '$weekLabel: ${selectedTeam.displayName} beats ${opponent.displayName} $userScore-$opponentScore'
        : '$weekLabel: ${selectedTeam.displayName} falls to ${opponent.displayName} $opponentScore-$userScore';

    final String playerHeadline;
    if (realPlayerOfGameName != null && realPlayerOfGameLine != null) {
      playerHeadline =
          '$weekLabel Player of the Game: $realPlayerOfGameName — $realPlayerOfGameLine';
    } else {
      final player = _playerOfGameForResult(won, opponent);
      final playerLine = _statLineForPlayer(player);
      final playerTag = won
          ? player.position
          : '${player.position}, ${opponent.name}';
      playerHeadline =
          '$weekLabel Player of the Game: ${player.cleanName} ($playerTag) — $playerLine';
    }
    final lastWeekHeadline = gameRecapHeadline(
      teamName: selectedTeam.displayName,
      opponentName: opponent.displayName,
      rng: rng,
    );

    weeklyNewsHeadlines.insert(0, playerHeadline);
    weeklyNewsHeadlines.insert(0, resultHeadline);
    weeklyNewsHeadlines.insert(2, lastWeekHeadline);

    if (weeklyNewsHeadlines.length > 10) {
      weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
    }
  }

  String _committeeSeasonReview() {
    if (_userHasPowerFourAutoBid()) {
      return '${widget.team.name} won the ${currentConference} Championship and receives a guaranteed Power 4 conference-champion bid to the 12-team KP.';
    }
    final powerFourChamp =
        isPowerFourConference(currentConference) &&
        trophyRoom.any(
          (t) => t.year == season && t.type == 'Conference Championship',
        );

    if (powerFourChamp) {
      return 'The committee values ${widget.team.name} as a ${currentConference} champion. Winning a Power 4 conference title gives this team an automatic KP bid.';
    }

    if (displayRank <= 12 && wins >= 10) {
      return '${widget.team.name} finished $recordText with a playoff-level resume. The committee rewards the strong record, ranking, and quality season with a KP spot.';
    }

    if (wins >= 9) {
      return '${widget.team.name} had a strong $recordText season, but the committee felt the resume was just outside the KP field. This team earns a strong bowl destination.';
    }

    if (wins >= 6) {
      return '${widget.team.name} finished bowl eligible at $recordText. The committee sends the program to a bowl game after a solid season.';
    }

    return '${widget.team.name} finished $recordText. The committee did not see enough wins for the postseason, so the season ends here.';
  }

  // Runs after conference championship week concludes (win or lose). The
  // first reveal show only ever announced "you're headed to the
  // conference championship" for eligible teams — it had no way to know
  // the real KP/bowl fate yet. This is the actual reveal of that fate,
  // now that it's decided.
  void _advanceFromSelectionShow() {
    _normalizeConferenceRecords();
    final seeds = _cfpSeeds();
    final userInCfp = seeds.any((team) => team.name == widget.team.name);
    final userBowlEligible = !userInCfp && wins >= 6;

    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => SelectionScreen(
          team: widget.team,
          season: season,
          record: recordText,
          wins: wins,
          losses: losses,
          confWins: confWins,
          confLosses: confLosses,
          rank: displayRank,
          teamOvr: teamOvr.round(),
          teamRecords: teamRecords,
          conferenceChampEligible: false,
          cfpEligible: userInCfp,
          bowlEligible: userBowlEligible,
          existingAssignedBowlName: assignedBowlName,
          postConferenceChamp: true,
          cfpField: seeds,
          onContinue: (SelectionResult result) {
            setState(() {
              if (result.bowlName != null &&
                  result.bowlName!.trim().isNotEmpty) {
                assignedBowlName = result.bowlName!;
              }
              if (result.phase == 'cfp') {
                seasonPhase = 'cfp';
                // The bracket screen promises seeds 1-4 a real first-round
                // bye — without this, everyone (including a #1 seed) was
                // forced to play an extra "round 1" game that shouldn't
                // exist for them.
                final userSeedIndex = seeds.indexWhere(
                  (team) => team.name == widget.team.name,
                );
                postseasonRound = (userSeedIndex >= 0 && userSeedIndex < 4)
                    ? 2
                    : 1;
                madeCfpThisSeason = true;
                // A fresh bracket run — clear anyone tracked from an
                // earlier postseason before picking this run's opponents.
                _cfpOpponentsFaced.clear();
                nextOpponent = _playoffOpponent();
                _cfpOpponentsFaced.add(nextOpponent.name);
              } else if (result.phase == 'bowl') {
                seasonPhase = 'bowl';
                postseasonRound = 1;
                nextOpponent = _bowlOpponent();
              } else {
                seasonPhase = 'offseason';
              }
            });
            _autoSaveCareer();
          },
        ),
      ),
    );
  }

  // Win probability for the user's side of a matchup. A dead-even overall
  // rating (diff == 0) resolves 65/35 in the user's favor — that bias tapers
  // to nothing by the time either side has a clear ratings edge, so blowout
  // odds are untouched. The national championship gets one extra, deliberately
  // tiny nudge on top, since the user has never won one across any save.
  double _userGameWinChance(
    double teamOverall,
    double opponentOverall, {
    bool isNationalChampionship = false,
  }) {
    final diff = teamOverall - opponentOverall;
    final closeGameBias = 0.15 * (1 - (diff.abs() / 6).clamp(0.0, 1.0));
    final titleGameBias = isNationalChampionship ? 0.03 : 0.0;
    return (0.5 + diff * 0.026 + closeGameBias + titleGameBias).clamp(
      0.10,
      0.90,
    );
  }

  // Runs a scheduled bye week — no game, just a week passing. Reused for
  // both the 2 regular-season byes and the conference-championship-week
  // "bye" a team gets when it isn't one of the conference's top 2.
  void _advanceByeWeek({String label = 'BYE WEEK'}) {
    setState(() {
      weeklyNewsHeadlines.insert(
        0,
        byeWeekHeadline(teamName: widget.team.name, label: label, rng: rng),
      );
      if (weeklyNewsHeadlines.length > 10) {
        weeklyNewsHeadlines.removeRange(10, weeklyNewsHeadlines.length);
      }
      _healInjuriesOneWeek();
      currentWeek++;
      if (currentWeek < schedule.length) {
        nextOpponent = _scheduledOpponentFrom(currentWeek);
      }
    });
    _autoSaveCareer();
  }

  bool get _isByeWeek =>
      seasonPhase == 'regular' &&
      currentWeek < schedule.length &&
      schedule[currentWeek] == null;

  void _simNextGame() {
    if (seasonPhase == 'selectionShow') {
      _advanceFromSelectionShow();
      return;
    }

    if (seasonPhase == 'confChampBye') {
      _advanceConfChampBye();
      return;
    }

    if (seasonPhase == 'regular' && currentWeek >= schedule.length) {
      _advancePostseason();
      return;
    }

    if (_isByeWeek) {
      _advanceByeWeek();
      return;
    }

    if (seasonPhase == 'offseason') {
      AdManager.showAd(context, onContinue: _openOffseason);
      return;
    }

    final myChance = _userGameWinChance(
      teamOvr.toDouble(),
      opponentOvr.toDouble(),
      isNationalChampionship: seasonPhase == 'cfp' && postseasonRound >= _finalPlayoffRound,
    );
    final won = rng.nextDouble() < myChance;
    final (genUserScore, genOpponentScore) = _headlineScoreForResult(won);

    _applyGameResult(
      GameCompletionResult(
        won: won,
        userScore: genUserScore,
        opponentScore: genOpponentScore,
        pressConference: PressConferenceResult(
          tone: 'Stay Composed',
          quote: won
              ? 'We handled our business, but there is still work to do.'
              : 'We will study it, correct it, and move forward together.',
          mediaReaction: won
              ? 'The media views the response as focused and professional.'
              : 'The media views the response as calm and accountable.',
          mediaDelta: 2,
          moraleDelta: won ? 2 : 1,
          boosterDelta: won ? 1 : 0,
          recruitingDelta: won ? 1 : 0,
        ),
      ),
    );
  }

  void _addTrophy({
    required String type,
    required String title,
    required CollegeTeam opponent,
  }) {
    trophyRoom.add(
      TrophyEntry(
        year: season,
        type: type,
        title: title,
        opponent: opponent.name,
        team: widget.team.name,
      ),
    );
  }

  String _championshipScore(bool won) {
    final userScore = won ? 27 + rng.nextInt(18) : 17 + rng.nextInt(14);
    final oppScore = won
        ? max(10, userScore - (3 + rng.nextInt(14)))
        : userScore + (3 + rng.nextInt(14));
    return won ? '$userScore-$oppScore' : '$oppScore-$userScore';
  }

