  void _recordSimulatedNationalTitleIfNeeded() {
    if (nationalHistoryRecordedThisSeason) return;

    final contenders = _rankedTeams()
        .where((t) => t.name != widget.team.name)
        .take(12)
        .toList();

    if (contenders.length < 2) return;

    contenders.shuffle(rng);
    final a = contenders[0];
    final b = contenders[1];
    final aChance =
        (0.50 + ((prestige100(_livePrestigeFor(a)) - prestige100(_livePrestigeFor(b))) / 220))
            .clamp(.38, .62);
    final aWon = rng.nextDouble() < aChance;
    final winner = aWon ? a : b;
    final loser = aWon ? b : a;
    final winnerScore = 24 + rng.nextInt(22);
    final loserScore = max(10, winnerScore - (3 + rng.nextInt(18)));

    _recordNationalTitleHistory(
      winner: winner.name,
      loser: loser.name,
      score: '$winnerScore-$loserScore',
    );
  }

  // Same fallback simulation as _recordSimulatedNationalTitleIfNeeded, but
  // for the FCS field — the FCS national championship still gets decided
  // and logged every season even when the user isn't the one playing in it
  // (including every season a user coaches in FBS at all).
  void _recordSimulatedFcsTitleIfNeeded() {
    if (fcsNationalHistoryRecordedThisSeason) return;

    final contenders = _fcsRankedTeams()
        .where((t) => t.name != widget.team.name)
        .take(24)
        .toList();

    if (contenders.length < 2) return;

    contenders.shuffle(rng);
    final a = contenders[0];
    final b = contenders[1];
    final aChance =
        (0.50 + ((prestige100(_livePrestigeFor(a)) - prestige100(_livePrestigeFor(b))) / 220))
            .clamp(.38, .62);
    final aWon = rng.nextDouble() < aChance;
    final winner = aWon ? a : b;
    final loser = aWon ? b : a;
    final winnerScore = 24 + rng.nextInt(22);
    final loserScore = max(10, winnerScore - (3 + rng.nextInt(18)));

    _recordFcsNationalTitleHistory(
      winner: winner.name,
      loser: loser.name,
      score: '$winnerScore-$loserScore',
    );
  }

  // Folds this game's real box score into the season accumulator. A
  // watched game already built its box score live, play by play — that
  // map is used directly so the recorded stats always match exactly what
  // was shown on screen during the game. A quick-simmed game never
  // generated any live plays, so its box score is derived after the fact
  // from the (real, already-decided) score and event counts instead.
  Map<String, GamePlayerLine> _recordGameStats(
    GameCompletionResult completion,
  ) {
    final Map<String, GamePlayerLine> gameLines;

    if (completion.playerLines != null) {
      gameLines = completion.playerLines!;
    } else {
      final userScore = completion.userScore ?? 0;
      final teamBigPlaysCount = completion.teamBigPlays ?? 0;
      final teamTurnoversCommitted = completion.teamTurnovers ?? 0;

      final totalYards = gameTotalYardsFor(
        score: userScore,
        bigPlays: teamBigPlaysCount,
        turnovers: teamTurnoversCommitted,
      );

      final decomposed = decomposeScoreIntoScoring(userScore);
      final turnoversForced = completion.opponentTurnovers ?? rng.nextInt(4);

      gameLines = attributeGameStatsToRoster(
        starters: starters,
        teamTDs: decomposed.tds,
        teamFGs: decomposed.fgs,
        teamTotalYards: totalYards,
        turnoversForced: turnoversForced,
        rng: rng,
      );
    }

    for (final entry in gameLines.entries) {
      seasonPlayerStats[entry.key] =
          (seasonPlayerStats[entry.key] ?? GamePlayerLine.zero) + entry.value;
    }

    return gameLines;
  }

  void _applyGameResult(GameCompletionResult completion) {
    final won = completion.won;
    final press = completion.pressConference;
    String? celebrationTitle;
    String? celebrationSubtitle;
    bool celebrationConfetti = false;
    final playedOpponent = nextOpponent;

    // A result landing deserves to be felt, not just read — this also
    // covers the quick-sim path, which never touches GameSimScreen's
    // play-by-play haptics.
    won ? HapticFeedback.mediumImpact() : HapticFeedback.selectionClick();

    setState(() {
      mediaReputation = (mediaReputation + press.mediaDelta).clamp(0, 100);
      playerMorale = (playerMorale + press.moraleDelta).clamp(0, 100);
      boosterApproval = (boosterApproval + press.boosterDelta).clamp(0, 100);
      recruitingBuzz = (recruitingBuzz + press.recruitingDelta).clamp(0, 100);
      fanHappiness = (fanHappiness + (won ? 4 : -5)).clamp(0, 100);
      lastPressTone = press.tone;
      lastPressQuote = press.quote;
      weeklyNewsHeadlines.insert(
        0,
        pressRoomHeadline(
          coachName: widget.coach.name,
          toneLower: press.tone.toLowerCase(),
          won: won,
          rng: rng,
        ),
      );

      final gameLines = _recordGameStats(completion);
      _healInjuriesOneWeek();
      _maybeInjureAPlayer();

      if (seasonPhase == 'regular') {
        final wasConfGame = gamesPlayed >= 3;

        _addGameHeadlines(
          won: won,
          opponent: playedOpponent,
          realUserScore: completion.userScore,
          realOpponentScore: completion.opponentScore,
          realPlayerOfGameName: completion.playerOfGameName,
          realPlayerOfGameLine: completion.playerOfGameLine,
        );

        final (resolvedUserScore, resolvedOpponentScore) =
            (completion.userScore != null && completion.opponentScore != null)
            ? (completion.userScore!, completion.opponentScore!)
            : _headlineScoreForResult(won);
        gameResults[currentWeek] = GameResultRecord(
          opponentName: playedOpponent.name,
          userScore: resolvedUserScore,
          opponentScore: resolvedOpponentScore,
          won: won,
          playerOfGameName: completion.playerOfGameName,
          playerOfGameLine: completion.playerOfGameLine,
          boxScore: gameLines,
        );

        gamesPlayed++;

        if (won) {
          wins++;
          if (wasConfGame) confWins++;
        } else {
          losses++;
          if (wasConfGame) confLosses++;
        }

        _updateUserAndOpponentRecord(
          won: won,
          wasConferenceGame: wasConfGame,
          opponent: playedOpponent,
        );
        _simulateNationalWeek(playedOpponent);
        _generateLivingWorldHeadlines(userWon: won);
        _recordRivalryResult(playedOpponent, won);
        _checkRecordWatch();

        if (gamesPlayed == 10) {
          _finalizeRecruitingClass();
        }

        currentWeek++;
        if (currentWeek < schedule.length) {
          nextOpponent = _scheduledOpponentFrom(currentWeek);
        }

        if (gamesPlayed == 3 || gamesPlayed == 6 || gamesPlayed == 9) {
          recruitingWindow = (gamesPlayed ~/ 3).clamp(1, 3);
          recruitingPoints = 150;
          _processRecruitDecisions();
        }
      } else if (seasonPhase == 'confChamp') {
        _addGameHeadlines(
          won: won,
          opponent: playedOpponent,
          realUserScore: completion.userScore,
          realOpponentScore: completion.opponentScore,
          realPlayerOfGameName: completion.playerOfGameName,
          realPlayerOfGameLine: completion.playerOfGameLine,
        );

        if (won) {
          wins++;
          celebrationTitle = 'CONFERENCE CHAMPIONS';
          celebrationSubtitle =
              '${widget.team.name} defeats ${playedOpponent.name} to win the ${currentConference} Championship.';
          HapticFeedback.heavyImpact();
          _addTrophy(
            type: 'Conference Championship',
            title: '${currentConference} Champions',
            opponent: playedOpponent,
          );
          resolvedConferenceChampions[currentConference] =
              widget.team.name;

          seasonPhase = 'selectionShow';
          assignedBowlName = '';
          nextOpponent =
              _cfpSeeds().any((team) => team.name == widget.team.name)
              ? _playoffOpponent()
              : (wins >= 6 ? _bowlOpponent() : nextOpponent);
        } else {
          losses++;
          resolvedConferenceChampions[currentConference] =
              playedOpponent.name;
          seasonPhase = 'selectionShow';
          assignedBowlName = '';
        }
      } else if (seasonPhase == 'cfp') {
        _addGameHeadlines(
          won: won,
          opponent: playedOpponent,
          realUserScore: completion.userScore,
          realOpponentScore: completion.opponentScore,
          realPlayerOfGameName: completion.playerOfGameName,
          realPlayerOfGameLine: completion.playerOfGameLine,
        );

        final isFcsRun = currentSubdivision == Subdivision.fcs;
        final finalRound = _finalPlayoffRound;

        if (won && postseasonRound < finalRound) {
          wins++;
          postseasonRound++;
          nextOpponent = _playoffOpponent();
          _cfpOpponentsFaced.add(nextOpponent.name);
        } else {
          if (won) {
            wins++;
            celebrationTitle = isFcsRun
                ? 'FCS NATIONAL CHAMPIONS'
                : 'NATIONAL CHAMPIONS';
            celebrationSubtitle = isFcsRun
                ? '${widget.team.name} finishes the run and wins the FCS National Championship.'
                : '${widget.team.name} finishes the run and wins the National Championship.';
            celebrationConfetti = true;
            HapticFeedback.heavyImpact();
            final titleScore = _championshipScore(true);
            _addTrophy(
              type: isFcsRun ? 'FCS National Championship' : 'National Championship',
              title: isFcsRun ? 'FCS National Champions' : 'National Champions',
              opponent: playedOpponent,
            );
            if (isFcsRun) {
              _recordFcsNationalTitleHistory(
                winner: widget.team.name,
                loser: playedOpponent.name,
                score: titleScore,
              );
            } else {
              _recordNationalTitleHistory(
                winner: widget.team.name,
                loser: playedOpponent.name,
                score: titleScore,
              );
            }
          } else {
            losses++;
            if (postseasonRound >= finalRound) {
              final titleScore = _championshipScore(false);
              if (isFcsRun) {
                _recordFcsNationalTitleHistory(
                  winner: playedOpponent.name,
                  loser: widget.team.name,
                  score: titleScore,
                );
              } else {
                _recordNationalTitleHistory(
                  winner: playedOpponent.name,
                  loser: widget.team.name,
                  score: titleScore,
                );
              }
            }
          }
          seasonPhase = 'offseason';
        }
      } else if (seasonPhase == 'bowl') {
        _addGameHeadlines(
          won: won,
          opponent: playedOpponent,
          realUserScore: completion.userScore,
          realOpponentScore: completion.opponentScore,
          realPlayerOfGameName: completion.playerOfGameName,
          realPlayerOfGameLine: completion.playerOfGameLine,
        );

        if (won) {
          wins++;
          celebrationTitle = '${_assignedBowlName.toUpperCase()} CHAMPIONS';
          celebrationSubtitle =
              '${widget.team.name} defeats ${playedOpponent.name} to win the $_assignedBowlName.';
          _addTrophy(
            type: 'Bowl Win',
            title: '$_assignedBowlName Champions',
            opponent: playedOpponent,
          );
        } else {
          losses++;
        }
        seasonPhase = 'offseason';
      }
    });

    _autoSaveCareer();

    if (celebrationTitle != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        Navigator.of(context).push(
          MaterialPageRoute(
            builder: (_) => ChampionshipCelebrationScreen(
              title: celebrationTitle!,
              subtitle: celebrationSubtitle ?? '',
              team: widget.team,
              record: recordText,
              confetti: celebrationConfetti,
            ),
          ),
        );
      });
    }
  }

  Future<void> _simToMidpoint() async {
    if (seasonPhase != 'regular') return;
    while (gamesPlayed < 6) {
      _simNextGame();
      // Yield to the event loop so Flutter can paint a frame between games —
      // without this the score/records never visibly update until the whole
      // run finishes, since a tight synchronous loop starves the scheduler.
      await Future.delayed(Duration.zero);
    }
  }

  Future<void> _simRegularSeasonEnd() async {
    if (seasonPhase != 'regular') return;
    while (seasonPhase == 'regular' && currentWeek < schedule.length) {
      _simNextGame();
      await Future.delayed(Duration.zero);
    }
  }

  void _openGameSim() {
    if (seasonPhase == 'selectionShow') {
      _advanceFromSelectionShow();
      return;
    }

    if (seasonPhase == 'confChampBye') {
      _advanceConfChampBye();
      return;
    }

    if (seasonPhase == 'regular' && currentWeek >= schedule.length) {
      _advancePostseason();
      return;
    }

    if (_isByeWeek) {
      _advanceByeWeek();
      return;
    }

    if (seasonPhase == 'offseason') {
      AdManager.showAd(context, onContinue: _openOffseason);
      return;
    }

    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => GameSimScreen(
          team: widget.team,
          opponent: nextOpponent,
          teamOvr: teamOvr.round(),
          opponentOvr: opponentOvr,
          teamStartingQb: _currentStartingQb(),
          opponentStartingQb: nationalStartingQbFor(nextOpponent, season),
          teamLeaders: _currentTeamLeaders(),
          teamStarters: starters,
          isNationalChampionship: seasonPhase == 'cfp' && postseasonRound >= _finalPlayoffRound,
          userOffensiveScheme: widget.coach.offensiveScheme,
          userDefensiveScheme: widget.coach.defensiveScheme,
          opponentOffensiveScheme: offensiveSchemeFor(nextOpponent, season),
          opponentDefensiveScheme: defensiveSchemeFor(nextOpponent, season),
          onFinished: _applyGameResult,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final pages = [
      _dashboardTab(),
      _rosterTab(),
      _playTab(),
      _recruitTab(),
      _menuTab(),
    ];

    return Scaffold(
      backgroundColor: GKColors.ledgerBlack,
      body: SafeArea(
        child: Column(
          children: [
            _kingdomMasthead(),
            Expanded(
              child: AnimatedSwitcher(
                duration: const Duration(milliseconds: 260),
                switchInCurve: Curves.easeOutCubic,
                switchOutCurve: Curves.easeInCubic,
                child: KeyedSubtree(
                  key: ValueKey(selectedTab),
                  child: pages[selectedTab],
                ),
              ),
            ),
            _commandDock(),
          ],
        ),
      ),
    );
  }

  String get _weekDisplay {
    if (seasonPhase == 'regular') {
      if (currentWeek >= schedule.length) return 'POSTSEASON';
      return _isByeWeek ? 'BYE WEEK' : 'WEEK ${currentWeek + 1}';
    }

    if (seasonPhase == 'confChampBye') return 'CONFERENCE TITLE (BYE)';
    if (seasonPhase == 'selectionShow') return 'SELECTION SHOW';
    if (seasonPhase == 'confChamp') return 'CONFERENCE TITLE';
    if (seasonPhase == 'cfp') return 'KP ROUND $postseasonRound';
    if (seasonPhase == 'bowl') return 'BOWL WEEK';
    return 'OFFSEASON';
  }

  String get _advanceLabel {
    if (seasonPhase == 'offseason') return 'Advance to Offseason';
    if (seasonPhase == 'selectionShow') return 'Reveal Postseason';
    if (seasonPhase == 'confChampBye')
      return 'Advance Past Conference Championship Week';
    if (gamesPlayed >= 12 && seasonPhase == 'regular') {
      return conferenceChampEligible
          ? 'Play Conference Championship'
          : 'Advance to Conference Championship Week';
    }
    if (seasonPhase == 'cfp') return 'Play KP Game';
    if (seasonPhase == 'bowl') return 'Play Bowl Game';
    if (seasonPhase == 'confChamp') return 'Play Conference Championship';
    if (_isByeWeek) return 'Advance Past Bye Week';
    return 'Advance to Week ${currentWeek + 1}';
  }

  // True once the regular season's 12 games are done but the postseason
  // destination hasn't been decided yet (Selection Show hasn't run) —
  // there's no real "next opponent" to show in this window.
  bool get _seasonJustEnded => gamesPlayed >= 12 && seasonPhase == 'regular';

  String get _seasonCompleteDescription {
    final next = conferenceChampEligible
        ? 'Advance to play for the conference title.'
        : 'You didn\'t finish top 2 in your conference, so championship week is a bye for you — advance through it to see your KP or bowl fate once every Power 4 title is decided.';
    return 'Your regular season is complete at $recordText. $next';
  }

  String get _gameLocation {
    return gamesPlayed.isEven ? 'AWAY' : 'HOME';
  }

  String get _weatherLabel {
    final value =
        (season * 19 + gamesPlayed * 11 + nextOpponent.name.length) % 5;

    return switch (value) {
      0 => 'Clear · 64°',
      1 => 'Cloudy · 58°',
      2 => 'Light rain · 51°',
      3 => 'Windy · 47°',
      _ => 'Clear · 72°',
    };
  }

  String get _broadcastLabel {
    if (displayRank <= 15 || _rankForTeam(nextOpponent) <= 15) {
      return 'NATIONAL TV';
    }
    if (rivalryTeam?.name == nextOpponent.name) return 'RIVALRY NETWORK';
    return gamesPlayed >= 8 ? 'PRIMETIME' : 'REGIONAL TV';
  }

  double get _projectedSpread {
    final raw = (teamOvr - opponentOvr) * .72;
    final rounded = (raw * 2).round() / 2;
    return rounded.clamp(-28, 28).toDouble();
  }

  String get _spreadLabel {
    final spread = _projectedSpread;

    if (spread == 0) return 'PICK';
    return spread > 0
        ? '${widget.team.name} -${spread.toStringAsFixed(1)}'
        : '${nextOpponent.name} -${spread.abs().toStringAsFixed(1)}';
  }

  String get _matchupStakes {
    if (seasonPhase == 'confChamp') {
      return 'Conference championship and possible automatic KP bid';
    }
    if (seasonPhase == 'cfp') return 'Win or the season ends';
    if (seasonPhase == 'bowl') return 'Finish the season with a trophy';
    if (rivalryTeam?.name == nextOpponent.name) {
      final series = rivalrySeries[nextOpponent.name];
      if (series == null || (series.userWins == 0 && series.rivalWins == 0)) {
        return 'Rivalry pride and recruiting momentum — the series starts here';
      }
      final seriesText = series.userWins >= series.rivalWins
          ? 'you lead the series ${series.userWins}-${series.rivalWins}'
          : '${nextOpponent.name} leads the series ${series.rivalWins}-${series.userWins}';
      final holderText = series.trophyHolder == widget.team.name
          ? 'you hold the trophy'
          : '${nextOpponent.name} holds the trophy';
      return 'Rivalry trophy on the line — $seriesText, $holderText';
    }
    if (displayRank <= 25 || _rankForTeam(nextOpponent) <= 25) {
      return 'Top 25 and postseason implications';
    }
    if (wins == 5) return 'A win secures bowl eligibility';
    if (gamesPlayed >= 8) return 'Conference race and bowl positioning';
    return 'Build momentum and strengthen the program résumé';
  }

  List<Player> get _dashboardTeamLeaders {
    final sorted = [...roster]
      ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
    return sorted.take(3).toList();
  }

  void _showAdvanceWeekSheet() {
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return SafeArea(
          child: Container(
            margin: const EdgeInsets.all(GKSpace.sm),
            padding: const EdgeInsets.all(GKSpace.xl),
            decoration: BoxDecoration(
              color: GKColors.elevatedPanel,
              border: Border.all(color: GKColors.divider),
              borderRadius: BorderRadius.circular(GKRadius.modal),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(.45),
                  blurRadius: 35,
                  offset: const Offset(0, 15),
                ),
              ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('WEEKLY COMMAND', style: GKText.sectionLabel),
                const SizedBox(height: GKSpace.xs),
                Text(_advanceLabel.toUpperCase(), style: GKText.pageTitle),
                const SizedBox(height: GKSpace.xs),
                Text(
                  seasonPhase == 'offseason'
                      ? 'The season is complete. Continue into the coaching carousel, retention, portal, development, and scheduling.'
                      : seasonPhase == 'confChampBye'
                      ? 'The rest of your conference\'s top 2 play for the title this week — you get a bye. Advance to find out your KP or bowl fate.'
                      : _isByeWeek
                      ? 'No game this week — a scheduled bye. Advance when you\'re ready for what\'s next.'
                      : _seasonJustEnded
                      ? _seasonCompleteDescription
                      : '$recordText ${widget.team.name} faces ${_rankedDisplayNameForTeam(nextOpponent)}. $_matchupStakes.',
                  style: GKText.body,
                ),
                const SizedBox(height: GKSpace.xl),
                if (seasonPhase != 'offseason') ...[
                  GKPrimaryButton(
                    label: seasonPhase == 'selectionShow'
                        ? 'Continue'
                        : (seasonPhase == 'confChampBye' ||
                              _isByeWeek ||
                              _seasonJustEnded)
                        ? _advanceLabel
                        : 'Play With Broadcast',
                    icon: Icons.sports_football_rounded,
                    large:
                        seasonPhase == 'confChampBye' ||
                        _isByeWeek ||
                        _seasonJustEnded,
                    onPressed: () {
                      Navigator.of(sheetContext).pop();

                      if (seasonPhase == 'selectionShow') {
                        _simNextGame();
                      } else if (seasonPhase == 'confChampBye') {
                        _advanceConfChampBye();
                      } else if (_isByeWeek) {
                        _advanceByeWeek();
                      } else if (_seasonJustEnded) {
                        _advancePostseason();
                      } else {
                        _openGameSim();
                      }
                    },
                  ),
                  const SizedBox(height: GKSpace.sm),
                ],
                // Once the regular season is over, or during a bye week,
                // advancing is the one real action — a "Quick Sim"
                // alternative to it doesn't mean anything, so it's dropped
                // rather than shown as a second button that does the same
                // thing a different way.
                if (!_seasonJustEnded &&
                    !_isByeWeek &&
                    seasonPhase != 'confChampBye')
                  GKSecondaryButton(
                    label: seasonPhase == 'offseason'
                        ? 'Enter Offseason'
                        : seasonPhase == 'selectionShow'
                        ? 'Reveal Selection'
                        : 'Quick Sim',
                    icon: seasonPhase == 'offseason'
                        ? Icons.arrow_forward_rounded
                        : Icons.fast_forward_rounded,
                    onPressed: () {
                      Navigator.of(sheetContext).pop();

                      if (seasonPhase == 'offseason') {
                        AdManager.showAd(context, onContinue: _openOffseason);
                      } else {
                        _simNextGame();
                      }
                    },
                  ),
                const SizedBox(height: GKSpace.xs),
                Center(
                  child: TextButton(
                    onPressed: () => Navigator.of(sheetContext).pop(),
                    child: Text(
                      'NOT YET',
                      style: TextStyle(
                        color: GKColors.mutedSilver,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1.4,
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

