  Widget _hqNextAssignment() {
    if (seasonPhase == 'offseason' ||
        seasonPhase == 'confChampBye' ||
        _seasonJustEnded) {
      // There's no real next opponent in any of these windows — the
      // offseason hasn't scheduled one yet, championship week is a bye for
      // a team that didn't finish top 2, and the postseason destination
      // isn't decided until the reveal resolves it. Showing whatever
      // nextOpponent still happens to hold here would be stale/fabricated.
      final label = seasonPhase == 'offseason'
          ? 'Advance to Offseason'
          : _advanceLabel;
      final description = seasonPhase == 'offseason'
          ? 'The season is complete. Continue into the coaching carousel, retention, portal, development, and scheduling.'
          : seasonPhase == 'confChampBye'
          ? 'The rest of your conference\'s top 2 play for the title this week — you get a bye. Advance to find out your KP or bowl fate.'
          : _seasonCompleteDescription;
      final onPressed = seasonPhase == 'offseason'
          ? () => AdManager.showAd(context, onContinue: _openOffseason)
          : seasonPhase == 'confChampBye'
          ? _advanceConfChampBye
          : _advancePostseason;

      return Container(
        decoration: const BoxDecoration(
          border: Border(
            top: BorderSide(color: GKColors.fieldGreen, width: 2),
            bottom: BorderSide(color: GKColors.elevatedLeather),
          ),
        ),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 18),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'NEXT ASSIGNMENT',
                style: TextStyle(
                  color: GKColors.parchmentWhite,
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 1.2,
                ),
              ),
              const SizedBox(height: 12),
              Text(
                postseasonStatus.toUpperCase(),
                style: const TextStyle(
                  color: GKColors.kingdomGold,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                description,
                style: const TextStyle(
                  color: GKColors.fadedInk,
                  fontSize: 12,
                  height: 1.4,
                ),
              ),
              const SizedBox(height: 16),
              GKPrimaryButton(
                label: label,
                icon: Icons.arrow_forward_rounded,
                large: true,
                onPressed: onPressed,
              ),
            ],
          ),
        ),
      );
    }

    if (_isByeWeek) {
      return Container(
        decoration: const BoxDecoration(
          border: Border(
            top: BorderSide(color: GKColors.fieldGreen, width: 2),
            bottom: BorderSide(color: GKColors.elevatedLeather),
          ),
        ),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 18),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'NEXT ASSIGNMENT',
                style: TextStyle(
                  color: GKColors.parchmentWhite,
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 1.2,
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'BYE WEEK',
                style: TextStyle(
                  color: GKColors.kingdomGold,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                'No game this week — the staff uses it to rest bumps and bruises, self-scout, and get ahead on the next opponent.',
                style: const TextStyle(
                  color: GKColors.fadedInk,
                  fontSize: 12,
                  height: 1.4,
                ),
              ),
              const SizedBox(height: 16),
              GKPrimaryButton(
                label: 'Advance Past Bye Week',
                icon: Icons.arrow_forward_rounded,
                large: true,
                onPressed: _advanceByeWeek,
              ),
            ],
          ),
        ),
      );
    }

    final opponentRank = _rankForTeam(nextOpponent);
    final opponentPrefix = opponentRank <= 25 ? '#$opponentRank ' : '';
    final spread = _projectedSpread;
    final pickEm = spread == 0;
    final favored = spread > 0;
    final spreadColor = pickEm
        ? GKColors.fadedInk
        : (favored ? GKColors.fieldGreen : GKColors.stampRed);
    final spreadTag = pickEm ? "PICK 'EM" : (favored ? 'FAVORED' : 'UNDERDOG');
    final spreadNumber = pickEm
        ? 'EVEN'
        : '-${spread.abs().toStringAsFixed(1)}';

    return GKCard(
      radius: GKRadius.featured,
      padding: const EdgeInsets.all(GKSpace.md),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Text(
                'NEXT ASSIGNMENT',
                style: TextStyle(
                  color: GKColors.parchmentWhite,
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 1.2,
                ),
              ),
              const Spacer(),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                decoration: BoxDecoration(
                  color: GKColors.stampRed.withOpacity(.14),
                  border: Border.all(color: GKColors.stampRed.withOpacity(.5)),
                  borderRadius: BorderRadius.circular(GKRadius.pill),
                ),
                child: Text(
                  _broadcastLabel,
                  style: const TextStyle(
                    color: GKColors.stampRed,
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    letterSpacing: .8,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              GKTeamBadge(team: nextOpponent, size: 54),
              const SizedBox(width: 14),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      '$_gameLocation · GAME ${gamesPlayed + 1}',
                      style: const TextStyle(
                        color: GKColors.kingdomBrass,
                        fontSize: 10,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      '$opponentPrefix${nextOpponent.displayName}'
                          .toUpperCase(),
                      style: const TextStyle(
                        color: GKColors.parchmentWhite,
                        fontSize: 19,
                        fontWeight: FontWeight.w900,
                        height: 1.08,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      '${_recordForTeam(nextOpponent)}  ·  $opponentOvr OVR  ·  ${nextOpponent.conference}',
                      style: const TextStyle(
                        color: GKColors.fadedInk,
                        fontSize: 11,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
            decoration: BoxDecoration(
              color: GKColors.elevatedLeather,
              border: Border.all(color: spreadColor.withOpacity(.6)),
            ),
            child: Row(
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'POINT SPREAD',
                      style: TextStyle(
                        color: GKColors.fadedInk,
                        fontSize: 9,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1.1,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      pickEm
                          ? spreadNumber
                          : '${favored ? widget.team.name : nextOpponent.name} $spreadNumber',
                      style: const TextStyle(
                        color: GKColors.parchmentWhite,
                        fontSize: 15,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ],
                ),
                const Spacer(),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 9,
                    vertical: 5,
                  ),
                  decoration: BoxDecoration(
                    color: spreadColor.withOpacity(.16),
                    border: Border.all(color: spreadColor.withOpacity(.6)),
                    borderRadius: BorderRadius.circular(GKRadius.pill),
                  ),
                  child: Text(
                    spreadTag,
                    style: TextStyle(
                      color: spreadColor,
                      fontSize: 10,
                      fontWeight: FontWeight.w900,
                      letterSpacing: .8,
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 14),
          Row(
            children: [
              const Icon(
                Icons.bolt_rounded,
                color: GKColors.kingdomBrass,
                size: 16,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  _matchupStakes,
                  style: const TextStyle(
                    color: GKColors.parchmentWhite,
                    fontSize: 11,
                    height: 1.35,
                  ),
                ),
              ),
              Text(
                _weatherLabel,
                style: const TextStyle(
                  color: GKColors.fadedInk,
                  fontSize: 10,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

