  Widget _hqProgramReadout() {
    final entries = <({String label, int value})>[
      (label: 'MEDIA', value: mediaReputation),
      (label: 'LOCKER ROOM', value: playerMorale),
      (label: 'BOOSTERS', value: boosterApproval),
      (label: 'RECRUITING', value: recruitingBuzz),
      (label: 'SUPPORTERS', value: fanHappiness),
    ];

    // Color the health, not just the number — a program running hot or cold
    // should read at a glance, not require reading five identical brass bars.
    Color healthColor(int value) {
      if (value >= 65) return GKColors.fieldGreen;
      if (value >= 35) return GKColors.kingdomBrass;
      return GKColors.stampRed;
    }

    return Column(
      children: entries.map((entry) {
        final color = healthColor(entry.value);
        return Padding(
          padding: const EdgeInsets.symmetric(vertical: 7),
          child: Row(
            children: [
              SizedBox(
                width: 92,
                child: Text(
                  entry.label,
                  style: const TextStyle(
                    color: GKColors.fadedInk,
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    letterSpacing: .7,
                  ),
                ),
              ),
              Expanded(
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(1),
                  child: LinearProgressIndicator(
                    value: entry.value / 100,
                    minHeight: 9,
                    backgroundColor: GKColors.elevatedLeather,
                    valueColor: AlwaysStoppedAnimation<Color>(color),
                  ),
                ),
              ),
              const SizedBox(width: 10),
              SizedBox(
                width: 28,
                child: Text(
                  '${entry.value}',
                  textAlign: TextAlign.right,
                  style: TextStyle(
                    color: color,
                    fontWeight: FontWeight.w900,
                    fontSize: 12,
                  ),
                ),
              ),
            ],
          ),
        );
      }).toList(),
    );
  }

