  // What's coming after this week's game/bye — real, useful information
  // (not filler) that also gives the home tab somewhere to put its weight
  // instead of trailing off into empty space once the wire runs dry.
  Widget _hqUpcomingSchedule() {
    final rows = <Widget>[];
    for (
      var week = currentWeek + 1;
      week < schedule.length && rows.length < 6;
      week++
    ) {
      final opponent = schedule[week];
      rows.add(_hqScheduleRow(week, opponent));
    }
    if (rows.isEmpty) return const SizedBox.shrink();

    return Column(children: rows);
  }

  Widget _hqScheduleRow(int week, CollegeTeam? opponent) {
    if (opponent == null) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 8),
        child: Row(
          children: [
            SizedBox(
              width: 32,
              child: Text(
                'W${week + 1}',
                style: const TextStyle(
                  color: GKColors.fadedInk,
                  fontWeight: FontWeight.w900,
                  fontSize: 11,
                ),
              ),
            ),
            const Icon(
              Icons.self_improvement_rounded,
              color: GKColors.fadedInk,
              size: 22,
            ),
            const SizedBox(width: 12),
            const Expanded(
              child: Text(
                'BYE WEEK',
                style: TextStyle(
                  color: GKColors.fadedInk,
                  fontWeight: FontWeight.w800,
                  fontSize: 12,
                  letterSpacing: .6,
                ),
              ),
            ),
          ],
        ),
      );
    }

    final rank = _rankForTeam(opponent);
    final rankPrefix = rank <= 25 ? '#$rank ' : '';
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: Row(
        children: [
          SizedBox(
            width: 32,
            child: Text(
              'W${week + 1}',
              style: const TextStyle(
                color: GKColors.fadedInk,
                fontWeight: FontWeight.w900,
                fontSize: 11,
              ),
            ),
          ),
          GKTeamBadge(team: opponent, size: 30),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              '$rankPrefix${opponent.displayName}',
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: GKColors.parchmentWhite,
                fontWeight: FontWeight.w800,
                fontSize: 12,
              ),
            ),
          ),
          Text(
            _recordForTeam(opponent),
            style: const TextStyle(
              color: GKColors.fadedInk,
              fontWeight: FontWeight.w700,
              fontSize: 11,
            ),
          ),
        ],
      ),
    );
  }

