                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(
                    item.$1,
                    color: selected
                        ? GKColors.kingdomGold
                        : GKColors.mutedSilver,
                    size: 25,
                  ),
                  const SizedBox(height: 4),
                  Text(
                    item.$2,
                    style: TextStyle(
                      color: selected
                          ? GKColors.kingdomGold
                          : GKColors.mutedSilver,
                      fontSize: 9,
                      fontWeight: FontWeight.w900,
