  bool get _wonNationalChampionshipThisSeason {
    return trophyRoom.any(
      (trophy) =>
          trophy.year == season && trophy.type == 'National Championship',
    );
  }

  bool get _wonBowlThisSeason {
    return trophyRoom.any(
      (trophy) => trophy.year == season && trophy.type == 'Bowl Win',
    );
  }

  bool get _wonConferenceChampionshipThisSeason {
    return trophyRoom.any(
      (trophy) =>
          trophy.year == season && trophy.type == 'Conference Championship',
    );
  }

  // Legacy Board: career-wide (not this-season) achievement counts, derived
  // live from trophyRoom — which already survives job changes — rather
  // than tracked as separate persisted counters.
  int get _careerNationalTitles =>
      trophyRoom.where((t) => t.type == 'National Championship').length;
  int get _careerConferenceTitles =>
      trophyRoom.where((t) => t.type == 'Conference Championship').length;
  int get _careerBowlWins =>
      trophyRoom.where((t) => t.type == 'Bowl Win').length;
  // Kept separate from the FBS counters above — used for FCS→FBS
  // promotion eligibility, which must judge a program on what it actually
  // won as an FCS team, not any FBS hardware from a different job.
  int get _careerFcsNationalTitles =>
      trophyRoom.where((t) => t.type == 'FCS National Championship').length;
  int get _careerFcsConferenceTitles => trophyRoom
      .where((t) => t.type == 'FCS Conference Championship')
      .length;
  int get _careerBowlPoints => trophyRoom
      .where((t) => t.type == 'Bowl Win')
      .fold(0, (sum, t) => sum + bowlWinPoints(t.title));

  int get _legacyScore => legacyScoreFor(
    nationalTitles: _careerNationalTitles,
    conferenceTitles: _careerConferenceTitles,
    bowlPoints: _careerBowlPoints,
    careerWins: careerWins,
    currentPrestige: programPrestige,
    undefeatedSeasons: undefeatedSeasons,
  );

  Future<void> _retireCoach(LegendCoachRecord snapshot) async {
    await addRetiredLegend(snapshot);
    setState(() => hasRetired = true);
    _autoSaveCareer();
  }

  Widget _postseasonCard() {
    String title;
    String detail;
    String eyebrow;
    IconData icon;
    VoidCallback action;

    if (seasonPhase == 'regular' && gamesPlayed >= 12) {
      eyebrow = 'SEASON COMPLETE';
      title = conferenceChampEligible
          ? 'Conference Championship Week'
          : 'Conference Championship Week (Bye)';
      detail = conferenceChampEligible
          ? 'You finished top 2 in ${currentConference}. Advance to play for the conference title.'
          : 'You didn\'t finish top 2 in ${currentConference}, so this week is a bye for you. Advance to see your Kingdom Football Playoff or bowl fate once the title game is decided.';
      icon = Icons.live_tv_rounded;
      action = _advancePostseason;
    } else if (seasonPhase == 'confChampBye') {
      eyebrow = 'BYE WEEK';
      title = 'Conference Championship Week';
      detail =
          'The top 2 in ${currentConference} play for the title this week — you get a bye. Advance to find out your Kingdom Football Playoff or bowl fate.';
      icon = Icons.event_available_rounded;
      action = _advanceConfChampBye;
    } else if (seasonPhase == 'selectionShow') {
      eyebrow = 'LIVE REVEAL';
      title = 'Postseason Selection Show';
      detail =
          'The final envelope is ready. Your postseason destination has not been announced yet.';
      icon = Icons.markunread_mailbox_rounded;
      action = _advancePostseason;
    } else if (seasonPhase == 'offseason') {
      eyebrow = 'SEASON COMPLETE';

      if (_wonNationalChampionshipThisSeason) {
        title = 'National Champions';
        detail =
            '${widget.team.name} completed the KP run and won the National Championship. Continue to the championship season recap and offseason.';
        icon = Icons.emoji_events_rounded;
      } else if (_wonBowlThisSeason) {
        title = '$_assignedBowlName Champions';
        detail =
            '${widget.team.name} finished the season with a victory in the $_assignedBowlName. Continue to the season recap and offseason.';
        icon = Icons.military_tech_rounded;
      } else if (_wonConferenceChampionshipThisSeason) {
        title = '${currentConference} Champions';
        detail =
            '${widget.team.name} won the conference championship and has completed its postseason run. Continue to the offseason.';
        icon = Icons.workspace_premium_rounded;
      } else if (gamesPlayed >= 12 && wins >= 6) {
        title = 'Postseason Complete';
        detail =
            'Your postseason run has ended. Continue into jobs, retention, the portal, development, and scheduling.';
        icon = Icons.flag_circle_rounded;
      } else {
        title = 'No Postseason Invitation';
        detail =
            'Your team did not receive a conference championship, KP, or bowl invitation. Continue directly into the offseason.';
        icon = Icons.event_available_rounded;
      }

      action = () {
        AdManager.showAd(context, onContinue: _openOffseason);
      };
    } else if (seasonPhase == 'confChamp') {
      eyebrow = 'DESTINATION REVEALED';
      title = '${currentConference} Championship';
      detail =
          'You earned a place in the conference title game. Win it and strengthen your path to the Kingdom Football Playoff.';
      icon = Icons.emoji_events_rounded;
      action = _openGameSim;
    } else if (seasonPhase == 'cfp') {
      eyebrow = 'DESTINATION REVEALED';
      title = _cfpGameNameForRound(postseasonRound);
      detail =
          'You are in the Kingdom Football Playoff. Your next opponent is now available on the matchup card below.';
      icon = Icons.workspace_premium_rounded;
      action = _openGameSim;
    } else {
      eyebrow = 'DESTINATION REVEALED';
      title = _assignedBowlName;
      detail =
          'Your season earned a bowl invitation. Your opponent is now available on the matchup card below.';
      icon = Icons.military_tech_rounded;
      action = _openGameSim;
    }

    return GKCard(
      onTap: action,
      color: Color(0xFF241E12),
      borderColor: GKColors.kingdomGold.withOpacity(.55),
      radius: GKRadius.featured,
      child: Row(
        children: [
          Container(
            width: 51,
            height: 51,
            decoration: BoxDecoration(
              color: GKColors.kingdomGold.withOpacity(.13),
              shape: BoxShape.circle,
            ),
            child: Icon(icon, color: GKColors.kingdomGold, size: 28),
          ),
          const SizedBox(width: GKSpace.md),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(eyebrow, style: GKText.sectionLabel),
                const SizedBox(height: 4),
                Text(title.toUpperCase(), style: GKText.cardTitle),
                const SizedBox(height: 4),
                Text(detail, style: GKText.body.copyWith(fontSize: 12)),
              ],
            ),
          ),
          const Icon(Icons.arrow_forward_rounded, color: GKColors.kingdomGold),
        ],
      ),
    );
  }

  Widget _nextGameCard() {
    if (gamesPlayed >= 12 && seasonPhase == 'offseason') {
      return GKCard(
        color: GKColors.broadcastNavy,
        borderColor: GKColors.kingdomGold.withOpacity(.38),
        radius: GKRadius.featured,
        child: Column(
          children: [
            const Icon(
              Icons.flag_circle_rounded,
              color: GKColors.kingdomGold,
              size: 42,
            ),
            const SizedBox(height: GKSpace.sm),
            Text(
              _wonNationalChampionshipThisSeason
                  ? 'NATIONAL CHAMPIONS'
                  : _wonBowlThisSeason
                  ? '${_assignedBowlName.toUpperCase()} CHAMPIONS'
                  : 'THE SEASON IS COMPLETE',
              textAlign: TextAlign.center,
              style: GKText.cardTitle,
            ),
            const SizedBox(height: GKSpace.xs),
            Text(
              _wonNationalChampionshipThisSeason
                  ? 'The national title is secured. Your championship season now moves into the offseason.'
                  : _wonBowlThisSeason
                  ? 'Your bowl victory is secured. Your next decisions begin in the offseason.'
                  : 'Your next decisions begin in the offseason.',
              textAlign: TextAlign.center,
              style: GKText.body,
            ),
            const SizedBox(height: GKSpace.md),
            GKPrimaryButton(
              label: 'Advance to Offseason',
              icon: Icons.arrow_forward_rounded,
              onPressed: () {
                AdManager.showAd(context, onContinue: _openOffseason);
              },
            ),
          ],
        ),
      );
    }

    if (_seasonJustEnded || seasonPhase == 'confChampBye' || _isByeWeek) {
      // None of these have a real "next opponent" matchup to show — the
      // regular season's postseason destination isn't decided until the
      // reveal resolves it, and a bye (in-season or conference
      // championship week) has no game at all. A specific matchup card
      // (with live Play/Quick Sim buttons) here would be stale/fabricated.
      final title = seasonPhase == 'confChampBye'
          ? 'CONFERENCE CHAMPIONSHIP WEEK — BYE'
          : _isByeWeek
          ? 'BYE WEEK'
          : postseasonStatus.toUpperCase();
      final description = seasonPhase == 'confChampBye'
          ? 'The top 2 in ${currentConference} play for the title this week — you get a bye. Advance to find out your KP or bowl fate.'
          : _isByeWeek
          ? 'No game this week — a scheduled bye. Advance when you\'re ready for what\'s next.'
          : _seasonCompleteDescription;
      final onPressed = seasonPhase == 'confChampBye'
          ? _advanceConfChampBye
          : _isByeWeek
          ? _advanceByeWeek
          : _advancePostseason;

      return GKCard(
        color: GKColors.broadcastNavy,
        borderColor: GKColors.kingdomGold.withOpacity(.38),
        radius: GKRadius.featured,
        child: Column(
          children: [
            const Icon(
              Icons.emoji_events_rounded,
              color: GKColors.kingdomGold,
              size: 42,
            ),
            const SizedBox(height: GKSpace.sm),
            Text(title, textAlign: TextAlign.center, style: GKText.cardTitle),
            const SizedBox(height: GKSpace.xs),
            Text(description, textAlign: TextAlign.center, style: GKText.body),
            const SizedBox(height: GKSpace.md),
            GKPrimaryButton(
              label: _advanceLabel,
              icon: Icons.arrow_forward_rounded,
              large: true,
              onPressed: onPressed,
            ),
          ],
        ),
      );
    }

    final opponentRank = _rankForTeam(nextOpponent);
    final userRankLabel = displayRank <= 25 ? '#$displayRank' : '';
    final opponentRankLabel = opponentRank <= 25 ? '#$opponentRank' : '';

    return GKCard(
      padding: EdgeInsets.zero,
      color: gkDarkenedSchoolColor(widget.team.primary, .78),
      borderColor: widget.team.primary.withOpacity(.65),
      radius: GKRadius.featured,
      child: Column(
        children: [
          Container(
            padding: const EdgeInsets.symmetric(
              horizontal: GKSpace.md,
              vertical: GKSpace.sm,
            ),
            decoration: const BoxDecoration(
              color: GKColors.broadcastNavy,
              borderRadius: BorderRadius.vertical(
                top: Radius.circular(GKRadius.featured),
              ),
            ),
            child: Row(
              children: [
                Text(
                  gamesPlayed >= 12
                      ? postseasonStatus.toUpperCase()
                      : 'GAME ${gamesPlayed + 1} • $_gameLocation',
                  style: const TextStyle(
                    color: GKColors.warmWhite,
                    fontSize: 11,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 1.3,
                  ),
                ),
                const Spacer(),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 9,
                    vertical: 5,
                  ),
                  decoration: BoxDecoration(
                    color: GKColors.alertRed.withOpacity(.12),
                    borderRadius: BorderRadius.circular(GKRadius.pill),
                  ),
                  child: Text(
                    _broadcastLabel,
                    style: const TextStyle(
                      color: GKColors.alertRed,
                      fontSize: 9,
                      fontWeight: FontWeight.w900,
                      letterSpacing: .7,
                    ),
                  ),
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(GKSpace.md),
            child: Column(
              children: [
                Row(
                  children: [
                    Expanded(
                      child: _matchupTeam(
                        team: widget.team,
                        ranking: userRankLabel,
                        record: recordText,
                        overall: teamOvr.round(),
                        isUser: true,
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.symmetric(
                        horizontal: GKSpace.sm,
                      ),
                      child: Column(
