  Widget _recruitBoardTabs({
    required int availableCount,
    required int myBoardCount,
  }) {
    final signedCount = recruits
        .where((r) => r.committedSchool == widget.team.name)
        .length;

    return Container(
      padding: const EdgeInsets.all(4),
      decoration: BoxDecoration(
        color: GKColors.broadcastNavy,
        borderRadius: BorderRadius.circular(GKRadius.card),
        border: Border.all(color: GKColors.divider),
      ),
      child: Row(
        children: [
          _boardTabButton('OPEN', 0, availableCount),
          _boardTabButton('ALL', 1, recruits.length),
          _boardTabButton('WATCHLIST', 2, myBoardCount),
          _boardTabButton('SIGNED', 3, signedCount),
        ],
      ),
    );
  }

  Widget _boardTabButton(String label, int index, int count) {
    final selected = recruitBoardTab == index;

    return Expanded(
      child: GestureDetector(
        onTap: () => setState(() => recruitBoardTab = index),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          padding: const EdgeInsets.symmetric(vertical: 11),
          decoration: BoxDecoration(
            color: selected ? GKColors.kingdomBrass : Colors.transparent,
            borderRadius: BorderRadius.circular(GKRadius.small),
          ),
          child: Column(
            children: [
              Text(
                label,
                style: TextStyle(
                  color: selected ? GKColors.inkBlack : GKColors.mutedSilver,
                  fontSize: 9,
                  fontWeight: FontWeight.w900,
                  letterSpacing: .7,
                ),
              ),
              const SizedBox(height: 2),
              Text(
                '$count',
                style: TextStyle(
                  color: selected ? GKColors.inkBlack : GKColors.warmWhite,
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _dropdownFilters() {
    final states = recruits.map((recruit) => recruit.state).toSet().toList()
      ..sort();
    const positions = ['QB', 'HB', 'WR', 'TE', 'DE', 'LB', 'DB'];

    return GKCard(
      padding: const EdgeInsets.all(GKSpace.sm),
      radius: GKRadius.small,
      child: Column(
        children: [
          Row(
            children: [
              Expanded(
                child: _phase5Filter<int?>(
                  value: starFilter,
                  items: const [null, 1, 2, 3, 4, 5],
                  label: (value) => value == null ? 'All Stars' : '$value★',
                  onChanged: (value) {
                    setState(() => starFilter = value);
                  },
                ),
              ),
              const SizedBox(width: GKSpace.xs),
              Expanded(
                child: _phase5Filter<String?>(
                  value: positionFilter,
                  items: const [null, ...positions],
                  label: (value) => value ?? 'All Positions',
                  onChanged: (value) {
                    setState(() => positionFilter = value);
                  },
                ),
              ),
            ],
          ),
          const SizedBox(height: GKSpace.xs),
          Row(
            children: [
              Expanded(
                child: _phase5Filter<String?>(
                  value: stateFilter,
                  items: [null, ...states],
                  label: (value) => value ?? 'All States',
                  onChanged: (value) {
                    setState(() => stateFilter = value);
                  },
                ),
              ),
              const SizedBox(width: GKSpace.xs),
              Expanded(
                child: _phase5Filter<String>(
                  value: recruitSort,
                  items: const ['Rank', 'Interest', 'Overall'],
                  label: (value) => value,
                  onChanged: (value) {
                    setState(() => recruitSort = value ?? 'Rank');
                  },
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _phase5Filter<T>({
    required T value,
    required List<T> items,
    required String Function(T) label,
    required ValueChanged<T?> onChanged,
  }) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10),
      decoration: BoxDecoration(
        color: GKColors.midnight.withOpacity(.64),
        border: Border.all(color: GKColors.divider),
        borderRadius: BorderRadius.circular(GKRadius.small),
      ),
      child: DropdownButtonHideUnderline(
        child: DropdownButton<T>(
          value: value,
          isExpanded: true,
          dropdownColor: GKColors.elevatedPanel,
          iconEnabledColor: GKColors.kingdomBrass,
          style: const TextStyle(
            color: GKColors.warmWhite,
            fontSize: 11,
            fontWeight: FontWeight.w800,
          ),
          items: items
              .map(
                (item) => DropdownMenuItem<T>(
                  value: item,
                  child: Text(label(item), overflow: TextOverflow.ellipsis),
                ),
              )
              .toList(),
          onChanged: onChanged,
        ),
      ),
    );
  }

  String _recruitMemory(Recruit recruit) {
    final seed = recruit.name.hashCode.abs() % 6;

    return switch (seed) {
      0 => 'Remembers your early scholarship offer.',
      1 => 'Watching how your offense uses his position.',
      2 => 'Interested in the program’s development record.',
      3 => 'Tracking your record in rivalry and ranked games.',
      4 => 'Wants a clear path to early playing time.',
      _ => 'Evaluating the relationship with your coaching staff.',
    };
  }

  String _visitStatus(Recruit recruit) {
    if (recruit.committedSchool != null) {
      return recruit.committedSchool == widget.team.name
          ? 'SIGNED WITH YOU'
          : 'SIGNED ELSEWHERE';
    }
    if (recruit.visits > 0) return 'VISITED';
    if (recruit.firstContactGame == null) return 'SCOUT OR OFFER FIRST';
    if (_canScheduleVisit(recruit)) return 'VISIT AVAILABLE';
    if (recruit.interest >= 70) return 'PRIORITY VISIT';
    if (recruit.interest >= 55) return 'VISIT CANDIDATE';
    return 'BUILD INTEREST';
  }

  Color _interestColor(int interest) {
    if (interest >= 75) return GKColors.victoryGreen;
    if (interest >= 55) return GKColors.kingdomBrass;
    return GKColors.alertRed;
  }

  Widget _statusChip(String label, Color color) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
      decoration: BoxDecoration(
        color: color.withOpacity(.16),
        border: Border.all(color: color.withOpacity(.55)),
        borderRadius: BorderRadius.circular(GKRadius.pill),
      ),
      child: Text(
        label,
        style: TextStyle(
          color: color,
          fontSize: 9,
          fontWeight: FontWeight.w900,
          letterSpacing: .5,
        ),
      ),
    );
  }

  Widget _recruitListRow(int index, Recruit recruit) {
    final committedToUser = recruit.committedSchool == widget.team.name;
    final committedElsewhere =
        recruit.committedSchool != null &&
        recruit.committedSchool != widget.team.name;
    final interestColor = _interestColor(recruit.interest);

    final bg = widget.coach.background;
    final isHomePipeline = recruit.state == bg.hometownState;
    final isRegionPipeline =
        !isHomePipeline && bg.regionStates.contains(recruit.state);

    return GKCard(
      onTap: () {
        Navigator.of(context)
            .push(
              MaterialPageRoute(
                builder: (_) => RecruitProfileScreen(
                  recruit: recruit,
                  rank: index,
                  userSchool: widget.team.name,
                  userTeamColor: widget.team.primary,
                  recruitingClosed: recruitingClosed,
                  recruitingPoints: () => recruitingPoints,
                  gamesPlayed: gamesPlayed,
                  nilBudgetRemaining: () =>
                      recruitingNilBudget - recruitingNilSpent,
                  canScheduleVisit: () => _canScheduleVisit(recruit),
                  canOfferNil: () => _canOfferNil(recruit),
                  canBoostMorale: () => _canBoostRecruitMorale(recruit),
                  classHasRoom: () => _recruitingClassHasRoom,
                  onScout: () => _scoutRecruit(recruit),
                  onOffer: () => _offerRecruit(recruit),
                  onScheduleVisit: () => _scheduleVisit(recruit),
                  onOfferNil: () => _offerRecruitNil(recruit),
                  onBoostMorale: () => _boostRecruitMorale(recruit),
                ),
              ),
            )
            .then((_) => setState(() {}));
      },
      color: committedToUser
          ? GKColors.elevatedLeather
          : committedElsewhere
          ? GKColors.saddleLeather
          : GKColors.broadcastNavy,
      borderColor: committedToUser
          ? GKColors.victoryGreen.withOpacity(.48)
          : committedElsewhere
          ? GKColors.alertRed.withOpacity(.42)
          : recruit.offered
          ? widget.team.primary.withOpacity(.50)
          : GKColors.divider,
      radius: GKRadius.card,
      child: Column(
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              SizedBox(
                width: 28,
                child: Text(
                  '#$index',
                  style: const TextStyle(
                    color: GKColors.mutedSilver,
                    fontSize: 11,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              PlayerAvatar(
                seed: recruit.name.hashCode,
                teamColor: widget.team.primary,
                size: 50,
              ),
              const SizedBox(width: GKSpace.sm),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            recruit.name.toUpperCase(),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: GKColors.warmWhite,
                              fontSize: 14,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 8,
                            vertical: 5,
                          ),
                          decoration: BoxDecoration(
                            color: GKColors.midnight.withOpacity(.60),
                            borderRadius: BorderRadius.circular(GKRadius.pill),
                          ),
                          child: Text(
                            recruit.position,
                            style: const TextStyle(
                              color: GKColors.kingdomBrass,
                              fontSize: 10,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 3),
                    Text(
                      '${recruit.state} • ${recruit.stars}★ • ${recruit.archetype}',
                      style: GKText.body.copyWith(
                        fontSize: 10,
                        color: isHomePipeline
                            ? GKColors.kingdomGold
                            : isRegionPipeline
                            ? GKColors.fieldGreen
                            : null,
                        fontWeight: (isHomePipeline || isRegionPipeline)
                            ? FontWeight.w800
                            : null,
                      ),
                    ),
                    if (isHomePipeline || isRegionPipeline) ...[
                      const SizedBox(height: 4),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 7,
                          vertical: 3,
                        ),
                        decoration: BoxDecoration(
                          color:
                              (isHomePipeline
                                      ? GKColors.kingdomGold
                                      : GKColors.fieldGreen)
                                  .withOpacity(.16),
                          border: Border.all(
                            color:
                                (isHomePipeline
                                        ? GKColors.kingdomGold
                                        : GKColors.fieldGreen)
                                    .withOpacity(.55),
                          ),
                          borderRadius: BorderRadius.circular(GKRadius.pill),
                        ),
                        child: Text(
                          isHomePipeline
                              ? 'HOME PIPELINE · ${bg.hometownState}'
                              : 'REGIONAL PIPELINE · ${bg.hometownRegion}',
                          style: TextStyle(
                            color: isHomePipeline
                                ? GKColors.kingdomGold
                                : GKColors.fieldGreen,
                            fontSize: 9,
                            fontWeight: FontWeight.w900,
                            letterSpacing: .6,
                          ),
                        ),
                      ),
                    ],
                    const SizedBox(height: 7),
                    if (recruit.committedSchool == null)
                      Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            children: [
                              Expanded(
                                child: ClipRRect(
                                  borderRadius: BorderRadius.circular(4),
                                  child: LinearProgressIndicator(
                                    value: (recruit.interest / 100).clamp(
                                      0,
                                      1,
                                    ),
                                    minHeight: 6,
                                    backgroundColor: GKColors.divider,
                                    valueColor: AlwaysStoppedAnimation<Color>(
                                      interestColor,
                                    ),
                                  ),
                                ),
                              ),
                              const SizedBox(width: GKSpace.xs),
                              Text(
                                '${recruit.interest}%',
                                style: TextStyle(
                                  color: interestColor,
                                  fontSize: 10,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ],
                          ),
                          // Exactly why this prospect is on your watchlist —
                          // offered, scouted, or both — instead of leaving
                          // the visitor to infer it from a border tint.
                          if (recruit.offered || recruit.scouts > 0) ...[
                            const SizedBox(height: 6),
                            Wrap(
                              spacing: 6,
                              runSpacing: 4,
                              children: [
                                if (recruit.offered)
                                  _statusChip(
                                    'OFFERED',
                                    widget.team.primary,
                                  ),
                                if (recruit.scouts > 0)
                                  _statusChip(
                                    'SCOUTED ×${recruit.scouts}',
                                    GKColors.kingdomBrass,
                                  ),
                              ],
                            ),
                          ],
                        ],
                      )
                    else
                      Row(
                        children: [
                          Icon(
                            committedToUser
                                ? Icons.check_circle_rounded
                                : Icons.school_rounded,
                            size: 14,
                            color: committedToUser
                                ? GKColors.victoryGreen
                                : GKColors.kingdomBrass,
                          ),
                          const SizedBox(width: 5),
                          Expanded(
                            child: Text(
                              committedToUser
                                  ? 'COMMITTED TO YOUR PROGRAM'
                                  : 'COMMITTED TO ${universityDisplayName(recruit.committedSchool!).toUpperCase()}',
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: committedToUser
                                    ? GKColors.victoryGreen
                                    : GKColors.kingdomBrass,
                                fontSize: 9,
                                fontWeight: FontWeight.w900,
                                letterSpacing: .5,
                              ),
                            ),
                          ),
                        ],
                      ),
                  ],
                ),
              ),
              const SizedBox(width: GKSpace.sm),
              Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Text(
                    recruit.scouts >= 3
                        ? '${recruit.displayedOverall}'
                        : recruit.cardOverallText,
                    style: const TextStyle(
                      color: GKColors.warmWhite,
                      fontSize: 22,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  Text(
                    'OVR',
                    style: TextStyle(
                      color: GKColors.mutedSilver,
                      fontSize: 8,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ],
              ),
            ],
          ),
          const SizedBox(height: GKSpace.sm),
          Container(
            padding: const EdgeInsets.only(top: GKSpace.sm),
            decoration: const BoxDecoration(
              border: Border(top: BorderSide(color: GKColors.divider)),
            ),
            child: Row(
              children: [
                Expanded(
                  child: Text(
                    recruit.committedSchool != null
                        ? recruit.committedSchool == widget.team.name
                              ? 'SIGNED WITH ${widget.team.displayName.toUpperCase()}'
                              : 'SIGNED WITH ${universityDisplayName(recruit.committedSchool!).toUpperCase()}'
                        : recruit.scoutingReport,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: committedToUser
                          ? GKColors.victoryGreen
                          : committedElsewhere
                          ? GKColors.alertRed
                          : GKColors.mutedSilver,
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
                const SizedBox(width: GKSpace.xs),
                Text(
                  _visitStatus(recruit),
                  style: TextStyle(
                    color: committedToUser
                        ? GKColors.victoryGreen
