  bool get recruitingClosed => gamesPlayed >= 10;

  String _randomOtherSchoolForRecruit(Recruit recruit) {
    // Compare prestige *tiers* (1-5), not raw prestige (45-99) against
    // stars — the raw comparison was true for nearly every school, so a
    // 5-star recruit could land at a bottom-tier program at random. That
    // undermines "which school a recruit goes to" actually reading as
    // credible.
    final possible =
        g5Teams
            .where(
              (team) =>
                  team.name != widget.team.name &&
                  prestigeTier(team.prestige) >= recruit.stars - 1,
            )
            .toList()
          ..shuffle(rng);

    return possible.isEmpty ? 'another school' : possible.first.name;
  }

