  // Shared by the instant-commit roll (on offer) and the decision-window
  // roll (_processRecruitDecisions), so paying NIL or landing a visit
  // matters the same way regardless of when a recruit's decision lands.
  // nilAsk is 0 for 1-2 star recruits, so this is a no-op for them.
  int _recruitCommitmentBoost(Recruit recruit) {
    final nilRatio = recruit.nilAsk == 0
        ? 0.0
        : (recruit.nilOffered / recruit.nilAsk).clamp(0.0, 1.5);
    final nilBoost = nilRatio * 18;
    final visitBoost = recruit.visits * 10;
    return (nilBoost + visitBoost).round();
  }

  void _offerRecruit(Recruit recruit) {
    if (recruitingClosed ||
        recruit.offered ||
        recruit.committedSchool != null ||
        recruitingPoints < 10)
      return;

    setState(() {
      recruitingPoints -= 10;
      recruit.offered = true;
      recruit.firstContactGame ??= gamesPlayed;

      final boost = _recruitCommitmentBoost(recruit);
      final instantChance =
          ((recruit.interest +
                      boost +
                      programPrestige * 5 -
                      recruit.stars * 8) /
                  420)
              .clamp(.02, .30);

      if (rng.nextDouble() < instantChance &&
          _recruitingClassHasRoom &&
          recruitCanCommitToSubdivision(recruit, currentSubdivision)) {
        recruit.committedSchool = widget.team.name;
        commits++;
      } else {
        final wait = 1 + rng.nextInt(3);
        recruit.decisionWindow = (recruitingWindow + wait).clamp(1, 3);
      }
    });

    if (recruit.committedSchool == widget.team.name &&
        !recruit.commitmentPopupShown) {
      recruit.commitmentPopupShown = true;
      _showCommitPopup(recruit, true);
    }
  }

  void _scoutRecruit(Recruit recruit) {
    if (recruitingClosed ||
        recruit.scouts >= 3 ||
        recruit.committedSchool != null ||
        recruitingPoints < 5)
      return;

    setState(() {
      recruitingPoints -= 5;
      recruit.scouts++;
      recruit.firstContactGame ??= gamesPlayed;
    });
  }

  bool _canBoostRecruitMorale(Recruit recruit) {
    if (recruitingClosed) return false;
    if (recruit.committedSchool != null) return false;
    if (recruit.interest >= 100) return false;
    if (recruitingPoints < 5) return false;
    return true;
  }

  // A direct relationship-building spend: 5 RP for a real, immediate bump
  // to how badly this prospect wants to play for you — separate from
  // scouting (learns his true grade) and offering (starts the clock).
  void _boostRecruitMorale(Recruit recruit) {
    if (!_canBoostRecruitMorale(recruit)) return;

    setState(() {
      recruitingPoints -= 5;
      recruit.interest = (recruit.interest + 10).clamp(0, 100);
      recruit.firstContactGame ??= gamesPlayed;
    });
  }

  // A visit can only be scheduled a week after the first time you've
  // engaged this recruit (via an offer or a scout), and only once.
  bool _canScheduleVisit(Recruit recruit) {
    if (recruitingClosed) return false;
    if (recruit.committedSchool != null) return false;
    if (recruit.firstContactGame == null) return false;
    if (gamesPlayed < recruit.firstContactGame! + 1) return false;
    if (recruit.visits >= 1) return false;
    if (recruitingPoints < 5) return false;
    return true;
  }

  void _scheduleVisit(Recruit recruit) {
    if (!_canScheduleVisit(recruit)) return;

    setState(() {
      recruitingPoints -= 5;
      recruit.visits += 1;
    });
  }

  bool _canOfferNil(Recruit recruit) {
    if (recruitingClosed) return false;
    if (recruit.committedSchool != null) return false;
    if (!recruit.offered) return false;
    if (!recruit.wantsNil) return false;
    if (recruit.nilOffered >= recruit.nilAsk) return false;
    final remainingAsk = recruit.nilAsk - recruit.nilOffered;
    return recruitingNilSpent + remainingAsk <= recruitingNilBudget;
  }

  void _offerRecruitNil(Recruit recruit) {
    if (!_canOfferNil(recruit)) return;

    final remainingAsk = recruit.nilAsk - recruit.nilOffered;
    setState(() {
      recruitingNilSpent += remainingAsk;
      recruit.nilOffered = recruit.nilAsk;
    });
  }

  void _processRecruitDecisions() {
    final userCommits = <Recruit>[];

    setState(() {
      for (final recruit in recruits) {
        if (recruit.committedSchool != null) continue;
        if (recruit.decisionWindow == null) continue;
        if (recruit.decisionWindow! > recruitingWindow) continue;

        final boost = _recruitCommitmentBoost(recruit);
        final userChance =
            ((recruit.interest +
                        boost +
                        (prestige100(programPrestige) * .8).round() -
                        recruit.stars * 7) /
                    100)
                .clamp(.15, .92);

        if (rng.nextDouble() < userChance &&
            _recruitingClassHasRoom &&
            recruitCanCommitToSubdivision(recruit, currentSubdivision)) {
          recruit.committedSchool = widget.team.name;
          commits++;
          userCommits.add(recruit);
        } else {
          recruit.committedSchool = _randomOtherSchoolForRecruit(recruit);
        }
      }
    });

    for (final recruit in userCommits) {
      if (!recruit.commitmentPopupShown) {
        recruit.commitmentPopupShown = true;
        _showCommitPopup(recruit, true);
      }
    }
  }

  void _finalizeRecruitingClass() {
    final userCommits = <Recruit>[];

    setState(() {
      recruitingWindow = 3;

      for (final recruit in recruits) {
        if (recruit.committedSchool != null) continue;

        // A player must have a destination once recruiting closes.
        // Offered players still give the user's program a final chance.
        if (recruit.offered) {
          final userChance =
              ((recruit.interest +
                          (prestige100(programPrestige) * .8).round() -
                          recruit.stars * 7) /
                      100)
                  .clamp(.15, .78);

          if (rng.nextDouble() < userChance &&
              _recruitingClassHasRoom &&
              recruitCanCommitToSubdivision(recruit, currentSubdivision)) {
            recruit.committedSchool = widget.team.name;
            commits++;
            userCommits.add(recruit);
          } else {
            recruit.committedSchool = _randomOtherSchoolForRecruit(recruit);
          }
        } else {
          // Unoffered prospects sign elsewhere instead of remaining
          // uncommitted through the postseason and offseason.
          recruit.committedSchool = _randomOtherSchoolForRecruit(recruit);
        }

        recruit.decisionWindow = 3;
      }
    });

    for (final recruit in userCommits) {
      if (!recruit.commitmentPopupShown) {
        recruit.commitmentPopupShown = true;
        _showCommitPopup(recruit, true);
      }
    }

    _autoSaveCareer();
  }

  List<Recruit> _filteredRecruits() {
    final band = recruitStarBandForPrestigeTier(prestigeTier(programPrestige));

    final list = recruits.where((recruit) {
      final boardMatch = switch (recruitBoardTab) {
        1 => true,
        2 =>
          (recruit.offered || recruit.scouts > 0) &&
              recruit.committedSchool != widget.team.name,
        3 => recruit.committedSchool == widget.team.name,
        _ => recruit.committedSchool == null,
      };

      // A program's board only ever shows recruits realistically within
      // its reach — an elite school never sees a 1-2 star scrub, and a
      // bottom-tier program never sees a blue-chip who was never coming.
      // Anyone already offered or committed stays visible even if the
      // program's tier has since shifted mid-cycle.
      final tierMatch =
          (recruit.stars >= band.min && recruit.stars <= band.max) ||
          recruit.offered ||
          recruit.committedSchool == widget.team.name;

      final starMatch = starFilter == null || recruit.stars == starFilter;
      final positionMatch =
          positionFilter == null || recruit.position == positionFilter;
      final stateMatch = stateFilter == null || recruit.state == stateFilter;

      return boardMatch &&
          tierMatch &&
          starMatch &&
          positionMatch &&
          stateMatch;
    }).toList();

    return _sortRecruitList(list);
  }

  Map<String, int> _positionNeeds() {
    final result = <String, int>{};
    for (final pos in ['QB', 'HB', 'WR', 'TE', 'DE']) {
      result[pos] = roster
          .where((p) => p.position == pos && p.year == 'SR')
          .length
          .clamp(1, 3);
    }
    return result;
  }

  String _recruitingAccessText() {
    return switch (prestigeTier(programPrestige)) {
      1 => '1★-2★ players',
      2 => '1★-3★ players',
      3 => '2★-4★ players',
      4 => '3★-5★ players',
      _ => 'all recruits',
    };
  }

