class TrophyRoomScreen extends StatelessWidget {
  final CollegeTeam team;
  final List<TrophyEntry> trophies;
  final Map<String, SeasonStatRecord> seasonStatRecords;
  final Map<String, RivalrySeriesRecord> rivalrySeries;
  final CollegeTeam? rivalryTeam;

  const TrophyRoomScreen({
    super.key,
    required this.team,
    required this.trophies,
    this.seasonStatRecords = const {},
    this.rivalrySeries = const {},
    this.rivalryTeam,
  });

  @override
  Widget build(BuildContext context) {
    final sorted = trophies.toList()..sort((a, b) => b.year.compareTo(a.year));
    final rivalryRecord = rivalryTeam == null
        ? null
        : rivalrySeries[rivalryTeam!.name];

    return Scaffold(
      appBar: AppBar(title: const AppTitle('Trophy Room')),
      body: GKBackground(
        child: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          Text(
            '${team.name.toUpperCase()} TROPHY ROOM',
            style: const TextStyle(
              color: GKColors.parchmentWhite,
              fontSize: 30,
              fontWeight: FontWeight.w900,
              letterSpacing: 3,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            'Career trophies collected across this dynasty.',
            style: TextStyle(
              color: GKColors.fadedInk,
              fontWeight: FontWeight.bold,
            ),
          ),
          const SizedBox(height: 20),
          _trophySummary(sorted),
          const SizedBox(height: 20),
          if (sorted.isEmpty)
            _emptyCard(
              'No trophies yet. Win a bowl, conference championship, or national championship to add one here.',
            )
          else
            ...sorted.map(_trophyCard),
          if (rivalryTeam != null && rivalryRecord != null) ...[
            const SizedBox(height: 28),
            _sectionHeading('RIVALRY TROPHY CASE'),
            const SizedBox(height: 12),
            _rivalryCard(rivalryTeam!, rivalryRecord),
          ],
          if (seasonStatRecords.isNotEmpty) ...[
            const SizedBox(height: 28),
            _sectionHeading('PROGRAM RECORDS'),
            const SizedBox(height: 12),
            ...seasonRecordCategoryLabels.keys
                .where((category) => seasonStatRecords.containsKey(category))
                .map((category) => _recordCard(category)),
