class ConfettiPainter extends CustomPainter {
  final double progress;

  ConfettiPainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint();
    const colors = [
      kGold,
      kRed,
      kGreen,
      GKColors.parchmentWhite,
      Color(0xFF4A90E2),
    ];

    for (int i = 0; i < 90; i++) {
      final seed = i * 37;
      final x = ((seed * 17) % max(size.width.toInt(), 1)).toDouble();
      final speed = 0.55 + ((seed % 13) / 20);
      final y =
          ((progress * size.height * speed) + (seed * 11)) %
              (size.height + 80) -
          80;
      final w = 6 + (seed % 5).toDouble();
      final h = 10 + (seed % 7).toDouble();

      paint.color = colors[i % colors.length].withOpacity(.92);
      canvas.save();
      canvas.translate(x, y);
      canvas.rotate((progress * 6.28) + i);
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromCenter(center: Offset.zero, width: w, height: h),
          const Radius.circular(2),
        ),
        paint,
      );
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant ConfettiPainter oldDelegate) {
    return oldDelegate.progress != progress;
  }
}

// A small decorative bracket-tree glyph for the broadcast shot's corner —
// two rounds converging to a line, echoing the network's on-screen graphic
// without needing real data (the actual bracket is the detailed one shown
// once the field is revealed).
class BracketGlyphPainter extends CustomPainter {
  const BracketGlyphPainter();

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = Colors.white.withOpacity(.82)
      ..strokeWidth = 1.4
      ..style = PaintingStyle.stroke;
    final w = size.width;
    final h = size.height;

    canvas.drawLine(Offset(2, h * .15), Offset(w * .4, h * .15), paint);
    canvas.drawLine(Offset(2, h * .38), Offset(w * .4, h * .38), paint);
    canvas.drawLine(Offset(w * .4, h * .15), Offset(w * .4, h * .38), paint);
    canvas.drawLine(Offset(w * .4, h * .26), Offset(w * .7, h * .26), paint);

    canvas.drawLine(Offset(2, h * .62), Offset(w * .4, h * .62), paint);
    canvas.drawLine(Offset(2, h * .85), Offset(w * .4, h * .85), paint);
    canvas.drawLine(Offset(w * .4, h * .62), Offset(w * .4, h * .85), paint);
    canvas.drawLine(Offset(w * .4, h * .73), Offset(w * .7, h * .73), paint);

    canvas.drawLine(Offset(w * .7, h * .26), Offset(w * .7, h * .73), paint);
    canvas.drawLine(Offset(w * .7, h * .5), Offset(w * .95, h * .5), paint);
  }

  @override
  bool shouldRepaint(covariant BracketGlyphPainter oldDelegate) => false;
}

// The FCS-coaching equivalent of SelectionScreen's Selection Show — an FBS
// coach watches that screen reveal the 12-team KP field; an FCS coach
// watches this one reveal the real 24-team FCS field instead. Deliberately
// simpler than SelectionScreen's full animated broadcast treatment (no
// bowl branch to resolve — real FCS has none), but still a genuine reveal
// moment with a Continue action, not a silent state change.
class FcsSelectionScreen extends StatelessWidget {
  final CollegeTeam team;
  final List<CollegeTeam> seeds;
  final Map<String, TeamSeasonRecord> teamRecords;
  final VoidCallback onContinue;

  const FcsSelectionScreen({
    super.key,
    required this.team,
    required this.seeds,
    this.teamRecords = const {},
    required this.onContinue,
  });

  int get _userSeedIndex => seeds.indexWhere((t) => t.name == team.name);

  @override
  Widget build(BuildContext context) {
    final madeField = _userSeedIndex >= 0;
    final seed = _userSeedIndex + 1;
    final hasBye = madeField && seed <= 8;

    return Scaffold(
      backgroundColor: kDark,
      body: GKBackground(
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.all(20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'FCS PLAYOFF SELECTION SHOW',
                      style: TextStyle(
                        color: kGold,
                        fontSize: 13,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 2,
                      ),
                    ),
                    const SizedBox(height: 8),
                    Text(
                      madeField
                          ? (hasBye
                              ? '${team.name} is the #$seed seed and earns a first-round bye.'
                              : '${team.name} is the #$seed seed and opens the bracket on the road.')
                          : '${team.name} is on the outside looking in — the season ends here.',
                      style: const TextStyle(
                        color: GKColors.parchmentWhite,
                        fontSize: 20,
                        fontWeight: FontWeight.bold,
                        height: 1.3,
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: ListView.builder(
                  padding: const EdgeInsets.symmetric(horizontal: 18),
                  itemCount: seeds.length,
                  itemBuilder: (context, index) {
                    final seedTeam = seeds[index];
                    final isUser = seedTeam.name == team.name;
                    return Container(
                      margin: const EdgeInsets.only(bottom: 8),
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: isUser ? kGold.withOpacity(.16) : kCardColor,
                        border: Border.all(color: isUser ? kGold : kBorder),
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: Row(
                        children: [
                          SizedBox(
                            width: 32,
                            child: Text(
                              '#${index + 1}',
                              style: TextStyle(
                                color: isUser ? kGold : GKColors.fadedInk,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ),
                          Expanded(
                            child: Text(
                              seedTeam.name,
                              style: TextStyle(
                                color: isUser
                                    ? kGold
                                    : GKColors.parchmentWhite,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ),
                          if (index < 8)
                            Text(
                              'BYE',
                              style: TextStyle(
                                color: GKColors.fadedInk,
                                fontSize: 11,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                        ],
                      ),
                    );
                  },
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(18, 0, 18, 12),
                child: SizedBox(
                  width: double.infinity,
                  child: OutlinedButton(
                    onPressed: () {
                      Navigator.of(context).push(
                        MaterialPageRoute(
                          builder: (_) => FcsBracketScreen(
                            seeds: seeds,
                            teamRecords: teamRecords,
                          ),
                        ),
                      );
                    },
                    style: OutlinedButton.styleFrom(
                      minimumSize: const Size(double.infinity, 54),
                      foregroundColor: kGold,
                      side: BorderSide(color: kGold),
                    ),
                    child: const Text('VIEW FULL BRACKET'),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(18, 0, 18, 18),
                child: SizedBox(
                  width: double.infinity,
                  child: DynastyButton(
                    text: madeField ? 'ENTER THE BRACKET' : 'CONTINUE',
                    onPressed: () {
                      onContinue();
                      Navigator.of(context).pop();
                    },
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class SelectionResult {
  final String phase;
  final String? bowlName;

  const SelectionResult(this.phase, {this.bowlName});
}

class SelectionScreen extends StatefulWidget {
  final CollegeTeam team;
  final int season;
  final String record;
  final int wins;
  final int losses;
  final int confWins;
  final int confLosses;
  final int rank;
  final int teamOvr;
  final Map<String, TeamSeasonRecord> teamRecords;
  final bool conferenceChampEligible;
  final bool cfpEligible;
  final bool bowlEligible;
  final String existingAssignedBowlName;
  // True for the second reveal — the one that runs after conference
  // championship week, once the real KP/bowl fate is known. The first
  // reveal (right after the regular season) only ever announces "you're
  // headed to the conference championship" for eligible teams; it never
  // pretends to know the KP/bowl outcome that game hasn't decided yet.
  final bool postConferenceChamp;
  // The real, seed-ordered 12-team KP field (Power 4 auto-bids resolved via
  // actual championship games, plus the best at-large teams nationally).
  // When empty/incomplete, the bracket falls back to a naive win-pct sort so
  // existing call sites that don't pass it still render something sensible.
  final List<CollegeTeam> cfpField;
  final ValueChanged<SelectionResult> onContinue;

  const SelectionScreen({
    super.key,
    required this.team,
    required this.season,
    required this.record,
    required this.wins,
    required this.losses,
    required this.confWins,
    required this.confLosses,
    required this.rank,
    required this.teamOvr,
    required this.teamRecords,
    required this.conferenceChampEligible,
    required this.cfpEligible,
    required this.bowlEligible,
    this.existingAssignedBowlName = '',
    this.postConferenceChamp = false,
    this.cfpField = const [],
    required this.onContinue,
  });

  @override
  State<SelectionScreen> createState() => _SelectionScreenState();
}

class _SelectionScreenState extends State<SelectionScreen>
    with TickerProviderStateMixin {
  int revealStep = 0;

  // Pulses the "LIVE" dot for the whole broadcast.
  late final AnimationController _liveController = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 900),
  )..repeat(reverse: true);

  // Plays once, fading/sliding the reactions screen's content in the
  // moment it first appears.
  late final AnimationController _reactionsController = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 500),
  );

  @override
  void dispose() {
    _liveController.dispose();
    _reactionsController.dispose();
    super.dispose();
  }

  void _advanceRevealStep() {
    setState(() => revealStep++);
    if (revealStep == 3) {
      _reactionsController.forward(from: 0);
    }
  }

  String get selectedBowlName {
    if (widget.existingAssignedBowlName.trim().isNotEmpty) {
      return widget.existingAssignedBowlName;
    }

    final recordKey =
        widget.wins * 31 + widget.losses * 17 + widget.team.name.hashCode.abs();

    final List<String> choices;

    if (widget.wins >= 11) {
      choices = const [
        'Grove Bowl',
        'Mission Bowl',
        'Bayfront Bowl',
        'Coastline Bowl',
      ];
    } else if (widget.wins == 10) {
      choices = const [
        'Harmony Bowl',
        'Rio Bowl',
        'Neon Bowl',
        'Riverside Bowl',
      ];
    } else if (widget.wins == 9) {
      choices = const [
        'Heritage Bowl',
        'Solstice Bowl',
        'Empire Bowl',
        'Queen City Bowl',
      ];
    } else if (widget.wins == 8) {
      choices = const [
        'Patriots Bowl',
        'Service Bowl',
        'Ironworks Bowl',
        'Desert Sky Bowl',
      ];
    } else if (widget.wins == 7) {
      choices = const [
        'Frontline Bowl',
        'Metroplex Bowl',
        'Mesa Bowl',
        'Buccaneer Bowl',
      ];
    } else {
      choices = const [
        'Beacon Bowl',
        'Boardwalk Bowl',
        'Bayou Bowl',
        'Magnolia Bowl',
      ];
    }

    return choices[recordKey % choices.length];
  }

  bool get lowRecordConferenceChamp {
    return widget.conferenceChampEligible && widget.wins < 10;
  }

  String get destination {
    if (widget.conferenceChampEligible) return 'Conference Championship';
    if (widget.cfpEligible) return 'Kingdom Football Playoff';
    if (widget.bowlEligible) return selectedBowlName;
    return 'No Bowl';
  }

  String get nextPhase {
    if (widget.conferenceChampEligible) return 'confChamp';
    if (widget.cfpEligible) return 'cfp';
    if (widget.bowlEligible) return 'bowl';
    return 'offseason';
  }

  String get committeeMessage {
    if (widget.conferenceChampEligible) {
      if (lowRecordConferenceChamp) {
        return 'You reached the conference championship, but your overall record is not strong enough for the KP. Win or lose, your postseason path is a bowl game.';
      }
      return 'The committee is watching your championship game. You still need an elite record and ranking to make the KP.';
    }
    if (widget.cfpEligible) {
      return 'Your record and ranking were strong enough. You are officially in the Kingdom Football Playoff.';
    }
    if (widget.bowlEligible) {
      return 'You missed the KP, but your record earned an invitation to the $selectedBowlName.';
    }
    return 'You were left out because you did not reach six wins. You are not bowl eligible.';
  }

  // The on-air talent for this broadcast — same names every time this
  // season comes up, different reporters on the pre- and post-conference-
  // championship editions.
  String get _anchorName => kingdomNetworkReportersFor(
    widget.season,
    salt:
        (widget.postConferenceChamp ? 9001 : 9000) +
        widget.team.name.hashCode.abs() % 613,
  ).first;

  List<String> get _analystNames => kingdomNetworkReportersFor(
    widget.season,
    count: 2,
    salt: 9100 + widget.team.name.hashCode.abs() % 997,
  );

  static const List<String> _fanHandles = [
    '@GridironTakes',
    '@SaturdayFaithful',
    '@KingdomFanatic',
    '@EndZoneEcho',
    '@BleacherLoud',
    '@FourthQuarterFire',
    '@RedZoneRadio',
    '@OptionRoute',
  ];

  List<String> get _fanHandlePair {
    final pool = [..._fanHandles];
    final local = Random(
      widget.season * 131 +
          widget.team.name.hashCode.abs() +
          (widget.postConferenceChamp ? 71 : 0),
    );
    pool.shuffle(local);
    return pool.take(2).toList();
  }

  List<String> get _analystQuotes {
    if (widget.cfpEligible) {
      return [
        '${widget.team.displayName} punches its ticket — #${widget.rank} nationally and playing for a championship.',
        'This bracket has real teeth. Nobody in that field is a guaranteed out.',
      ];
    }
    if (widget.bowlEligible) {
      return [
        '${widget.team.displayName} finishes bowl eligible at ${widget.record} — a real building block heading into next year.',
        'The $selectedBowlName is a good measuring-stick game for this staff.',
      ];
    }
    if (widget.conferenceChampEligible) {
      return [
        '${widget.team.displayName} crashed the championship game — the conference didn\'t see that coming.',
        'Win this and the whole story of the season changes.',
      ];
    }
    return [
      '${widget.team.displayName} finishes at ${widget.record}. The offseason questions start now for this staff.',
      'A long winter ahead, but there\'s a foundation here to build on.',
    ];
  }

  List<String> get _fanQuotes {
    if (widget.cfpEligible) {
      return [
        '${widget.team.name} in the field?! Let\'s ride.',
        'Real shot at this thing. #${widget.rank} and rising.',
      ];
    }
    if (widget.bowlEligible) {
      return [
        '$selectedBowlName trip locked in. See you there.',
        '${widget.record} season — I\'ll take it.',
      ];
    }
    if (widget.conferenceChampEligible) {
      return [
        'CHAMPIONSHIP GAME. Nobody believed in us.',
        'Whatever happens Saturday, this season already overdelivered.',
      ];
    }
    return [
      'Rough year. Trust the staff, though.',
      'On to next season. ${widget.record} isn\'t good enough and we know it.',
    ];
  }

  Widget _liveBadge() {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
      decoration: BoxDecoration(
        color: kRed.withOpacity(.16),
        border: Border.all(color: kRed),
        borderRadius: BorderRadius.circular(6),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          FadeTransition(
            opacity: Tween<double>(begin: 1, end: .25).animate(
              CurvedAnimation(parent: _liveController, curve: Curves.easeInOut),
            ),
            child: Container(
              width: 7,
              height: 7,
              decoration: const BoxDecoration(
                color: kRed,
                shape: BoxShape.circle,
              ),
            ),
          ),
          const SizedBox(width: 5),
          Text(
            'LIVE',
            style: TextStyle(
              color: kRed,
              fontWeight: FontWeight.w900,
              fontSize: 11,
              letterSpacing: 1,
            ),
          ),
        ],
      ),
    );
  }

  // A deterministic, neutral "network anchor" — a professional desk
  // presenter, not the user's own coach, whose look ties to whichever
  // reporter is on air today (same reporter always looks the same).
  Widget _anchorAvatar() {
    final seed = _anchorName.hashCode.abs();
    const hairColors = ['Gray', 'Silver', 'Dark Brown', 'Black', 'Brown'];
    const hairStyles = ['Short', 'Slick Back', 'Bald', 'Buzz Cut'];
    const skinTones = [
      'Fair',
      'Light',
      'Tan',
      'Olive',
      'Brown',
      'Deep',
      'Dark',
    ];

    return Container(
      width: 96,
      height: 96,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        border: Border.all(color: kGold.withOpacity(.7), width: 2),
      ),
      child: ClipOval(
        child: CustomPaint(
          painter: CoachAvatarPainter(
            skinColor: coachSkinColorFor(skinTones[seed % skinTones.length]),
            hairColor: coachHairColorFor(
              hairColors[(seed ~/ 7) % hairColors.length],
            ),
            hairStyle: hairStyles[(seed ~/ 13) % hairStyles.length],
            beard: 'None',
            glasses: seed % 3 != 0,
            teamColor: const Color(0xFF1B3A5C),
          ),
        ),
      ),
    );
  }

  // The "broadcast shot": a studio backdrop with the LIVE badge and a
  // decorative bracket glyph in the corners (like a network's persistent
  // on-screen graphics), the anchor on camera, and a lower-third banner
  // carrying the show's title.
  Widget _broadcastHeader() {
    return Column(
      children: [
        Container(
          width: double.infinity,
          decoration: BoxDecoration(
            gradient: const LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [Color(0xFF0B1420), Color(0xFF16283D)],
            ),
            borderRadius: BorderRadius.circular(22),
            border: Border.all(color: kBorder),
          ),
          clipBehavior: Clip.antiAlias,
          child: Stack(
            children: [
              Positioned(top: 12, left: 12, child: _liveBadge()),
              Positioned(
                top: 12,
                right: 12,
                child: Container(
                  width: 42,
                  height: 42,
                  padding: const EdgeInsets.all(6),
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(.06),
                    border: Border.all(color: Colors.white.withOpacity(.25)),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: const CustomPaint(painter: BracketGlyphPainter()),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 54, 20, 18),
                child: Column(
                  children: [
                    _anchorAvatar(),
                    const SizedBox(height: 16),
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.symmetric(vertical: 10),
                      decoration: BoxDecoration(
                        color: kGold,
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Column(
                        children: [
                          Text(
                            'KINGDOM NETWORK',
                            style: TextStyle(
                              color: GKColors.inkBlack,
                              fontWeight: FontWeight.w900,
                              fontSize: 11,
                              letterSpacing: 2,
                            ),
                          ),
                          const SizedBox(height: 2),
                          Text(
                            widget.postConferenceChamp
                                ? 'FINAL SELECTION SHOW'
                                : 'SELECTION SHOW',
                            style: const TextStyle(
                              color: GKColors.inkBlack,
                              fontSize: 20,
                              fontWeight: FontWeight.w900,
                              letterSpacing: 1,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 8),
        Text(
          'With $_anchorName',
          textAlign: TextAlign.center,
          style: TextStyle(
            color: GKColors.mutedSilver,
            fontSize: 12,
            fontWeight: FontWeight.w700,
          ),
        ),
      ],
    );
  }

  Widget _theFieldRow() {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: kCardColor,
        border: Border.all(color: kBorder),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        children: [
          Text(
            'COMMITTEE ROOM',
            style: TextStyle(
              color: kGold,
              fontWeight: FontWeight.w900,
              letterSpacing: 3,
              fontSize: 10,
            ),
          ),
          const SizedBox(height: 6),
          Text(
            'THE FIELD',
            style: const TextStyle(
              color: GKColors.parchmentWhite,
              fontWeight: FontWeight.w900,
              fontSize: 22,
              letterSpacing: 1,
            ),
          ),
          const SizedBox(height: 14),
          Row(
            children: [
              Expanded(child: _stat('12', 'TEAMS')),
              Expanded(child: _stat('4', 'BYES')),
              Expanded(child: _stat('8', 'FIRST ROUND')),
            ],
          ),
        ],
      ),
    );
  }

  Widget _revealBody() {
    final showResult = revealStep >= 2;

    return ListView(
      padding: const EdgeInsets.all(20),
      children: [
        _broadcastHeader(),
        const SizedBox(height: 10),
        Text(
          widget.postConferenceChamp
              ? 'The conference championship is in the books — the committee finalizes the field.'
              : 'Conference officials, bowl committees, and the KP committee are reviewing your season...',
          textAlign: TextAlign.center,
          style: TextStyle(
            color: GKColors.fadedInk,
            fontWeight: FontWeight.bold,
          ),
        ),
        const SizedBox(height: 24),
        Container(
          padding: const EdgeInsets.all(22),
          decoration: BoxDecoration(
            color: kCardColor,
            border: Border.all(color: kBorder),
            borderRadius: BorderRadius.circular(24),
          ),
          child: Column(
            children: [
              Text(
                widget.team.fullName.toUpperCase(),
                style: const TextStyle(
                  color: kGold,
                  fontSize: 28,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 2,
                ),
              ),
              const SizedBox(height: 18),
              Row(
                children: [
                  Expanded(child: _stat(widget.record, 'RECORD')),
                  Expanded(
                    child: _stat(
                      '${widget.confWins}-${widget.confLosses}',
                      'CONF',
                    ),
                  ),
                  Expanded(child: _stat('#${widget.rank}', 'RANK')),
                  Expanded(child: _stat('${widget.teamOvr}', 'Overall')),
                ],
              ),
              const Divider(color: kBorder, height: 34),
              AnimatedSwitcher(
                duration: const Duration(milliseconds: 450),
                transitionBuilder: (child, animation) => FadeTransition(
                  opacity: animation,
                  child: ScaleTransition(
                    scale: Tween<double>(begin: .92, end: 1).animate(
                      CurvedAnimation(
                        parent: animation,
                        curve: Curves.easeOutBack,
                      ),
                    ),
                    child: child,
                  ),
                ),
                child: revealStep == 0
                    ? Text(
                        'Committee Discussion...',
                        key: const ValueKey('step0'),
                        style: TextStyle(
                          color: GKColors.fadedInk,
                          fontSize: 24,
                          fontWeight: FontWeight.w900,
                        ),
                      )
                    : revealStep == 1
                    ? Text(
                        'Final Envelope Is In...',
                        key: const ValueKey('step1'),
                        style: TextStyle(
                          color: kGold,
                          fontSize: 24,
                          fontWeight: FontWeight.w900,
                        ),
                      )
                    : Text(
                        destination.toUpperCase(),
                        key: const ValueKey('step2'),
                        textAlign: TextAlign.center,
                        style: TextStyle(
                          color: destination == 'No Bowl' ? kRed : kGold,
                          fontSize: 26,
                          fontWeight: FontWeight.w900,
                          letterSpacing: 2,
                        ),
                      ),
              ),
              const SizedBox(height: 14),
              if (showResult)
                Text(
                  committeeMessage,
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: GKColors.parchmentWhite,
                    height: 1.4,
                    fontSize: 16,
                  ),
                ),
            ],
          ),
        ),
        const SizedBox(height: 24),
        if (showResult)
          TweenAnimationBuilder<double>(
            tween: Tween(begin: 0, end: 1),
            duration: const Duration(milliseconds: 500),
            curve: Curves.easeOut,
            builder: (context, value, child) => Opacity(
              opacity: value,
              child: Transform.translate(
                offset: Offset(0, (1 - value) * 16),
                child: child,
              ),
            ),
            child: Column(
              children: [
                // The bracket reveals for everyone watching, not just
                // whoever made the field — same as a real selection show.
                // The one exception is a team still waiting on its
                // conference championship: the field genuinely isn't
                // final yet.
                if (!widget.conferenceChampEligible) ...[
                  _theFieldRow(),
                  const SizedBox(height: 16),
                  _cfpSeeds(),
                  const SizedBox(height: 16),
                ],
                if (widget.bowlEligible &&
                    !widget.cfpEligible &&
                    !widget.conferenceChampEligible)
                  _bowlCard(),
                if (lowRecordConferenceChamp)
                  _bowlCard(
                    note:
                        'Projected bowl if your record keeps you out of the KP after the conference championship.',
                  ),
                if (!widget.bowlEligible &&
                    !widget.cfpEligible &&
                    !widget.conferenceChampEligible)
                  _noBowlCard(),
              ],
            ),
          ),
        const SizedBox(height: 24),
        DynastyButton(
          text: showResult ? 'Continue' : 'Reveal',
          onPressed: _advanceRevealStep,
        ),
      ],
    );
  }

  Widget _reactionCard({
    required String name,
    required String handle,
    required String quote,
    bool fan = false,
  }) {
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: kCardColor,
        border: Border.all(color: kBorder),
        borderRadius: BorderRadius.circular(16),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          CircleAvatar(
            radius: 20,
            backgroundColor: fan
                ? GKColors.mutedSilver.withOpacity(.25)
                : kGold.withOpacity(.22),
            child: Icon(
              fan ? Icons.person_outline_rounded : Icons.mic_rounded,
              color: fan ? GKColors.mutedSilver : kGold,
              size: 18,
            ),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (!fan)
                  Text(
                    name,
                    style: const TextStyle(
                      color: GKColors.parchmentWhite,
                      fontWeight: FontWeight.w900,
                      fontSize: 14,
                    ),
                  ),
                Text(
                  handle,
                  style: TextStyle(
                    color: GKColors.fadedInk,
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  quote,
                  style: const TextStyle(
                    color: GKColors.parchmentWhite,
                    height: 1.35,
                    fontSize: 13,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _reactionsBody() {
    final analysts = _analystNames;
    final analystQuotes = _analystQuotes;
    final fanHandles = _fanHandlePair;
    final fanQuotes = _fanQuotes;

    return FadeTransition(
      opacity: _reactionsController,
      child: SlideTransition(
        position: Tween<Offset>(begin: const Offset(0, .05), end: Offset.zero)
            .animate(
              CurvedAnimation(
                parent: _reactionsController,
                curve: Curves.easeOut,
              ),
            ),
        child: ListView(
          padding: const EdgeInsets.all(20),
          children: [
            _broadcastHeader(),
            const SizedBox(height: 10),
            Text(
              'Our reporters have circled the biggest storylines from the reveal.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: GKColors.fadedInk,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 24),
            Text(
              'AROUND THE KINGDOM',
              style: TextStyle(
                color: kGold,
                fontWeight: FontWeight.w900,
                letterSpacing: 3,
                fontSize: 12,
              ),
            ),
            const SizedBox(height: 10),
            Text(
              'REACTIONS',
              style: const TextStyle(
                color: GKColors.parchmentWhite,
                fontSize: 26,
                fontWeight: FontWeight.w900,
                letterSpacing: 2,
              ),
            ),
            const SizedBox(height: 16),
            for (var i = 0; i < analysts.length; i++)
              _reactionCard(
                name: analysts[i],
                handle:
                    '@${analysts[i].replaceAll(' ', '').replaceAll('’', '')}',
                quote: i < analystQuotes.length
                    ? analystQuotes[i]
                    : analystQuotes.last,
              ),
            const SizedBox(height: 8),
            Text(
              'FAN REACTIONS',
              style: TextStyle(
                color: GKColors.mutedSilver,
                fontWeight: FontWeight.w900,
                letterSpacing: 2,
                fontSize: 11,
              ),
            ),
            const SizedBox(height: 10),
            for (var i = 0; i < fanHandles.length; i++)
              _reactionCard(
                name: '',
                handle: fanHandles[i],
                quote: i < fanQuotes.length ? fanQuotes[i] : fanQuotes.last,
                fan: true,
              ),
            if (widget.cfpField.isNotEmpty) ...[
              const SizedBox(height: 12),
              OutlinedButton(
                onPressed: () {
                  Navigator.of(context).push(
                    MaterialPageRoute(
                      builder: (_) => CFPBracketScreen(
                        seeds: widget.cfpField,
                        teamRecords: widget.teamRecords,
                      ),
                    ),
                  );
                },
                style: OutlinedButton.styleFrom(
                  minimumSize: const Size(double.infinity, 54),
                  foregroundColor: kGold,
                  side: BorderSide(color: kGold),
                ),
                child: const Text('VIEW FULL BRACKET'),
              ),
            ],
            const SizedBox(height: 24),
            DynastyButton(
              text: 'Continue',
              onPressed: () {
                widget.onContinue(
                  SelectionResult(
                    nextPhase,
                    bowlName: nextPhase == 'bowl' ? selectedBowlName : null,
                  ),
                );
                Navigator.of(context).pop();
              },
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const AppTitle('Kingdom Network')),
      body: GKBackground(
        child: revealStep >= 3 ? _reactionsBody() : _revealBody(),
      ),
    );
  }

  Widget _stat(String value, String label) {
    return Column(
      children: [
        Text(
          value,
          style: const TextStyle(
            color: GKColors.parchmentWhite,
            fontSize: 23,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 4),
        Text(
          label,
          style: const TextStyle(
            color: GKColors.fadedInk,
            fontSize: 11,
            fontWeight: FontWeight.w900,
            letterSpacing: 1.5,
          ),
        ),
      ],
    );
  }

  List<CollegeTeam> _topTwelve() {
    if (widget.cfpField.length >= 12) {
      return widget.cfpField.take(12).toList();
    }

    final teams = g5Teams.toList();
    teams.sort((a, b) {
      final ar = widget.teamRecords[a.name] ?? TeamSeasonRecord();
      final br = widget.teamRecords[b.name] ?? TeamSeasonRecord();

      final pct = br.winPct.compareTo(ar.winPct);
      if (pct != 0) return pct;

      final wins = br.wins.compareTo(ar.wins);
      if (wins != 0) return wins;

      final prestige = b.prestige.compareTo(a.prestige);
      if (prestige != 0) return prestige;

      return a.name.compareTo(b.name);
    });

    return teams.take(12).toList();
  }

  Widget _bracketSeedRow(int seed, CollegeTeam team) {
    final isUser = team.name == widget.team.name;
    final rec = widget.teamRecords[team.name]?.overallText ?? '0-0';
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Row(
        children: [
          SizedBox(
            width: 22,
            child: Text(
              '$seed',
              style: TextStyle(
                color: isUser ? kGold : GKColors.fadedInk,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          GKTeamBadge(team: team, size: 24),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              team.name,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: isUser ? kGold : GKColors.parchmentWhite,
                fontWeight: FontWeight.w900,
                fontSize: 13,
              ),
            ),
          ),
          Text(
            rec,
            style: const TextStyle(
              color: GKColors.fadedInk,
              fontSize: 12,
              fontWeight: FontWeight.w700,
            ),
          ),
        ],
      ),
    );
  }

  Widget _bracketMatchup(
    CollegeTeam high,
    CollegeTeam low,
    int highSeed,
    int lowSeed,
  ) {
    final featured =
        high.name == widget.team.name || low.name == widget.team.name;
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 10),
      decoration: BoxDecoration(
        color: featured ? kGold.withOpacity(.08) : Colors.transparent,
        border: Border.all(color: featured ? kGold.withOpacity(.5) : kBorder),
        borderRadius: BorderRadius.circular(10),
      ),
      child: Column(
        children: [
          _bracketSeedRow(highSeed, high),
          const Divider(color: kBorder, height: 10),
          _bracketSeedRow(lowSeed, low),
        ],
      ),
    );
  }

  // A real 12-team bracket: seeds 1-4 draw a bye into the quarterfinals,
  // seeds 5-12 play the first round (5v12, 6v11, 7v10, 8v9) — not just a
  // flat ranked list.
  Widget _cfpSeeds() {
    final seeds = _topTwelve();
    if (seeds.length < 12) {
      return Container(
        padding: const EdgeInsets.all(18),
        decoration: BoxDecoration(
          color: kCardColor,
          border: Border.all(color: kBorder),
          borderRadius: BorderRadius.circular(22),
        ),
        child: Text(
          'Not enough tracked teams to fill the bracket.',
          style: TextStyle(
            color: GKColors.fadedInk,
            fontWeight: FontWeight.bold,
          ),
        ),
      );
    }

    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: kCardColor,
        border: Border.all(color: kBorder),
        borderRadius: BorderRadius.circular(22),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '12-TEAM KP BRACKET',
            style: TextStyle(
              color: kGold,
              fontWeight: FontWeight.w900,
              letterSpacing: 3,
            ),
          ),
          const SizedBox(height: 4),
          Text(
            'Seeds 1-4 earn a bye into the quarterfinals.',
            style: TextStyle(
              color: GKColors.fadedInk,
              fontSize: 11,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 14),
          Text(
            'BYES',
            style: TextStyle(
              color: kGreen,
              fontWeight: FontWeight.w900,
              fontSize: 11,
              letterSpacing: 2,
            ),
          ),
          const SizedBox(height: 4),
          ...List.generate(4, (i) => _bracketSeedRow(i + 1, seeds[i])),
          const SizedBox(height: 14),
          Text(
            'FIRST ROUND',
            style: TextStyle(
              color: kGold,
              fontWeight: FontWeight.w900,
              fontSize: 11,
              letterSpacing: 2,
            ),
          ),
          const SizedBox(height: 8),
          _bracketMatchup(seeds[4], seeds[11], 5, 12),
          _bracketMatchup(seeds[5], seeds[10], 6, 11),
          _bracketMatchup(seeds[6], seeds[9], 7, 10),
          _bracketMatchup(seeds[7], seeds[8], 8, 9),
        ],
      ),
    );
  }

  Widget _bowlCard({String? note}) {
    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: kGold.withOpacity(.08),
        border: Border.all(color: kGold.withOpacity(.4)),
        borderRadius: BorderRadius.circular(22),
      ),
      child: Text(
        'BOWL INVITE: $selectedBowlName\n${note ?? 'Your record earned this bowl slot based on your season resume.'}',
        style: const TextStyle(
          color: GKColors.parchmentWhite,
          height: 1.4,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }

  Widget _noBowlCard() {
    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: kRed.withOpacity(.08),
        border: Border.all(color: kRed.withOpacity(.4)),
        borderRadius: BorderRadius.circular(22),
      ),
      child: Text(
        'NO BOWL INVITE\nYou need at least 6 wins to become bowl eligible.',
        style: TextStyle(
          color: GKColors.parchmentWhite,
          height: 1.4,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }
}

/// A real locker-room read: which players are genuinely at transfer risk
/// and why (playing time, scheme fit, or NIL), not just the flat 0-100
/// team morale number already shown on the Dashboard's Program Pulse.
/// Every player currently sidelined, and how many weeks until they're
/// back — the injuries listed here are the exact same ones _playersAt
/// excludes from starting, so this always matches what's actually
/// happening on the field.
class MedicalScreen extends StatelessWidget {
  final CollegeTeam team;
  final List<Player> roster;
  final List<Injury> activeInjuries;
  final int currentWeek;

  const MedicalScreen({
    super.key,
    required this.team,
    required this.roster,
    required this.activeInjuries,
    required this.currentWeek,
  });

  Player? _playerByName(String name) {
    for (final p in roster) {
      if (p.name == name) return p;
    }
    return null;
  }

  Color _severityColor(int weeksRemaining) {
    if (weeksRemaining >= 5) return kRed;
    if (weeksRemaining >= 2) return kGold;
    return GKColors.fieldGreen;
  }

  @override
  Widget build(BuildContext context) {
    final sorted = activeInjuries.toList()
      ..sort((a, b) => b.weeksRemaining.compareTo(a.weeksRemaining));

    return Scaffold(
      appBar: AppBar(title: const AppTitle('Medical')),
      body: GKBackground(
        child: ListView(
          padding: const EdgeInsets.all(18),
          children: [
            Container(
              padding: const EdgeInsets.all(18),
              decoration: BoxDecoration(
                color: kCardColor,
                border: Border.all(color: kBorder),
                borderRadius: BorderRadius.circular(18),
              ),
              child: Row(
                children: [
                  Icon(
                    Icons.medical_services_outlined,
                    color: sorted.isEmpty ? kGreen : kGold,
                    size: 30,
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'TRAINING ROOM',
                          style: TextStyle(
                            color: GKColors.fadedInk,
                            fontSize: 10,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 1,
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          sorted.isEmpty
                              ? 'Full health across the roster'
                              : '${sorted.length} player${sorted.length == 1 ? '' : 's'} sidelined',
                          style: const TextStyle(
                            color: GKColors.parchmentWhite,
                            fontSize: 16,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 18),
            if (sorted.isEmpty)
              Container(
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: kCardColor,
                  border: Border.all(color: kBorder),
                  borderRadius: BorderRadius.circular(16),
                ),
                child: const Text(
                  'No one is currently hurt. Every starter is available for the next game.',
                  style: TextStyle(color: GKColors.fadedInk, height: 1.4),
                ),
              )
            else
              ...sorted.map((injury) {
                final player = _playerByName(injury.playerName);
                final color = _severityColor(injury.weeksRemaining);
                return Container(
                  margin: const EdgeInsets.only(bottom: 10),
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: kCardColor,
                    border: Border.all(color: color.withOpacity(.6)),
                    borderRadius: BorderRadius.circular(16),
                  ),
                  child: Row(
                    children: [
                      PlayerAvatar(
                        seed: injury.playerName.hashCode,
                        teamColor: team.primary,
                        size: 42,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              (player?.cleanName ?? injury.playerName)
                                  .toUpperCase(),
                              style: const TextStyle(
                                color: GKColors.parchmentWhite,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              player == null
                                  ? injury.description
                                  : '${player.position} · ${injury.description}',
                              style: const TextStyle(
                                color: GKColors.fadedInk,
                                fontSize: 11,
                              ),
                            ),
                          ],
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 9,
                          vertical: 6,
                        ),
                        decoration: BoxDecoration(
                          color: color.withOpacity(.14),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(color: color.withOpacity(.6)),
                        ),
                        child: Text(
                          '${injury.weeksRemaining}W OUT',
                          style: TextStyle(
                            color: color,
                            fontSize: 11,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                    ],
                  ),
                );
              }),
          ],
        ),
      ),
    );
  }
}

class MoraleScreen extends StatefulWidget {
  final CollegeTeam team;
  final List<Player> roster;
  final Set<String> starterNames;
  final String? offensiveScheme;
  final String? defensiveScheme;
  final int boosterApproval;
  final int teamMorale;
  final int Function() recruitingPoints;
  final int Function(Player) moraleForPlayer;
  final bool Function(Player) canTalkToPlayer;
  final bool Function(Player) isIrreconcilable;
  final void Function(Player) onTalkToPlayer;

  const MoraleScreen({
    super.key,
    required this.team,
    required this.roster,
    required this.starterNames,
    required this.offensiveScheme,
    required this.defensiveScheme,
    required this.boosterApproval,
    required this.teamMorale,
    required this.recruitingPoints,
    required this.moraleForPlayer,
    required this.canTalkToPlayer,
    required this.isIrreconcilable,
    required this.onTalkToPlayer,
  });

  @override
  State<MoraleScreen> createState() => _MoraleScreenState();
}

class _MoraleScreenState extends State<MoraleScreen> {
  static const List<String> _positionOrder = [
    'QB',
    'HB',
    'WR',
    'TE',
    'DE',
    'LB',
    'DB',
  ];

  Color _moraleColor(int morale) {
    if (morale < 45) return kRed;
    if (morale < 70) return kGold;
    return GKColors.fieldGreen;
  }

  void _talk(Player p) {
    widget.onTalkToPlayer(p);
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final assessments = {
      for (final p in widget.roster)
        p.name: transferRiskFor(
          p,
          isStarter: widget.starterNames.contains(p.name),
          offensiveScheme: widget.offensiveScheme,
          defensiveScheme: widget.defensiveScheme,
          boosterApproval: widget.boosterApproval,
        ),
    };
    final unhappyCount = widget.roster
        .where((p) => widget.moraleForPlayer(p) < 45)
        .length;

    return Scaffold(
      appBar: AppBar(title: const AppTitle('Morale')),
      body: GKBackground(
        child: ListView(
          padding: const EdgeInsets.all(18),
          children: [
            Container(
              padding: const EdgeInsets.all(18),
              decoration: BoxDecoration(
                color: kCardColor,
                border: Border.all(color: kBorder),
                borderRadius: BorderRadius.circular(18),
              ),
              child: Row(
                children: [
                  const Icon(Icons.groups_rounded, color: kGold, size: 30),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'LOCKER ROOM MORALE',
                          style: TextStyle(
                            color: GKColors.fadedInk,
                            fontSize: 10,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 1,
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          '${widget.teamMorale} / 100',
                          style: const TextStyle(
                            color: GKColors.parchmentWhite,
                            fontSize: 22,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                    ),
                  ),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.end,
                    children: [
                      Text(
                        '${widget.recruitingPoints()} RP',
                        style: const TextStyle(
                          color: kGold,
                          fontSize: 14,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      if (unhappyCount > 0)
                        Container(
                          margin: const EdgeInsets.only(top: 4),
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 6,
                          ),
                          decoration: BoxDecoration(
                            color: kRed.withOpacity(.14),
                            border: Border.all(color: kRed.withOpacity(.6)),
                            borderRadius: BorderRadius.circular(10),
                          ),
                          child: Text(
                            '$unhappyCount UNHAPPY',
                            style: const TextStyle(
                              color: kRed,
                              fontSize: 10,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                    ],
                  ),
                ],
              ),
            ),
            const SizedBox(height: 6),
            Text(
              'Talk to an unhappy player for 5 RP to raise their morale — already-happy players have no need for it.',
              style: TextStyle(
                color: GKColors.fadedInk,
                fontSize: 11,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 12),
            ..._positionOrder.map((position) {
              final players =
                  widget.roster.where((p) => p.position == position).toList()
                    ..sort(
                      (a, b) => widget
                          .moraleForPlayer(a)
                          .compareTo(widget.moraleForPlayer(b)),
                    );
              return _positionGroup(position, players, assessments);
            }),
          ],
        ),
      ),
    );
  }

  String _reasonDetail(TransferRiskReason reason, Player p) => switch (reason) {
    TransferRiskReason.playingTime =>
      '${p.cleanName.split(' ').first} is a ${p.year} stuck behind the depth chart and wants a real path to the field.',
    TransferRiskReason.schemeFit =>
      "${p.position} isn't a natural fit for this program's current scheme.",
    TransferRiskReason.nil =>
      '${p.cleanName.split(' ').first} expected stronger NIL backing from the program given their talent.',
  };

  Widget _positionGroup(
    String position,
    List<Player> players,
    Map<String, TransferRiskAssessment> assessments,
  ) {
    if (players.isEmpty) return const SizedBox.shrink();

    return Container(
      margin: const EdgeInsets.only(bottom: GKSpace.sm),
      decoration: BoxDecoration(
        color: GKColors.saddleLeather,
        border: Border.all(color: GKColors.divider),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(
              horizontal: GKSpace.md,
              vertical: GKSpace.sm,
            ),
            decoration: const BoxDecoration(
              border: Border(bottom: BorderSide(color: GKColors.divider)),
            ),
            child: Row(
              children: [
                Container(
                  width: 34,
                  height: 34,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: GKColors.kingdomBrass.withOpacity(.10),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Text(
                    position,
                    style: const TextStyle(
                      color: GKColors.kingdomBrass,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
                const SizedBox(width: GKSpace.sm),
                Expanded(
                  child: Text(
                    '$position ROOM',
                    style: const TextStyle(
                      color: GKColors.parchmentWhite,
                      fontWeight: FontWeight.w900,
                      letterSpacing: 1.4,
                    ),
                  ),
                ),
                Text(
                  '${players.length} PLAYERS',
                  style: const TextStyle(
                    color: GKColors.fadedInk,
                    fontSize: 9,
                    fontWeight: FontWeight.w900,
                    letterSpacing: .7,
                  ),
                ),
              ],
            ),
          ),
          ...players.asMap().entries.map((entry) {
            final p = entry.value;
            final a = assessments[p.name]!;
            final morale = widget.moraleForPlayer(p);
            final color = _moraleColor(morale);
            final irreconcilable = widget.isIrreconcilable(p);
            final canTalk = widget.canTalkToPlayer(p);
            return Container(
              padding: const EdgeInsets.all(GKSpace.sm),
              decoration: BoxDecoration(
                border: entry.key == players.length - 1
                    ? null
                    : const Border(
                        bottom: BorderSide(color: GKColors.stitchLine),
                      ),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      PlayerAvatar(
                        seed: p.name.hashCode,
                        teamColor: widget.team.primary,
                        size: 40,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              p.cleanName.toUpperCase(),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: GKColors.parchmentWhite,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            Text(
                              '${p.year} · ${p.stars}★ · ${awardOverall(p)} OVR',
                              style: const TextStyle(
                                color: GKColors.fadedInk,
                                fontSize: 11,
                              ),
                            ),
                          ],
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 9,
                          vertical: 6,
                        ),
                        decoration: BoxDecoration(
                          color: color.withOpacity(.14),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(color: color.withOpacity(.6)),
                        ),
                        child: Text(
                          '$morale',
                          style: TextStyle(
                            color: color,
                            fontSize: 15,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                    ],
                  ),
                  if (irreconcilable) ...[
                    const SizedBox(height: 8),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 9,
                        vertical: 5,
                      ),
                      decoration: BoxDecoration(
                        color: kRed.withOpacity(.16),
                        border: Border.all(color: kRed.withOpacity(.6)),
                        borderRadius: BorderRadius.circular(99),
                      ),
                      child: Text(
                        'WANTS TO TRANSFER — DIFFERENCES IRRECONCILABLE',
                        style: TextStyle(
                          color: kRed,
                          fontSize: 9,
                          fontWeight: FontWeight.w900,
                          letterSpacing: .5,
                        ),
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      '${p.cleanName.split(' ').first} has made up their mind. A retention NIL offer will no longer keep them.',
                      style: const TextStyle(
                        color: GKColors.fadedInk,
                        fontSize: 11,
                        height: 1.3,
                      ),
                    ),
                  ] else if (a.reasons.isNotEmpty) ...[
                    const SizedBox(height: 8),
                    Wrap(
                      spacing: 6,
                      runSpacing: 6,
                      children: a.reasons
                          .map(
                            (r) => Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 9,
                                vertical: 5,
                              ),
                              decoration: BoxDecoration(
                                color: GKColors.midnight.withOpacity(.5),
                                borderRadius: BorderRadius.circular(99),
                              ),
                              child: Text(
                                a.reasonLabel(r),
                                style: const TextStyle(
                                  color: GKColors.kingdomBrass,
                                  fontSize: 9,
                                  fontWeight: FontWeight.w900,
                                  letterSpacing: .5,
                                ),
                              ),
                            ),
                          )
                          .toList(),
                    ),
                    const SizedBox(height: 6),
                    ...a.reasons.map(
                      (r) => Padding(
                        padding: const EdgeInsets.only(top: 2),
                        child: Text(
                          _reasonDetail(r, p),
                          style: const TextStyle(
                            color: GKColors.fadedInk,
                            fontSize: 11,
                            height: 1.3,
                          ),
                        ),
                      ),
                    ),
                  ],
                  if (!irreconcilable) ...[
                    const SizedBox(height: 8),
                    SizedBox(
                      width: double.infinity,
                      child: GKSecondaryButton(
                        label: morale >= 70
                            ? 'Content — No Need'
                            : 'Talk to Player · 5 RP',
                        icon: Icons.forum_outlined,
                        onPressed: canTalk ? () => _talk(p) : null,
                      ),
                    ),
                  ],
                ],
              ),
            );
          }),
        ],
      ),
    );
