/// The full roster organized by position group — distinct from the depth
/// chart (Lineup), which splits players into the active starting unit vs.
/// the bench. This screen just names every player at their position.
class RosterScreen extends StatelessWidget {
  final CollegeTeam team;
  final List<Player> roster;
  final Set<String> starterNames;

  const RosterScreen({
    super.key,
    required this.team,
    required this.roster,
    required this.starterNames,
  });

  static const List<String> _positionOrder = [
    'QB',
    'HB',
    'WR',
    'TE',
    'DE',
    'LB',
    'DB',
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const AppTitle('Roster')),
      body: GKBackground(
        child: ListView(
          padding: const EdgeInsets.all(18),
          children: [
            Text('${roster.length} PLAYERS BY POSITION', style: GKText.sectionLabel),
            const SizedBox(height: 12),
            ..._positionOrder.map((position) {
              final players =
                  roster.where((p) => p.position == position).toList()
                    ..sort(
                      (a, b) => awardOverall(b).compareTo(awardOverall(a)),
