class ArchiveBracketScreen extends StatelessWidget {
  final NationalTitleHistoryEntry entry;

  const ArchiveBracketScreen({super.key, required this.entry});

  @override
  Widget build(BuildContext context) {
    final seeds = archiveBracketFieldFor(
      year: entry.year,
      winnerName: entry.winner,
      loserName: entry.loser,
    );

    String seedLabel(int index) {
      if (index >= seeds.length) return 'TBD';
      return '${index + 1}. ${seeds[index].displayName}';
    }

    Widget seedCard(String text, {bool winner = false, bool bye = false}) {
      return Container(
        width: double.infinity,
        margin: const EdgeInsets.only(bottom: 10),
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: winner
              ? kGold.withOpacity(.22)
              : bye
              ? kGold.withOpacity(.10)
              : kCardColor,
          border: Border.all(color: winner || bye ? kGold : kBorder),
          borderRadius: BorderRadius.circular(16),
        ),
        child: Text(
          text,
          style: TextStyle(
            color: winner || bye ? kGold : GKColors.parchmentWhite,
            fontWeight: FontWeight.w900,
          ),
        ),
      );
    }

    Widget gameCard(String title, int seedA, int seedB, {String? note}) {
      // Chalk holds every round except the recorded title game — the lower
      // seed always advances, which is what naturally seats the real
      // champion (seed 1) against the real runner-up (seed 2) in the final.
      final aWins = seedA < seedB;
      return Container(
        width: double.infinity,
        margin: const EdgeInsets.only(bottom: 14),
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: kCardColor,
          border: Border.all(color: kBorder),
          borderRadius: BorderRadius.circular(18),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              title.toUpperCase(),
              style: const TextStyle(
                color: kGold,
                fontWeight: FontWeight.w900,
                letterSpacing: 2,
              ),
            ),
            const SizedBox(height: 10),
            Text(
              seedLabel(seedA),
              style: TextStyle(
                color: aWins ? kGold : GKColors.parchmentWhite,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 6),
            const Text(
              'vs',
              style: TextStyle(
                color: GKColors.fadedInk,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 6),
            Text(
              seedLabel(seedB),
              style: TextStyle(
                color: !aWins ? kGold : GKColors.parchmentWhite,
                fontWeight: FontWeight.w900,
              ),
            ),
            if (note != null) ...[
              const SizedBox(height: 8),
              Text(
                note,
                style: const TextStyle(
                  color: GKColors.fadedInk,
                  fontSize: 11,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
          ],
        ),
      );
    }

    return Scaffold(
      appBar: AppBar(title: Text('Season ${entry.year} KP Bracket')),
      body: GKBackground(
        child: ListView(
          padding: const EdgeInsets.all(18),
          children: [
            Text(
              'SEASON ${entry.year} · 12-TEAM KP BRACKET',
              style: const TextStyle(
                color: kGold,
                fontSize: 20,
                fontWeight: FontWeight.w900,
                letterSpacing: 2,
              ),
            ),
            const SizedBox(height: 8),
            Text(
              'Reconstructed from the recorded result — seeds 1 and 2 are '
              'the real champion and runner-up; the rest of the field is '
              'a plausible fill from that season.',
              style: TextStyle(
                color: GKColors.fadedInk,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 18),
            SectionCard(
              title: 'First Round Byes',
              child: Column(
                children: [
                  seedCard(seedLabel(0), bye: true),
                  seedCard(seedLabel(1), bye: true),
                  seedCard(seedLabel(2), bye: true),
                  seedCard(seedLabel(3), bye: true),
                ],
              ),
            ),
            SectionCard(
              title: 'First Round',
              child: Column(
                children: [
                  gameCard('First Round', 4, 11),
                  gameCard('First Round', 5, 10),
                  gameCard('First Round', 6, 9),
                  gameCard('First Round', 7, 8),
                ],
              ),
            ),
            SectionCard(
              title: 'Quarterfinals',
              child: Column(
                children: [
                  gameCard('Quarterfinal', 0, 7),
                  gameCard('Quarterfinal', 3, 4),
                  gameCard('Quarterfinal', 1, 6),
                  gameCard('Quarterfinal', 2, 5),
                ],
              ),
            ),
            SectionCard(
              title: 'Semifinals',
              child: Column(
                children: [
                  gameCard('Semifinal', 0, 3),
                  gameCard('Semifinal', 1, 2),
                ],
              ),
            ),
            SectionCard(
              title: 'National Championship',
              child: gameCard(
                'National Championship',
                0,
                1,
                note: 'Final: ${entry.winner} def. ${entry.loser} ${entry.score}',
              ),
            ),
          ],
        ),
      ),
    );
  }
}

