String seasonStatLineFor(GamePlayerLine line) {
  final parts = <String>[];
  if (line.passYards > 0) parts.add('${line.passYards} pass yds');
  if (line.passTDs > 0) parts.add('${line.passTDs} pass TD');
  if (line.rushYards > 0) parts.add('${line.rushYards} rush yds');
  if (line.rushTDs > 0) parts.add('${line.rushTDs} rush TD');
  if (line.recYards > 0) parts.add('${line.recYards} rec yds');
  if (line.recTDs > 0) parts.add('${line.recTDs} rec TD');
  if (line.tackles > 0) parts.add('${line.tackles} tkl');
  if (line.sacks > 0) parts.add('${line.sacks} sacks');
  if (line.interceptions > 0) parts.add('${line.interceptions} INT');
  return parts.isEmpty ? 'No stats recorded yet' : parts.join(' · ');
}

/// The real season stat book for this team — every number here is the exact
/// sum of what actually happened in every game simulated this season (see
/// attributeGameStatsToRoster / _recordGameStats), never a separately
/// generated approximation.
class SeasonStatsScreen extends StatelessWidget {
  final CollegeTeam team;
  final String record;
  final int gamesPlayed;
  final List<Player> roster;
  final Map<String, GamePlayerLine> seasonPlayerStats;

  const SeasonStatsScreen({
    super.key,
    required this.team,
    required this.record,
    required this.gamesPlayed,
    required this.roster,
    required this.seasonPlayerStats,
  });

  Widget _statTile(String value, String label) {
    return SizedBox(
      width: 84,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            value,
            style: const TextStyle(
              color: GKColors.parchmentWhite,
              fontSize: 20,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 2),
          Text(
            label,
            style: TextStyle(
              color: GKColors.fadedInk,
              fontSize: 9,
              fontWeight: FontWeight.w900,
              letterSpacing: .8,
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final rosterByName = {for (final p in roster) p.name: p};

    int totalOf(int Function(GamePlayerLine) pick) =>
        seasonPlayerStats.values.fold(0, (sum, line) => sum + pick(line));

    final teamPassYards = totalOf((l) => l.passYards);
    final teamRushYards = totalOf((l) => l.rushYards);
    final teamPassTDs = totalOf((l) => l.passTDs);
    final teamRushTDs = totalOf((l) => l.rushTDs);
    final teamSacks = totalOf((l) => l.sacks);
    final teamInts = totalOf((l) => l.interceptions);

    int productionScore(GamePlayerLine l) =>
        l.totalYards +
        l.totalTDs * 20 +
        l.sacks * 15 +
        l.interceptions * 15 +
        l.tackles;

    final entries = seasonPlayerStats.entries.toList()
      ..sort(
        (a, b) => productionScore(b.value).compareTo(productionScore(a.value)),
      );

    return Scaffold(
      backgroundColor: GKColors.ledgerBlack,
      appBar: AppBar(title: const AppTitle('Season Stats')),
      body: entries.isEmpty
          ? Center(
              child: Padding(
                padding: const EdgeInsets.all(GKSpace.xl),
                child: Text(
                  'No games simulated yet this season. Real stats appear here after your first game.',
                  textAlign: TextAlign.center,
                  style: GKText.body,
                ),
              ),
            )
          : ListView(
              padding: const EdgeInsets.all(GKSpace.md),
              children: [
                GKCard(
                  radius: GKRadius.featured,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          GKTeamBadge(team: team, size: 46),
                          const SizedBox(width: GKSpace.sm),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  'TEAM SEASON TOTALS',
                                  style: GKText.sectionLabel,
                                ),
                                const SizedBox(height: 2),
                                Text(
                                  '$record  ·  $gamesPlayed GP',
                                  style: GKText.body,
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: GKSpace.md),
                      Wrap(
                        spacing: GKSpace.md,
                        runSpacing: GKSpace.sm,
                        children: [
                          _statTile(
                            '${teamPassYards + teamRushYards}',
                            'TOTAL YDS',
                          ),
                          _statTile('$teamPassYards', 'PASS YDS'),
                          _statTile('$teamRushYards', 'RUSH YDS'),
                          _statTile('${teamPassTDs + teamRushTDs}', 'TOTAL TD'),
                          _statTile('$teamSacks', 'SACKS'),
                          _statTile('$teamInts', 'INT'),
                        ],
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: GKSpace.lg),
                const Text(
                  'PLAYER STAT LEADERS',
                  style: TextStyle(
                    color: GKColors.parchmentWhite,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 1.4,
                  ),
                ),
                const SizedBox(height: GKSpace.sm),
                ...entries.map((entry) {
                  final player = rosterByName[entry.key];
                  return Padding(
                    padding: const EdgeInsets.only(bottom: GKSpace.sm),
                    child: GKCard(
                      child: Row(
                        children: [
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  player?.cleanName ?? entry.key,
                                  style: GKText.cardTitle,
                                ),
                                const SizedBox(height: 3),
                                Text(
                                  seasonStatLineFor(entry.value),
                                  style: GKText.body,
                                ),
                              ],
                            ),
                          ),
                          if (player != null)
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 8,
                                vertical: 4,
                              ),
                              decoration: BoxDecoration(
                                color: GKColors.elevatedLeather,
                                border: Border.all(color: GKColors.stitchLine),
                              ),
                              child: Text(
                                player.position,
                                style: const TextStyle(
                                  color: GKColors.kingdomBrass,
                                  fontSize: 11,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                        ],
                      ),
                    ),
                  );
                }),
              ],
            ),
    );
  }
}

class StandingsScreen extends StatelessWidget {
  final CollegeTeam team;
  final Map<String, TeamSeasonRecord> teamRecords;

  const StandingsScreen({
    super.key,
    required this.team,
    required this.teamRecords,
  });

  @override
  Widget build(BuildContext context) {
    // FBS and FCS never share a conference name, but g5Teams alone would
    // silently render an empty standings screen for an FCS coach — search
    // both pools for whichever conference the viewer's own team is in.
    final teams = allTeams
        .where((t) => t.conference == team.conference)
        .toList();

    teams.sort((a, b) {
      final ar = teamRecords[a.name] ?? TeamSeasonRecord();
      final br = teamRecords[b.name] ?? TeamSeasonRecord();

      final confPctA = (ar.confWins + ar.confLosses) == 0
          ? 0
          : ar.confWins / (ar.confWins + ar.confLosses);
      final confPctB = (br.confWins + br.confLosses) == 0
          ? 0
          : br.confWins / (br.confWins + br.confLosses);

      final confCompare = confPctB.compareTo(confPctA);
      if (confCompare != 0) return confCompare;

      return br.wins.compareTo(ar.wins);
    });

    return Scaffold(
      appBar: AppBar(title: AppTitle('${team.conference} Standings')),
      body: GKBackground(
        child: ListView(
          padding: const EdgeInsets.all(18),
          children: teams.map((t) {
            final record = teamRecords[t.name] ?? TeamSeasonRecord();
            return _row(t, record, t.name == team.name);
          }).toList(),
        ),
      ),
    );
  }

  Widget _row(CollegeTeam t, TeamSeasonRecord record, bool user) {
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: user ? kGold.withOpacity(.15) : kCardColor,
        border: Border.all(color: user ? kGold : kBorder),
        borderRadius: BorderRadius.circular(16),
      ),
      child: Row(
        children: [
          GKTeamBadge(team: t, size: 38),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              t.name,
              style: TextStyle(
                color: user ? kGold : GKColors.parchmentWhite,
                fontSize: 18,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          Column(
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              Text(
                record.confText,
                style: const TextStyle(
                  color: GKColors.parchmentWhite,
                  fontWeight: FontWeight.w900,
                ),
              ),
              Text(
                record.overallText,
                style: const TextStyle(
                  color: GKColors.fadedInk,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

class LegacyBoardScreen extends StatefulWidget {
  final CoachProfile coach;
  final CollegeTeam team;
  final List<RivalCoachRecord> rivalCoaches;
  final int userNationalTitles;
  final int userConferenceTitles;
  final int userBowlWins;
  final int userBowlPoints;
  final int userCareerWins;
  final int userCurrentPrestige;
  final int userUndefeatedSeasons;
  final SeasonGoal? currentSeasonGoal;
  final List<SeasonGoalRecord> seasonGoalHistory;
  // Once true, this career already has a permanent Hall of Fame entry —
  // the retire action is a one-time, irreversible milestone per career.
  final bool alreadyRetired;
  // Persists the snapshot globally (survives even if this career's save is
  // later deleted) and marks this career retired, so the button can't fire
  // twice. Runs before the screen updates its own local Hall of Fame list.
  final Future<void> Function(LegendCoachRecord snapshot) onRetire;

  const LegacyBoardScreen({
    super.key,
    required this.coach,
    required this.team,
    required this.rivalCoaches,
    required this.userNationalTitles,
    required this.userConferenceTitles,
    required this.userBowlWins,
    required this.userBowlPoints,
    required this.userCareerWins,
    required this.userCurrentPrestige,
    required this.userUndefeatedSeasons,
    required this.currentSeasonGoal,
    required this.seasonGoalHistory,
    required this.alreadyRetired,
    required this.onRetire,
  });

  @override
  State<LegacyBoardScreen> createState() => _LegacyBoardScreenState();
}

class _LegacyBoardScreenState extends State<LegacyBoardScreen> {
  static const int _visibleRankedCount = 25;
  // Legends have no live prestige — a fixed high reference keeps their
  // minor tiebreaker term consistent with a top-tier active program.
  static const int _legendReferencePrestige = 99;

  List<LegendCoachRecord> _retiredLegends = [];
  bool _retiring = false;

  @override
  void initState() {
    super.initState();
    loadRetiredLegends().then((legends) {
      if (mounted) setState(() => _retiredLegends = legends);
    });
  }

  int get _userScore => legacyScoreFor(
    nationalTitles: widget.userNationalTitles,
    conferenceTitles: widget.userConferenceTitles,
    bowlPoints: widget.userBowlPoints,
    careerWins: widget.userCareerWins,
    currentPrestige: widget.userCurrentPrestige,
    undefeatedSeasons: widget.userUndefeatedSeasons,
  );

  int _rivalScore(RivalCoachRecord r) => legacyScoreFor(
    nationalTitles: r.nationalTitles,
    conferenceTitles: r.conferenceTitles,
    bowlPoints: r.bowlPoints,
    careerWins: r.careerWins,
    currentPrestige: r.currentPrestige,
    undefeatedSeasons: r.undefeatedSeasons,
  );

  int _legendScore(LegendCoachRecord l) => legacyScoreFor(
    nationalTitles: l.nationalTitles,
    conferenceTitles: l.conferenceTitles,
    bowlPoints: l.bowlPoints,
    careerWins: l.careerWins,
    currentPrestige: _legendReferencePrestige,
    undefeatedSeasons: l.undefeatedSeasons,
  );

  Future<void> _confirmRetire() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: kCardColor,
        title: const Text(
          'Retire This Coach?',
          style: TextStyle(color: GKColors.parchmentWhite, fontWeight: FontWeight.w900),
        ),
        content: Text(
          'This permanently adds ${widget.coach.name}\'s record — $_userScore Legacy Score, '
          '${widget.userNationalTitles} national title${widget.userNationalTitles == 1 ? '' : 's'}, '
          '${widget.userConferenceTitles} conference title${widget.userConferenceTitles == 1 ? '' : 's'}, '
          '${widget.userCareerWins} career wins — to the Hall of Fame at their earned rank. '
          'This can\'t be undone, but your save isn\'t deleted — you can keep coaching this career afterward.',
          style: const TextStyle(color: GKColors.fadedInk),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('Cancel'),
          ),
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('Retire', style: TextStyle(color: kGold, fontWeight: FontWeight.w900)),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;

    setState(() => _retiring = true);
    final snapshot = LegendCoachRecord(
      name: widget.coach.name,
      archetype:
          'Retired from ${widget.team.displayName} with a career Legacy '
          'Score of $_userScore — the standard this coach set for every '
          'program they built.',
      careerWins: widget.userCareerWins,
      nationalTitles: widget.userNationalTitles,
      conferenceTitles: widget.userConferenceTitles,
      bowlWins: widget.userBowlWins,
      bowlPoints: widget.userBowlPoints,
      undefeatedSeasons: widget.userUndefeatedSeasons,
    );
    await widget.onRetire(snapshot);
    if (!mounted) return;
    setState(() {
      _retiredLegends = [..._retiredLegends, snapshot];
      _retiring = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final legends = [...legendCoaches, ..._retiredLegends]
      ..sort((a, b) => _legendScore(b).compareTo(_legendScore(a)));

    // The numbered ladder is active coaches only (rivals + user) — legends
    // are a permanent Hall of Fame reference, not part of "this career's"
    // league standings.
    final ranked = List<RivalCoachRecord>.from(widget.rivalCoaches)
      ..sort((a, b) => _rivalScore(b).compareTo(_rivalScore(a)));
    final userScore = _userScore;
    final userRank =
        ranked.where((r) => _rivalScore(r) > userScore).length + 1;
    final visible = ranked.take(_visibleRankedCount).toList();
    final userVisible = userRank <= _visibleRankedCount;

    return Scaffold(
      appBar: AppBar(
        title: const AppTitle('Legacy Board'),
        actions: [
          IconButton(
            tooltip: widget.alreadyRetired
                ? 'Already retired this career'
                : 'Retire this coach',
            icon: Icon(
              widget.alreadyRetired
                  ? Icons.military_tech
                  : Icons.flag_circle_outlined,
              color: widget.alreadyRetired ? kGold : GKColors.fadedInk,
            ),
            onPressed: (widget.alreadyRetired || _retiring)
                ? null
                : _confirmRetire,
          ),
        ],
      ),
      body: GKBackground(
        child: ListView(
        padding: const EdgeInsets.all(18),
        children: [
          _sectionLabel('HALL OF FAME'),
          const SizedBox(height: 10),
          ...legends.map(
            (l) => _legendRow(
              l,
              isRetiredUser: widget.alreadyRetired && l.name == widget.coach.name,
            ),
          ),
          const SizedBox(height: 26),
          _sectionLabel('THIS SEASON'),
          const SizedBox(height: 10),
          _seasonGoalCard(),
          if (widget.seasonGoalHistory.isNotEmpty) ...[
            const SizedBox(height: 14),
            ...widget.seasonGoalHistory.reversed
                .take(5)
                .map((r) => _seasonGoalHistoryRow(r)),
          ],
          const SizedBox(height: 26),
          _sectionLabel(
            'ACTIVE COACHES',
            'TOP $_visibleRankedCount OF ${ranked.length + 1}',
          ),
          const SizedBox(height: 10),
          for (var i = 0; i < visible.length; i++) ...[
            if (userVisible && userRank == i + 1)
              _userRow(rank: userRank, score: userScore),
            _rivalRow(
              // Once the user's own row has been inserted above this
              // point, every rival below it is shifted down one spot in
              // the combined ranking — i+1 alone would relabel this rival
              // with the same rank number the user's row just used.
              rank: (userVisible && i + 1 >= userRank) ? i + 2 : i + 1,
              rival: visible[i],
              score: _rivalScore(visible[i]),
            ),
          ],
          if (!userVisible) ...[
            const SizedBox(height: 10),
            const Divider(color: kBorder),
            const SizedBox(height: 10),
            _userRow(rank: userRank, score: userScore),
          ],
        ],
        ),
      ),
    );
  }

  Widget _sectionLabel(String title, [String meta = '']) => Row(
    children: [
      Text(
        title,
        style: const TextStyle(
          color: GKColors.parchmentWhite,
          fontSize: 13,
          fontWeight: FontWeight.w900,
          letterSpacing: 1.2,
        ),
      ),
      const SizedBox(width: 10),
      const Expanded(child: Divider(color: GKColors.stitchLine, height: 1)),
      if (meta.isNotEmpty) ...[
        const SizedBox(width: 10),
        Text(
          meta,
          style: const TextStyle(
            color: GKColors.fadedInk,
            fontSize: 9,
            fontWeight: FontWeight.w900,
            letterSpacing: .8,
          ),
        ),
      ],
    ],
  );

  Widget _legendRow(LegendCoachRecord l, {bool isRetiredUser = false}) =>
      Container(
        margin: const EdgeInsets.only(bottom: 10),
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: kGold.withOpacity(isRetiredUser ? .16 : .08),
          border: Border.all(color: kGold.withOpacity(.6), width: isRetiredUser ? 2 : 1),
          borderRadius: BorderRadius.circular(16),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Icon(Icons.military_tech, color: kGold, size: 30),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          isRetiredUser ? '${l.name} (YOU, RETIRED)' : l.name,
                          style: const TextStyle(
                            color: kGold,
                            fontSize: 16,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                      Text(
                        '${_legendScore(l)}',
                        style: const TextStyle(
                          color: kGold,
                          fontSize: 17,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 4),
                  Text(
                    l.archetype,
                    style: const TextStyle(
                      color: GKColors.fadedInk,
                      fontSize: 12,
                      height: 1.35,
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    '${l.careerWins} WINS · ${l.nationalTitles} NATIONAL · ${l.conferenceTitles} CONFERENCE · ${l.bowlWins} BOWLS'
                    '${l.undefeatedSeasons > 0 ? ' · ${l.undefeatedSeasons} UNDEFEATED' : ''}',
                    style: const TextStyle(
                      color: GKColors.fadedInk,
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      );

  Widget _rivalRow({
    required int rank,
    required RivalCoachRecord rival,
    required int score,
  }) {
    final rivalTeam = teamByName(rival.teamName);
    final subdivision = rival.subdivisionOverride ?? rivalTeam.subdivision;
    return _rankedRow(
      rank: rank,
      badge: GKTeamBadge(team: rivalTeam, size: 34),
      name: rival.coachName,
      subtitle: '${rivalTeam.displayName} · ${subdivision.name.toUpperCase()}',
      score: score,
      highlighted: false,
    );
  }

  Widget _userRow({required int rank, required int score}) => _rankedRow(
    rank: rank,
    badge: GKTeamBadge(team: widget.team, size: 34),
    name: widget.coach.name,
    subtitle: '${widget.team.displayName} (YOU) · ${widget.team.subdivision.name.toUpperCase()}',
    score: score,
    highlighted: true,
  );

  Widget _rankedRow({
    required int rank,
    required Widget badge,
    required String name,
    required String subtitle,
    required int score,
    required bool highlighted,
  }) {
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: highlighted ? kGold.withOpacity(.15) : kCardColor,
        border: Border.all(color: highlighted ? kGold : kBorder),
        borderRadius: BorderRadius.circular(14),
      ),
      child: Row(
        children: [
          SizedBox(
            width: 30,
            child: Text(
              '#$rank',
              style: TextStyle(
                color: highlighted ? kGold : GKColors.fadedInk,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          badge,
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  name,
                  style: TextStyle(
                    color: highlighted ? kGold : GKColors.parchmentWhite,
                    fontSize: 15,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                Text(
                  subtitle,
                  style: const TextStyle(
                    color: GKColors.fadedInk,
                    fontSize: 11,
                  ),
                ),
              ],
            ),
          ),
          Text(
            '$score',
            style: TextStyle(
              color: highlighted ? kGold : GKColors.parchmentWhite,
              fontSize: 16,
              fontWeight: FontWeight.w900,
            ),
          ),
        ],
      ),
    );
  }

  Widget _seasonGoalCard() {
    final goal = widget.currentSeasonGoal;
    return GKCard(
      child: goal == null
          ? const Text(
              'No goal set yet.',
              style: TextStyle(color: GKColors.fadedInk),
            )
          : Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'SEASON GOAL',
                  style: TextStyle(
                    color: GKColors.fadedInk,
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 1.0,
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  goal.description,
                  style: const TextStyle(
                    color: GKColors.kingdomGold,
                    fontSize: 18,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ],
            ),
    );
  }

  Widget _seasonGoalHistoryRow(SeasonGoalRecord r) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 6),
    child: Row(
      children: [
        Icon(
          r.met ? Icons.check_circle : Icons.cancel,
          color: r.met ? GKColors.fieldGreen : GKColors.stampRed,
          size: 16,
        ),
        const SizedBox(width: 8),
        Text(
          'YEAR ${r.year}',
          style: const TextStyle(
            color: GKColors.fadedInk,
            fontSize: 11,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(width: 10),
        Expanded(
          child: Text(
            r.description,
            style: const TextStyle(
              color: GKColors.parchmentWhite,
              fontSize: 12,
            ),
          ),
        ),
      ],
    ),
  );
}

class KingdomNetworkScreen extends StatefulWidget {
  final CollegeTeam team;
  final CoachProfile coach;
  final int season;
  final int rank;
  final String record;
  final Map<String, TeamSeasonRecord> teamRecords;
  final List<Player> roster;
  final List<TrophyEntry> trophies;
  final List<NationalTitleHistoryEntry> history;
  final int initialChannel;

  const KingdomNetworkScreen({
    super.key,
    required this.team,
    required this.coach,
    required this.season,
    required this.rank,
    required this.record,
    required this.teamRecords,
    required this.roster,
    required this.trophies,
    required this.history,
    this.initialChannel = 0,
  });

  @override
  State<KingdomNetworkScreen> createState() => _KingdomNetworkScreenState();
}

class _KingdomNetworkScreenState extends State<KingdomNetworkScreen> {
  late int channel = widget.initialChannel;

  static const _channels = [
    'WIRE',
    'POLL',
    'HEISMAN',
    'CAROUSEL',
    'LEGACY',
    'ARCHIVE',
  ];

  List<CollegeTeam> get _rankedTeams {
    // Never show an FCS coach the FBS poll (or vice versa) — stay scoped
    // to the viewer's own subdivision.
    final ranked = (widget.team.isFcs ? fcsTeams : g5Teams).toList();
    ranked.sort((a, b) {
      final ar = widget.teamRecords[a.name] ?? TeamSeasonRecord();
      final br = widget.teamRecords[b.name] ?? TeamSeasonRecord();
      final pct = br.winPct.compareTo(ar.winPct);
      if (pct != 0) return pct;
      final wins = br.wins.compareTo(ar.wins);
      if (wins != 0) return wins;
      final prestige = b.prestige.compareTo(a.prestige);
      if (prestige != 0) return prestige;
      return a.name.compareTo(b.name);
    });
    return ranked;
  }

  // A real Heisman race: the user's own roster plus real (deterministic,
  // season-stable) skill players from the nation's best other programs —
  // not just whoever happens to be on the user's own team. Weighted
  // toward the top-prestige schools, same as an actual Heisman watch list
  // skews toward bluebloods.
  List<Player> get _nationalHeismanPool {
    final candidates = <Player>[...widget.roster];

    final bestOtherTeams =
        g5Teams.where((team) => team.name != widget.team.name).toList()
          ..sort((a, b) => b.prestige.compareTo(a.prestige));

    for (final team in bestOtherTeams.take(20)) {
      final roster = nationalRosterFor(team, widget.season);
      final skillPositions =
          roster
              .where((p) => ['QB', 'HB', 'WR', 'TE'].contains(p.position))
              .toList()
            ..sort((a, b) => b.overall.compareTo(a.overall));
      candidates.addAll(skillPositions.take(2));
    }

    if (candidates.isEmpty) {
      return const [
        Player(
          name: 'National Leader',
          position: 'QB',
          overall: 88,
          potential: 92,
          year: 'JR',
          stars: 4,
        ),
      ];
    }
    candidates.sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
    return candidates;
  }

  int get _userPollRank {
    final index = _rankedTeams.indexWhere(
      (team) => team.name == widget.team.name,
    );
    return index == -1 ? widget.rank : index + 1;
  }

