class RankingsScreen extends StatelessWidget {
  final CollegeTeam team;
  final int rank;
  final String record;
  final Map<String, TeamSeasonRecord> teamRecords;

  const RankingsScreen({
    super.key,
    required this.team,
    required this.rank,
    required this.record,
    required this.teamRecords,
  });

  List<CollegeTeam> _rankedTeams() {
    // Rank within the viewer's own subdivision only — an FCS coach's
    // national ranking is a separate field from FBS's, never a shared one.
    final ranked = (team.isFcs ? fcsTeams : g5Teams).toList();

    ranked.sort((a, b) {
      final ar = teamRecords[a.name] ?? TeamSeasonRecord();
      final br = teamRecords[b.name] ?? TeamSeasonRecord();

      final pct = br.winPct.compareTo(ar.winPct);
      if (pct != 0) return pct;

      final wins = br.wins.compareTo(ar.wins);
      if (wins != 0) return wins;

      final prestige = b.prestige.compareTo(a.prestige);
      if (prestige != 0) return prestige;

      return a.name.compareTo(b.name);
    });

    return ranked;
  }

  @override
  Widget build(BuildContext context) {
    final ranked = _rankedTeams();

    return Scaffold(
      appBar: AppBar(
        title: AppTitle(team.isFcs ? 'FCS Rankings' : 'FBS Rankings'),
      ),
      body: GKBackground(
        child: ListView(
          padding: const EdgeInsets.all(18),
          children: List.generate(min(25, ranked.length), (i) {
            final rankedTeam = ranked[i];
            final rec = teamRecords[rankedTeam.name] ?? TeamSeasonRecord();
            return _rankRow(i + 1, rankedTeam, rec, rankedTeam.name == team.name);
          }),
        ),
      ),
    );
  }

  Widget _rankRow(
    int r,
    CollegeTeam rankedTeam,
    TeamSeasonRecord rec,
    bool user,
  ) {
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: user ? kGold.withOpacity(.16) : kCardColor,
        border: Border.all(color: user ? kGold : kBorder),
        borderRadius: BorderRadius.circular(14),
      ),
      child: Row(
        children: [
          SizedBox(
            width: 45,
            child: Text(
              '#$r',
              style: const TextStyle(
                color: kGold,
                fontSize: 18,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          GKTeamBadge(team: rankedTeam, size: 34),
          const SizedBox(width: 10),
          Expanded(
            child: Text(
              rankedTeam.name,
              style: TextStyle(
                color: user ? kGold : GKColors.parchmentWhite,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          Text(
            rec.overallText,
            style: const TextStyle(
              color: GKColors.fadedInk,
              fontWeight: FontWeight.w900,
            ),
          ),
        ],
      ),
    );
  }
}

