// The on-air roster for the Kingdom Network: anchors, analysts, and
// reporters drawn from this pool rather than left unnamed.
const List<String> kingdomNetworkReporters = [
  'Jake Pietrzak',
  'Braden Ansaldi',
  'Sal Annino',
  'Zach Previte',
  'Kyle O’Connor',
  'Matt Spinella',
  'Cam Wagner',
  'Nick Davenport',
  'Clark Gulycz',
  'Dugan Chase',
  'Wyatt Jumper',
  'Vincent Franco',
  'Joe Sevison',
  'Henry Jennings',
  'Finn Jennings',
  'Jacob Correria',
  'Ryan Moricas',
];

// A deterministic, season-stable set of [count] distinct reporters —
// same season always puts the same names on air, but which ones varies
// season to season and by [salt] (so an anchor and that segment's
// analysts don't collide).
List<String> kingdomNetworkReportersFor(
  int season, {
  int count = 1,
  int salt = 0,
}) {
  final pool = [...kingdomNetworkReporters];
  final local = Random(season * 7919 + salt * 104729 + 17);
  pool.shuffle(local);
  return pool.take(count).toList();
}

String awardPlayerDisplayName(Player player) {
  if (player.name.contains('|')) {
    return player.name.split('|').first;
  }
  return player.cleanName;
}

String awardPlayerSchool(Player player) {
  if (player.name.contains('|')) {
    return player.name.split('|').last;
  }
  return 'Your Team';
}

int awardOverallCapped(Player player) {
  final raw = awardOverall(player);
  if (player.year == 'FR') return raw.clamp(45, 93);
  if (player.year == 'SO') return raw.clamp(45, 96);
  return raw.clamp(45, 99);
}

int realisticAwardScore(Player player) {
  final overall = awardOverallCapped(player);
  final posBoost = switch (player.position) {
    'QB' => 16,
    'HB' => 10,
    'WR' => 8,
    'TE' => 2,
    'DE' => 7,
    'LB' => 6,
    'DB' => 5,
    _ => 0,
  };

  final classBoost = switch (player.year) {
    'SR' => 8,
    'JR' => 6,
    'SO' => 3,
    _ => -5,
  };

  final teamWinEstimate = player.teamWins.clamp(0, 15);
  final statSeed = player.name.hashCode.abs() % 15;

  return (overall * 5 + teamWinEstimate * 4 + posBoost + classBoost + statSeed)
      .round();
}

List<Player> realisticFullAllAmericanTeam(
  List<Player> players, {
  required Set<String> usedNames,
}) {
  final positionNeeds = <String, int>{
    'QB': 1,
    'HB': 1,
    'WR': 2,
    'TE': 1,
    'DE': 2,
    'LB': 2,
    'DB': 3,
  };

  final selected = <Player>[];

  for (final entry in positionNeeds.entries) {
    final candidates =
        players
            .where(
              (p) => p.position == entry.key && !usedNames.contains(p.name),
            )
            .toList()
          ..sort(
            (a, b) => realisticAwardScore(b).compareTo(realisticAwardScore(a)),
          );

    for (final player in candidates.take(entry.value)) {
      selected.add(player);
      usedNames.add(player.name);
    }
  }

  selected.sort(
    (a, b) => realisticAwardScore(b).compareTo(realisticAwardScore(a)),
  );
  return selected;
}

class SeasonAwardsCard extends StatelessWidget {
  final List<Player> roster;
  final int season;
  final int userWins;
  final String userTeamName;

  const SeasonAwardsCard({
    super.key,
    required this.roster,
    required this.season,
    required this.userWins,
    required this.userTeamName,
  });

  int _stableSeed(String value) {
    var hash = 17;
    for (final unit in value.codeUnits) {
      hash = ((hash * 31) + unit) & 0x7fffffff;
    }
    return hash;
  }

  int _seasonWinsForSchool(String school) {
    if (school == userTeamName || school == 'Your Team') {
      return userWins.clamp(0, 15);
    }

    final team = g5Teams.firstWhere(
      (candidate) => candidate.name == school,
      orElse: () => const CollegeTeam(
        name: 'National Program',
        conference: 'Independent',
        prestige: 70,
        primary: Color(0xFF333333),
        secondary: GKColors.parchmentWhite,
      ),
    );

    final tier = prestigeTier(team.prestige);
    final random = Random(season * 100003 + _stableSeed(school) * 37);

    final baseWins = switch (tier) {
      5 => 9,
      4 => 8,
      3 => 7,
      2 => 6,
      _ => 4,
    };

    final variation = random.nextInt(7) - 3;
    return (baseWins + variation).clamp(2, 12);
  }

  int _teamWinsForPlayer(Player player) {
    return _seasonWinsForSchool(awardPlayerSchool(player));
  }

  List<Player> _buildPool() {
    final list = <Player>[];

    // Use the actual user roster and this season's user record.
    for (final player in roster) {
      list.add(
        Player(
          name: '${player.cleanName}|$userTeamName',
          position: player.position,
          overall: player.overall,
          potential: player.potential,
          year: player.year,
          stars: player.stars,
        ),
      );
    }

    // Every other school's roster comes from the same deterministic
    // generator used for Player of the Game and pregame team leaders, so
    // an award ballot names the same real players you'd see anywhere else
    // that school comes up this season.
    for (final school in awardNationalSchools) {
      final team = g5Teams.firstWhere(
        (candidate) => candidate.name == school,
        orElse: () => const CollegeTeam(
          name: 'National Program',
          conference: 'Independent',
          prestige: 70,
          primary: Color(0xFF333333),
          secondary: GKColors.parchmentWhite,
        ),
      );
      list.addAll(nationalRosterFor(team, season));
    }

    final unique = <String, Player>{};
    for (final player in list) {
      unique['${player.name}-${player.position}-${player.year}'] = player;
    }

    return unique.values.toList();
  }

  int _awardScore(Player player) {
    final overall = awardOverallCapped(player);
    final teamWins = _teamWinsForPlayer(player);

    final positionBonus = switch (player.position) {
      'QB' => 20,
      'HB' => 14,
      'WR' => 11,
      'TE' => 5,
      'DE' => 9,
      'LB' => 8,
      'DB' => 7,
      _ => 0,
    };

    final classBonus = switch (player.year) {
      'SR' => 7,
      'JR' => 6,
      'SO' => 3,
      _ => -5,
    };

    final seasonVariance = Random(
      season * 300007 + _stableSeed(player.name) * 19,
    ).nextInt(22);

    return overall * 6 +
        teamWins * 11 +
        positionBonus +
        classBonus +
        seasonVariance;
  }

  int _heismanScore(Player player) {
    final overall = awardOverallCapped(player);
    final teamWins = _teamWinsForPlayer(player);

    final offensiveProduction = switch (player.position) {
      'QB' => 32,
      'HB' => 25,
      'WR' => 20,
      'TE' => 8,
      _ => -35,
    };

    final recordBonus = teamWins >= 12
        ? 58
        : teamWins == 11
        ? 48
        : teamWins == 10
        ? 36
        : teamWins == 9
        ? 22
        : teamWins == 8
        ? 10
        : -18;

    final seasonalStats = Random(
      season * 400009 + _stableSeed(player.name) * 23,
    ).nextInt(42);

    return overall * 8 + recordBonus + offensiveProduction + seasonalStats;
  }

  Player _heismanWinner(List<Player> pool) {
    if (pool.isEmpty) {
      return const Player(
        name: 'No Player',
        position: 'QB',
        overall: 0,
        potential: 0,
        year: 'JR',
        stars: 1,
      );
    }

    final candidates = pool.toList()
      ..sort((a, b) => _heismanScore(b).compareTo(_heismanScore(a)));

    return candidates.first;
  }

  List<Player> _allAmericanTeam(List<Player> pool, Set<String> usedNames) {
    final needs = <String, int>{
      'QB': 1,
      'HB': 1,
      'WR': 2,
      'TE': 1,
      'DE': 2,
      'LB': 2,
      'DB': 3,
    };

    final selected = <Player>[];

    for (final entry in needs.entries) {
      final candidates =
          pool
              .where(
                (p) => p.position == entry.key && !usedNames.contains(p.name),
              )
              .toList()
            ..sort((a, b) => _awardScore(b).compareTo(_awardScore(a)));

      for (final player in candidates.take(entry.value)) {
        selected.add(player);
        usedNames.add(player.name);
      }
    }

    selected.sort((a, b) => _awardScore(b).compareTo(_awardScore(a)));
    return selected;
  }

  List<Player> _firstTeam(List<Player> pool, Player heisman) {
    final used = <String>{heisman.name};
    final first = <Player>[heisman];

    final needs = <String, int>{
      'QB': 1,
      'HB': 1,
      'WR': 2,
      'TE': 1,
      'DE': 2,
      'LB': 2,
      'DB': 3,
    };

    needs[heisman.position] = max(0, (needs[heisman.position] ?? 0) - 1);

    for (final entry in needs.entries) {
      final candidates =
          pool
              .where((p) => p.position == entry.key && !used.contains(p.name))
              .toList()
            ..sort((a, b) => _awardScore(b).compareTo(_awardScore(a)));

      for (final player in candidates.take(entry.value)) {
        first.add(player);
        used.add(player.name);
      }
    }

    return first;
  }

  List<Player> _freshmanTeam(List<Player> pool) {
    final used = <String>{};
    final freshmen = pool.where((p) => p.year == 'FR').toList();
    return _allAmericanTeam(freshmen, used);
  }

  Player? _bestAt(List<Player> pool, List<String> positions) {
    final choices = pool.where((p) => positions.contains(p.position)).toList();
    if (choices.isEmpty) return null;
    choices.sort((a, b) => _awardScore(b).compareTo(_awardScore(a)));
    return choices.first;
  }

  String _playerLine(Player? p) {
    if (p == null) return 'None';
    return '${awardPlayerDisplayName(p)} • ${p.position} • ${p.year} • ${awardPlayerSchool(p)} • ${awardOverallCapped(p)} OVR';
  }

  Widget _playerRow(Player p, {bool heisman = false}) {
    return Container(
      margin: const EdgeInsets.only(bottom: 7),
      padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 10),
      decoration: BoxDecoration(
        color: heisman ? kGold.withOpacity(.16) : kDark.withOpacity(.50),
        border: Border.all(color: heisman ? kGold : kBorder),
        borderRadius: BorderRadius.circular(13),
      ),
      child: Row(
        children: [
          Expanded(
            child: Text(
              '${awardPlayerDisplayName(p)} • ${p.position} • ${p.year} • ${awardPlayerSchool(p)}',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: GKColors.parchmentWhite,
                fontWeight: FontWeight.w900,
                fontSize: 12,
              ),
            ),
          ),
          Text(
            heisman ? 'HEISMAN' : '${awardOverallCapped(p)} OVR',
            style: TextStyle(
              color: heisman ? kGold : GKColors.fadedInk,
              fontWeight: FontWeight.w900,
              fontSize: 11,
            ),
          ),
        ],
      ),
    );
  }

  Widget _block(String title, List<Player> players, {Player? heisman}) {
    return Container(
      width: double.infinity,
      margin: const EdgeInsets.only(bottom: 14),
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: kCardColor,
        border: Border.all(color: kBorder),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            title.toUpperCase(),
            style: const TextStyle(
              color: kGold,
              fontSize: 12,
              fontWeight: FontWeight.w900,
              letterSpacing: 3,
            ),
          ),
          const SizedBox(height: 10),
          if (players.isEmpty)
            Text(
              'No eligible players.',
              style: TextStyle(
                color: GKColors.fadedInk,
                fontWeight: FontWeight.bold,
              ),
            ),
          ...players.map(
            (p) => _playerRow(
              p,
              heisman: heisman != null && p.name == heisman.name,
            ),
          ),
        ],
      ),
    );
  }

  Widget _seasonAwardsBlock(List<Player> pool) {
    final rows = [
      'Offensive Player: ${_playerLine(_bestAt(pool, ['QB', 'HB', 'WR', 'TE']))}',
      'Defensive Player: ${_playerLine(_bestAt(pool, ['DE', 'LB', 'DB']))}',
      'Best QB: ${_playerLine(_bestAt(pool, ['QB']))}',
      'Best RB: ${_playerLine(_bestAt(pool, ['HB']))}',
      'Best WR: ${_playerLine(_bestAt(pool, ['WR']))}',
    ];

    return Container(
      width: double.infinity,
      margin: const EdgeInsets.only(bottom: 14),
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: kCardColor,
        border: Border.all(color: kBorder),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'SEASON AWARDS',
            style: TextStyle(
              color: kGold,
              fontSize: 12,
              fontWeight: FontWeight.w900,
              letterSpacing: 3,
            ),
          ),
          const SizedBox(height: 10),
          ...rows.map(
            (row) => Padding(
              padding: const EdgeInsets.only(bottom: 7),
              child: Text(
                row,
                style: const TextStyle(
                  color: GKColors.parchmentWhite,
                  fontWeight: FontWeight.bold,
                  height: 1.3,
                  fontSize: 12,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final pool = _buildPool();
    final heisman = _heismanWinner(pool);
    final first = _firstTeam(pool, heisman);
    final used = first.map((p) => p.name).toSet();
    final second = _allAmericanTeam(pool, used);
    final freshmen = _freshmanTeam(pool);

    return Column(
      children: [
        Container(
          width: double.infinity,
          margin: const EdgeInsets.only(bottom: 14),
          padding: const EdgeInsets.all(13),
          decoration: BoxDecoration(
            color: kGold.withOpacity(.13),
            border: Border.all(color: kGold),
            borderRadius: BorderRadius.circular(18),
          ),
          child: Row(
            children: [
              const Icon(Icons.emoji_events, color: kGold, size: 26),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  'Heisman Trophy: ${awardPlayerDisplayName(heisman)} • ${heisman.position} • ${heisman.year} • ${awardPlayerSchool(heisman)} • ${awardOverallCapped(heisman)} OVR',
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: GKColors.parchmentWhite,
                    fontWeight: FontWeight.w900,
                    height: 1.25,
                  ),
                ),
              ),
            ],
          ),
        ),
        _block('First Team All-American', first, heisman: heisman),
        _block('Second Team All-American', second),
        _block('Freshman All-American Team', freshmen),
        _seasonAwardsBlock(pool),
      ],
    );
  }
}

class _DraftProspect {
  final Player player;
  final bool isUserPlayer;
  final CollegeTeam college;
  final int stock;

  const _DraftProspect({
    required this.player,
    required this.isUserPlayer,
    required this.college,
    required this.stock,
  });
}

class MockDraftScreen extends StatefulWidget {
  final List<Player> roster;
  final CollegeTeam userTeam;
  final int season;

  const MockDraftScreen({
    super.key,
    required this.roster,
    required this.userTeam,
    required this.season,
  });

  @override
  State<MockDraftScreen> createState() => _MockDraftScreenState();
}

class _MockDraftScreenState extends State<MockDraftScreen> {
  static const int _picksPerRound = 32;
  static const int _rounds = 7;

  int _selectedRound = 1;
  late final List<_DraftProspect> _draftClass = _buildDraftClass();

  // A senior with real production, or an elite underclassman declaring
  // early — mirrors the same bar the offseason draft-decision flow uses
  // for the user's own roster (see _finalizeRetention), applied here
  // uniformly to every program nationally.
  bool _eligible(Player p) =>
      (p.year == 'SR' && awardOverall(p) >= 52) || awardOverall(p) >= 80;

  // Deterministic per-player draft-stock jitter so the board's order is
  // stable across rebuilds but never just a flat overall-sorted list —
  // real draft boards reward premium positions and always carry some
  // scout-to-scout disagreement.
  int _stockFor(Player p) {
    final base = awardOverall(p) * 10;
    final posBonus = switch (p.position) {
      'QB' => 60,
      'DE' => 25,
      'WR' => 15,
      'DB' => 15,
      'LB' => 10,
      _ => 0,
    };
    final jitter = (p.name.hashCode.abs() % 31) - 15;
    return base + posBonus + jitter;
  }

  List<_DraftProspect> _buildDraftClass() {
    final prospects = <_DraftProspect>[];

    for (final p in widget.roster.where(_eligible)) {
      prospects.add(
        _DraftProspect(
          player: p,
          isUserPlayer: true,
          college: widget.userTeam,
          stock: _stockFor(p),
        ),
      );
    }

    for (final team in g5Teams) {
      if (team.name == widget.userTeam.name) continue;
      final national = nationalRosterFor(team, widget.season);
      for (final p in national.where(_eligible)) {
        prospects.add(
          _DraftProspect(
            player: p,
            isUserPlayer: false,
            college: team,
            stock: _stockFor(p),
          ),
        );
      }
    }

    prospects.sort((a, b) => b.stock.compareTo(a.stock));
    return prospects.take(_picksPerRound * _rounds).toList();
  }

  @override
  Widget build(BuildContext context) {
    final startIndex = (_selectedRound - 1) * _picksPerRound;
    final roundProspects = _draftClass
        .skip(startIndex)
        .take(_picksPerRound)
        .toList();

    return Scaffold(
      appBar: AppBar(title: const AppTitle('Mock Draft')),
      body: GKBackground(
        child: Column(
          children: [
            SizedBox(
              height: 56,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.fromLTRB(18, 8, 18, 8),
                itemCount: _rounds,
                separatorBuilder: (_, _) => const SizedBox(width: 8),
                itemBuilder: (context, i) {
                  final round = i + 1;
                  final selected = round == _selectedRound;
                  return ChoiceChip(
                    label: Text('ROUND $round'),
                    selected: selected,
                    onSelected: (_) => setState(() => _selectedRound = round),
                    selectedColor: kGold,
                    backgroundColor: kCardColor,
                    side: BorderSide(color: selected ? kGold : kBorder),
                    labelStyle: TextStyle(
                      color: selected
                          ? GKColors.inkBlack
                          : GKColors.parchmentWhite,
                      fontWeight: FontWeight.w900,
                      fontSize: 11,
                    ),
                  );
                },
              ),
            ),
            Expanded(
              child: roundProspects.isEmpty
                  ? const Center(
                      child: Text(
                        'No draft-eligible players yet.',
                        style: TextStyle(color: GKColors.fadedInk),
                      ),
                    )
                  : ListView.builder(
                      padding: const EdgeInsets.fromLTRB(18, 0, 18, 18),
                      itemCount: roundProspects.length,
                      itemBuilder: (context, i) {
                        final overallPick = startIndex + i + 1;
                        final prospect = roundProspects[i];
                        final p = prospect.player;
                        return Container(
                          margin: const EdgeInsets.only(bottom: 10),
                          padding: const EdgeInsets.all(14),
                          decoration: BoxDecoration(
                            color: prospect.isUserPlayer
                                ? kGold.withOpacity(.14)
                                : kCardColor,
                            border: Border.all(
                              color: prospect.isUserPlayer ? kGold : kBorder,
                            ),
                            borderRadius: BorderRadius.circular(14),
                          ),
                          child: Row(
                            children: [
                              SizedBox(
                                width: 34,
                                child: Text(
                                  '$overallPick',
                                  style: TextStyle(
                                    color: prospect.isUserPlayer
                                        ? kGold
                                        : GKColors.fadedInk,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                              ),
                              GKTeamBadge(team: prospect.college, size: 30),
                              const SizedBox(width: 10),
                              PlayerAvatar(
                                seed: p.name.hashCode,
                                teamColor: prospect.college.primary,
                                size: 38,
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                child: Text(
                                  '${p.cleanName}${prospect.isUserPlayer ? ' (YOU)' : ''}\n'
                                  '${p.position} · ${prospect.college.displayName}',
                                  style: TextStyle(
                                    color: prospect.isUserPlayer
                                        ? kGold
                                        : GKColors.parchmentWhite,
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                              ),
                              Text(
                                '${awardOverall(p)}',
                                style: const TextStyle(
                                  color: kGold,
                                  fontSize: 22,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ],
                          ),
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

class RecruitProfileScreen extends StatefulWidget {
  final Recruit recruit;
  final int rank;
  final String userSchool;
  final Color userTeamColor;
  final bool recruitingClosed;
  final int Function() recruitingPoints;
  final int gamesPlayed;
  final int Function() nilBudgetRemaining;
  final bool Function() canScheduleVisit;
  final bool Function() canOfferNil;
  final bool Function() canBoostMorale;
  // Whether the incoming class still has an open roster slot for one more
  // signee (see _DashboardScreenState._recruitingClassHasRoom) — an offer
  // that could never turn into a real roster spot next season shouldn't be
  // presented as live.
  final bool Function() classHasRoom;
  final VoidCallback onScout;
  final VoidCallback onOffer;
  final VoidCallback onScheduleVisit;
  final VoidCallback onOfferNil;
  final VoidCallback onBoostMorale;

  const RecruitProfileScreen({
    super.key,
    required this.recruit,
    required this.rank,
    required this.userSchool,
    this.userTeamColor = GKColors.kingdomGold,
    required this.recruitingClosed,
    required this.recruitingPoints,
    required this.gamesPlayed,
    required this.nilBudgetRemaining,
    required this.canScheduleVisit,
    required this.canOfferNil,
    required this.canBoostMorale,
    required this.classHasRoom,
    required this.onScout,
    required this.onOffer,
    required this.onScheduleVisit,
    required this.onOfferNil,
    required this.onBoostMorale,
  });

  @override
  State<RecruitProfileScreen> createState() => _RecruitProfileScreenState();
}

class _RecruitProfileScreenState extends State<RecruitProfileScreen> {
  int tab = 0;

  Recruit get recruit => widget.recruit;

  Color get _interestColor {
    if (recruit.interest >= 75) return GKColors.victoryGreen;
    if (recruit.interest >= 55) return GKColors.kingdomBrass;
    return GKColors.alertRed;
  }

  String get _memoryText {
    final seed = recruit.name.hashCode.abs() % 6;

    return switch (seed) {
      0 => 'Your early evaluation made an impression.',
      1 => 'Watching how your offense uses his position.',
      2 => 'Interested in your recent player development.',
      3 => 'Tracking the atmosphere of ranked and rivalry games.',
      4 => 'Needs a believable route to early playing time.',
      _ => 'His family is evaluating the relationship with your staff.',
    };
  }

  String get _visitOutlook {
    if (recruit.committedSchool != null) {
      return recruit.committedSchool == widget.userSchool
          ? 'Committed prospects are preparing to join the class.'
          : 'This prospect is no longer available for a visit.';
    }
    if (recruit.visits > 0) {
      return 'Official visit complete. A strong home-game atmosphere could close the recruitment.';
    }
    if (recruit.firstContactGame == null) {
      return 'Scout or offer this prospect first — a visit unlocks a week after that first contact.';
    }
    if (widget.canScheduleVisit()) {
      return 'Visit unlocked. Schedule it below while recruiting points last.';
    }
    return "Visit unlocks Week ${_visitAvailableWeek! + 1} (you're in Week ${widget.gamesPlayed + 1}).";
  }

  bool get _canScout {
    return !widget.recruitingClosed &&
        recruit.committedSchool == null &&
        recruit.scouts < 3 &&
        widget.recruitingPoints() >= 5;
  }

  bool get _canOffer {
    return !widget.recruitingClosed &&
        recruit.committedSchool == null &&
        !recruit.offered &&
        widget.recruitingPoints() >= 10 &&
        widget.classHasRoom();
  }

  void _scout() {
    if (!_canScout) return;
    widget.onScout();
    setState(() {});
  }

  void _offer() {
    if (!_canOffer) return;
    widget.onOffer();
    setState(() {});
  }

  // Visits only unlock a week (in game weeks) after the first time this
  // recruit was scouted or offered — widget.canScheduleVisit already
  // encodes that gate (plus the point cost and one-visit cap).
  int? get _visitAvailableWeek =>
      recruit.firstContactGame == null ? null : recruit.firstContactGame! + 1;

  void _scheduleVisit() {
    if (!widget.canScheduleVisit()) return;
    widget.onScheduleVisit();
    setState(() {});
  }

  void _offerNil() {
    if (!widget.canOfferNil()) return;
    widget.onOfferNil();
    setState(() {});
  }

  void _boostMorale() {
    if (!widget.canBoostMorale()) return;
    widget.onBoostMorale();
    setState(() {});
  }

  String _visitStatusText() {
    if (recruit.visits > 0) {
      return 'Official visit completed — his decision reflects it.';
    }
    if (recruit.firstContactGame == null) {
      return 'Scout or offer this prospect first — a visit unlocks a week after your first contact.';
    }
    final availableWeek = _visitAvailableWeek!;
    if (widget.gamesPlayed >= availableWeek) {
      return 'Visit available now — schedule it while points last.';
    }
    return "Visit unlocks Week ${availableWeek + 1} (you're in Week ${widget.gamesPlayed + 1}).";
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GKColors.midnight,
      body: GKBackground(
        child: SafeArea(
          child: Column(
            children: [
              _profileTopBar(context),
              Expanded(
                child: ListView(
                  padding: const EdgeInsets.fromLTRB(
                    GKSpace.md,
                    GKSpace.sm,
                    GKSpace.md,
                    GKSpace.xxl,
                  ),
                  children: [
