class SeasonAwardWinners {
  final Player heisman;
  final Player offensivePlayer;
  final Player defensivePlayer;
  final Player qb;
  final Player rb;
  final Player wr;
  final Player te;
  final Player lineman;
  final Player db;
  final Player freshman;

  const SeasonAwardWinners({
    required this.heisman,
    required this.offensivePlayer,
    required this.defensivePlayer,
    required this.qb,
    required this.rb,
    required this.wr,
    required this.te,
    required this.lineman,
    required this.db,
    required this.freshman,
  });
}

bool _isOffensivePosition(String pos) =>
    ['QB', 'RB', 'HB', 'WR', 'TE', 'OL'].contains(pos);
bool _isDefensivePosition(String pos) =>
    ['DL', 'DE', 'DT', 'LB', 'CB', 'DB', 'S'].contains(pos);

Player _bestByPosition(
  List<Player> players,
  List<String> positions,
  Player fallback,
) {
  final pool = players.where((p) => positions.contains(p.position)).toList();
  if (pool.isEmpty) return fallback;
  pool.sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
  return pool.first;
}

SeasonAwardWinners buildSeasonAwards(List<Player> allPlayers) {
  final players = allPlayers.toList();
  players.sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
  final fallback = players.isNotEmpty
      ? players.first
      : Player(
          name: 'No Player',
          position: 'QB',
          year: 'FR',
          overall: 60,
          potential: 70,
          stars: 1,
        );

  final offense =
      players.where((p) => _isOffensivePosition(p.position)).toList()
        ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
  final defense =
      players.where((p) => _isDefensivePosition(p.position)).toList()
        ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));

  final freshman = players.where((p) => p.year == 'FR').toList()
    ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));

  final qb = _bestByPosition(players, ['QB'], fallback);
  final rb = _bestByPosition(players, ['RB', 'HB'], fallback);
  final wr = _bestByPosition(players, ['WR'], fallback);
  final te = _bestByPosition(players, ['TE'], fallback);
  final lineman = _bestByPosition(players, [
    'OL',
    'DL',
    'DE',
    'DT',
    'LB',
  ], fallback);
  final db = _bestByPosition(players, ['CB', 'DB', 'S'], fallback);

  // Heisman = best season, not just best raw overall.
  // It favors elite production from QB/HB/WR/TE and gives a small boost for winners.
  final heismanPool = <Player>[...offense];
  if (heismanPool.isEmpty) heismanPool.addAll(players);

  double heismanSeasonScore(Player p) {
    final ovr = awardOverall(p).toDouble();

    final ppg = p.ppg;
    final rush = p.rushYards;
    final pass = p.passYards;
    final rec = p.recYards;
    final td = p.touchdowns;
    final sacks = p.sacks;
    final ints = p.interceptions;

    double production;
    switch (p.position) {
      case 'QB':
        production = (pass / 120.0) + (td * 1.8) + (ppg * 1.2);
        break;
      case 'HB':
      case 'RB':
        production = (rush / 65.0) + (td * 2.0) + (rec / 120.0);
        break;
      case 'WR':
      case 'TE':
        production = (rec / 55.0) + (td * 2.1);
        break;
      default:
        production = (sacks * 2.4) + (ints * 3.0) + (ppg * .6);
        break;
    }

    final teamBoost = p.teamWins >= 10
        ? 10
        : p.teamWins >= 8
        ? 5
        : 0;
    final positionBoost = p.position == 'QB'
        ? 6
        : (p.position == 'HB' || p.position == 'RB')
        ? 4
        : (p.position == 'WR' || p.position == 'TE')
        ? 3
        : 0;

    return production + (ovr * .45) + teamBoost + positionBoost;
  }

  heismanPool.sort(
    (a, b) => heismanSeasonScore(b).compareTo(heismanSeasonScore(a)),
  );

  return SeasonAwardWinners(
    heisman: (() {
      final firstTeamSkill = [
        qb,
        rb,
        wr,
      ].where((p) => p.name != fallback.name).toList();
      if (firstTeamSkill.isNotEmpty) {
        firstTeamSkill.sort(
          (a, b) => heismanSeasonScore(b).compareTo(heismanSeasonScore(a)),
        );
        return firstTeamSkill.first;
      }
      final firstTeam = [
        qb,
        rb,
        wr,
        te,
        lineman,
        db,
      ].where((p) => p.name != fallback.name).toList();
      firstTeam.sort(
        (a, b) => heismanSeasonScore(b).compareTo(heismanSeasonScore(a)),
      );
      return firstTeam.isNotEmpty ? firstTeam.first : heismanPool.first;
    })(),
    offensivePlayer: offense.isNotEmpty ? offense.first : fallback,
    defensivePlayer: defense.isNotEmpty ? defense.first : fallback,
    qb: qb,
    rb: rb,
    wr: wr,
    te: te,
    lineman: lineman,
    db: db,
    freshman: freshman.isNotEmpty ? freshman.first : fallback,
  );
}

class OffseasonScreen extends StatefulWidget {
  final CollegeTeam team;
  final CoachProfile coach;
  final int season;
  final int wins;
  final int losses;
  final int confWins;
  final int confLosses;
  final List<Player> roster;
  final List<Recruit> incomingRecruits;
  final int contractYearsRemaining;
  // The real, simulated current prestige of every AI program (see
  // simulateRivalCoachSeason) — job offers should reflect how programs
  // have actually fared, not their static day-one CollegeTeam.prestige.
  final List<RivalCoachRecord> rivalCoaches;
  // Players who told the coach the relationship is unfixable during a
  // Talk to Player conversation — no retention NIL offer can keep them,
  // whatever the budget (see _playerRetentionCard).
  final Set<String> irreconcilablePlayerNames;
  // Computed once, at season-end, by _DashboardScreenState (see
  // realignmentInvitationOptionsFor) — empty unless this program has
  // actually earned a real look this offseason.
  final List<ConferenceInvitation> realignmentInvitations;
  final ValueChanged<OffseasonResult> onFinish;

  const OffseasonScreen({
    super.key,
    required this.team,
    required this.coach,
    required this.season,
    required this.wins,
    required this.losses,
    required this.confWins,
    required this.confLosses,
    required this.roster,
    required this.incomingRecruits,
    required this.contractYearsRemaining,
    this.rivalCoaches = const [],
    this.irreconcilablePlayerNames = const {},
    this.realignmentInvitations = const [],
    required this.onFinish,
  });

  @override
  State<OffseasonScreen> createState() => _OffseasonScreenState();
}

class _OffseasonScreenState extends State<OffseasonScreen> {
  List<Recruit> get committedRecruits => widget.incomingRecruits
      .where((r) => r.committedSchool == widget.team.name)
      .toList();

  CoachTransitionResult? transitionResult;
  List<Recruit> get recruits => committedRecruits;

  int step = 0;
  late CollegeTeam selectedTeam;
  late List<Player> roster;
  late Set<String> _originalRosterNames;
  late List<JobOffer> jobOffers;
  late int retentionBudget;
  late int retentionSpent;
  late int transferNilBudget;
  late int transferNilSpent;
  late int trainingPoints;
  final retainedPlayerNames = <String>{};
  late List<Player> graduatingPlayers;
  late List<Player> draftEligibleJuniors;
  late List<Player> retentionCandidates;
  final draftedPlayers = <Player>[];
  bool retentionFinalized = false;
  final playerSkillBoosts = <String, Map<String, int>>{};
  final trainingBaseOveralls = <String, int>{};
  late List<TransferTarget> transferTargets;
  final signedTransfers = <TransferTarget>[];
  // Which invitation (if any) the coach has accepted this offseason — null
  // means still deciding, or declined everything. Accepting rewrites
  // selectedTeam's conference/subdivision, exactly like a job offer
  // rewrites selectedTeam entirely (see _acceptJobOffer).
  ConferenceInvitation? acceptedRealignment;
  CollegeTeam? rivalryTeam;
  List<CollegeTeam> customNonConference = [];
  // null = auto-place the 2 bye weeks the way the game always has
  // (generateByeWeeks) — the default for every coach who doesn't touch
  // this. A non-null value is always a validated, non-adjacent pair.
  List<int>? customByeWeeks;
  final redshirtedPlayerNames = <String>{};

  final steps = const [
    'Program Review',
    'Coaching Market',
    'Contract Decision',
    'Roster Decisions',
    'Portal Window',
    'Signing Day',
    'Spring Practice',
    'Eligibility Desk',
    'Conference Invitations',
    'Schedule Reveal',
  ];

  @override
  void initState() {
    super.initState();
    selectedTeam = widget.team;
    graduatingPlayers = widget.roster.where((p) => p.year == 'SR').toList()
      ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));

    roster = _initialRoster();
    // Snapshot before Portal Window/Signing Day can add anyone new, so
    // _finish() can tell a signed transfer apart from a holdover of
    // widget.team's original roster even after a job change swaps which
    // list _finish() otherwise builds finalRoster from (see _finish()).
    _originalRosterNames = roster.map((p) => p.name).toSet();

    draftEligibleJuniors =
        roster
            .where(
              (p) =>
                  p.year == 'JR' &&
                  (awardOverall(p) >= 86 ||
                      (awardOverall(p) >= 82 && p.potential >= 91)),
            )
            .toList()
          ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));

    retentionCandidates =
        roster
            .where(
              (p) =>
                  p.year != 'FR' &&
                  (p.overall >= 68 ||
                      p.year == 'JR' ||
                      draftEligibleJuniors.any(
                        (junior) => junior.name == p.name,
                      )),
            )
            .toList()
          ..sort((a, b) {
            final aDraftBonus =
                draftEligibleJuniors.any((junior) => junior.name == a.name)
                ? 45
                : 0;
            final bDraftBonus =
                draftEligibleJuniors.any((junior) => junior.name == b.name)
                ? 45
                : 0;
            final aScore =
                a.overall * 3 +
                a.potential +
                (a.year == 'JR' ? 10 : 0) +
                aDraftBonus;
            final bScore =
                b.overall * 3 +
                b.potential +
                (b.year == 'JR' ? 10 : 0) +
                bDraftBonus;
            return bScore.compareTo(aScore);
          });

    final riskCount = max(
      draftEligibleJuniors.length,
      (2 + widget.losses ~/ 3).clamp(2, 7),
    );
    retentionCandidates = retentionCandidates.take(riskCount).toList();

    jobOffers = _jobOffers();
    retentionBudget = retentionBudgetForSeason(
      widget.wins,
      widget.losses,
      widget.team.prestige,
    );
    retentionSpent = 0;
    transferNilBudget = transferNilBudgetForSeason(widget.team.prestige);
    transferNilSpent = 0;
    trainingPoints = _trainingPoints();
    transferTargets = _generateTransfers();
  }

  String _advancePlayerYear(String year) {
    return switch (year) {
      'FR' => 'SO',
      'SO' => 'JR',
      'JR' => 'SR',
      _ => year,
    };
  }

  // Inverse of _advancePlayerYear — a redshirt year doesn't count against
  // eligibility, so toggling one on undoes the automatic advance
  // _initialRoster() already applied; toggling it back off re-applies it.
  String _revertPlayerYear(String year) {
    return switch (year) {
      'SO' => 'FR',
      'JR' => 'SO',
      'SR' => 'JR',
      _ => year,
    };
  }

  void _setPlayerYear(String name, String year, {bool? hasRedshirted}) {
    final idx = roster.indexWhere((p) => p.name == name);
    if (idx < 0) return;
    final old = roster[idx];
    roster[idx] = Player(
      name: old.name,
      position: old.position,
      overall: old.overall,
      potential: old.potential,
      year: year,
      stars: old.stars,
      hasRedshirted: hasRedshirted ?? old.hasRedshirted,
    );
  }

  List<Player> _initialRoster() {
    // Keep every non-senior player from the user's current roster.
    // Their identity and ratings stay intact; only their class year advances.
    final returning = widget.roster
        .where((player) => player.year != 'SR')
        .map(
          (player) => Player(
            name: player.name,
            position: player.position,
            overall: player.overall,
            potential: player.potential,
            year: _advancePlayerYear(player.year),
            stars: player.stars,
            hasRedshirted: player.hasRedshirted,
          ),
        )
        .toList();

    // Returning players are never cut automatically to make room.
    // New recruits are added only when an actual roster spot is available.
    final availableRecruitSlots = max(0, 22 - returning.length);

    // Best commits first: the in-season recruiting board now refuses to
    // let a class over-commit past availableRecruitSlots (see
    // _DashboardScreenState._recruitingClassHasRoom), so this take() should
    // rarely truncate anything going forward — this ordering is just a
    // safety net (e.g. a career saved before that gate existed) so if it
    // ever does, it's the lowest-rated commit that's dropped, not whoever
    // happened to land earliest in the list.
    final sortedIncoming = widget.incomingRecruits.toList()
      ..sort((a, b) {
        final byStars = b.stars.compareTo(a.stars);
        if (byStars != 0) return byStars;
        return b.displayedOverall.compareTo(a.displayedOverall);
      });

    final incoming = sortedIncoming
        .take(availableRecruitSlots)
        .map(
          (recruit) => Player(
            name: recruit.name,
            position: recruit.position,
            overall: (recruit.displayedOverall - 2 + rng.nextInt(5)).clamp(
              45,
              widget.team.isFcs ? fcsMaxPlayerOverall : 94,
            ),
            potential: widget.team.isFcs
                ? min(recruit.truePotential, fcsMaxPlayerOverall)
                : recruit.truePotential,
            year: 'FR',
            stars: recruit.stars,
          ),
        )
        .toList();

    return [...returning, ...incoming]
      ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
  }

  int _trainingPoints() {
    final base = 70 + widget.wins * 6;
    final lowPrestigeBonus =
        prestigeTier(widget.team.prestige) <= 2 && widget.wins >= 7 ? 20 : 0;
    return (base + lowPrestigeBonus).clamp(60, 170);
  }

  // How this AI program has actually fared under simulated seasons (see
  // simulateRivalCoachSeason) — falls back to the team's static day-one
  // prestige only if no rival record exists for it (shouldn't happen for
  // a real g5Teams entry, but keeps this safe either way).
  int _livePrestigeFor(CollegeTeam team) {
    for (final r in widget.rivalCoaches) {
      if (r.teamName == team.name) return r.currentPrestige;
    }
    return team.prestige;
  }

  // A live-resolved copy of `team` — prestige, conference, and subdivision
  // all reflect real career history via widget.rivalCoaches (a job-offer
  // candidate could itself be a formerly-FCS program already promoted to
  // FBS, whose static allTeams entry would otherwise show the wrong
  // conference/subdivision for the job the user is actually accepting).
  CollegeTeam _liveTeamFor(CollegeTeam team) {
    final rival = widget.rivalCoaches.where((r) => r.teamName == team.name).firstOrNull;
    if (rival == null) return team;
    return CollegeTeam(
      name: team.name,
      conference: rival.conferenceOverride ?? team.conference,
      prestige: rival.currentPrestige,
      primary: team.primary,
      secondary: team.secondary,
      subdivision: rival.subdivisionOverride ?? team.subdivision,
      emoji: team.emoji,
      mascot: team.mascot,
    );
  }

  List<JobOffer> _jobOffers() {
    final expected = prestigeExpectationWins(widget.team.prestige);
    final overExpectation = widget.wins - expected;
    final targets = jobOfferPrestigeTargets(
      currentPrestige: widget.team.prestige,
      wins: widget.wins,
      losses: widget.losses,
      expectedWins: max(4, (prestige100(widget.team.prestige) - 45) ~/ 6),
    );

    // allTeams, not g5Teams: a successful FCS coach's live-simulated
    // prestige/record can now surface real FBS offers, and a struggling
    // FBS coach's fallback target band can dip low enough to surface a
    // realistic FCS offer — jobOfferPrestigeTargets already does the right
    // scaling, this just widens the candidate pool it searches.
    final primaryPool =
        allTeams
            .where((t) => t.name != widget.team.name)
            .where(
              (t) => targets.any(
                (target) => (prestige100(_livePrestigeFor(t)) - target).abs() <= 12,
              ),
            )
            .where(
              (t) =>
                  widget.wins >= 8 ||
                  prestige100(_livePrestigeFor(t)) <=
                      prestige100(widget.team.prestige) + 10,
            )
            .toList()
          ..shuffle(rng);

    final teams = <CollegeTeam>[];
    for (final team in primaryPool) {
      if (!teams.any((t) => t.name == team.name)) teams.add(team);
      if (teams.length >= 3) break;
    }

    if (teams.length < 3) {
      final fallback =
          allTeams
              .where((t) => t.name != widget.team.name)
              .where((t) => !teams.any((o) => o.name == t.name))
              .toList()
            ..shuffle(rng);

      for (final team in fallback) {
        teams.add(team);
        if (teams.length >= 3) break;
      }
    }

    final count = overExpectation >= 4 || widget.wins >= 10 ? 4 : 3;
    return teams
        .take(count)
        .map((team) => JobOffer(team: team, years: 2 + rng.nextInt(2)))
        .toList();
  }

  // The one true retention cost for a player — a draft-eligible junior
  // asks 1.65x the base NIL number to stay instead of testing the NFL.
  // _playerRetentionCard must show and afford-check this exact same
  // number, or the amount actually charged on PAY can silently come in
  // higher than what the user was shown (the real bug: the card used to
  // display/afford-check the un-multiplied base ask while _retainPlayer
  // charged the multiplied one, so retaining one draft-eligible star could
  // quietly eat far more of the budget than the number on screen).
  int _retentionAskFor(Player p) {
    final baseAsk = playerRetentionAsk(p);
    return _isJuniorDraftCandidate(p) ? (baseAsk * 1.65).round() : baseAsk;
  }

  void _retainPlayer(Player p) {
    // Once _finalizeRetention() has run, every un-retained transfer/draft
    // candidate is already stripped from roster — retaining one now would
    // spend NIL budget on a player who can no longer come back. The stage
    // rail still lets the user tap back into this step, so this can't rely
    // on the step index alone.
    if (retentionFinalized) return;
    if (retainedPlayerNames.contains(p.name)) return;
    // A player who already told the coach the relationship is
    // unreconcilable is leaving no matter what's offered.
    if (widget.irreconcilablePlayerNames.contains(p.name)) return;

    final ask = _retentionAskFor(p);
    if (retentionSpent + ask > retentionBudget) return;

    setState(() {
      retentionSpent += ask;
      retainedPlayerNames.add(p.name);
    });
  }

  Player _baseTrainingPlayer(Player p) {
    final baseOverall = trainingBaseOveralls[p.name] ?? p.overall;
    return Player(
      name: p.name,
      position: p.position,
      overall: baseOverall,
      potential: p.potential,
      year: p.year,
      stars: p.stars,
      hasRedshirted: p.hasRedshirted,
    );
  }

  // A player who fits the program's current scheme gets more out of every
  // training point spent on him; a player who doesn't fit gets less. Read
  // live off the coach's current scheme rather than frozen at recruitment,
  // so it stays correct if the coach's system ever changes. fit spans
  // [-8, 12], so this multiplier spans exactly [0.85, 1.20] by construction.
  double _schemeFitTrainingMultiplier(String position) {
    final fit = schemeFitBonus(
      position,
      offensiveScheme: widget.coach.offensiveScheme,
      defensiveScheme: widget.coach.defensiveScheme,
    );
    return (1.0 + fit / 60).clamp(0.85, 1.20);
  }

  int _trainingProjectedOverall(Player p, Map<String, int> boosts) {
    final basePlayer = _baseTrainingPlayer(p);
    final baseSkills = playerSkillRatings(basePlayer);
    final fitMultiplier = _schemeFitTrainingMultiplier(p.position);
    final upgradedSkills = {
      for (final entry in baseSkills.entries)
        entry.key:
            (entry.value + ((boosts[entry.key] ?? 0) * fitMultiplier).round())
                .clamp(40, 94),
    };

    final newOverall =
        (upgradedSkills.values.reduce((a, b) => a + b) / upgradedSkills.length)
            .round();
    return max(basePlayer.overall, newOverall).clamp(45, basePlayer.potential);
  }

  void _applyTrainingOverall(Player p) {
    final idx = roster.indexWhere((x) => x.name == p.name);
    if (idx < 0) return;

    final old = roster[idx];
    final boosts = playerSkillBoosts[old.name] ?? {};
    final newOverall = _trainingProjectedOverall(old, boosts);

    roster[idx] = Player(
      name: old.name,
      position: old.position,
      overall: newOverall,
      potential: old.potential,
      year: old.year,
      stars: old.stars,
      hasRedshirted: old.hasRedshirted,
    );
  }

  void _upgradePlayerSkill(Player p, String skill) {
    if (trainingPoints < 10 || p.overall >= p.potential) return;

    setState(() {
      trainingBaseOveralls.putIfAbsent(p.name, () => p.overall);
      final boosts = playerSkillBoosts.putIfAbsent(p.name, () => {});
      boosts[skill] = (boosts[skill] ?? 0) + 1;
      trainingPoints -= 10;
      _applyTrainingOverall(p);
    });
  }

  void _removePlayerSkill(Player p, String skill) {
    final boosts = playerSkillBoosts[p.name];
    final currentBoost = boosts?[skill] ?? 0;
    if (currentBoost <= 0) return;

    setState(() {
      boosts![skill] = currentBoost - 1;
      if (boosts[skill] == 0) boosts.remove(skill);
      if (boosts.isEmpty) {
        playerSkillBoosts.remove(p.name);
      }

      trainingPoints += 10;
      _applyTrainingOverall(p);
    });
  }

  List<TransferTarget> _generateTransfers() {
    final positions = ['QB', 'HB', 'WR', 'TE', 'DE', 'LB', 'DB'];
    final years = ['SO', 'JR', 'SR'];
    final needs = _positionNeeds();

    final prestige = prestige100(widget.team.prestige);
    final tier = prestigeTier(widget.team.prestige);

    // Portal access by school prestige:
    // 50-59: mostly 1-2★
    // 60-69: mostly 2-3★, no 5★
    // 70-79: 2-4★
    // 80-89: 3-4★, rare 5★
    // 90-100: full portal access
    int maxStars;
    if (prestige >= 90) {
      maxStars = 5;
    } else if (prestige >= 80) {
      maxStars = widget.wins >= 9 ? 5 : 4;
    } else if (prestige >= 70) {
      maxStars = 4;
    } else if (prestige >= 60) {
      maxStars = 3;
    } else {
      maxStars = widget.wins >= 10 ? 3 : 2;
    }

    // The transfer portal follows the same star-tier ceiling as recruiting
    // (see recruitCanCommitToSubdivision) — without this, an elite FCS
    // program's prestige alone (up to 78, tier 3) would unlock the same
    // 4★ portal access as a mid-tier FBS program, quietly bypassing the
    // whole point of the recruiting restriction.
    if (widget.team.subdivision == Subdivision.fcs) {
      maxStars = min(maxStars, 3);
    }

    int rollStars() {
      final roll = rng.nextInt(100);

      if (maxStars <= 2) {
        if (roll < 70) return 1;
        return 2;
      }

      if (maxStars == 3) {
        if (roll < 25) return 1;
        if (roll < 72) return 2;
        return 3;
      }

      if (maxStars == 4) {
        if (roll < 12) return 2;
        if (roll < 52) return 3;
        return 4;
      }

      if (roll < 12) return 3;
      if (roll < 48) return 4;
      return 5;
    }

    int overallForStars(int stars) {
      switch (stars) {
        case 1:
          return 50 + rng.nextInt(11); // 50-60
        case 2:
          return 58 + rng.nextInt(13); // 58-70
        case 3:
          return 66 + rng.nextInt(13); // 66-78
        case 4:
          return 76 + rng.nextInt(11); // 76-86
        default:
          return 86 + rng.nextInt(9); // 86-94
      }
    }

    int interestFor(int stars, int overall, String position) {
      final needBoost = (needs[position] ?? 0) * 5;
      final seasonBoost = widget.wins >= 9
          ? 12
          : widget.wins >= 7
          ? 6
          : widget.wins <= 4
          ? -10
          : 0;

      var interest =
          40 +
          ((prestige - 50) ~/ 2) +
          seasonBoost +
          needBoost +
          rng.nextInt(16);

      if (stars > maxStars) interest -= 45;
      if (stars == maxStars) interest -= 8;
      if (overall >= 88 && prestige < 80) interest -= 35;
      if (overall >= 84 && prestige < 70) interest -= 25;

      return interest.clamp(5, 99);
    }

    final list = <TransferTarget>[];

    for (int i = 0; i < 24; i++) {
      final position = positions[rng.nextInt(positions.length)];
      final stars = rollStars();
      final overall = overallForStars(stars);
      final interest = interestFor(stars, overall, position);

      final rawPotential = (overall + 4 + rng.nextInt(11)).clamp(overall, 96);
      // Uncapped, a 3★ transfer's own potential (up to overall+14) could
      // still develop an FCS roster spot toward FBS-elite territory years
      // later — the same loophole fcsMaxPlayerOverall closes for recruits.
      final potential = widget.team.isFcs
          ? min(rawPotential, fcsMaxPlayerOverall)
          : rawPotential;

      list.add(
        TransferTarget(
          name: NameGenerator.generate(),
          position: position,
          overall: overall,
          potential: potential,
          year: years[rng.nextInt(years.length)],
          stars: stars,
          interest: interest,
        ),
      );
    }

    // Show the most interested players first, not just the highest overall players.
    list.sort((a, b) {
      final byInterest = b.interest.compareTo(a.interest);
      if (byInterest != 0) return byInterest;
      return b.overall.compareTo(a.overall);
    });

    return list.take(18).toList();
  }

  Map<String, int> _positionNeeds() {
    final desired = {
      'QB': 2,
      'HB': 2,
      'WR': 4,
      'TE': 2,
      'DE': 4,
      'LB': 4,
      'DB': 4,
    };

    final counts = <String, int>{};
    for (final p in roster) {
      counts[p.position] = (counts[p.position] ?? 0) + 1;
    }

    final needs = <String, int>{};
    for (final entry in desired.entries) {
      needs[entry.key] = max(0, entry.value - (counts[entry.key] ?? 0));
    }
    return needs;
  }

  bool get _rosterHasOpenSlot => roster.length < 22;

  void _finalizeTransferSign(TransferTarget transfer, {required bool payNil}) {
    final signedPlayer = transfer.toPlayer();
    // A name-collision "ghost" transfer never actually joins the roster —
    // bail before any NIL budget is spent, rather than paying for a player
    // who then vanishes.
    if (roster.any((player) => player.name == signedPlayer.name)) return;

    setState(() {
      if (payNil && transfer.wantsNil) {
        transferNilSpent += transfer.nilAsk;
        transfer.nilOffered = transfer.nilAsk;
      }
      transfer.signed = true;
      signedTransfers.add(transfer);

      roster.add(signedPlayer);
      trainingBaseOveralls[signedPlayer.name] = signedPlayer.overall;
      roster.sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
    });
  }

  String _randomOtherSchoolForTransfer(TransferTarget transfer) {
    final possible =
        g5Teams
            .where(
              (team) =>
                  team.name != widget.team.name &&
                  prestigeTier(team.prestige) >= transfer.stars - 1,
            )
            .toList()
          ..shuffle(rng);

    return possible.isEmpty ? 'another school' : possible.first.name;
  }

  void _finalizeTransferDecline(TransferTarget transfer) {
    setState(() {
      transfer.declined = true;
      transfer.destinationSchool = _randomOtherSchoolForTransfer(transfer);
    });
  }

  // 3+ star transfers don't just decide on their own — the coach gets the
  // final call. Whichever way the player is leaning after the initial
  // interest check, this is where a NIL package actually closes it — but
  // paying is a real offer, not a guaranteed sign. A program that was
  // never realistically in a player's range can't just buy him outright;
  // real money narrows the gap, it doesn't erase it. 1-2 star transfers
  // never reach this: they aren't asking for NIL, so their interest-based
  // lean is the final word, same as before.
  void _showTransferNilCloseDialog(
    TransferTarget transfer, {
    required bool leaningYes,
  }) {
    final canAfford = transferNilSpent + transfer.nilAsk <= transferNilBudget;
    final closeChance = ((leaningYes ? 0.80 : 0.45) + (transfer.interest / 500))
        .clamp(0.15, 0.95);

    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (_) => AlertDialog(
        backgroundColor: kCardColor,
        title: Text(
          leaningYes ? 'Ready To Commit' : 'Leaning Elsewhere',
          style: TextStyle(
            color: GKColors.parchmentWhite,
            fontWeight: FontWeight.w900,
          ),
        ),
        content: Text(
          leaningYes
              ? '${transfer.name} wants to join your program — but it isn\'t official until you sign off. '
                    'Offer ${moneyText(transfer.nilAsk)} in NIL to try to bring him in, or pass and let him walk.'
              : '${transfer.name} is leaning toward another program. A ${moneyText(transfer.nilAsk)} NIL package '
                    'might still flip him to your team, but it\'s no sure thing — this is the coach\'s final call.',
          style: const TextStyle(color: GKColors.parchmentWhite, height: 1.35),
        ),
        actions: [
          TextButton(
            onPressed: () {
              Navigator.pop(context);
              _finalizeTransferDecline(transfer);
            },
            child: Text(
              leaningYes ? 'LET HIM WALK' : 'PASS',
              style: TextStyle(
                color: GKColors.fadedInk,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          TextButton(
            onPressed: canAfford
                ? () {
                    Navigator.pop(context);
                    if (rng.nextDouble() < closeChance) {
                      _finalizeTransferSign(transfer, payNil: true);
                    } else {
                      _finalizeTransferDecline(transfer);
                    }
                  }
                : null,
            child: Text(
              canAfford
                  ? 'OFFER ${moneyText(transfer.nilAsk)} IN NIL'
                  : 'NOT ENOUGH NIL LEFT',
              style: TextStyle(
                color: canAfford ? kGreen : GKColors.fadedInk.withOpacity(.5),
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
        ],
      ),
    );
  }

  void _offerTransfer(TransferTarget transfer) {
    if (transfer.offered || transfer.signed || transfer.declined) return;
    if (!_rosterHasOpenSlot) return;

    final signChance = (transfer.interest / 240).clamp(.05, .92);
    final leaningYes = rng.nextDouble() < signChance;

    setState(() {
      transfer.offered = true;
    });

    if (!transfer.wantsNil) {
      if (leaningYes) {
        _finalizeTransferSign(transfer, payNil: false);
      } else {
        _finalizeTransferDecline(transfer);
      }
      return;
    }

    // A 3+ star transfer gets a real say before any money is on the
    // table — a program that was never realistically on their radar can
    // lose them outright, the same way a real transfer just picks
    // elsewhere without ever taking the call.
    if (!leaningYes) {
      final hardDeclineChance = (1 - transfer.interest / 100).clamp(0.0, 0.85);
      if (rng.nextDouble() < hardDeclineChance) {
        _finalizeTransferDecline(transfer);
        return;
      }
    }

    _showTransferNilCloseDialog(transfer, leaningYes: leaningYes);
  }

  bool _isJuniorDraftCandidate(Player player) {
    return draftEligibleJuniors.any(
      (candidate) => candidate.name == player.name,
    );
  }

  String _draftProjection(Player player) {
    final overall = awardOverall(player);

    if (overall >= 94) return 'ROUND 1';
    if (overall >= 90) return 'ROUNDS 1-2';
    if (overall >= 86) return 'ROUNDS 2-4';
    if (overall >= 80) return 'ROUNDS 4-6';
    return 'ROUND 7 / UDFA';
  }

  String _draftTeam(Player player) {
    const teams = [
      'Arizona',
      'Atlanta',
      'Baltimore',
      'Buffalo',
      'Carolina',
      'Chicago',
      'Cincinnati',
      'Cleveland',
      'Dallas',
      'Denver',
      'Detroit',
      'Green Bay',
      'Houston',
      'Indianapolis',
      'Jacksonville',
      'Kansas City',
      'Las Vegas',
      'Los Angeles',
      'Miami',
      'Minnesota',
      'New England',
      'New Orleans',
      'New York',
      'Philadelphia',
      'Pittsburgh',
      'San Francisco',
      'Seattle',
      'Tampa Bay',
      'Tennessee',
      'Washington',
    ];

    return teams[player.name.hashCode.abs() % teams.length];
  }

  String _projectedTransferDestination(Player player) {
    final options = g5Teams
        .where((team) => team.name != selectedTeam.name)
        .toList();

    if (options.isEmpty) return 'Transfer Portal';

    final index = player.name.hashCode.abs() % options.length;
    return options[index].name;
  }

  void _finalizeRetention() {
    if (retentionFinalized) return;

    draftedPlayers.clear();

    // Seniors who are good enough are drafted after graduating.
    draftedPlayers.addAll(
      graduatingPlayers.where(
        (player) =>
            awardOverall(player) >= 72 ||
            (awardOverall(player) >= 68 && player.stars >= 4),
      ),
    );

    // Elite juniors declare unless the coach successfully retains them with NIL.
    final juniorsLeavingForDraft = draftEligibleJuniors
        .where((player) => !retainedPlayerNames.contains(player.name))
        .toList();

    draftedPlayers.addAll(juniorsLeavingForDraft);

    final transferNames = retentionCandidates
        .where(
          (player) =>
              !retainedPlayerNames.contains(player.name) &&
              !draftEligibleJuniors.any((junior) => junior.name == player.name),
        )
        .map((player) => player.name)
        .toSet();

    final draftNames = juniorsLeavingForDraft.map((p) => p.name).toSet();

    roster.removeWhere(
      (player) =>
          transferNames.contains(player.name) ||
          draftNames.contains(player.name),
    );

    retentionFinalized = true;
  }

  // A non-conference rivalry already spends one of the 3 non-conference
  // game slots — without accounting for that here, the randomizer and the
  // 3-slot picker below both offered a full 3 picks on top of the rivalry
  // game, and the 4th team silently never made it into the real schedule
  // (_generateTwelveGameSlate's final take(3) had to drop one).
  int get _nonConferenceSlotCount {
    if (rivalryTeam == null) return 3;
    if (rivalryTeam!.conference == selectedTeam.conference) return 3;
    return 2;
  }

  void _randomizeNonConference() {
    // selectedTeam, not widget.team — see _scheduleBody's own note: a job
    // change earlier in this offseason already moved selectedTeam to the
    // new program, and this schedule is being built for that new job.
    final ownSubdivisionPool =
        selectedTeam.subdivision == Subdivision.fbs ? g5Teams : fcsTeams;
    final otherSubdivisionPool =
        selectedTeam.subdivision == Subdivision.fbs ? fcsTeams : g5Teams;

    final optionMap = <String, CollegeTeam>{};
    for (final team in ownSubdivisionPool) {
      if (team.name != selectedTeam.name &&
          team.conference != selectedTeam.conference) {
        optionMap[team.name] = team;
      }
    }

    final options = optionMap.values.toList()..shuffle(rng);
    final slots = _nonConferenceSlotCount;

    // Same ~40%-of-one-slot cross-subdivision chance as the automatic
    // season schedule generator (_generateTwelveGameSlate), so "Randomize"
    // produces a realistic mix instead of always defaulting to same-
    // subdivision-only.
    final picks = <CollegeTeam>[];
    if (rng.nextDouble() < 0.40 && otherSubdivisionPool.isNotEmpty) {
      picks.add(otherSubdivisionPool[rng.nextInt(otherSubdivisionPool.length)]);
    }
    for (final team in options) {
      if (picks.length >= slots) break;
      if (!picks.any((t) => t.name == team.name)) picks.add(team);
    }

    setState(() {
      customNonConference = picks.take(slots).toList();
    });
  }

  void _finish() {
    // A job change means transitionResult.playersFollowing (old-roster
    // holdovers who chose to follow you) replaces roster as the base for
    // finalRoster — but roster is still the only place a transfer signed
    // (or a player cut) during this same offseason actually lives, since
    // neither Portal Window nor Signing Day writes to transitionResult.
    // Without this, anyone signed after a job change vanished on kickoff.
    // See _originalRosterNames' declaration for why this set is safe to
    // use as "signed this offseason, not a widget.team holdover."
    final newlySignedThisOffseason = roster
        .where((p) => !_originalRosterNames.contains(p.name))
        .toList();

    final finalRoster = [
      ...(selectedTeam.name == widget.team.name
          ? roster
          : [
              ...(transitionResult?.playersFollowing ?? <Player>[]),
              ...newlySignedThisOffseason,
            ]),
    ]..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));

    // Fill genuine open roster spots with walk-ons, but never replace or
    // silently cut a returning player. Each walk-on targets whichever
    // position is furthest below the ideal roster shape, so a thin
    // recruiting/transfer class doesn't leave the team lopsided — and each
    // one is a single generated player, not a full discarded 22-man roster.
    while (finalRoster.length < 22) {
      final counts = <String, int>{};
      for (final player in finalRoster) {
        counts[player.position] = (counts[player.position] ?? 0) + 1;
      }

      var neediestPosition = idealRosterPositionCounts.keys.first;
      var worstDeficit = -1 << 30;
      for (final entry in idealRosterPositionCounts.entries) {
        final deficit = entry.value - (counts[entry.key] ?? 0);
        if (deficit > worstDeficit) {
          worstDeficit = deficit;
          neediestPosition = entry.key;
        }
      }

      finalRoster.add(generateWalkOn(widget.team.prestige, neediestPosition));
    }

    final changedJobs = selectedTeam.name != widget.team.name;

    widget.onFinish(
      OffseasonResult(
        team: selectedTeam,
        roster: finalRoster,
        rivalry: rivalryTeam,
        customNonConference: customNonConference,
        contractYearsRemaining: _contractYearsRemainingAfterDecision,
        customByeWeeks: customByeWeeks,
      ),
    );

    if (!changedJobs) {
      Navigator.of(context).pop();
    }
  }

  void _next() {
    if (step >= steps.length - 1) {
      _finish();
      return;
    }

    if (step == 3) {
      setState(() {
        _finalizeRetention();
        step++;
      });
      return;
    }

    setState(() => step++);
  }

