  // True when the coach is taking a different job this offseason — a new
  // job always means a fresh contract, not an extension of the old one.
  bool get _contractTookNewJob => selectedTeam.name != widget.team.name;

  int get _contractScore =>
      seasonScoreFor(widget.wins, widget.losses, widget.team.prestige);

  int get _contractExtensionYears =>
      _contractTookNewJob ? 0 : contractExtensionYearsForScore(_contractScore);

  int get _contractYearsRemainingAfterDecision => contractYearsAfterOffseason(
    tookNewJob: _contractTookNewJob,
    previousYearsRemaining: widget.contractYearsRemaining,
    newJobPrestige: selectedTeam.prestige,
    extensionYears: _contractExtensionYears,
  );

  Widget _contractBody() {
    final contractPrestige = selectedTeam.prestige;
    final contractTier = prestigeTier(contractPrestige);
    final contractExpectedWins = realisticExpectedWins(contractPrestige);
    final contractGoal = realisticContractGoal(contractPrestige);
    final contractSecurity = realisticJobSecurityLabel(contractPrestige);

    final tookNewJob = _contractTookNewJob;
    final extension = _contractExtensionYears;
    final score = _contractScore;
    final yearsRemaining = _contractYearsRemainingAfterDecision;

    final headline = tookNewJob
        ? 'NEW CONTRACT SIGNED'
        : extension > 0
        ? 'CONTRACT EXTENDED'
        : score < 35
        ? 'HOT SEAT'
        : 'NO EXTENSION';

    final detail = tookNewJob
        ? 'You accepted the ${selectedTeam.name} job. New coaches are protected during year one.'
        : extension > 0
        ? '+$extension years added — $yearsRemaining years remaining'
        : 'Reach next season’s expectation to improve job security. $yearsRemaining years remaining.';

    return Column(
      children: [
        if (selectedTeam.name != widget.team.name) _transitionBody(),
        _card(
          child: Column(
            children: [
              Text(
                headline,
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: tookNewJob || extension > 0
                      ? kGreen
                      : score < 35
                      ? kRed
                      : GKColors.fadedInk,
                  fontSize: 28,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 3,
                ),
              ),
              const SizedBox(height: 12),
              Text(
                detail,
                textAlign: TextAlign.center,
                style: const TextStyle(
                  color: GKColors.parchmentWhite,
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  height: 1.35,
                ),
              ),
              const SizedBox(height: 18),
              _teamLogo(selectedTeam, 74),
              const SizedBox(height: 12),
              Text(
                selectedTeam.name.toUpperCase(),
                textAlign: TextAlign.center,
                style: const TextStyle(
                  color: GKColors.parchmentWhite,
                  fontSize: 24,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 2,
                ),
              ),
              const SizedBox(height: 6),
              Text(
                '${prestigeStars(contractPrestige)}  $contractTier-STAR PROGRAM',
                textAlign: TextAlign.center,
