  CoachTransitionResult _calculateCoachTransition(CollegeTeam newTeam) {
    final playersFollowing = <Player>[];
    final recruitsFollowing = <Recruit>[];
    final recruitsStayed = <Recruit>[];
    final recruitsReopened = <Recruit>[];

    final prestigeDiff = newTeam.prestige - widget.team.prestige;
    final coachPull = coachRecruitingRating(widget.coach) / 100.0;

    for (final player in roster) {
      final youthBoost = player.year == 'FR' || player.year == 'SO' ? .12 : 0.0;
      final starterBoost = player.overall >= 75 ? .06 : 0.0;
      final chance =
          (.08 +
                  coachPull * .18 +
                  youthBoost +
                  starterBoost +
                  prestigeDiff * .004)
              .clamp(.03, .42);
      if (rng.nextDouble() < chance) playersFollowing.add(player);
    }

    final committedToYou = recruits
        .where((r) => r.committedSchool == widget.team.name)
        .toList();
    for (final recruit in committedToYou) {
      final starStay = recruit.stars >= 4 ? .10 : 0.0;
      final chanceFollow =
          (.20 + coachPull * .35 + prestigeDiff * .006 - starStay).clamp(
            .08,
            .72,
          );
      final roll = rng.nextDouble();
      if (roll < chanceFollow) {
        recruitsFollowing.add(recruit);
      } else if (roll < chanceFollow + .45) {
        recruitsStayed.add(recruit);
      } else {
        recruitsReopened.add(recruit);
      }
    }

    return CoachTransitionResult(
      playersFollowing: playersFollowing,
      recruitsFollowing: recruitsFollowing,
      recruitsStayed: recruitsStayed,
      recruitsReopened: recruitsReopened,
    );
  }

  void _acceptJobOffer(CollegeTeam team) {
    final isNewDeparture =
        team.name != widget.team.name && selectedTeam.name != team.name;

    // The offer itself was targeted using this program's real, simulated
    // prestige/conference/subdivision (_liveTeamFor) — carry that same
    // state into the job you actually take, not the static day-one
    // CollegeTeam (which would show the wrong conference/subdivision for a
    // program that's since been realigned or promoted).
    final liveTeam = _liveTeamFor(team);

    setState(() {
      selectedTeam = liveTeam;
      transitionResult = team.name == widget.team.name
          ? null
          : _calculateCoachTransition(liveTeam);
    });

    if (isNewDeparture) {
      _showDepartureBreakingNews(team);
    }
  }

  void _showDepartureBreakingNews(CollegeTeam newTeam) {
    final reporter = kingdomNetworkReportersFor(
      widget.season,
      salt:
          8800 + widget.team.name.hashCode.abs() + newTeam.name.hashCode.abs(),
    ).first;
    final storyline = coachDepartureStorylineFor(
      widget.coach.name,
      widget.team.name,
      newTeam.name,
      widget.season,
    );

    showDialog<void>(
