  void _acceptRealignment(ConferenceInvitation invite) {
    setState(() {
      acceptedRealignment = invite;
      selectedTeam = CollegeTeam(
        name: selectedTeam.name,
        conference: invite.conference,
        prestige: selectedTeam.prestige,
        primary: selectedTeam.primary,
        secondary: selectedTeam.secondary,
        subdivision: invite.subdivision,
        emoji: selectedTeam.emoji,
        mascot: selectedTeam.mascot,
      );
      // A brand-new conference means last year's rivalry/nonconference
      // picks may no longer even be legal (a different conference pool
      // entirely) — clear them so schedule generation rebuilds clean for
      // the new home, instead of carrying over a stale, possibly-invalid
      // pick from the old conference.
      rivalryTeam = null;
      customNonConference = [];
    });
  }

  void _declineRealignment() {
    setState(() => acceptedRealignment = null);
  }

