  Widget _transferCard(TransferTarget transfer) {
    // An OFFER tap is otherwise silently ignored once the 22-man roster is
    // full (see _offerTransfer's own guard) — reflect that here so the
    // button never looks live when it can't actually do anything.
    final rosterFull =
        !transfer.signed &&
        !transfer.declined &&
        !transfer.offered &&
        !_rosterHasOpenSlot;

    final statusColor = transfer.signed
        ? kGreen
        : transfer.declined
        ? kRed
        : rosterFull
        ? GKColors.fadedInk
        : kGold;
    final statusFill = transfer.signed
        ? kGreen.withOpacity(.12)
        : transfer.declined
        ? kRed.withOpacity(.12)
        : Colors.transparent;

    final status = transfer.signed
        ? 'SIGNED'
        : transfer.declined
        ? 'DECLINED'
        : transfer.offered
        ? 'WAITING'
        : rosterFull
        ? 'ROSTER FULL'
        : 'OFFER';
    final color = transfer.signed
        ? kGreen
        : transfer.declined
        ? kRed
        : kGold;

    return GestureDetector(
      onTap: () => _showTransferProfile(transfer),
      child: _card(
        margin: EdgeInsets.only(bottom: 10),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                PlayerAvatar(
                  seed: transfer.name.hashCode,
                  teamColor: widget.team.primary,
                  size: 42,
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Text(
                    '${transfer.name}\n${transfer.position} · ${transfer.year} · ${transfer.stars}★ · ${transfer.interest}% interest',
                    style: TextStyle(
                      color: GKColors.parchmentWhite,
                      fontWeight: FontWeight.bold,
                      height: 1.35,
                    ),
                  ),
                ),
                Text(
                  '${transfer.overall}',
                  style: TextStyle(
                    color: statusColor,
                    fontSize: 26,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(width: 10),
                GestureDetector(
                  onTap: rosterFull ? null : () => _offerTransfer(transfer),
                  child: Container(
                    padding: EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                    decoration: BoxDecoration(
                      color: statusFill,
                      border: Border.all(color: statusColor),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: Text(
                      status,
                      style: TextStyle(
                        color: statusColor,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                ),
              ],
            ),
            if (transfer.declined && transfer.destinationSchool != null) ...[
              const SizedBox(height: 8),
              Text(
                'Signed with ${universityDisplayName(transfer.destinationSchool!)}.',
                style: TextStyle(
                  color: GKColors.fadedInk,
                  fontSize: 11,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
            if (transfer.wantsNil) ...[
              const SizedBox(height: 8),
              Text(
                transfer.signed && transfer.nilOffered > 0
                    ? 'Signed for ${moneyText(transfer.nilOffered)} in NIL.'
                    : transfer.declined
                    ? 'Passed on a ${moneyText(transfer.nilAsk)} NIL package.'
                    : 'Wants ${moneyText(transfer.nilAsk)} in NIL — the coach gets a final call once you offer.',
                style: TextStyle(
                  color: GKColors.fadedInk,
                  fontSize: 11,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  Widget _trainingBody() {
    final sorted = roster.toList()
      ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _tripleStat([
          ['$trainingPoints', 'POINTS'],
          ['10', 'COST'],
          ['+ / −', 'TRIAL'],
        ]),
        const SizedBox(height: 18),
        ...sorted.map((p) => _trainingPlayerCard(p)),
      ],
    );
  }

  Widget _redshirtBody() {
    final eligible =
        roster.where((p) => p.year == 'FR' || p.year == 'SO').toList()
          ..sort((a, b) {
            final byYear = a.year.compareTo(b.year);
            if (byYear != 0) return byYear;
            return a.overall.compareTo(b.overall);
          });

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _card(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: const [
              Text(
                'REDSHIRT PLAYERS',
                style: TextStyle(
                  color: kGold,
                  fontSize: 22,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 3,
                ),
              ),
              SizedBox(height: 10),
              Text(
                'Choose freshmen or sophomores to redshirt before setting next year’s schedule. A redshirt year doesn’t count against eligibility, but every player only gets one across their career.',
                style: TextStyle(
                  color: GKColors.fadedInk,
                  fontWeight: FontWeight.bold,
                  height: 1.35,
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 14),
        _tripleStat([
          ['${redshirtedPlayerNames.length}', 'REDSHIRTS'],
          ['FR / SO', 'ELIGIBLE'],
          ['DEV', 'FOCUS'],
        ]),
        const SizedBox(height: 18),
        if (eligible.isEmpty)
          _card(
            child: Text(
              'No eligible freshmen or sophomores are available to redshirt.',
              style: TextStyle(
                color: GKColors.fadedInk,
                fontWeight: FontWeight.bold,
              ),
            ),
          )
        else
          ...eligible.map((p) => _redshirtPlayerCard(p)),
      ],
    );
  }

  Widget _redshirtPlayerCard(Player p) {
    final isRedshirted = redshirtedPlayerNames.contains(p.name);
    // Real NCAA rule: exactly one redshirt per career. p.hasRedshirted
    // tracks that permanently (see Player.hasRedshirted); isRedshirted is
    // only this offseason's still-reversible pending choice, so the two
    // can never both be true for the same player.
    final alreadyUsedRedshirt = p.hasRedshirted && !isRedshirted;
    final canRedshirt =
        (p.year == 'FR' || p.year == 'SO') && !alreadyUsedRedshirt;

    return _card(
      margin: const EdgeInsets.only(bottom: 10),
      child: Row(
        children: [
          PlayerAvatar(
            seed: p.name.hashCode,
            teamColor: widget.team.primary,
            size: 42,
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              '${p.cleanName}\n${p.position} · ${p.year} · ${awardOverall(p)} OVR · POT ${p.potential}',
              style: const TextStyle(
                color: GKColors.parchmentWhite,
                fontWeight: FontWeight.bold,
                height: 1.25,
              ),
            ),
          ),
          GestureDetector(
            onTap: !canRedshirt
                ? null
                : () {
                    setState(() {
                      if (isRedshirted) {
                        redshirtedPlayerNames.remove(p.name);
                        // Un-redshirting re-applies the year advance that
                        // was undone when this player was marked redshirt,
                        // and frees up their one career redshirt again.
                        _setPlayerYear(
                          p.name,
                          _advancePlayerYear(p.year),
                          hasRedshirted: false,
                        );
                      } else {
                        redshirtedPlayerNames.add(p.name);
                        // A redshirt year doesn't count against
                        // eligibility — undo the automatic class-year
                        // advance _initialRoster() already applied, so
                        // this player is genuinely still a FR/SO next
                        // season instead of just cosmetically labeled one.
                        // hasRedshirted:true permanently spends this
                        // player's one career redshirt (see canRedshirt).
                        _setPlayerYear(
                          p.name,
                          _revertPlayerYear(p.year),
                          hasRedshirted: true,
                        );
                      }
                    });
                  },
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                color: isRedshirted
                    ? kGreen.withOpacity(.14)
                    : alreadyUsedRedshirt
                    ? Colors.transparent
                    : kGold.withOpacity(.14),
                border: Border.all(
                  color: isRedshirted
                      ? kGreen
                      : alreadyUsedRedshirt
                      ? GKColors.fadedInk
                      : kGold,
                ),
                borderRadius: BorderRadius.circular(12),
              ),
              child: Text(
                isRedshirted
                    ? 'REDSHIRTED'
                    : alreadyUsedRedshirt
                    ? 'REDSHIRT USED'
                    : 'REDSHIRT',
                style: TextStyle(
                  color: isRedshirted
                      ? kGreen
                      : alreadyUsedRedshirt
                      ? GKColors.fadedInk
                      : kGold,
                  fontWeight: FontWeight.w900,
                  fontSize: 12,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _scheduleBody() {
    // selectedTeam, not widget.team: widget.team is the program the coach
    // led THIS PAST SEASON, but a job change earlier in this same
    // offseason flow already moved selectedTeam to the new program — the
    // schedule being built here is for that new job, conference and all.
    // allTeams, not g5Teams: an FCS coach's conference-mates live in
    // fcsTeams, and non-conference options should offer cross-subdivision
    // opponents too (FBS/FCS "buy games") — see the FCS subdivision plan.
    final optionMap = <String, CollegeTeam>{};
    for (final team in allTeams) {
      if (team.name != selectedTeam.name) {
        optionMap[team.name] = team;
      }
    }

    final allOptions = optionMap.values.toList()
      ..sort((a, b) => b.prestige.compareTo(a.prestige));

    final nonConferenceOptions = allOptions
        .where((team) => team.conference != selectedTeam.conference)
        .toList();
    // Real rivalries are conference rivalries — the same in-state,
    // played-every-year games the sport actually calls rivalries. This
    // also means a rivalry game always lands in confGames, never
    // competing with the 3 non-conference slots for room.
    final conferenceOptions = allOptions
        .where((team) => team.conference == selectedTeam.conference)
        .toList();

    CollegeTeam? teamByName(String? name) {
      if (name == null) return null;
      return optionMap[name];
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _card(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'RIVALRY',
                style: TextStyle(
                  color: kGold,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 3,
                ),
              ),
              const SizedBox(height: 12),
              Text(
                rivalryTeam == null
                    ? 'No rivalry selected'
                    : 'Rivalry: ${rivalryTeam!.name}',
                style: const TextStyle(
                  color: GKColors.parchmentWhite,
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 12),
              DropdownButton<String>(
                value: rivalryTeam?.name,
                dropdownColor: kCardColor,
                hint: Text(
                  'Choose Rivalry',
                  style: TextStyle(color: GKColors.fadedInk),
                ),
                isExpanded: true,
                // Always includes the current pick even if it predates the
                // in-conference-only rule (an older save's out-of-conference
                // rivalry) — a selected value missing from its own dropdown
                // renders blank, which is exactly the bug this avoids.
                items: <CollegeTeam>{...conferenceOptions, ?rivalryTeam}.map((
                  team,
                ) {
                  return DropdownMenuItem<String>(
                    value: team.name,
                    child: Text(
                      '${team.name} · ${team.subdivision.name.toUpperCase()} · ${team.conference} · P${prestige100(team.prestige)}',
                      style: const TextStyle(color: GKColors.parchmentWhite),
                    ),
                  );
                }).toList(),
                onChanged: (name) => setState(() {
                  rivalryTeam = teamByName(name);
                  // A rivalry that now eats a non-conference slot can make
                  // an already-picked 3rd game illegal — trim rather than
                  // let it silently vanish later in schedule generation.
                  if (customNonConference.length > _nonConferenceSlotCount) {
                    customNonConference = customNonConference
                        .take(_nonConferenceSlotCount)
                        .toList();
                  }
                }),
              ),
            ],
          ),
        ),
        const SizedBox(height: 16),
        _card(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'NON-CONFERENCE GAMES',
                style: TextStyle(
                  color: kGold,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 3,
                ),
              ),
              if (_nonConferenceSlotCount < 3) ...[
                const SizedBox(height: 4),
                Text(
                  'Your rivalry game is already using one non-conference slot.',
                  style: TextStyle(color: GKColors.fadedInk, fontSize: 11),
                ),
              ],
              const SizedBox(height: 12),
              DynastyButton(
                text: 'Randomize $_nonConferenceSlotCount Game${_nonConferenceSlotCount == 1 ? '' : 's'}',
                onPressed: _randomizeNonConference,
              ),
              const SizedBox(height: 12),
              ...List.generate(_nonConferenceSlotCount, (i) {
                final currentValue = i < customNonConference.length
                    ? customNonConference[i].name
                    : null;

                final usedNames = customNonConference
                    .asMap()
                    .entries
                    .where((entry) => entry.key != i)
                    .map((entry) => entry.value.name)
                    .toSet();

                // No take(N) cap here: nonConferenceOptions is a fixed
                // prestige-sorted list, so a cap taken *after* filtering
                // could silently exclude the currently-selected team
                // whenever it fell outside the cut — a valid pick from
                // Randomize would then render as an empty slot even
                // though customNonConference genuinely held 3 teams. That
                // was the actual bug: the state was always right, only
                // the dropdown's own rendered list was dropping the value.
                final menuItems = nonConferenceOptions
                    .where(
                      (team) =>
                          !usedNames.contains(team.name) ||
                          team.name == currentValue,
                    )
                    .map((team) {
                      return DropdownMenuItem<String>(
                        value: team.name,
                        child: Text(
                          '${team.name} · ${team.subdivision.name.toUpperCase()} · ${team.conference} · P${prestige100(team.prestige)}',
                          style: const TextStyle(
                            color: GKColors.parchmentWhite,
                          ),
                        ),
                      );
                    })
                    .toList();

                final safeValue =
                    currentValue != null &&
                        menuItems.any((item) => item.value == currentValue)
                    ? currentValue
                    : null;

                return DropdownButton<String>(
                  value: safeValue,
                  dropdownColor: kCardColor,
                  hint: Text(
                    'Game ${i + 1}',
                    style: const TextStyle(color: GKColors.fadedInk),
                  ),
                  isExpanded: true,
                  items: menuItems,
                  onChanged: (name) {
                    final team = teamByName(name);
                    if (team == null) return;

                    setState(() {
                      while (customNonConference.length <= i) {
                        final filler = nonConferenceOptions.firstWhere(
                          (candidate) => !customNonConference.any(
                            (picked) => picked.name == candidate.name,
                          ),
                          orElse: () => nonConferenceOptions.first,
                        );
                        customNonConference.add(filler);
                      }
                      customNonConference[i] = team;
                    });
                  },
                );
              }),
            ],
          ),
        ),
        const SizedBox(height: 16),
        _byeWeekCard(),
      ],
    );
  }

  // Real week indices, matching _generateSchedule/generateByeWeeks exactly:
  // week 0 is always a game (nobody byes in the season opener) and the
  // last week is always a game (it leads into conference championship
  // week), so only weeks 1-12 (displayed as WEEK 2 - WEEK 13) are pickable.
  static const int _totalScheduleWeeks = 14;

  Widget _byeWeekCard() {
    final picked = customByeWeeks ?? const <int>[];

    void setByeWeek(int week) {
      setState(() {
        final current = List<int>.from(picked);
        if (current.contains(week)) {
          current.remove(week);
        } else if (current.length < 2) {
          current.add(week);
        } else {
          // Already have both picks — deselect one first rather than
          // silently swapping, so the placement never changes by surprise.
          return;
        }
        customByeWeeks = current;
      });
    }

    return _card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'BYE WEEKS',
            style: TextStyle(
              color: kGold,
              fontWeight: FontWeight.w900,
              letterSpacing: 3,
            ),
          ),
          const SizedBox(height: 4),
          Text(
            picked.length == 2
                ? 'Weeks ${(picked.toList()..sort()).map((w) => w + 1).join(' and ')} — never back-to-back.'
                : 'Auto-placed for you, spaced apart. Tap two weeks below to pick them yourself.',
            style: TextStyle(color: GKColors.fadedInk, fontSize: 11),
          ),
          const SizedBox(height: 12),
          DynastyButton(
            text: 'Auto-Set Bye Weeks',
            onPressed: () => setState(() => customByeWeeks = null),
          ),
          const SizedBox(height: 12),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: List.generate(_totalScheduleWeeks, (week) {
              final isEnds = week == 0 || week == _totalScheduleWeeks - 1;
              final isPicked = picked.contains(week);
              // Would picking this week land it adjacent to the other
              // already-picked week? Shown disabled, not just rejected on
              // tap, so "never back-to-back" is visible before you try.
              final wouldBeAdjacent =
                  !isPicked &&
                  picked.length == 1 &&
                  (picked.first - week).abs() < 2;
              final disabled = isEnds || wouldBeAdjacent;

              return GestureDetector(
                onTap: disabled ? null : () => setByeWeek(week),
                child: Container(
                  width: 44,
                  height: 44,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: isPicked
                        ? kGold.withOpacity(.22)
                        : disabled
                        ? GKColors.fadedInk.withOpacity(.06)
                        : kCardColor,
                    border: Border.all(
                      color: isPicked
                          ? kGold
                          : disabled
                          ? GKColors.fadedInk.withOpacity(.25)
                          : kBorder,
                    ),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Text(
                    '${week + 1}',
                    style: TextStyle(
                      color: isPicked
                          ? kGold
                          : disabled
                          ? GKColors.fadedInk.withOpacity(.4)
                          : GKColors.parchmentWhite,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              );
            }),
          ),
        ],
      ),
    );
  }

  Widget _playerRetentionCard(Player p) {
    final ask = _retentionAskFor(p);
    final paid = retainedPlayerNames.contains(p.name);
    final irreconcilable = widget.irreconcilablePlayerNames.contains(p.name);
    final canAfford =
        !retentionFinalized &&
        !irreconcilable &&
        retentionSpent + ask <= retentionBudget;

    return _card(
      margin: const EdgeInsets.only(bottom: 10),
      child: Row(
        children: [
          PlayerAvatar(
            seed: p.name.hashCode,
            teamColor: widget.team.primary,
            size: 42,
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              '${p.cleanName}\n${p.position} · ${p.year} · ${awardOverall(p)} OVR\n${paid
                  ? 'Returning to ${selectedTeam.name}'
                  : irreconcilable
                  ? 'Differences irreconcilable — leaving no matter what\'s offered'
                  : _isJuniorDraftCandidate(p)
                  ? 'Considering NFL Draft · ${_draftProjection(p)}'
                  : 'Projected destination: ${_projectedTransferDestination(p)}'}',
              style: const TextStyle(
                color: GKColors.parchmentWhite,
                fontWeight: FontWeight.bold,
                height: 1.25,
              ),
            ),
          ),
          Text(
            moneyText(ask),
            style: const TextStyle(color: kGold, fontWeight: FontWeight.w900),
          ),
          const SizedBox(width: 10),
          GestureDetector(
            onTap: (paid || !canAfford) ? null : () => _retainPlayer(p),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                color: paid
                    ? kGreen.withOpacity(.16)
                    : canAfford
                    ? kGold.withOpacity(.16)
                    : GKColors.fadedInk.withOpacity(.10),
                border: Border.all(
                  color: paid
                      ? kGreen
                      : canAfford
                      ? kGold
                      : GKColors.fadedInk,
                ),
                borderRadius: BorderRadius.circular(12),
              ),
              child: Text(
                paid
                    ? 'KEPT'
                    : canAfford
                    ? 'PAY'
                    : irreconcilable
                    ? 'LEAVING'
                    : retentionFinalized
                    ? 'DECIDED'
                    : 'BUDGET FULL',
                style: TextStyle(
                  color: paid
                      ? kGreen
                      : canAfford
                      ? kGold
                      : GKColors.fadedInk,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _trainingPlayerCard(Player p) {
    final basePlayer = _baseTrainingPlayer(p);
    final baseSkills = playerSkillRatings(basePlayer);
    final boosts = playerSkillBoosts[p.name] ?? {};
    final canUpgrade = trainingPoints >= 10 && p.overall < p.potential;
    final baseOverall = trainingBaseOveralls[p.name] ?? p.overall;
    final overallGain = p.overall - baseOverall;

    return _card(
      margin: const EdgeInsets.only(bottom: 10),
      child: Column(
        children: [
          Row(
            children: [
              PlayerAvatar(
                seed: p.name.hashCode,
                teamColor: widget.team.primary,
                size: 42,
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Text(
                  '${p.cleanName}\n${p.position} · ${p.year} · POT ${p.potential}${overallGain > 0 ? ' · +$overallGain OVR' : ''}',
                  style: const TextStyle(
                    color: GKColors.parchmentWhite,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
              Text(
                '${awardOverall(p)}',
                style: const TextStyle(
                  color: kGold,
                  fontSize: 26,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          ...baseSkills.entries.map((entry) {
            final boost = boosts[entry.key] ?? 0;
            final rating = (entry.value + boost).clamp(40, 94);
            final canRemove = boost > 0;

            return Padding(
              padding: const EdgeInsets.only(top: 8),
              child: Row(
                children: [
                  Expanded(
                    child: Text(
                      entry.key.toUpperCase(),
                      style: const TextStyle(
                        color: GKColors.fadedInk,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1.5,
                      ),
                    ),
                  ),
                  Text(
                    '$rating${boost > 0 ? ' +$boost' : ''}',
                    style: const TextStyle(
                      color: GKColors.parchmentWhite,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(width: 10),
                  GestureDetector(
                    onTap: canRemove
                        ? () => _removePlayerSkill(p, entry.key)
                        : null,
                    child: Container(
                      width: 38,
                      height: 34,
                      decoration: BoxDecoration(
                        color: canRemove ? kRed.withOpacity(.16) : kBorder,
                        border: Border.all(
                          color: canRemove
                              ? kRed
                              : GKColors.fadedInk.withOpacity(.55),
                        ),
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Icon(
                        Icons.remove,
                        color: canRemove ? kRed : GKColors.fadedInk,
                        size: 18,
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  GestureDetector(
                    onTap: canUpgrade
                        ? () => _upgradePlayerSkill(p, entry.key)
                        : null,
                    child: Container(
                      width: 44,
                      height: 34,
                      decoration: BoxDecoration(
                        color: canUpgrade ? kGold : kBorder,
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Center(
                        child: Text(
                          '+1',
                          style: TextStyle(
                            color: canUpgrade
                                ? GKColors.inkBlack
                                : GKColors.fadedInk,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            );
          }),
        ],
      ),
    );
  }

  Widget _tripleStat(List<List<String>> stats) {
    return Container(
      padding: const EdgeInsets.symmetric(vertical: 18),
      decoration: BoxDecoration(
        color: kCardColor,
        border: Border.all(color: kBorder),
        borderRadius: BorderRadius.circular(20),
      ),
      child: Row(
        children: stats
            .map(
              (s) => Expanded(
                child: Column(
                  children: [
                    Text(
                      s[0],
                      style: const TextStyle(
                        color: kGold,
                        fontSize: 28,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      s[1],
                      style: const TextStyle(
                        color: GKColors.fadedInk,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 2,
                      ),
                    ),
                  ],
                ),
              ),
            )
            .toList(),
      ),
    );
  }

  Widget _card({required Widget child, EdgeInsets? margin}) {
    return Container(
      margin: margin,
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: kCardColor,
        border: Border.all(color: kBorder),
        borderRadius: BorderRadius.circular(20),
      ),
      child: child,
    );
  }

  Widget _teamLogo(CollegeTeam team, double size) =>
      GKTeamBadge(team: team, size: size);
}

class GameCompletionResult {
  final bool won;
  final PressConferenceResult pressConference;
  // The real score and Player of the Game from a watched GameSimScreen run —
  // null when the game was resolved via quick-sim (no live drive-by-drive
  // simulation happened, so there is no real score/player to report).
  final int? userScore;
  final int? opponentScore;
  final String? playerOfGameName;
  final String? playerOfGameLine;
  // Real per-drive event counts from a watched GameSimScreen run — null for
  // a quick-simmed game, which has no live drives to count. When present,
  // these are what the box score and season stat accumulation are built
  // from, so a watched game's recorded stats always match what was shown
  // on screen during the game.
  final int? teamTouchdowns;
  final int? teamFieldGoals;
  final int? teamBigPlays;
  final int? teamTurnovers;
  final int? opponentTurnovers;
  // The real, play-by-play box score built live during a watched game —
  // null for a quick-simmed game. When present, this is used directly for
  // season stat accumulation instead of being re-derived from the
  // aggregate counts above, so it always matches exactly what the player
  // saw update on screen during the game.
  final Map<String, GamePlayerLine>? playerLines;

  const GameCompletionResult({
    required this.won,
    required this.pressConference,
    this.userScore,
    this.opponentScore,
    this.playerOfGameName,
    this.playerOfGameLine,
    this.teamTouchdowns,
    this.teamFieldGoals,
    this.teamBigPlays,
    this.teamTurnovers,
    this.opponentTurnovers,
    this.playerLines,
  });
}

enum _DriveOutcome {
  touchdown,
  fieldGoal,
  turnover,
  explosivePlay,
  threeAndOut,
  punt,
}

/// A yard-line diagram sketched on the ledger page, not a photoreal turf
/// render — hairline yard markers, tinted end zones in each team's own
/// color, and a small brass football marking the ball's synthetic field
/// position for the current drive.
class _FootballFieldPainter extends CustomPainter {
  final double yardPosition; // 0 (home goal line) .. 100 (away goal line)
  final Color homeColor;
  final Color awayColor;
  final String homeAbbr;
  final String awayAbbr;
  final bool possessionIsUser;

  const _FootballFieldPainter({
    required this.yardPosition,
    required this.homeColor,
    required this.awayColor,
    required this.homeAbbr,
    required this.awayAbbr,
    required this.possessionIsUser,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final endzone = size.width * 0.09;
    final fieldLeft = endzone;
    final fieldWidth = size.width - endzone * 2;
    final top = size.height * 0.10;
    final bottom = size.height * 0.90;
    double xFor(double yard) => fieldLeft + fieldWidth * (yard / 100);

    final fieldRect = Rect.fromLTRB(
      fieldLeft,
      top,
      fieldLeft + fieldWidth,
      bottom,
    );

    // A real green field with each team's own color filling its end zone.
    canvas.drawRect(fieldRect, Paint()..color = GKColors.fieldGreen);
    canvas.drawRect(
      Rect.fromLTRB(0, top, endzone, bottom),
      Paint()..color = homeColor,
    );
    canvas.drawRect(
      Rect.fromLTRB(fieldLeft + fieldWidth, top, size.width, bottom),
      Paint()..color = awayColor,
    );

    final outline = Paint()
      ..color = GKColors.inkBlack.withOpacity(.6)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.4;
    canvas.drawRect(Rect.fromLTRB(0, top, size.width, bottom), outline);
    canvas.drawLine(Offset(fieldLeft, top), Offset(fieldLeft, bottom), outline);
    canvas.drawLine(
      Offset(fieldLeft + fieldWidth, top),
      Offset(fieldLeft + fieldWidth, bottom),
      outline,
    );

    // Yard lines every 10, numbered, 50 bolder.
    final line = Paint()
      ..color = GKColors.inkBlack.withOpacity(.32)
      ..strokeWidth = 1;
    final midline = Paint()
      ..color = GKColors.inkBlack.withOpacity(.55)
      ..strokeWidth = 1.6;
    for (var yard = 0; yard <= 100; yard += 10) {
      final x = xFor(yard.toDouble());
      canvas.drawLine(
        Offset(x, top),
        Offset(x, bottom),
        yard == 50 ? midline : line,
      );
      if (yard == 0 || yard == 100) continue;
      final number = yard <= 50 ? yard : 100 - yard;
      final tp = TextPainter(
        text: TextSpan(
          text: '$number',
          style: GoogleFonts.zillaSlab(
            fontSize: size.height * .14,
            fontWeight: FontWeight.w700,
            color: GKColors.inkBlack.withOpacity(.45),
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(x - tp.width / 2, top + 3));
    }

    // Hash ticks every 5 yards.
    final tick = Paint()
      ..color = GKColors.inkBlack.withOpacity(.28)
      ..strokeWidth = 1;
    for (var yard = 5; yard < 100; yard += 5) {
      if (yard % 10 == 0) continue;
      final x = xFor(yard.toDouble());
      canvas.drawLine(Offset(x, top), Offset(x, top + 6), tick);
      canvas.drawLine(Offset(x, bottom - 6), Offset(x, bottom), tick);
    }

    void endzoneLabel(String text, double cx, Color bg) {
      final tp = TextPainter(
        text: TextSpan(
          text: text,
          style: GoogleFonts.cinzel(
            fontSize: size.height * .16,
            fontWeight: FontWeight.w700,
            color: gkReadableOn(bg),
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      canvas.save();
      canvas.translate(cx, size.height / 2);
      canvas.rotate(-pi / 2);
      tp.paint(canvas, Offset(-tp.width / 2, -tp.height / 2));
      canvas.restore();
    }

    endzoneLabel(homeAbbr, endzone / 2, homeColor);
    endzoneLabel(awayAbbr, size.width - endzone / 2, awayColor);

    // Ball marker with a grounding shadow and a small drive-direction chevron.
    final ballX = xFor(yardPosition.clamp(0, 100));
    final ballY = size.height / 2;
    final shadow = Paint()..color = Colors.black.withOpacity(.25);
    canvas.drawOval(
      Rect.fromCenter(center: Offset(ballX, ballY + 5), width: 13, height: 5),
      shadow,
    );

    final ballPaint = Paint()..color = GKColors.kingdomBrass;
    final ballOutline = Paint()
      ..color = GKColors.inkBlack
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.1;
    final ballRect = Rect.fromCenter(
      center: Offset(ballX, ballY),
      width: 15,
      height: 8,
    );
    canvas.drawOval(ballRect, ballPaint);
    canvas.drawOval(ballRect, ballOutline);
    canvas.drawLine(
      Offset(ballX - 4, ballY),
      Offset(ballX + 4, ballY),
      Paint()
        ..color = GKColors.inkBlack
        ..strokeWidth = 1,
    );

    final dir = possessionIsUser ? 1 : -1;
    final chevron = Path()
      ..moveTo(ballX + dir * 11, ballY)
      ..lineTo(ballX + dir * 16, ballY - 4)
      ..moveTo(ballX + dir * 11, ballY)
      ..lineTo(ballX + dir * 16, ballY + 4);
    canvas.drawPath(
      chevron,
      Paint()
        ..color = GKColors.inkBlack.withOpacity(.6)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.4,
    );
  }

  @override
  bool shouldRepaint(covariant _FootballFieldPainter oldDelegate) =>
      oldDelegate.yardPosition != yardPosition ||
      oldDelegate.possessionIsUser != possessionIsUser ||
      oldDelegate.homeColor != homeColor ||
      oldDelegate.awayColor != awayColor;
}

/// A brass split-flap digit reveal for the live scoreboard — the specific
/// mechanical-scoreboard flip real stadiums are named for, not a generic
/// fade. The old score rotates away top-first; the new score rotates in
/// on the same axis, like a physical flap turning over. This is the one
/// authored focal motion for the scoreboard: every other number on this
/// screen stays a plain Text, so the flip stays legible as *the* moment
/// rather than a repeated tic.
class _ScoreFlipDigits extends StatelessWidget {
  final int score;
  final TextStyle style;

  const _ScoreFlipDigits({required this.score, required this.style});

  @override
  Widget build(BuildContext context) {
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 420),
      switchInCurve: Curves.easeOutCubic,
      switchOutCurve: Curves.easeInCubic,
      transitionBuilder: (child, animation) {
        final incoming = (child.key as ValueKey<int>).value == score;
        return AnimatedBuilder(
          animation: animation,
          child: child,
          builder: (context, child) {
            final t = incoming ? animation.value : 1 - animation.value;
            final angle = (1 - t) * (pi / 2.3);
            return Transform(
              alignment: Alignment.center,
              transform: Matrix4.identity()
                ..setEntry(3, 2, 0.0018)
                ..rotateX(incoming ? -angle : angle),
              child: Opacity(opacity: t.clamp(0.0, 1.0), child: child),
            );
          },
        );
      },
      child: Text('$score', key: ValueKey(score), style: style),
    );
  }
}

class GameSimScreen extends StatefulWidget {
  final CollegeTeam team;
  final CollegeTeam opponent;
  final int teamOvr;
  final int opponentOvr;
  final int teamRank;
  final int opponentRank;
  final Player teamStartingQb;
  final Player opponentStartingQb;
  final List<Player> teamLeaders;
  // The full starting lineup — used to attribute live touchdowns, yardage,
  // and defensive stats to real players as the game is actually played,
  // not just the QB/HB/best-defender trio teamLeaders carries for the
  // pregame card.
  final List<Player> teamStarters;
  final bool isNationalChampionship;
  // Scheme identity for both sides — feeds schemeMatchupModifier so the
  // live sim reflects the same scheme mastery system that already shapes
  // recruiting and development. Neutral defaults ('Pro Style'/'4-3
  // Defense', whose matchup row/column is all zeros) mean any call site
  // that doesn't pass these keeps working exactly as before.
  final String userOffensiveScheme;
  final String userDefensiveScheme;
  final String opponentOffensiveScheme;
  final String opponentDefensiveScheme;
  final ValueChanged<GameCompletionResult> onFinished;

  const GameSimScreen({
    super.key,
    required this.team,
    required this.opponent,
    required this.teamOvr,
    required this.opponentOvr,
    this.teamRank = 999,
    this.opponentRank = 999,
    required this.teamStartingQb,
    required this.opponentStartingQb,
    this.teamLeaders = const [],
    this.teamStarters = const [],
    this.isNationalChampionship = false,
    this.userOffensiveScheme = 'Pro Style',
    this.userDefensiveScheme = '4-3 Defense',
    this.opponentOffensiveScheme = 'Pro Style',
    this.opponentDefensiveScheme = '4-3 Defense',
    required this.onFinished,
  });

  @override
  State<GameSimScreen> createState() => _GameSimScreenState();
}

class _GameSimScreenState extends State<GameSimScreen>
    with TickerProviderStateMixin {
  // Repointed from the old neon-cyan game-sim palette to the Kingdom's
  // Ledger tokens; every usage in this screen cascades from here.
  static const Color _gameCyan = GKColors.kingdomBrass;
  static const Color _gameTeal = GKColors.fieldGreen;
  static const Color _gameCoral = GKColors.stampRed;
  static const Color _gamePanel = GKColors.saddleLeather;
  static const Color _gamePanelRaised = GKColors.elevatedLeather;
  static const Color _gameText = GKColors.parchmentWhite;
  static const Color _gameMuted = GKColors.fadedInk;
  final List<String> plays = [];

  // Scheme mastery: each side's offense-vs-defense matchup, computed once
  // per game (not re-derived every play) and added into _simPlay's diff
  // the same way userBias already is.
  late final int _userOffVsOppDefMod = schemeMatchupModifier(
    widget.userOffensiveScheme,
    widget.opponentDefensiveScheme,
  );
  late final int _oppOffVsUserDefMod = schemeMatchupModifier(
    widget.opponentOffensiveScheme,
    widget.userDefensiveScheme,
  );

  // Field visualization: the sim resolves whole drives (touchdown, field
  // goal, turnover, explosive play, punt, three-and-out) rather than
  // tracking real per-play yardage, so field position here is a synthetic,
  // display-only reconstruction driven by each drive's outcome — it never
  // feeds back into the score/turnover logic above.
  late final AnimationController _fieldController = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 750),
  );
  late final Animation<double> _fieldCurve = CurvedAnimation(
    parent: _fieldController,
    curve: Curves.easeOutCubic,
  );
  double _ballYardFrom = 25;
  double _ballYardTo = 25;
  bool _fieldPossessionIsUser = true;

  double get _ballYard =>
      _ballYardFrom + (_ballYardTo - _ballYardFrom) * _fieldCurve.value;

  void _animateDriveOnField(bool userBall, _DriveOutcome outcome) {
    final start = userBall ? 25.0 : 75.0;
    final dir = userBall ? 1.0 : -1.0;
    double end;
    switch (outcome) {
      case _DriveOutcome.touchdown:
        end = userBall ? 100.0 : 0.0;
      case _DriveOutcome.fieldGoal:
        end = start + dir * (35 + rng.nextDouble() * 15);
      case _DriveOutcome.explosivePlay:
        end = start + dir * (38 + rng.nextDouble() * 20);
      case _DriveOutcome.turnover:
        end = start + dir * (8 + rng.nextDouble() * 12);
      case _DriveOutcome.threeAndOut:
        end = start + dir * (2 + rng.nextDouble() * 6);
      case _DriveOutcome.punt:
        end = start + dir * (28 + rng.nextDouble() * 14);
    }
    _ballYardFrom = _ballYard;
    _ballYardTo = end.clamp(2.0, 98.0);
    _fieldPossessionIsUser = userBall;
    _fieldController.forward(from: 0);
  }

  int teamScore = 0;
  int opponentScore = 0;
  int quarter = 1;
  int drive = 0;
  int teamTouchdowns = 0;
  int opponentTouchdowns = 0;
  int teamFieldGoals = 0;
  int opponentFieldGoals = 0;
  int teamTurnovers = 0;
  int opponentTurnovers = 0;
  int teamBigPlays = 0;
  int opponentBigPlays = 0;

  // The real, live-updating box score — built play by play as the game
  // actually happens, not regenerated afterward. This is what both the
  // in-game and postgame box score panels read, and it's exactly what
  // flows back into season stats, so there's never a mismatch between what
  // was shown live and what gets recorded.
  final Map<String, GamePlayerLine> liveBoxScore = {};

  Player? _qb;
  Player? _hb;
  List<Player> _receivers = const [];
  List<Player> _defenders = const [];

  void _creditPlayerLine(Player player, GamePlayerLine line) {
    liveBoxScore[player.name] =
        (liveBoxScore[player.name] ?? GamePlayerLine.zero) + line;
  }

  // The touchdown popup — a brief "player card" celebrating whoever just
  // scored, with their line for the game so far.
  late final AnimationController _celebrationController = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 380),
  );
  late final Animation<double> _celebrationScale = CurvedAnimation(
    parent: _celebrationController,
    curve: Curves.elasticOut,
  );
  Player? _celebratingPlayer;
  String? _celebratingLine;

  void _showTouchdownCelebration(Player player) {
    _celebratingPlayer = player;
    _celebratingLine = seasonStatLineFor(
      liveBoxScore[player.name] ?? GamePlayerLine.zero,
    );
    _celebrationController.forward(from: 0);
    Future.delayed(const Duration(milliseconds: 2400), () {
      if (!mounted || _celebratingPlayer?.name != player.name) return;
      _celebrationController.reverse().then((_) {
        if (mounted && _celebratingPlayer?.name == player.name) {
          setState(() => _celebratingPlayer = null);
        }
      });
    });
  }

  bool gameStarted = false;
  bool finished = false;
  bool resultSent = false;
  bool autoRunning = false;
  double speed = 1;
  int selectedGameTab = 0;
  double momentum = 0;
  bool halftimeInserted = false;

  // Halftime adjustments — set once at the drive==14 hook, consumed by
  // whichever loop (_startAuto or _simToEnd) is currently driving the sim.
  bool _halftimeAdjustmentPending = false;
  // True for the entire time the halftime sheet is up. _simPlay() itself
  // refuses to run another play while this is true, so the game genuinely
  // cannot advance no matter how long the user takes to decide.
  bool _halftimeSheetOpen = false;
  int _firstHalfTeamScore = 0;
  int _firstHalfOpponentScore = 0;
  int _firstHalfTeamTurnovers = 0;
  int _firstHalfOpponentTurnovers = 0;
  int _firstHalfTeamBigPlays = 0;
  int _firstHalfOpponentBigPlays = 0;

  // Second-half chance deltas set by the user's halftime choice. All start
  // at 0 (no effect) until a choice is made — magnitudes are deliberately a
  // few hundredths, the same ballpark as schemeMatchupModifier's own effect
  // on these same four chances, so no single choice can dominate a real
  // Overall gap.
  double _halftimeOffTdDelta = 0;
  double _halftimeOffFgDelta = 0;
  double _halftimeOffTurnoverDelta = 0;
  double _halftimeOffBigPlayDelta = 0;
  double _halftimeDefTdDelta = 0;
  double _halftimeDefTurnoverDelta = 0;
  double _halftimeDefBigPlayDelta = 0;

  // Set once the halftime choice is confirmed — surfaced in the live HUD
  // for the rest of the game so the adjustment reads as something that's
  // actually in effect, not just a one-time popup.
  String? _activeOffensivePlanLabel;
  String? _activeDefensivePlanLabel;

  String get _broadcastLabel {
    if (widget.teamRank <= 10 || widget.opponentRank <= 10) {
      return 'PRIME WINDOW';
    }
    if (widget.teamRank <= 25 || widget.opponentRank <= 25) {
      return 'NATIONAL WINDOW';
    }
    return 'KINGDOM GAMECAST';
  }

  String get _stakesLabel {
    if (widget.teamRank <= 12 && widget.opponentRank <= 12) {
      return 'PLAYOFF IMPACT';
    }
    if (widget.team.conference == widget.opponent.conference) {
      return 'CONFERENCE GAME';
    }
    if (widget.teamRank <= 25 || widget.opponentRank <= 25) {
      return 'RANKED MATCHUP';
    }
    return 'REGULAR SEASON';
  }

  String get _weatherLabel {
    final value =
        (widget.team.name.length * 7 + widget.opponent.name.length * 11) % 5;

    return switch (value) {
      0 => 'Clear · 68°',
      1 => 'Cloudy · 57°',
      2 => 'Light rain · 52°',
      3 => 'Windy · 49°',
      _ => 'Clear · 74°',
    };
  }

  String get _spreadLabel {
    final raw = (widget.teamOvr - widget.opponentOvr) * .72;
    final rounded = ((raw * 2).round() / 2).clamp(-28, 28);

    if (rounded == 0) return 'PICK';
    return rounded > 0
        ? '${widget.team.name} -${rounded.toStringAsFixed(1)}'
        : '${widget.opponent.name} -${rounded.abs().toStringAsFixed(1)}';
  }

  double get _overUnder {
    final base =
        43.5 +
        ((widget.teamOvr + widget.opponentOvr - 140) * .32) +
        ((widget.team.name.length + widget.opponent.name.length) % 5);
    return (base * 2).round() / 2;
  }

  String get _overUnderLabel => 'O/U ${_overUnder.toStringAsFixed(1)}';

  String get _venueLabel {
    final stadium = switch (widget.opponent.name.hashCode.abs() % 6) {
      0 => 'Kingdom Field',
      1 => 'Memorial Stadium',
      2 => 'Legends Stadium',
      3 => 'Champions Field',
      4 => 'University Stadium',
      _ => 'National Stadium',
    };
    return '$stadium · ${widget.opponent.name}';
  }

  String get _kickoffLabel {
    return switch ((widget.team.name.length + widget.opponent.name.length) %
        4) {
      0 => '12:00 PM ET',
      1 => '3:30 PM ET',
      2 => '7:30 PM ET',
      _ => '8:00 PM ET',
    };
  }

  int get _attendance {
    final rankedBoost = (widget.teamRank <= 25 || widget.opponentRank <= 25)
        ? 9000
        : 0;
    final conferenceBoost = widget.team.conference == widget.opponent.conference
        ? 5500
        : 0;
    return (38500 + widget.opponentOvr * 310 + rankedBoost + conferenceBoost)
        .clamp(42000, 108000);
  }

  String get _crowdLabel {
    if (_attendance >= 90000) return 'HOSTILE SELLOUT';
    if (_attendance >= 70000) return 'PACKED HOUSE';
    return 'STRONG CROWD';
  }

  List<String> get _storylines {
    final stories = <String>[];

    if (widget.teamRank <= 12 && widget.opponentRank <= 12) {
      stories.add('KP ELIMINATION GAME');
    } else if (widget.teamRank <= 25 && widget.opponentRank <= 25) {
      stories.add('TOP 25 MATCHUP');
    }

    if (widget.team.conference == widget.opponent.conference) {
      stories.add('CONFERENCE IMPLICATIONS');
    }

    if ((widget.team.name.hashCode - widget.opponent.name.hashCode).abs() % 5 ==
        0) {
      stories.add('RIVALRY ENERGY');
    }

    if (_weatherLabel.contains('rain') || _weatherLabel.contains('Windy')) {
      stories.add('WEATHER COULD MATTER');
    }

    if (_broadcastLabel.contains('NATIONAL')) {
      stories.add('NATIONAL TV SPOTLIGHT');
    }

    stories.add(
      widget.teamOvr >= widget.opponentOvr
          ? '${widget.team.name.toUpperCase()} ENTERS FAVORED'
          : '${widget.team.name.toUpperCase()} SEEKS THE UPSET',
    );

    return stories.take(4).toList();
  }

  // Names come from the user's real roster (widget.teamLeaders); only the
  // per-game stat line is still flavor text, since this sim doesn't track
  // individual box-score stats across a season.
  List<(String, String, String)> get _teamLeaders {
    String statLineFor(Player p) {
      return switch (p.position) {
        'QB' =>
          '${2650 + widget.teamOvr * 11} YDS · ${18 + widget.teamOvr ~/ 5} TD',
        'HB' => '${720 + widget.teamOvr * 6} RUSH YDS',
        _ => '${6 + widget.teamOvr ~/ 12} SACKS',
      };
    }

    if (widget.teamLeaders.isEmpty) {
      return [
        (
          widget.teamStartingQb.cleanName,
          'QB',
          statLineFor(widget.teamStartingQb),
        ),
      ];
    }

    return widget.teamLeaders
        .map((p) => (p.cleanName, p.position, statLineFor(p)))
        .toList();
  }

  List<String> get _aroundNationScores {
    final teams = (widget.team.isFcs ? fcsTeams : g5Teams)
        .where(
          (team) =>
              team.name != widget.team.name &&
              team.name != widget.opponent.name,
        )
        .take(6)
        .toList();

    if (teams.length < 6) return const [];

    return [
      '${teams[0].name} ${10 + teams[0].prestige % 24} · ${teams[1].name} ${7 + teams[1].prestige % 20} · HALF',
      '${teams[2].name} ${13 + teams[2].prestige % 21} · ${teams[3].name} ${6 + teams[3].prestige % 18} · 3Q',
      '${teams[4].name} ${17 + teams[4].prestige % 18} · ${teams[5].name} ${10 + teams[5].prestige % 17} · HALF',
    ];
  }

  String get _socialReaction {
    final won = teamScore > opponentScore;
    final margin = (teamScore - opponentScore).abs();

    if (won && widget.opponentRank <= 25) {
      return '@KingdomSaturday · ${widget.team.name} delivers a season-defining ranked win.';
    }
    if (won && margin >= 21) {
      return '@CFBAlerts · ${widget.team.name} makes a statement in dominant fashion.';
    }
    if (won) {
      return '@SaturdayCentral · ${widget.team.name} survives and keeps the season moving.';
    }
    if (margin <= 7) {
      return '@CollegeFootballNow · ${widget.team.name} falls just short in a thriller.';
    }
    return '@GridironReport · ${widget.team.name} must regroup after a difficult result.';
  }

  String get _clockLabel {
    if (finished) return 'FINAL';
    final drivesInQuarter = drive % 7;
    final minutes = max(0, 15 - drivesInQuarter * 2);
    final seconds = (drive * 17) % 60;
    return '$minutes:${seconds.toString().padLeft(2, '0')}';
  }

  String get _quarterLabel {
    if (finished) return 'FINAL';
    if (!gameStarted) return 'PREGAME';
    return quarter > 4 ? 'OT' : 'Q$quarter';
  }

  bool get _userHasBall => drive % 2 == 0;

  String get _momentumText {
    if (momentum >= .58) return '${widget.team.name} SURGING';
    if (momentum >= .18) return '${widget.team.name} EDGE';
    if (momentum <= -.58) return '${widget.opponent.name} SURGING';
    if (momentum <= -.18) return '${widget.opponent.name} EDGE';
    return 'EVEN';
  }

  Color get _momentumColor {
    if (momentum > .12) return widget.team.primary;
    if (momentum < -.12) return widget.opponent.primary;
    return _gameMuted;
  }

  // Credits one offensive play's yardage (and, for a touchdown, the score)
  // to real starters — the QB throws it or carries it himself if there's
  // no back, a receiver catches it on a passing play, the HB carries a
  // rushing one. Returns whoever actually scored, for the celebration
  // popup (null on a non-scoring play).
  Player? _creditOffensivePlay(int yards, {required bool isTouchdown}) {
    final isPassPlay = _hb == null || rng.nextDouble() < 0.6;

    if (isPassPlay && _qb != null) {
      _creditPlayerLine(
        _qb!,
        GamePlayerLine(passYards: yards, passTDs: isTouchdown ? 1 : 0),
      );
      if (_receivers.isNotEmpty) {
        final receiver = _receivers[rng.nextInt(_receivers.length)];
        _creditPlayerLine(
          receiver,
          GamePlayerLine(recYards: yards, recTDs: isTouchdown ? 1 : 0),
        );
        return isTouchdown ? receiver : null;
      }
      return isTouchdown ? _qb : null;
    }

    final rusher = _hb ?? _qb;
    if (rusher != null) {
      _creditPlayerLine(
        rusher,
        GamePlayerLine(rushYards: yards, rushTDs: isTouchdown ? 1 : 0),
      );
      return isTouchdown ? rusher : null;
    }
    return null;
  }

  void _creditDefensivePlay({bool forcedTurnover = false}) {
    if (_defenders.isEmpty) return;
    final defender = _defenders[rng.nextInt(_defenders.length)];
    _creditPlayerLine(
      defender,
      GamePlayerLine(
        tackles: 1 + rng.nextInt(3),
        interceptions: forcedTurnover && rng.nextDouble() < .4 ? 1 : 0,
      ),
    );
  }

  Player? _bestStarterAt(List<String> positions) {
    final matches =
        widget.teamStarters
            .where((p) => positions.contains(p.position))
            .toList()
          ..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
    return matches.isEmpty ? null : matches.first;
  }

  @override
  void initState() {
    super.initState();
    plays.add(
      '${rankedDisplayName(widget.team, widget.teamRank)} and '
      '${rankedDisplayName(widget.opponent, widget.opponentRank)} '
      'are preparing for kickoff.',
    );

    _qb = _bestStarterAt(const ['QB']) ?? widget.teamStartingQb;
    _hb = _bestStarterAt(const ['HB', 'RB']);
    _receivers = [
      ...widget.teamStarters.where((p) => p.position == 'WR'),
      ...widget.teamStarters.where((p) => p.position == 'TE'),
    ]..sort((a, b) => awardOverall(b).compareTo(awardOverall(a)));
    _defenders = widget.teamStarters
        .where(
          (p) => const [
            'DE',
            'DL',
            'DT',
            'LB',
            'DB',
            'CB',
            'S',
          ].contains(p.position),
        )
        .toList();
  }

  @override
  void dispose() {
    _fieldController.dispose();
    _celebrationController.dispose();
    super.dispose();
  }

  void _beginGame() {
    if (gameStarted || finished) return;

    setState(() {
      gameStarted = true;
      plays.insert(
        0,
        'Kickoff: ${widget.team.name} vs ${widget.opponent.name}.',
      );
    });

    _startAuto();
  }

  Future<void> _startAuto() async {
    if (finished) return;

    if (!gameStarted) {
      setState(() => gameStarted = true);
    }

    setState(() => autoRunning = true);

    while (autoRunning && !finished && mounted) {
      _simPlay();
      if (_halftimeAdjustmentPending) {
        _halftimeAdjustmentPending = false;
        setState(() => _halftimeSheetOpen = true);
        await _showHalftimeAdjustments();
        if (!mounted) return;
        setState(() => _halftimeSheetOpen = false);
      }
      final delay = (920 / speed).round();
      await Future.delayed(Duration(milliseconds: delay));
    }
  }

  void _stopAuto() {
    if (!mounted) return;
    setState(() => autoRunning = false);
  }

  void _addPlay(String text, {required bool userPositive}) {
    plays.insert(0, text);

    final shift = userPositive ? .15 : -.15;
    momentum = (momentum * .72 + shift).clamp(-1, 1);
  }

  void _simPlay() {
    // Redundant, belt-and-suspenders guard: whichever loop is driving the
    // sim already blocks on _showHalftimeAdjustments() before calling this
    // again, but this makes it structurally impossible for ANY caller
    // (present or future) to advance the game while that sheet is open.
    if (finished || _halftimeSheetOpen) return;

    final userBall = drive % 2 == 0;
    final offense = userBall ? widget.team.name : widget.opponent.name;
    final offOvr = userBall ? widget.teamOvr : widget.opponentOvr;
    final defOvr = userBall ? widget.opponentOvr : widget.teamOvr;
    final rawDiff = offOvr - defOvr;

    // Mirrors _userGameWinChance's close-game bias for the quick-sim path: a
    // dead-even matchup gets the user a ~6-OVR-point thumb on the scale that
    // fades out entirely once either side has a clear ratings edge, plus a
    // deliberately tiny extra nudge in the national championship specifically.
    final closeGameBias = 6.0 * (1 - (rawDiff.abs() / 6).clamp(0.0, 1.0));
    final titleGameBias = widget.isNationalChampionship ? 1.0 : 0.0;
    final userBias = closeGameBias + titleGameBias;
    // Scheme mastery: whichever side is on offense right now gets their
    // own scheme's matchup value against the other side's defense — same
    // OVR-point units as rawDiff, so it can only ever nudge outcomes like
    // a handful of Overall points would, never override a real talent gap.
    final schemeMod = userBall ? _userOffVsOppDefMod : _oppOffVsUserDefMod;
    final diff = rawDiff + schemeMod + (userBall ? userBias : -userBias);

    final chances = driveChancesFor(
      diff: diff,
      tdDelta: userBall ? _halftimeOffTdDelta : _halftimeDefTdDelta,
      fgDelta: userBall ? _halftimeOffFgDelta : 0,
      turnoverDelta: userBall
          ? _halftimeOffTurnoverDelta
          : _halftimeDefTurnoverDelta,
      bigPlayDelta: userBall
          ? _halftimeOffBigPlayDelta
          : _halftimeDefBigPlayDelta,
    );
    final tdChance = chances.td;
    final fgChance = chances.fg;
    final turnoverChance = chances.turnover;
    final bigPlayChance = chances.bigPlay;
    final roll = rng.nextDouble();

    setState(() {
      if (roll < tdChance) {
        Player? scorer;
        if (userBall) {
          teamScore += 7;
          teamTouchdowns++;
          HapticFeedback.heavyImpact();
          scorer = _creditOffensivePlay(
            25 + rng.nextInt(55),
            isTouchdown: true,
          );
        } else {
          opponentScore += 7;
          opponentTouchdowns++;
          HapticFeedback.lightImpact();
        }

        _addPlay(
          'Q$quarter · TOUCHDOWN — $offense finishes a complete scoring drive. '
          '$teamScore-$opponentScore',
          userPositive: userBall,
        );
        _animateDriveOnField(userBall, _DriveOutcome.touchdown);
        if (scorer != null) {
          _showTouchdownCelebration(scorer);
        }
      } else if (roll < tdChance + fgChance) {
        if (userBall) {
          teamScore += 3;
          teamFieldGoals++;
          HapticFeedback.mediumImpact();
          _creditOffensivePlay(15 + rng.nextInt(30), isTouchdown: false);
        } else {
          opponentScore += 3;
          opponentFieldGoals++;
        }

        _addPlay(
          'Q$quarter · FIELD GOAL — $offense takes the points. '
          '$teamScore-$opponentScore',
          userPositive: userBall,
        );
        _animateDriveOnField(userBall, _DriveOutcome.fieldGoal);
      } else if (roll < tdChance + fgChance + turnoverChance) {
        if (userBall) {
          teamTurnovers++;
        } else {
          opponentTurnovers++;
          HapticFeedback.mediumImpact();
          _creditDefensivePlay(forcedTurnover: true);
        }

        _addPlay(
          'Q$quarter · TURNOVER — $offense gives the ball away under pressure.',
          userPositive: !userBall,
        );
        _animateDriveOnField(userBall, _DriveOutcome.turnover);
      } else if (roll < tdChance + fgChance + turnoverChance + bigPlayChance) {
        if (userBall) {
          teamBigPlays++;
          _creditOffensivePlay(20 + rng.nextInt(35), isTouchdown: false);
        } else {
          opponentBigPlays++;
          _creditDefensivePlay();
        }

        _addPlay(
          'Q$quarter · EXPLOSIVE PLAY — $offense flips the field before the drive stalls.',
          userPositive: userBall,
        );
        _animateDriveOnField(userBall, _DriveOutcome.explosivePlay);
      } else if (diff < -22 && rng.nextDouble() < .48) {
        _addPlay(
          'Q$quarter · THREE-AND-OUT — $offense is overwhelmed at the line.',
          userPositive: !userBall,
        );
        _animateDriveOnField(userBall, _DriveOutcome.threeAndOut);
      } else {
        _addPlay(
          'Q$quarter · PUNT — $offense cannot sustain the drive.',
          userPositive: !userBall,
        );
        _animateDriveOnField(userBall, _DriveOutcome.punt);
      }

      drive++;
      quarter = (drive ~/ 7) + 1;

      if (drive == 14 && !halftimeInserted) {
        halftimeInserted = true;
        _firstHalfTeamScore = teamScore;
        _firstHalfOpponentScore = opponentScore;
        _firstHalfTeamTurnovers = teamTurnovers;
        _firstHalfOpponentTurnovers = opponentTurnovers;
        _firstHalfTeamBigPlays = teamBigPlays;
        _firstHalfOpponentBigPlays = opponentBigPlays;
        _halftimeAdjustmentPending = true;
        plays.insert(
          0,
          'HALFTIME · ${widget.team.name} $teamScore, '
          '${widget.opponent.name} $opponentScore',
        );
        for (final score in _aroundNationScores.reversed) {
          plays.insert(1, 'AROUND THE NATION · $score');
        }
      }

      if (drive >= 28) {
        _finishGameInternal();
      }
    });
  }

  bool _simmingToEnd = false;

  Future<void> _simToEnd() async {
    if (_simmingToEnd || finished) return;

    if (!gameStarted) {
      setState(() => gameStarted = true);
    }

    setState(() {
      autoRunning = false;
      _simmingToEnd = true;
    });

    while (!finished) {
      _simPlay();
      if (_halftimeAdjustmentPending) {
        _halftimeAdjustmentPending = false;
        setState(() => _halftimeSheetOpen = true);
        await _showHalftimeAdjustments();
        if (!mounted) return;
        setState(() => _halftimeSheetOpen = false);
      }
      // Yield so Flutter actually paints a frame between plays — a bare
      // synchronous loop blocks the UI thread and the score never renders
      // until every play has resolved.
      await Future.delayed(Duration.zero);
      if (!mounted) return;
    }

    if (mounted) {
      setState(() => _simmingToEnd = false);
    }
  }

  // Offense: trailing by a score or more means push for points, leading
  // comfortably means run the clock, otherwise stay balanced.
  _OffensivePlan get _recommendedOffensivePlan {
    final margin = _firstHalfTeamScore - _firstHalfOpponentScore;
    if (margin <= -7) return _OffensivePlan.airItOut;
    if (margin >= 7) return _OffensivePlan.runItOut;
    return _OffensivePlan.balanced;
  }

  // Defense: down big and need the ball back means bring pressure; getting
  // gashed by explosive plays (and not desperate for a turnover) means
  // play it safer; otherwise stay balanced.
  _DefensivePlan get _recommendedDefensivePlan {
    final margin = _firstHalfTeamScore - _firstHalfOpponentScore;
    if (margin <= -7) return _DefensivePlan.bringPressure;
    if (_firstHalfOpponentBigPlays > _firstHalfTeamBigPlays) {
      return _DefensivePlan.bendDontBreak;
    }
    return _DefensivePlan.balanced;
  }

  String _offensivePlanLabel(_OffensivePlan plan) => switch (plan) {
    _OffensivePlan.airItOut => 'AIR IT OUT',
    _OffensivePlan.balanced => 'STAY BALANCED',
    _OffensivePlan.runItOut => 'RUN IT OUT',
  };

  String _defensivePlanLabel(_DefensivePlan plan) => switch (plan) {
    _DefensivePlan.bringPressure => 'BRING PRESSURE',
    _DefensivePlan.balanced => 'STAY BALANCED',
    _DefensivePlan.bendDontBreak => 'BEND, DON\'T BREAK',
  };

  // Named after the coach's own actual scheme where it reads naturally, so
  // the advice feels like it's about this program's real system, not a
  // generic label.
  String _offensivePlanReason(_OffensivePlan plan) {
    final margin = _firstHalfTeamScore - _firstHalfOpponentScore;
    switch (plan) {
      case _OffensivePlan.airItOut:
        return margin <= -7
            ? "You're down ${-margin} — turn the ${widget.userOffensiveScheme} loose and push tempo."
            : "Bigger turnover risk for upside you don't need right now.";
      case _OffensivePlan.runItOut:
        return margin >= 7
            ? 'Up $margin — grind the clock and protect the football.'
            : 'Lower-risk football: shorter drives, fewer chances to give it away.';
      case _OffensivePlan.balanced:
        return 'No wholesale changes — keep running the ${widget.userOffensiveScheme} as installed.';
    }
  }

  String _defensivePlanReason(_DefensivePlan plan) {
    switch (plan) {
      case _DefensivePlan.bringPressure:
        return _firstHalfTeamScore - _firstHalfOpponentScore <= -7
            ? 'Dial up the ${widget.userDefensiveScheme} pressure — you need the ball back.'
            : 'More takeaway upside, but exposed if the pressure doesn\'t get there.';
      case _DefensivePlan.bendDontBreak:
        return _firstHalfOpponentBigPlays > _firstHalfTeamBigPlays
            ? "${widget.opponent.name} has hit you for explosive plays — play it safe and take that away."
            : 'Lower-risk coverage — concede the short stuff, take away the big one.';
      case _DefensivePlan.balanced:
        return 'Stick with the ${widget.userDefensiveScheme} as called — no overreaction.';
    }
  }

  void _applyHalftimePlans(
    _OffensivePlan offense,
    _DefensivePlan defense,
    BuildContext sheetContext,
  ) {
    setState(() {
      switch (offense) {
        case _OffensivePlan.airItOut:
          // A real gamble: scoring upside, meaningfully higher turnover risk.
          _halftimeOffTdDelta = 0.018;
          _halftimeOffFgDelta = -0.008;
          _halftimeOffTurnoverDelta = 0.022;
          _halftimeOffBigPlayDelta = 0.016;
        case _OffensivePlan.runItOut:
          // Lower variance, and not even a higher expected value
          // (-7*.008 + 3*.010 nets slightly negative) — a real hedge.
          _halftimeOffTdDelta = -0.008;
          _halftimeOffFgDelta = 0.010;
          _halftimeOffTurnoverDelta = -0.018;
          _halftimeOffBigPlayDelta = -0.012;
        case _OffensivePlan.balanced:
          _halftimeOffTdDelta = 0;
          _halftimeOffFgDelta = 0;
          _halftimeOffTurnoverDelta = 0;
          _halftimeOffBigPlayDelta = 0;
      }
      switch (defense) {
        case _DefensivePlan.bringPressure:
          // Aggressive: real takeaway upside, but a real cost if the
          // pressure doesn't get home — genuinely boom-or-bust, mirroring
          // the offense's own Air It Out risk profile.
          _halftimeDefTdDelta = -0.012;
          _halftimeDefTurnoverDelta = 0.024;
          _halftimeDefBigPlayDelta = 0.014;
        case _DefensivePlan.bendDontBreak:
          // Passive and safe: caps explosive plays, doesn't chase extra
          // takeaways.
          _halftimeDefTdDelta = -0.010;
          _halftimeDefTurnoverDelta = -0.006;
          _halftimeDefBigPlayDelta = -0.016;
        case _DefensivePlan.balanced:
          _halftimeDefTdDelta = 0;
          _halftimeDefTurnoverDelta = 0;
          _halftimeDefBigPlayDelta = 0;
      }
      _activeOffensivePlanLabel = _offensivePlanLabel(offense);
      _activeDefensivePlanLabel = _defensivePlanLabel(defense);
    });
    Navigator.of(sheetContext).pop();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        backgroundColor: GKColors.elevatedPanel,
        behavior: SnackBarBehavior.floating,
        duration: const Duration(seconds: 3),
        content: Text(
          'ADJUSTMENTS LOCKED IN: ${_offensivePlanLabel(offense)} · ${_defensivePlanLabel(defense)}',
          style: GKText.bodyStrong.copyWith(fontSize: 12),
        ),
      ),
    );
  }

  Widget _planChip({
    required String label,
    required String? reason,
    required bool selected,
    required bool recommended,
    required bool risky,
    required VoidCallback onTap,
  }) {
    final tagColor = recommended
        ? GKColors.fieldGreen
        : risky
        ? GKColors.stampRed
        : null;

    return GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 150),
        padding: const EdgeInsets.symmetric(
          horizontal: GKSpace.sm,
          vertical: GKSpace.sm,
        ),
        decoration: BoxDecoration(
          color: selected
              ? GKColors.kingdomBrass.withOpacity(.16)
              : Colors.transparent,
          border: Border.all(
            color: selected ? GKColors.kingdomBrass : GKColors.divider,
            width: selected ? 1.5 : 1,
          ),
          borderRadius: BorderRadius.circular(GKRadius.small),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(
                  selected
                      ? Icons.radio_button_checked
                      : Icons.radio_button_off,
                  size: 16,
                  color: selected ? GKColors.kingdomBrass : GKColors.fadedInk,
                ),
                const SizedBox(width: GKSpace.xs),
                Expanded(
                  child: Text(
                    label,
                    style: GKText.bodyStrong.copyWith(fontSize: 12),
                  ),
                ),
                if (tagColor != null)
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 6,
                      vertical: 2,
                    ),
                    decoration: BoxDecoration(
                      color: tagColor.withOpacity(.16),
                      border: Border.all(color: tagColor.withOpacity(.6)),
                      borderRadius: BorderRadius.circular(GKRadius.pill),
                    ),
                    child: Text(
                      recommended ? 'RECOMMENDED' : 'HIGH RISK',
                      style: TextStyle(
                        color: tagColor,
                        fontSize: 8,
                        fontWeight: FontWeight.w900,
                        letterSpacing: .5,
                      ),
                    ),
                  ),
              ],
            ),
            if (reason != null) ...[
              const SizedBox(height: 4),
              Padding(
                padding: const EdgeInsets.only(left: 24),
                child: Text(
                  reason,
                  style: GKText.body.copyWith(fontSize: 10.5),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  Future<void> _showHalftimeAdjustments() {
    var selectedOffense = _recommendedOffensivePlan;
    var selectedDefense = _recommendedDefensivePlan;

    return showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      isDismissible: false,
      enableDrag: false,
      backgroundColor: Colors.transparent,
      // Bounds the sheet's own max size (not just its content) so on a
      // short screen the choices scroll instead of rendering off-screen
      // and unreachable.
      constraints: BoxConstraints(
        maxHeight: MediaQuery.of(context).size.height * 0.85,
      ),
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return SafeArea(
              child: Container(
                margin: const EdgeInsets.all(GKSpace.sm),
                padding: const EdgeInsets.all(GKSpace.xl),
                decoration: BoxDecoration(
                  color: GKColors.elevatedPanel,
                  border: Border.all(color: GKColors.divider),
                  borderRadius: BorderRadius.circular(GKRadius.modal),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withOpacity(.45),
                      blurRadius: 35,
                      offset: const Offset(0, 15),
                    ),
                  ],
                ),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'HALFTIME ADJUSTMENTS',
                        style: GKText.sectionLabel,
                      ),
                      const SizedBox(height: GKSpace.xs),
                      Text(
                        '${widget.team.name} $teamScore, ${widget.opponent.name} $opponentScore',
                        style: GKText.pageTitle,
                      ),
                      const SizedBox(height: GKSpace.lg),
                      Text('OFFENSIVE PLAN', style: GKText.sectionLabel),
                      const SizedBox(height: GKSpace.xs),
                      for (final plan in _OffensivePlan.values) ...[
                        _planChip(
                          label: _offensivePlanLabel(plan),
                          reason: _offensivePlanReason(plan),
                          selected: selectedOffense == plan,
                          recommended: plan == _recommendedOffensivePlan,
                          risky:
                              plan == _OffensivePlan.airItOut &&
                              plan != _recommendedOffensivePlan,
                          onTap: () =>
                              setSheetState(() => selectedOffense = plan),
                        ),
                        const SizedBox(height: GKSpace.xs),
                      ],
                      const SizedBox(height: GKSpace.md),
                      Text('DEFENSIVE PLAN', style: GKText.sectionLabel),
                      const SizedBox(height: GKSpace.xs),
                      for (final plan in _DefensivePlan.values) ...[
                        _planChip(
                          label: _defensivePlanLabel(plan),
                          reason: _defensivePlanReason(plan),
                          selected: selectedDefense == plan,
                          recommended: plan == _recommendedDefensivePlan,
                          risky:
                              plan == _DefensivePlan.bringPressure &&
                              plan != _recommendedDefensivePlan,
                          onTap: () =>
                              setSheetState(() => selectedDefense = plan),
                        ),
                        const SizedBox(height: GKSpace.xs),
                      ],
                      const SizedBox(height: GKSpace.md),
                      GKPrimaryButton(
                        label: 'Confirm Adjustments',
                        icon: Icons.check_circle_outline_rounded,
                        onPressed: () => _applyHalftimePlans(
                          selectedOffense,
                          selectedDefense,
                          sheetContext,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );
  }

  void _finishGameInternal() {
    if (teamScore == opponentScore) {
      if (rng.nextDouble() < .5) {
        teamScore += 3;
        teamFieldGoals++;
        _addPlay(
          'OVERTIME · ${widget.team.name} wins on a walk-off field goal.',
          userPositive: true,
        );
        _animateDriveOnField(true, _DriveOutcome.fieldGoal);
      } else {
        opponentScore += 3;
        opponentFieldGoals++;
        _addPlay(
          'OVERTIME · ${widget.opponent.name} wins on a walk-off field goal.',
          userPositive: false,
        );
        _animateDriveOnField(false, _DriveOutcome.fieldGoal);
      }
    }

    finished = true;
    autoRunning = false;
    momentum = teamScore > opponentScore ? 1 : -1;

    plays.insert(
      0,
      'FINAL · ${rankedDisplayName(widget.team, widget.teamRank)} '
      '$teamScore, ${rankedDisplayName(widget.opponent, widget.opponentRank)} '
      '$opponentScore',
    );

    // Phase 6.2: the dynasty result is intentionally deferred until the
    // mandatory postgame press conference has been completed.
  }

  String get _resultHeadline {
    final won = teamScore > opponentScore;
    final margin = (teamScore - opponentScore).abs();

    if (won && margin >= 21) {
      return '${widget.team.name} MAKES A STATEMENT';
    }
    if (won && margin <= 7) {
      return '${widget.team.name} SURVIVES A THRILLER';
    }
    if (won) return '${widget.team.name} GETS THE WIN';

    if (margin <= 7) return '${widget.team.name} FALLS JUST SHORT';
    return '${widget.team.name} SUFFERS A TOUGH LOSS';
  }

  String get _turningPoint {
    if (teamTurnovers != opponentTurnovers) {
      final winner = teamTurnovers < opponentTurnovers
          ? widget.team.name
          : widget.opponent.name;
      return '$winner won the turnover battle '
          '$opponentTurnovers-$teamTurnovers.';
    }

    if (teamBigPlays != opponentBigPlays) {
      final winner = teamBigPlays > opponentBigPlays
          ? widget.team.name
          : widget.opponent.name;
      return '$winner created more explosive plays at the decisive moments.';
    }

    final winningTeam = teamScore > opponentScore
        ? widget.team.name
        : widget.opponent.name;
    return '$winningTeam executed better in scoring territory.';
  }

  // The real top performer from this game's actual box score — the same
  // map every touchdown popup and the box score panel already read, ranked
  // by the same production formula SeasonStatsScreen uses — so "Player of
  // the Game" always ends up naming whoever those touchdown popups were
  // actually celebrating, instead of defaulting to the starting QB no
  // matter who scored. Only meaningful on a win: liveBoxScore only ever
  // tracks our own team's plays, so there's no real per-player data to
  // rank when the opponent wins instead.
  Player? get _topPerformer {
    if (liveBoxScore.isEmpty) return null;
    int score(GamePlayerLine l) =>
        l.totalYards +
        l.totalTDs * 20 +
        l.sacks * 15 +
        l.interceptions * 15 +
        l.tackles;
    final byName = {for (final p in widget.teamStarters) p.name: p};
    MapEntry<String, GamePlayerLine>? best;
    for (final entry in liveBoxScore.entries) {
      if (best == null || score(entry.value) > score(best.value)) best = entry;
    }
    return byName[best?.key];
  }

  String get _playerOfGameName {
    if (teamScore > opponentScore) {
      return (_topPerformer ?? widget.teamStartingQb).cleanName;
    }
    return widget.opponentStartingQb.cleanName;
  }

  String get _playerOfGameLine {
    if (teamScore > opponentScore) {
      final top = _topPerformer;
      final line = top != null
          ? liveBoxScore[top.name]!
          : (liveBoxScore[widget.teamStartingQb.name] ?? GamePlayerLine.zero);
      return '${widget.team.name} · ${seasonStatLineFor(line)}';
    }

    // No real per-player data exists for the opposing roster, so this
    // stays an estimate off the real final score — but it's never shown
    // next to a touchdown popup for the user to compare against, since
    // only our own team's scores trigger one.
    return '${widget.opponent.name} QB · '
        '${220 + opponentScore * 3} total yards · '
        '${max(1, opponentTouchdowns)} TD';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GKColors.midnight,
      body: GKBackground(
        child: SafeArea(
          child: Stack(
            children: [
              Column(
                children: [
                  _broadcastTopBar(context),
                  _scoreboard(),
                  if (!finished) _momentumStrip(),
                  Expanded(
                    child: finished
                        ? _postgamePresentation()
                        : gameStarted
                        ? _liveGamePresentation()
                        : _pregamePresentation(),
                  ),
                  _controlDeck(),
                ],
              ),
              _touchdownCelebrationOverlay(),
            ],
          ),
        ),
      ),
    );
  }

  Widget _touchdownCelebrationOverlay() {
    final player = _celebratingPlayer;
    if (player == null) return const SizedBox.shrink();

    return Positioned.fill(
      child: IgnorePointer(
        child: Align(
          alignment: const Alignment(0, -.25),
          child: ScaleTransition(
            scale: _celebrationScale,
            child: FadeTransition(
              opacity: _celebrationController,
              child: Container(
                margin: const EdgeInsets.symmetric(horizontal: 40),
