  Widget _scoreboardTeam({
    required CollegeTeam team,
    required int ranking,
    required int score,
    required bool hasBall,
    required bool alignRight,
  }) {
    final rankLabel = ranking <= 25 ? '#$ranking ' : '';

    final teamInfo = Expanded(
      child: Column(
        crossAxisAlignment: alignRight
            ? CrossAxisAlignment.end
            : CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: alignRight
                ? MainAxisAlignment.end
                : MainAxisAlignment.start,
            children: [
              if (hasBall && !alignRight)
                const Padding(
                  padding: EdgeInsets.only(right: 4),
                  child: Icon(
                    Icons.sports_football_rounded,
                    color: _gameCyan,
                    size: 12,
                  ),
                ),
              Flexible(
                child: Text(
                  '$rankLabel${team.name}'.toUpperCase(),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  textAlign: alignRight ? TextAlign.right : TextAlign.left,
                  style: const TextStyle(
                    color: _gameText,
                    fontSize: 11,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              if (hasBall && alignRight)
                const Padding(
                  padding: EdgeInsets.only(left: 4),
                  child: Icon(
                    Icons.sports_football_rounded,
                    color: _gameCyan,
                    size: 12,
                  ),
                ),
            ],
          ),
          const SizedBox(height: 2),
          Text(
            '${team.name == widget.team.name ? widget.teamOvr : widget.opponentOvr} OVR',
            style: const TextStyle(
              color: _gameMuted,
              fontSize: 9,
              fontWeight: FontWeight.w800,
            ),
          ),
        ],
      ),
    );

    final scoreText = _ScoreFlipDigits(
      score: score,
      style: const TextStyle(
        color: _gameText,
        fontSize: 35,
        fontWeight: FontWeight.w900,
        height: 1,
      ),
    );

    return Row(
      mainAxisAlignment: alignRight
          ? MainAxisAlignment.end
          : MainAxisAlignment.start,
      children: alignRight
          ? [
              scoreText,
              const SizedBox(width: GKSpace.xs),
              teamInfo,
              const SizedBox(width: GKSpace.xs),
              GKTeamBadge(team: team, size: 41),
            ]
          : [
              GKTeamBadge(team: team, size: 41),
              const SizedBox(width: GKSpace.xs),
              teamInfo,
              const SizedBox(width: GKSpace.xs),
              scoreText,
            ],
    );
  }

