  Widget _comparisonRow(String label, int userValue, int opponentValue) {
    final maxValue = max(1, userValue + opponentValue);
    final userShare = userValue / maxValue;

    return Padding(
      padding: const EdgeInsets.only(bottom: GKSpace.sm),
      child: Column(
        children: [
          Row(
            children: [
              Text(
                '$userValue',
                style: const TextStyle(
                  color: _gameCyan,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const Spacer(),
              Text(
                label.toUpperCase(),
                style: const TextStyle(
                  color: _gameMuted,
                  fontSize: 9,
                  fontWeight: FontWeight.w900,
                  letterSpacing: .8,
                ),
              ),
              const Spacer(),
              Text(
                '$opponentValue',
                style: const TextStyle(
                  color: _gameText,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
          const SizedBox(height: 5),
          ClipRRect(
            borderRadius: BorderRadius.circular(4),
            child: LinearProgressIndicator(
              value: userShare,
              minHeight: 6,
              backgroundColor: widget.opponent.primary,
              valueColor: AlwaysStoppedAnimation<Color>(widget.team.primary),
            ),
          ),
        ],
      ),
    );
  }

