        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(
                  Icons.sports_football_rounded,
                  size: 13,
                  color: GKColors.inkBlack.withOpacity(.55),
                ),
                const SizedBox(width: 5),
                Text(
                  '${possessor.name.toUpperCase()} DRIVING',
                  style: GoogleFonts.zillaSlab(
                    color: GKColors.inkBlack.withOpacity(.7),
                    fontSize: 10,
                    fontWeight: FontWeight.w700,
                    letterSpacing: 1.1,
                  ),
                ),
                const Spacer(),
                AnimatedBuilder(
                  animation: _fieldController,
                  builder: (context, _) => Text(
                    _fieldSpotLabel(_ballYard, _fieldPossessionIsUser),
                    style: GoogleFonts.zillaSlab(
                      color: GKColors.inkBlack.withOpacity(.7),
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                      letterSpacing: .6,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            AspectRatio(
              aspectRatio: 3.1,
              child: AnimatedBuilder(
                animation: _fieldController,
                builder: (context, _) => CustomPaint(
                  painter: _FootballFieldPainter(
                    yardPosition: _ballYard,
                    homeColor: widget.team.primary,
                    awayColor: widget.opponent.primary,
                    homeAbbr: teamMonogram(widget.team.name),
                    awayAbbr: teamMonogram(widget.opponent.name),
                    possessionIsUser: _fieldPossessionIsUser,
                  ),
                  size: Size.infinite,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  static String _fieldSpotLabel(double absoluteYard, bool userBall) {
    final ownYard = userBall ? absoluteYard : 100 - absoluteYard;
    if (ownYard.round() == 50) return 'MIDFIELD';
    if (ownYard < 50) return 'OWN ${ownYard.round()}';
    return 'OPP ${(100 - ownYard).round()}';
  }

  Widget _gamecastFeed() {
    return Column(
      children: [
        _fieldVisualization(),
        Expanded(child: _gamecastList()),
      ],
    );
  }

  Widget _gamecastList() {
    return ListView.separated(
      reverse: false,
      padding: const EdgeInsets.all(GKSpace.md),
      itemCount: plays.length,
      separatorBuilder: (_, _unused) => const SizedBox(height: GKSpace.xs),
      itemBuilder: (context, index) {
        final play = plays[index];
        final major =
            play.contains('TOUCHDOWN') ||
            play.contains('TURNOVER') ||
            play.contains('FINAL') ||
            play.contains('OVERTIME');

        return GKCard(
          padding: const EdgeInsets.all(GKSpace.sm),
          color: major ? Color(0xFF201B12) : _gamePanelRaised,
          borderColor: major ? _gameCyan.withOpacity(.38) : GKColors.divider,
          radius: GKRadius.small,
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(
                major ? Icons.bolt_rounded : Icons.sports_football_rounded,
                color: major ? _gameCyan : _gameMuted,
                size: 17,
              ),
              const SizedBox(width: GKSpace.xs),
              Expanded(
                child: Text(
                  play,
                  style: const TextStyle(
                    color: _gameText,
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    height: 1.35,
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _teamStatsPanel() {
    final teamYards = gameTotalYardsFor(
      score: teamScore,
      bigPlays: teamBigPlays,
      turnovers: teamTurnovers,
    );
    final opponentYards = gameTotalYardsFor(
      score: opponentScore,
      bigPlays: opponentBigPlays,
      turnovers: opponentTurnovers,
    );

    // A plain (non-scrolling) widget: this is nested as a list item inside
    // _postgamePresentation()'s own ListView, and a scrolling viewport given
    // unbounded height by an ancestor ListView throws at layout time. The
    // live-game "TEAM STATS" tab, which does need this to scroll on its own,
    // wraps this call in a SingleChildScrollView instead.
    return Padding(
      padding: const EdgeInsets.all(GKSpace.md),
      child: Column(
        children: [
          GKCard(
            child: Column(
              children: [
                _statComparison('Total yards', teamYards, opponentYards),
                _statComparison(
                  'Touchdowns',
                  teamTouchdowns,
                  opponentTouchdowns,
                ),
                _statComparison(
                  'Field goals',
                  teamFieldGoals,
                  opponentFieldGoals,
                ),
                _statComparison(
                  'Turnovers',
                  teamTurnovers,
                  opponentTurnovers,
                  lowerIsBetter: true,
                ),
                _statComparison(
                  'Explosive plays',
                  teamBigPlays,
                  opponentBigPlays,
                ),
              ],
            ),
          ),
          if (liveBoxScore.isNotEmpty) ...[
            const SizedBox(height: GKSpace.md),
            _playerBoxScorePanel(),
          ],
        ],
      ),
    );
  }

  // The real, live box score — same map the touchdown popup and season
  // stats read from, so this list never disagrees with what's actually
  // happened. Grows in place as the game goes on, both here (mid-game) and
  // in the identical postgame view, since both call _teamStatsPanel().
  Widget _playerBoxScorePanel() {
    final entries = liveBoxScore.entries.toList()
      ..sort((a, b) {
        int score(GamePlayerLine l) =>
            l.totalYards +
            l.totalTDs * 20 +
            l.sacks * 15 +
            l.interceptions * 15 +
            l.tackles;
        return score(b.value).compareTo(score(a.value));
      });

    final rosterByName = {for (final p in widget.teamStarters) p.name: p};

    return GKCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('PLAYER STATS', style: GKText.sectionLabel),
          const SizedBox(height: GKSpace.sm),
          ...entries.map((entry) {
            final player = rosterByName[entry.key];
            return Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  SizedBox(
                    width: 34,
                    child: Text(
                      player?.position ?? '',
                      style: const TextStyle(
                        color: GKColors.kingdomBrass,
                        fontSize: 11,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          player?.cleanName ?? entry.key,
                          style: const TextStyle(
                            color: _gameText,
                            fontSize: 13,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                        Text(
                          seasonStatLineFor(entry.value),
                          style: const TextStyle(
                            color: _gameMuted,
                            fontSize: 11,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            );
          }),
        ],
      ),
    );
  }

  Widget _statComparison(
    String label,
    int userValue,
    int opponentValue, {
    bool lowerIsBetter = false,
  }) {
    final userLeading = lowerIsBetter
        ? userValue < opponentValue
        : userValue > opponentValue;
    final opponentLeading = lowerIsBetter
        ? opponentValue < userValue
        : opponentValue > userValue;

    return Container(
      padding: const EdgeInsets.symmetric(vertical: GKSpace.sm),
      decoration: const BoxDecoration(
        border: Border(bottom: BorderSide(color: GKColors.divider)),
      ),
      child: Row(
        children: [
          SizedBox(
            width: 54,
            child: Text(
              '$userValue',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: userLeading ? _gameCyan : _gameText,
                fontSize: 17,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          Expanded(
            child: Text(
              label.toUpperCase(),
              textAlign: TextAlign.center,
              style: const TextStyle(
                color: _gameMuted,
                fontSize: 9,
                fontWeight: FontWeight.w900,
                letterSpacing: .8,
              ),
            ),
          ),
          SizedBox(
            width: 54,
            child: Text(
              '$opponentValue',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: opponentLeading ? _gameCyan : _gameText,
                fontSize: 17,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _boxScorePanel() {
    final teamQuarterScores = _quarterScores(
      teamScore,
      widget.team.name.length,
    );
    final opponentQuarterScores = _quarterScores(
      opponentScore,
      widget.opponent.name.length,
    );

    return ListView(
      padding: const EdgeInsets.all(GKSpace.md),
      children: [
        GKCard(
          padding: EdgeInsets.zero,
          child: Column(
            children: [
              _boxScoreHeader(),
