class PlayerAvatar extends StatelessWidget {
  final int seed;
  final Color teamColor;
  final double size;

  const PlayerAvatar({
    super.key,
    required this.seed,
    required this.teamColor,
    this.size = 48,
  });

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: Size(size, size),
      painter: PlayerAvatarPainter(seed: seed, teamColor: teamColor),
    );
  }
}

/// A player's face, drawn by the exact same painter as the coach's — same
/// proportions, same eyes, same mouth, same hair/beard system — just with
/// skin tone, hair, and facial hair rolled deterministically from the
/// player's seed instead of picked by a user. Coach and player portraits
/// are the same visual system on purpose: a roster shouldn't look like a
/// different artist drew it than the sideline.
class PlayerAvatarPainter extends CustomPainter {
  final int seed;
  final Color teamColor;

  PlayerAvatarPainter({required this.seed, required this.teamColor});

  static const _skinTones = [
    'Fair',
    'Light',
    'Tan',
    'Olive',
    'Brown',
    'Deep',
    'Dark',
  ];

  static const _hairColorNames = [
    'Black',
    'Dark Brown',
    'Brown',
    'Auburn',
    'Sandy',
    'Blonde',
    'Red',
  ];

  static const _hairStyles = [
    'Short',
    'Buzz Cut',
    'Curly',
    'Waves',
    'Long',
    'Bald',
    'Fade',
    'Afro',
    'Mohawk',
    'Slick Back',
    'Man Bun',
    'Dreads',
  ];

  static const _beardOptions = [
    'None',
    'Stubble',
    'Goatee',
    'Mustache',
    'Chin Strap',
    'Soul Patch',
    'Full Beard',
  ];

  @override
  void paint(Canvas canvas, Size size) {
    final random = Random(seed);
    final skinTone = _skinTones[random.nextInt(_skinTones.length)];
    final hairColorName =
        _hairColorNames[random.nextInt(_hairColorNames.length)];
    final hairStyle = _hairStyles[random.nextInt(_hairStyles.length)];
    final beard = _beardOptions[random.nextInt(_beardOptions.length)];
    final glasses = random.nextDouble() < .16;

    CoachAvatarPainter(
      skinColor: coachSkinColorFor(skinTone),
      hairColor: coachHairColorFor(hairColorName),
      hairStyle: hairStyle,
      beard: beard,
      glasses: glasses,
      teamColor: teamColor,
      wearsHeadset: false,
    ).paint(canvas, size);
  }

  @override
  bool shouldRepaint(covariant PlayerAvatarPainter oldDelegate) =>
      oldDelegate.seed != seed || oldDelegate.teamColor != teamColor;
}

class CoachAvatarPainter extends CustomPainter {
  final Color skinColor;
  final Color hairColor;
  final String hairStyle;
  final String beard;
  final bool glasses;
  final Color teamColor;
  // A headset is a sideline coach's tool, not a player's — on by default
  // for the coach's own portrait, off for player avatars (which paint
  // through this same class; see PlayerAvatarPainter).
  final bool wearsHeadset;

  CoachAvatarPainter({
    required this.skinColor,
    required this.hairColor,
    required this.hairStyle,
    required this.beard,
    this.glasses = false,
    required this.teamColor,
    this.wearsHeadset = true,
  });

  Color _shade(Color color, double amount) =>
      Color.lerp(color, GKColors.inkBlack, amount) ?? color;

  Color _tint(Color color, double amount) =>
      Color.lerp(color, GKColors.parchmentWhite, amount) ?? color;

  void _drawHairTexture(Canvas canvas, Paint stroke, List<Offset> points) {
    for (var i = 0; i < points.length - 1; i++) {
      canvas.drawLine(points[i], points[i + 1], stroke);
    }
  }

  // A flat single-color fill is what made hair and beards read as plastic
  // stickers rather than actual hair — this gives every strand-mass a real,
  // pronounced top-lit gradient (a genuine highlight catching the crown,
  // sweeping down to a deep shadow at the nape/jaw) using one shared
  // shader space so every hairstyle and beard style gets the same
  // lighting logic for free. Deliberately high-contrast — a subtle tonal
  // shift didn't read as different at avatar size; this has to be
  // unmistakable at a glance.
  Paint get _hairFill => Paint()
    ..isAntiAlias = true
    ..shader = LinearGradient(
      begin: Alignment.topLeft,
      end: Alignment.bottomRight,
      colors: [
        _tint(hairColor, .55),
        _tint(hairColor, .18),
        hairColor,
        _shade(hairColor, .32),
        _shade(hairColor, .58),
      ],
      stops: const [0, .2, .48, .76, 1],
    ).createShader(const Rect.fromLTWH(30, 4, 90, 70));

  Paint get _beardFill => Paint()
    ..isAntiAlias = true
    ..shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: [
        _tint(hairColor, .15),
        _shade(hairColor, .10),
        _shade(hairColor, .30),
        _shade(hairColor, .52),
      ],
      stops: const [0, .35, .68, 1],
    ).createShader(const Rect.fromLTWH(40, 65, 70, 45));

  // A soft catch-light streak across the crown — the single detail that
  // makes hair read as glossy and dimensional instead of a painted-on
  // silhouette, regardless of which style is selected.
  void _paintHairSheen(Canvas canvas) {
    if (hairStyle == 'Bald') return;
    final sheen = Paint()
      ..isAntiAlias = true
      ..style = PaintingStyle.stroke
      ..strokeWidth = 3.4
      ..strokeCap = StrokeCap.round
      ..color = _tint(hairColor, .6).withOpacity(.55);
    canvas.drawArc(
      const Rect.fromLTWH(46, 14, 42, 22),
      3.55,
      1.05,
      false,
      sheen,
    );
    final sheenNarrow = Paint()
      ..isAntiAlias = true
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.6
      ..strokeCap = StrokeCap.round
      ..color = _tint(hairColor, .75).withOpacity(.6);
    canvas.drawArc(
      const Rect.fromLTWH(50, 16, 34, 18),
      3.7,
      .8,
      false,
      sheenNarrow,
    );
  }

  @override
  void paint(Canvas canvas, Size size) {
    final scale = size.width / 150;
    canvas.save();
    canvas.scale(scale, scale);

    final fill = Paint()..isAntiAlias = true;
    final stroke = Paint()
      ..isAntiAlias = true
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;

    // Background portrait badge.
    fill.color = _shade(teamColor, .78);
    canvas.drawCircle(const Offset(75, 75), 73, fill);

    stroke
      ..color = _tint(teamColor, .18)
      ..strokeWidth = 2;
    canvas.drawCircle(const Offset(75, 75), 71, stroke);

    // Shoulders and coaching quarter-zip.
    fill.color = _shade(teamColor, .10);
    canvas.drawPath(
      Path()
        ..moveTo(14, 150)
        ..quadraticBezierTo(19, 118, 47, 108)
        ..quadraticBezierTo(58, 103, 75, 103)
        ..quadraticBezierTo(92, 103, 103, 108)
        ..quadraticBezierTo(131, 118, 136, 150)
        ..close(),
      fill,
    );

    // Shoulder shadows.
    fill.color = _shade(teamColor, .28);
    canvas.drawPath(
      Path()
        ..moveTo(14, 150)
        ..quadraticBezierTo(21, 124, 45, 115)
        ..lineTo(53, 150)
        ..close(),
      fill,
    );
    canvas.drawPath(
      Path()
        ..moveTo(136, 150)
        ..quadraticBezierTo(129, 124, 105, 115)
        ..lineTo(97, 150)
        ..close(),
      fill,
    );

    // Quarter zip collar.
    fill.color = _tint(teamColor, .13);
    canvas.drawPath(
      Path()
        ..moveTo(51, 108)
        ..lineTo(67, 123)
        ..lineTo(75, 113)
        ..lineTo(83, 123)
        ..lineTo(99, 108)
        ..lineTo(91, 103)
        ..lineTo(59, 103)
        ..close(),
      fill,
    );

    fill.color = _shade(teamColor, .30);
    canvas.drawPath(
      Path()
        ..moveTo(51, 108)
        ..lineTo(67, 123)
        ..lineTo(75, 113)
        ..lineTo(83, 123)
        ..lineTo(99, 108)
        ..lineTo(91, 103)
        ..lineTo(59, 103)
        ..close(),
      fill,
    );

    // Neck.
    fill.color = skinColor;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        const Rect.fromLTWH(59, 84, 32, 29),
        const Radius.circular(10),
      ),
      fill,
    );

    fill.color = _shade(skinColor, .14);
    canvas.drawPath(
      Path()
        ..moveTo(61, 91)
        ..quadraticBezierTo(75, 102, 89, 91)
        ..lineTo(89, 103)
        ..quadraticBezierTo(75, 112, 61, 103)
        ..close(),
      fill,
    );

    // Ears.
    fill.color = skinColor;
    canvas.drawOval(const Rect.fromLTWH(25, 44, 17, 31), fill);
    canvas.drawOval(const Rect.fromLTWH(108, 44, 17, 31), fill);

    stroke
      ..color = _shade(skinColor, .22)
      ..strokeWidth = 1.3;
    canvas.drawArc(const Rect.fromLTWH(29, 50, 9, 18), 4.5, 3.0, false, stroke);
    canvas.drawArc(
      const Rect.fromLTWH(112, 50, 9, 18),
      1.8,
      3.0,
      false,
      stroke,
    );

    // Realistic face silhouette.
    final face = Path()
      ..moveTo(42, 30)
      ..quadraticBezierTo(49, 15, 75, 14)
      ..quadraticBezierTo(101, 15, 108, 30)
      ..lineTo(106, 60)
      ..quadraticBezierTo(104, 77, 95, 88)
      ..quadraticBezierTo(87, 98, 75, 101)
      ..quadraticBezierTo(63, 98, 55, 88)
      ..quadraticBezierTo(46, 77, 44, 60)
      ..close();

    fill.color = skinColor;
    canvas.drawPath(face, fill);

    // Facial planes — pushed to real, visible contrast (not a faint 7-8%
    // tint) so the face reads as sculpted rather than a flat skin-colored
    // shape with an outline.
    fill.color = _shade(skinColor, .20);
    canvas.drawPath(
      Path()
        ..moveTo(44, 42)
        ..quadraticBezierTo(50, 32, 61, 29)
        ..quadraticBezierTo(56, 51, 58, 67)
        ..quadraticBezierTo(54, 80, 60, 91)
        ..quadraticBezierTo(49, 81, 46, 65)
        ..close(),
      fill,
    );

    // A warm forehead/cheek highlight — the light source catching the
    // brow ridge and cheekbone.
    fill.shader = RadialGradient(
      center: const Alignment(-.1, -.7),
      radius: .9,
      colors: [_tint(skinColor, .30), Colors.transparent],
    ).createShader(const Rect.fromLTWH(44, 18, 64, 55));
    canvas.drawPath(face, fill);
    fill.shader = null;

    fill.color = _shade(skinColor, .16);
    canvas.drawPath(
      Path()
        ..moveTo(76, 25)
        ..quadraticBezierTo(95, 27, 104, 40)
        ..lineTo(102, 63)
        ..quadraticBezierTo(96, 79, 87, 88)
        ..quadraticBezierTo(89, 66, 87, 45)
        ..close(),
      fill,
    );

    // Jaw/chin shadow — separates the chin from the neck instead of
    // leaving the whole lower face one flat tone.
    fill.color = _shade(skinColor, .18);
    canvas.drawPath(
      Path()
        ..moveTo(58, 88)
        ..quadraticBezierTo(75, 100, 92, 88)
        ..quadraticBezierTo(75, 96, 58, 88)
        ..close(),
      fill,
    );

    stroke
      ..color = _shade(skinColor, .32)
      ..strokeWidth = 1.6;
    canvas.drawPath(face, stroke);

    // Hair base and shape — a shared top-lit gradient (_hairFill) instead
    // of one flat color, so every style has real volume.
    if (hairStyle == 'Bald') {
      stroke
        ..color = _shade(skinColor, .13)
        ..strokeWidth = 1;
      canvas.drawArc(
        const Rect.fromLTWH(47, 15, 56, 22),
        3.28,
        2.75,
        false,
        stroke,
      );
    } else if (hairStyle == 'Buzz Cut') {
      canvas.drawPath(
        Path()
          ..moveTo(43, 34)
          ..quadraticBezierTo(47, 16, 75, 15)
          ..quadraticBezierTo(103, 16, 107, 34)
          ..quadraticBezierTo(91, 28, 75, 28)
          ..quadraticBezierTo(59, 28, 43, 34)
          ..close(),
        _hairFill,
      );
    } else if (hairStyle == 'Fade') {
      canvas.drawPath(
        Path()
          ..moveTo(42, 38)
          ..quadraticBezierTo(45, 16, 75, 14)
          ..quadraticBezierTo(105, 16, 108, 38)
          ..quadraticBezierTo(93, 29, 75, 28)
          ..quadraticBezierTo(57, 29, 42, 38)
          ..close(),
        _hairFill,
      );

      fill.color = _shade(hairColor, .27);
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(42, 34, 8, 26),
          const Radius.circular(4),
        ),
        fill,
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(100, 34, 8, 26),
          const Radius.circular(4),
        ),
        fill,
      );
    } else if (hairStyle == 'Curly') {
      final curls = <Offset>[
        const Offset(45, 31),
        const Offset(52, 22),
        const Offset(62, 18),
        const Offset(74, 17),
        const Offset(86, 18),
        const Offset(97, 23),
        const Offset(105, 32),
        const Offset(55, 31),
        const Offset(67, 26),
        const Offset(79, 26),
        const Offset(91, 31),
      ];

      final curlFill = _hairFill;
      for (final curl in curls) {
        canvas.drawCircle(curl, 8.7, curlFill);
      }
      // Small highlight dots so each curl reads as individually rounded
      // rather than one flat mass.
      fill.color = _tint(hairColor, .30).withOpacity(.5);
      for (final curl in curls) {
        canvas.drawCircle(curl.translate(-2.6, -2.6), 2.1, fill);
      }
    } else if (hairStyle == 'Waves') {
      canvas.drawPath(
        Path()
          ..moveTo(43, 36)
          ..quadraticBezierTo(47, 16, 75, 15)
          ..quadraticBezierTo(103, 16, 107, 36)
          ..quadraticBezierTo(91, 29, 75, 29)
          ..quadraticBezierTo(59, 29, 43, 36)
          ..close(),
        _hairFill,
      );

      stroke
        ..color = _tint(hairColor, .25)
        ..strokeWidth = 1.1;
      _drawHairTexture(canvas, stroke, const [
        Offset(52, 26),
        Offset(61, 23),
        Offset(70, 25),
        Offset(80, 22),
        Offset(90, 25),
        Offset(98, 23),
      ]);
      _drawHairTexture(canvas, stroke, const [
        Offset(55, 31),
        Offset(65, 28),
        Offset(75, 30),
        Offset(85, 27),
        Offset(95, 30),
      ]);
    } else if (hairStyle == 'Long') {
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(34, 16, 82, 92),
          const Radius.circular(33),
        ),
        _hairFill,
      );

      fill.color = skinColor;
      canvas.drawPath(face, fill);

      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(34, 39, 14, 65),
          const Radius.circular(8),
        ),
        _hairFill,
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(102, 39, 14, 65),
          const Radius.circular(8),
        ),
        _hairFill,
      );
      canvas.drawPath(
        Path()
          ..moveTo(42, 37)
          ..quadraticBezierTo(47, 15, 75, 14)
          ..quadraticBezierTo(103, 15, 108, 37)
          ..quadraticBezierTo(92, 27, 75, 27)
          ..quadraticBezierTo(58, 27, 42, 37)
          ..close(),
        _hairFill,
      );
    } else if (hairStyle == 'Afro') {
      canvas.drawOval(const Rect.fromLTWH(18, 6, 114, 78), _hairFill);
      fill.color = skinColor;
      canvas.drawPath(face, fill);
      final afroFill = _hairFill;
      const afroRing = [
        Offset(28, 34),
        Offset(24, 20),
        Offset(35, 10),
        Offset(50, 5),
        Offset(65, 4),
        Offset(75, 3),
        Offset(85, 4),
        Offset(100, 5),
        Offset(115, 10),
        Offset(126, 20),
        Offset(122, 34),
        Offset(112, 42),
      ];
      for (final p in afroRing) {
        canvas.drawCircle(p, 11, afroFill);
      }
    } else if (hairStyle == 'Mohawk') {
      stroke
        ..color = _shade(skinColor, .13)
        ..strokeWidth = 1;
      canvas.drawArc(
        const Rect.fromLTWH(43, 16, 30, 24),
        2.6,
        2.2,
        false,
        stroke,
      );
      canvas.drawArc(
        const Rect.fromLTWH(77, 16, 30, 24),
        .35,
        2.2,
        false,
        stroke,
      );
      canvas.drawPath(
        Path()
          ..moveTo(66, 12)
          ..lineTo(84, 12)
          ..quadraticBezierTo(80, 40, 78, 52)
          ..lineTo(72, 52)
          ..quadraticBezierTo(70, 40, 66, 12)
          ..close(),
        _hairFill,
      );
    } else if (hairStyle == 'Slick Back') {
      canvas.drawPath(
        Path()
          ..moveTo(42, 40)
          ..quadraticBezierTo(45, 15, 75, 13)
          ..quadraticBezierTo(105, 15, 108, 40)
          ..quadraticBezierTo(97, 22, 75, 20)
          ..quadraticBezierTo(53, 22, 42, 40)
          ..close(),
        _hairFill,
      );
      stroke
        ..color = _tint(hairColor, .35)
        ..strokeWidth = 1.2;
      canvas.drawLine(const Offset(52, 22), const Offset(45, 36), stroke);
      canvas.drawLine(const Offset(98, 22), const Offset(105, 36), stroke);
    } else if (hairStyle == 'Man Bun') {
      canvas.drawPath(
        Path()
          ..moveTo(43, 34)
          ..quadraticBezierTo(47, 16, 75, 15)
          ..quadraticBezierTo(103, 16, 107, 34)
          ..quadraticBezierTo(91, 28, 75, 28)
          ..quadraticBezierTo(59, 28, 43, 34)
          ..close(),
        _hairFill,
      );
      canvas.drawCircle(const Offset(75, 9), 9, _hairFill);
      stroke
        ..color = _shade(hairColor, .2)
        ..strokeWidth = 1;
      canvas.drawCircle(const Offset(75, 9), 9, stroke);
    } else if (hairStyle == 'Dreads') {
      canvas.drawPath(
        Path()
          ..moveTo(43, 30)
          ..quadraticBezierTo(47, 15, 75, 14)
          ..quadraticBezierTo(103, 15, 107, 30)
          ..quadraticBezierTo(91, 24, 75, 24)
          ..quadraticBezierTo(59, 24, 43, 30)
          ..close(),
        _hairFill,
      );
      // Two side clusters, hugging the temples outside the face (which
      // spans roughly x=42-108) rather than crossing it — the old
      // x=48/58/92 strands ran straight down over the eyes and nose.
      // Also shortened so they stop at the jaw instead of the chin.
      const strandX = [26.0, 34.0, 116.0, 124.0];
      final dreadFill = _hairFill;
      for (final x in strandX) {
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromLTWH(x, 24, 7, 38),
            const Radius.circular(3.5),
          ),
          dreadFill,
        );
      }
    } else {
      // Short / side-part.
      canvas.drawPath(
        Path()
          ..moveTo(42, 38)
          ..quadraticBezierTo(46, 16, 75, 14)
          ..quadraticBezierTo(103, 16, 108, 36)
          ..quadraticBezierTo(94, 29, 81, 27)
          ..lineTo(67, 32)
          ..quadraticBezierTo(55, 29, 42, 38)
          ..close(),
        _hairFill,
      );

      stroke
        ..color = _tint(hairColor, .20)
        ..strokeWidth = 1.1;
      canvas.drawLine(const Offset(68, 20), const Offset(67, 31), stroke);
    }

    _paintHairSheen(canvas);

    // Eyebrows — a slight taper (thicker at the bridge, thinner at the
    // temple) instead of a single dead-straight stroke of one width.
    stroke
      ..color = _shade(hairColor, .12)
      ..strokeWidth = 3.4;
    canvas.drawLine(const Offset(52, 46.5), const Offset(63, 44.5), stroke);
    canvas.drawLine(const Offset(87, 44.5), const Offset(98, 46.5), stroke);
    stroke.strokeWidth = 2;
    canvas.drawLine(const Offset(63, 44.5), const Offset(67, 45.5), stroke);
    canvas.drawLine(const Offset(83, 45.5), const Offset(87, 44.5), stroke);

    // Eyes — a calm, closed-lid-adjacent shape: a shorter, narrower white
    // opening with a large iris that fills most of it, so the eye reads as
    // relaxed rather than the startled, too-much-white-showing look a big
    // sclera oval with a small iris produced.
    fill.color = GKColors.parchmentWhite.withOpacity(.93);
    canvas.drawOval(const Rect.fromLTWH(51, 51, 14, 6), fill);
    canvas.drawOval(const Rect.fromLTWH(85, 51, 14, 6), fill);

    // Iris — a real radial gradient (light center fading to a dark ring)
    // instead of a flat disc, so eyes actually catch light. Sized to fill
    // most of the eye opening rather than floating small inside it.
    fill.shader =
        const RadialGradient(
          colors: [Color(0xFF7A5B3D), Color(0xFF4A3928), Color(0xFF2E2013)],
          stops: [0, .6, 1],
        ).createShader(
          Rect.fromCircle(center: const Offset(58, 54), radius: 3.1),
        );
    canvas.drawCircle(const Offset(58, 54), 3.1, fill);
    fill.shader =
        const RadialGradient(
          colors: [Color(0xFF7A5B3D), Color(0xFF4A3928), Color(0xFF2E2013)],
          stops: [0, .6, 1],
        ).createShader(
          Rect.fromCircle(center: const Offset(92, 54), radius: 3.1),
        );
    canvas.drawCircle(const Offset(92, 54), 3.1, fill);
    fill.shader = null;

    fill.color = GKColors.inkBlack;
    canvas.drawCircle(const Offset(58, 54), 1.3, fill);
    canvas.drawCircle(const Offset(92, 54), 1.3, fill);

    fill.color = GKColors.parchmentWhite;
    canvas.drawCircle(const Offset(57, 53), .7, fill);
    canvas.drawCircle(const Offset(91, 53), .7, fill);

    // Upper eyelid — a solid skin-toned cap over the top third of the eye
    // opening, not just a thin crease line, so the eye reads as lidded and
    // relaxed instead of a wide circle with a ring drawn on top of it.
    fill.color = skinColor;
    canvas.drawPath(
      Path()
        ..moveTo(50.5, 52)
        ..quadraticBezierTo(58, 47.5, 65.5, 52)
        ..quadraticBezierTo(58, 50.5, 50.5, 52)
        ..close(),
      fill,
    );
    canvas.drawPath(
      Path()
        ..moveTo(84.5, 52)
        ..quadraticBezierTo(92, 47.5, 99.5, 52)
        ..quadraticBezierTo(92, 50.5, 84.5, 52)
        ..close(),
      fill,
    );
    stroke
      ..color = _shade(skinColor, .28)
      ..strokeWidth = 1;
    canvas.drawArc(
      const Rect.fromLTWH(50.5, 48.5, 15, 7),
      3.3,
      2.6,
      false,
      stroke,
    );
    canvas.drawArc(
      const Rect.fromLTWH(84.5, 48.5, 15, 7),
      3.3,
      2.6,
      false,
      stroke,
    );

    // Nose bridge and nostrils.
    stroke
      ..color = _shade(skinColor, .23)
      ..strokeWidth = 1.5;
    canvas.drawPath(
      Path()
        ..moveTo(75, 52)
        ..quadraticBezierTo(72, 65, 72, 69)
        ..quadraticBezierTo(75, 72, 80, 69),
      stroke,
    );
    canvas.drawLine(const Offset(69, 71), const Offset(73, 72), stroke);
    canvas.drawLine(const Offset(78, 72), const Offset(82, 71), stroke);

    // Cheek definition.
    stroke
      ..color = _shade(skinColor, .13)
      ..strokeWidth = 1;
    canvas.drawArc(const Rect.fromLTWH(47, 58, 22, 18), .4, 1.4, false, stroke);
    canvas.drawArc(
      const Rect.fromLTWH(81, 58, 22, 18),
      1.35,
      1.4,
      false,
      stroke,
    );

    // Facial hair — real top-lit gradient shading (_beardFill) plus a
    // defining edge stroke on every solid style, instead of one flat fill
    // that read as a color sticker glued onto the jaw.
    if (beard == 'Goatee') {
      final goateeStroke = Paint()
        ..isAntiAlias = true
        ..style = PaintingStyle.stroke
        ..strokeWidth = .9
        ..color = _shade(hairColor, .35);

      final mustache = RRect.fromRectAndRadius(
        const Rect.fromLTWH(65, 75, 20, 4),
        const Radius.circular(2),
      );
      canvas.drawRRect(mustache, _beardFill);
      canvas.drawRRect(mustache, goateeStroke);

      final chin = Path()
        ..moveTo(68, 81)
        ..quadraticBezierTo(75, 85, 82, 81)
        ..lineTo(80, 93)
        ..quadraticBezierTo(75, 97, 70, 93)
        ..close();
      canvas.drawPath(chin, _beardFill);
      canvas.drawPath(chin, goateeStroke);
    } else if (beard == 'Mustache') {
      final shape = RRect.fromRectAndRadius(
        const Rect.fromLTWH(64, 74, 22, 5),
        const Radius.circular(2.5),
      );
      canvas.drawRRect(shape, _beardFill);
      canvas.drawRRect(
        shape,
        Paint()
          ..isAntiAlias = true
          ..style = PaintingStyle.stroke
          ..strokeWidth = .9
          ..color = _shade(hairColor, .35),
      );
    } else if (beard == 'Soul Patch') {
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(72, 88, 6, 7),
          const Radius.circular(2),
        ),
        _beardFill,
      );
    } else if (beard == 'Chin Strap') {
      stroke
        ..color = _shade(hairColor, .05)
        ..strokeWidth = 4.4;
      final strap = Path()
        ..moveTo(46, 65)
        ..quadraticBezierTo(50, 82, 62, 92)
        ..quadraticBezierTo(75, 100, 88, 92)
        ..quadraticBezierTo(100, 82, 104, 65);
      canvas.drawPath(strap, stroke);
      stroke
        ..color = _tint(hairColor, .22)
        ..strokeWidth = 1.3;
      canvas.drawPath(strap, stroke);
    } else if (beard == 'Stubble') {
      final random = Random(hairColor.toARGB32());
      for (var i = 0; i < 80; i++) {
        final dx = 47 + random.nextDouble() * 56;
        final dy = 68 + random.nextDouble() * 30;
        // Keep the stipple inside the jaw/chin silhouette roughly.
        if ((dx - 75).abs() > (dy - 68) * .95 + 8) continue;
        // Vary each grain's tone a little so it reads as real growth
        // rather than a uniform dot pattern.
        fill.color = _shade(
          hairColor,
          .1 + random.nextDouble() * .3,
        ).withOpacity(.28 + random.nextDouble() * .22);
        canvas.drawCircle(
          Offset(dx, dy),
          .45 + random.nextDouble() * .35,
          fill,
        );
      }
    } else if (beard == 'Full Beard') {
      final shape = Path()
        ..moveTo(46, 67)
        ..quadraticBezierTo(48, 84, 60, 94)
        ..quadraticBezierTo(75, 105, 90, 94)
        ..quadraticBezierTo(102, 84, 104, 67)
        ..quadraticBezierTo(94, 74, 87, 77)
        ..quadraticBezierTo(75, 82, 63, 77)
        ..quadraticBezierTo(56, 74, 46, 67)
        ..close();
      canvas.drawPath(shape, _beardFill);
      canvas.drawPath(
        shape,
        Paint()
          ..isAntiAlias = true
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1
          ..color = _shade(hairColor, .38),
      );

      fill.color = skinColor;
      canvas.drawOval(const Rect.fromLTWH(62, 72, 26, 13), fill);
    }

    // Mouth — a single closed, confident smile line. A filled lip shape
    // at this size collapsed into a dark oval blob that read as an open,
    // startled mouth rather than a face at rest; a stroke can't do that.
    stroke
      ..color = Color.lerp(skinColor, const Color(0xFF5C332E), .65) ?? skinColor
      ..strokeWidth = 2.2;
    canvas.drawPath(
      Path()
        ..moveTo(64, 81.5)
        ..quadraticBezierTo(75, 85.5, 86, 81.5),
      stroke,
    );
    // A soft crease under the lower lip gives the mouth real ground on
    // the face without reopening it into a shape.
    stroke
      ..color = _shade(skinColor, .16)
      ..strokeWidth = 1;
    canvas.drawPath(
      Path()
        ..moveTo(67, 85.5)
        ..quadraticBezierTo(75, 88, 83, 85.5),
      stroke,
    );

    // Glasses — sideline sunglasses, drawn over the eyes.
    if (glasses) {
      fill.color = GKColors.ledgerBlack.withOpacity(.55);
      final leftLens = RRect.fromRectAndRadius(
        const Rect.fromLTWH(47, 47, 22, 13),
        const Radius.circular(4),
      );
      final rightLens = RRect.fromRectAndRadius(
        const Rect.fromLTWH(81, 47, 22, 13),
        const Radius.circular(4),
      );
      canvas.drawRRect(leftLens, fill);
      canvas.drawRRect(rightLens, fill);

      stroke
        ..color = GKColors.inkBlack
        ..strokeWidth = 2;
      canvas.drawRRect(leftLens, stroke);
      canvas.drawRRect(rightLens, stroke);
      canvas.drawLine(const Offset(69, 52), const Offset(81, 52), stroke);
      canvas.drawLine(const Offset(47, 52), const Offset(38, 49), stroke);
      canvas.drawLine(const Offset(103, 52), const Offset(112, 49), stroke);
    }

    // Headset — coach only.
    if (wearsHeadset) {
      stroke
        ..color = Color(0xFF1D1D1D)
        ..strokeWidth = 3.5;
      canvas.drawArc(
        const Rect.fromLTWH(32, 22, 86, 80),
        3.4,
        2.6,
        false,
        stroke,
      );

      fill.color = Color(0xFF202020);
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(26, 53, 10, 24),
          const Radius.circular(4),
        ),
        fill,
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          const Rect.fromLTWH(114, 53, 10, 24),
          const Radius.circular(4),
        ),
        fill,
      );

      stroke
        ..color = Color(0xFF2B2B2B)
        ..strokeWidth = 2.5;
      canvas.drawPath(
        Path()
          ..moveTo(116, 70)
          ..quadraticBezierTo(124, 78, 116, 86)
          ..lineTo(96, 88),
        stroke,
      );

      fill.color = kRed;
      canvas.drawCircle(const Offset(95, 88), 3.2, fill);
    }

    // Quarter-zip seam.
    stroke
      ..color = GKColors.parchmentWhite.withOpacity(.75)
      ..strokeWidth = 1.5;
    canvas.drawLine(const Offset(75, 113), const Offset(75, 144), stroke);

    fill.color = kRed;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        const Rect.fromLTWH(66, 123, 18, 5),
        const Radius.circular(3),
      ),
      fill,
    );

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant CoachAvatarPainter oldDelegate) {
    return oldDelegate.skinColor != skinColor ||
        oldDelegate.hairColor != hairColor ||
        oldDelegate.hairStyle != hairStyle ||
        oldDelegate.beard != beard ||
        oldDelegate.glasses != glasses ||
        oldDelegate.teamColor != teamColor ||
        oldDelegate.wearsHeadset != wearsHeadset;
  }
}
